_builtin_format = format

def format(value, sep=" "):
    """Форматирование чисел с пробелами.
    Сохраняет работу встроенного format(value, spec) для '.2f', '>10', 'x' и т.д."""
    if isinstance(sep, str) and sep:
        if sep[0] in ".<>^=+-#% " and len(sep) <= 10:
            if not sep.isspace() or len(sep) > 1:
                return _builtin_format(value, sep)
        if sep[-1:] in ("b", "c", "d", "o", "x", "X", "e", "E", "f", "F", "g", "G", "n", "%", "s"):
            return _builtin_format(value, sep)
    try:
        return f"{int(value):,}".replace(",", " ")
    except Exception:
        return str(value)


def format_short(value):
    try:
        v = int(value)
    except Exception:
        return str(value)
    if v >= 1_000_000_000_000:
        return str(round(v / 1_000_000_000_000, 1)).rstrip("0").rstrip(".") + "KKK"
    if v >= 1_000_000_000:
        return str(round(v / 1_000_000_000, 1)).rstrip("0").rstrip(".") + "KK"
    if v >= 1_000_000:
        return str(round(v / 1_000_000, 1)).rstrip("0").rstrip(".") + "M"
    if v >= 1_000:
        return str(round(v / 1_000, 1)).rstrip("0").rstrip(".") + "K"
    return str(v)


# ============================================================
# ✅ BIG-INT: работа с огромными балансами через TEXT
# ============================================================
MAX_BALANCE = 10 ** 100
BALANCE_PAD = 100


def big_normalize(value):
    try:
        v = int(value)
    except Exception:
        v = 0
    if v < 0:
        v = 0
    if v > MAX_BALANCE:
        v = MAX_BALANCE
    return str(v).zfill(BALANCE_PAD)


def big_load(stored):
    if stored is None:
        return 0
    s = str(stored).lstrip("0")
    if not s:
        return 0
    try:
        return int(s)
    except Exception:
        return 0


def big_add(a, b):
    try:
        r = int(a) + int(b)
    except Exception:
        return False, 0
    if r > MAX_BALANCE:
        return False, int(a)
    if r < 0:
        r = 0
    return True, r


def big_sub(a, b):
    try:
        r = int(a) - int(b)
    except Exception:
        return False, 0
    if r < 0:
        return False, int(a)
    return True, r


def big_cmp(a, b):
    try:
        ai = int(a); bi = int(b)
        if ai > bi:
            return 1
        if ai == bi:
            return 0
        return -1
    except Exception:
        return 0


