@contextmanager
def _conn():
    conn = sqlite3.connect(DB_PATH, timeout=30, check_same_thread=False)
    conn.row_factory = sqlite3.Row
    try:
        conn.execute("PRAGMA journal_mode=WAL")
        conn.execute("PRAGMA synchronous=NORMAL")
        conn.execute("PRAGMA busy_timeout=30000")
    except Exception:
        pass
    try:
        yield conn
    finally:
        conn.close()


def user_state_set(user_id, state):
    user_states[user_id] = state
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("""INSERT OR REPLACE INTO user_states_db (user_id, state_json, updated_at)
                             VALUES (?, ?, ?)""",
                          (user_id, json.dumps(state, ensure_ascii=False, default=str), db_now()))
                conn.commit()
    except Exception as e:
        print("⚠️ user_state_set: " + str(e))


def user_state_get(user_id):
    if user_id in user_states:
        return user_states[user_id]
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT state_json FROM user_states_db WHERE user_id = ?", (user_id,))
                r = c.fetchone()
                if r and r["state_json"]:
                    state = json.loads(r["state_json"])
                    user_states[user_id] = state
                    return state
    except Exception:
        pass
    return None


def user_state_pop(user_id):
    user_states.pop(user_id, None)
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("DELETE FROM user_states_db WHERE user_id = ?", (user_id,))
                conn.commit()
    except Exception:
        pass


