# ============================================================

def get_balance(user_id):
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT balance FROM users WHERE user_id = ?", (user_id,))
                r = c.fetchone()
                if not r:
                    return 0
                return big_load(r["balance"])
    except Exception as e:
        print("⚠️ get_balance: " + str(e))
        return 0


def save_balance(user_id, amount):
    try:
        v = int(amount)
    except Exception:
        return False
    if v < 0:
        v = 0
    if v > MAX_BALANCE:
        v = MAX_BALANCE
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("UPDATE users SET balance = ? WHERE user_id = ?",
                          (big_normalize(v), user_id))
                if c.rowcount == 0:
                    conn.rollback()
                    return False
                conn.commit()
        return True
    except Exception as e:
        print("⚠️ save_balance: " + str(e))
        return False


def add_balance(user_id, amount):
    with DB_LOCK:
        try:
            amt = int(amount)
        except Exception:
            return False, 0, "❌ Неверная сумма"
        if amt < 0:
            return sub_balance(user_id, -amt)
        cur = get_balance(user_id)
        if amt == 0:
            return True, cur, ""
        new_val = cur + amt
        if new_val > MAX_BALANCE:
            return False, cur, "❌ Достигнут максимум баланса (10^100)"
        if not save_balance(user_id, new_val):
            return False, cur, "❌ Ошибка сохранения баланса"
        return True, new_val, ""


def sub_balance(user_id, amount):
    with DB_LOCK:
        try:
            amt = int(amount)
        except Exception:
            return False, 0, "❌ Неверная сумма"
        if amt < 0:
            return add_balance(user_id, -amt)
        cur = get_balance(user_id)
        if amt == 0:
            return True, cur, ""
        if cur < amt:
            return False, cur, "❌ Недостаточно поинтов: " + format(cur)
        new_val = cur - amt
        if not save_balance(user_id, new_val):
            return False, cur, "❌ Ошибка сохранения баланса"
        return True, new_val, ""


def reset_balance(user_id, amount=15_000_000):
    return save_balance(user_id, amount)


