def get_user_titles(user_id):
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT title_key, custom_text FROM titles WHERE user_id = ? ORDER BY awarded_at ASC, id ASC", (user_id,))
                rows = c.fetchall()
        result = []
        for r in rows:
            key = r["title_key"]
            if key.startswith("custom_"):
                custom_name = r["custom_text"] or key.replace("custom_", "")
                result.append({"key": key, "name": "✨ " + esc(custom_name), "condition": "Выдан админом/крафтом", "custom": True})
            elif key in TITLES:
                t = TITLES[key]
                result.append({"key": key, "name": t["name"], "condition": t["condition"], "custom": False})
        return result
    except Exception:
        return []


