# ========== 🏛 КАЗНА ==========
def get_treasury(chat_id):
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT balance FROM treasury WHERE chat_id = ?", (chat_id,))
                r = c.fetchone()
                return big_load(r["balance"]) if r else 0
    except Exception:
        return 0


def _save_treasury(chat_id, amount):
    try:
        v = int(amount)
    except Exception:
        return False
    if v < 0:
        v = 0
    if v > MAX_BALANCE:
        v = MAX_BALANCE
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("INSERT OR IGNORE INTO treasury (chat_id, balance) VALUES (?, ?)",
                          (chat_id, big_normalize(0)))
                c.execute("UPDATE treasury SET balance = ?, last_updated = ? WHERE chat_id = ?",
                          (big_normalize(v), db_now(), chat_id))
                conn.commit()
        return True
    except Exception as e:
        print("⚠️ _save_treasury: " + str(e))
        return False


def donate_to_treasury(chat_id, user_id, amount):
    if amount < 500_000:
        return False, "❌ Минимум 500,000!"
    ok, new_bal, reason = sub_balance(user_id, amount)
    if not ok:
        return False, reason
    cur_t = get_treasury(chat_id)
    new_t = cur_t + amount
    if new_t > MAX_BALANCE:
        new_t = MAX_BALANCE
    if not _save_treasury(chat_id, new_t):
        add_balance(user_id, amount)
        return False, "❌ Ошибка казны"
    add_transaction(user_id, -amount, "treasury_donation", "treasury", "Пожертвование")
    return True, "🙏 Спасибо! +" + format(amount) + "\n💎 Поинты: " + format(new_bal)


def treasury_withdraw(chat_id, user_id, amount, reason):
    cur_t = get_treasury(chat_id)
    if cur_t < amount:
        return False, "❌ Мало в казне! Сейчас: " + format(cur_t)
    ok, new_bal, r = add_balance(user_id, amount)
    if not ok:
        return False, r
    _save_treasury(chat_id, cur_t - amount)
    add_transaction(user_id, amount, "treasury_withdraw", "treasury", reason)
    return True, "✅ Выдано " + format(amount)


