# ⚔️ ДУЭЛИ
# ============================================================
def create_duel(challenger_id, opponent_id, amount, chat_id=None):
    if challenger_id == opponent_id:
        return False, "❌ Себя нельзя!"
    balance = get_balance(challenger_id)
    if amount > balance:
        return False, "❌ Баланс: " + format(balance)
    try:
        with DUEL_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT id FROM duels WHERE (challenger IN (?, ?) OR opponent IN (?, ?)) AND status IN ('pending', 'processing')",
                          (challenger_id, opponent_id, challenger_id, opponent_id))
                if c.fetchone():
                    return False, "❌ У кого-то уже есть активная дуэль!"
                c.execute("INSERT INTO duels (challenger, opponent, amount) VALUES (?, ?, ?)",
                          (challenger_id, opponent_id, big_normalize(amount)))
                duel_id = c.lastrowid
                conn.commit()
            return True, duel_id
    except Exception as e:
        return False, "❌ " + str(e)


def accept_duel(duel_id, opponent_id, chat_id=None):
    tax_percent = get_tax_percent()
    if chat_id is None:
        chat_id = CHAT_ID
    try:
        with DUEL_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("UPDATE duels SET status = 'processing' WHERE id = ? AND status = 'pending'", (duel_id,))
                if c.rowcount == 0:
                    conn.rollback()
                    return False, "❌ Не найдена или уже принята!"
                c.execute("SELECT * FROM duels WHERE id = ?", (duel_id,))
                duel = c.fetchone()
                if duel["opponent"] != opponent_id:
                    conn.rollback()
                    return False, "❌ Не ваша!"
                if duel["challenger"] == opponent_id:
                    conn.rollback()
                    return False, "❌ Нельзя принять свою дуэль!"
                amount = big_load(duel["amount"])
                challenger = duel["challenger"]
                conn.commit()

        ch_bal = get_balance(challenger)
        op_bal = get_balance(opponent_id)
        if ch_bal < amount:
            with DB_LOCK:
                with _conn() as conn:
                    c = conn.cursor()
                    c.execute("UPDATE duels SET status = 'cancelled' WHERE id = ?", (duel_id,))
                    conn.commit()
            return False, "❌ У создателя недостаточно средств!"
        if op_bal < amount:
            with DB_LOCK:
                with _conn() as conn:
                    c = conn.cursor()
                    c.execute("UPDATE duels SET status = 'pending' WHERE id = ?", (duel_id,))
                    conn.commit()
            return False, "❌ Баланс: " + format(op_bal)

        ok1, _, r1 = sub_balance(challenger, amount)
        if not ok1:
            with DB_LOCK:
                with _conn() as conn:
                    c = conn.cursor()
                    c.execute("UPDATE duels SET status = 'cancelled' WHERE id = ?", (duel_id,))
                    conn.commit()
            return False, "❌ Ошибка списания у создателя: " + r1
        ok2, _, r2 = sub_balance(opponent_id, amount)
        if not ok2:
            add_balance(challenger, amount)
            with DB_LOCK:
                with _conn() as conn:
                    c = conn.cursor()
                    c.execute("UPDATE duels SET status = 'cancelled' WHERE id = ?", (duel_id,))
                    conn.commit()
            return False, "❌ Ошибка списания у соперника: " + r2

        winner = random.choice([challenger, opponent_id])
        total_pot = amount * 2
        tax = int(total_pot * tax_percent / 100)
        win_amount = total_pot - tax

        add_balance(winner, win_amount)

        add_transaction(challenger, -amount, "duel_bet", "duel", "Дуэль #" + str(duel_id))
        add_transaction(opponent_id, -amount, "duel_bet", "duel", "Дуэль #" + str(duel_id))
        add_transaction(winner, win_amount, "duel_win", "duel", "Дуэль #" + str(duel_id))

        if tax > 0:
            cur_t = get_treasury(chat_id)
            new_t = cur_t + tax
            if new_t > MAX_BALANCE:
                new_t = MAX_BALANCE
            _save_treasury(chat_id, new_t)
            add_transaction(0, tax, "duel_tax", "treasury", "Налог #" + str(duel_id))

        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("UPDATE duels SET status = 'finished', winner = ?, ended_at = ? WHERE id = ?",
                          (winner, db_now(), duel_id))
                conn.commit()

        return True, "⚔️ ДУЭЛЬ! Победитель: " + str(get_display_name(winner)) + "\n💰 Ставка: " + format(amount) + "\n💎 Выигрыш: " + format(win_amount) + "\n🏛️ Казне: +" + format(tax)
    except Exception as e:
        return False, "❌ " + str(e)


