def crypto_get_all():
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT * FROM crypto_coins")
                rows = {r["ticker"]: r for r in c.fetchall()}
        ordered = []
        for t in CRYPTO_ORDER:
            if t in rows:
                ordered.append(rows[t])
        for t, r in rows.items():
            if t not in CRYPTO_ORDER:
                ordered.append(r)
        return ordered
    except Exception as e:
        print("⚠️ crypto_get_all: " + str(e))
        return []


def crypto_get(ticker):
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT * FROM crypto_coins WHERE ticker = ?", (ticker,))
                return c.fetchone()
    except Exception:
        return None


def crypto_get_unit(ticker):
    return CRYPTO_UNIT_BTC if ticker == "BTC" else CRYPTO_UNIT_DEFAULT


def crypto_format_amount(ticker, amount_units):
    try:
        amount_units = int(amount_units)
    except Exception:
        amount_units = 0
    if ticker == "BTC":
        whole = amount_units // CRYPTO_UNIT_BTC
        frac = amount_units % CRYPTO_UNIT_BTC
        if frac == 0:
            return str(whole)
        s = f"{whole}.{frac:06d}".rstrip("0").rstrip(".")
        return s if s else "0"
    return str(amount_units)


def crypto_parse_amount(ticker, raw_text):
    txt = (raw_text or "").strip().replace(",", ".").replace(" ", "")
    if not txt:
        return False, 0, "❌ Пусто!"
    if ticker == "BTC":
        m = re.fullmatch(r"(\d+)(?:\.(\d{1,6}))?", txt)
        if not m:
            return False, 0, "❌ Для BTC число с до 6 знаками (пример: 1.25)"
        whole = int(m.group(1))
        frac_str = (m.group(2) or "").ljust(6, "0")
        frac = int(frac_str) if frac_str else 0
        units = whole * CRYPTO_UNIT_BTC + frac
        if units <= 0:
            return False, 0, "❌ Больше 0!"
        return True, units, ""
    else:
        if not re.fullmatch(r"\d+", txt):
            return False, 0, "❌ Только целое число штук!"
        units = int(txt)
        if units <= 0:
            return False, 0, "❌ Больше 0!"
        return True, units, ""


def crypto_update_prices():
    updated = []
    try:
        now = datetime.now()
        with CRYPTO_LOCK:
            with DB_LOCK:
                with _conn() as conn:
                    c = conn.cursor()
                    c.execute("SELECT * FROM crypto_coins")
                    rows = c.fetchall()
                    for r in rows:
                        last = db_parse(r["last_update"]) if r["last_update"] else None
                        interval = r["interval_sec"] or 300
                        if last and (now - last).total_seconds() < interval:
                            continue
                        min_p = big_load(r["min_price"])
                        max_p = big_load(r["max_price"])
                        if max_p <= min_p:
                            continue
                        new_price = random.randint(min_p, max_p)
                        old_price = big_load(r["price"])
                        c.execute("""UPDATE crypto_coins
                                     SET prev_price = ?,
                                         price = ?,
                                         last_update = ?,
                                         update_count = COALESCE(update_count, 0) + 1
                                     WHERE ticker = ?""",
                                  (big_normalize(old_price),
                                   big_normalize(new_price),
                                   db_now(),
                                   r["ticker"]))
                        updated.append(r["ticker"])
                    conn.commit()
    except Exception as e:
        print("⚠️ crypto_update_prices: " + str(e))
    return updated


def crypto_get_position(user_id, ticker):
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("""SELECT amount, total_spent, total_earned
                             FROM crypto_portfolio WHERE user_id = ? AND ticker = ?""",
                          (user_id, ticker))
                r = c.fetchone()
                if not r:
                    return {"amount": 0, "total_spent": 0, "total_earned": 0}
                return {
                    "amount": big_load(r["amount"]),
                    "total_spent": big_load(r["total_spent"]),
                    "total_earned": big_load(r["total_earned"]),
                }
    except Exception:
        return {"amount": 0, "total_spent": 0, "total_earned": 0}


def crypto_get_portfolio(user_id):
    result = []
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("""SELECT ticker, amount, total_spent, total_earned
                             FROM crypto_portfolio WHERE user_id = ?""", (user_id,))
                rows = {r["ticker"]: r for r in c.fetchall()}
        for ticker in CRYPTO_ORDER:
            if ticker not in rows:
                continue
            r = rows[ticker]
            amt = big_load(r["amount"])
            if amt <= 0:
                continue
            coin = crypto_get(ticker)
            if not coin:
                continue
            price = big_load(coin["price"])
            unit = crypto_get_unit(ticker)
            if unit == 1:
                cur_value = price * amt
            else:
                cur_value = (price * amt) // unit
            result.append({
                "ticker": ticker,
                "name": coin["name"],
                "emoji": coin["emoji"],
                "amount": amt,
                "amount_str": crypto_format_amount(ticker, amt),
                "price": price,
                "cur_value": cur_value,
                "total_spent": big_load(r["total_spent"]),
                "total_earned": big_load(r["total_earned"]),
            })
    except Exception as e:
        print("⚠️ crypto_get_portfolio: " + str(e))
    return result


def crypto_get_total_value(user_id):
    total = 0
    for p in crypto_get_portfolio(user_id):
        total += p["cur_value"]
    return total


def crypto_buy(user_id, ticker, amount_units):
    coin = crypto_get(ticker)
    if not coin:
        return False, "❌ Валюта не найдена!", get_balance(user_id)
    if amount_units <= 0:
        return False, "❌ Количество > 0!", get_balance(user_id)
    price = big_load(coin["price"])
    unit = crypto_get_unit(ticker)
    if unit == 1:
        total = price * amount_units
    else:
        total = (price * amount_units) // unit
    if total <= 0:
        return False, "❌ Слишком маленькая сумма сделки!", get_balance(user_id)

    bal = get_balance(user_id)
    if bal < total:
        if unit == 1:
            can_buy = bal // price if price > 0 else 0
        else:
            can_buy = (bal * unit) // price if price > 0 else 0
        can_str = crypto_format_amount(ticker, can_buy)
        return False, ("❌ Недостаточно поинтов!\n"
                       "Нужно: " + format(total) + "\n"
                       "У тебя: " + format(bal) + "\n"
                       "Можешь купить только " + can_str + " " + ticker), bal

    ok, new_bal, reason = sub_balance(user_id, total)
    if not ok:
        return False, reason, bal

    try:
        with CRYPTO_LOCK:
            with DB_LOCK:
                with _conn() as conn:
                    c = conn.cursor()
                    c.execute("""SELECT amount, total_spent FROM crypto_portfolio
                                 WHERE user_id = ? AND ticker = ?""", (user_id, ticker))
                    r = c.fetchone()
                    if r:
                        old_amt = big_load(r["amount"])
                        new_amt = old_amt + amount_units
                        old_spent = big_load(r["total_spent"])
                        new_spent = old_spent + total
                        if new_spent > MAX_BALANCE:
                            new_spent = MAX_BALANCE
                        c.execute("""UPDATE crypto_portfolio
                                     SET amount = ?, total_spent = ?
                                     WHERE user_id = ? AND ticker = ?""",
                                  (big_normalize(new_amt), big_normalize(new_spent),
                                   user_id, ticker))
                    else:
                        c.execute("""INSERT INTO crypto_portfolio
                                     (user_id, ticker, amount, total_spent, total_earned)
                                     VALUES (?, ?, ?, ?, ?)""",
                                  (user_id, ticker, big_normalize(amount_units),
                                   big_normalize(total), big_normalize(0)))
                    c.execute("""INSERT INTO crypto_history
                                 (user_id, ticker, action, amount, price, total)
                                 VALUES (?, ?, 'buy', ?, ?, ?)""",
                              (user_id, ticker, big_normalize(amount_units),
                               big_normalize(price), big_normalize(total)))
                    conn.commit()
    except Exception as e:
        add_balance(user_id, total)
        return False, "❌ Ошибка БД: " + str(e), bal

    add_transaction(user_id, -total, "crypto_buy", "crypto",
                    "Куплено " + crypto_format_amount(ticker, amount_units) + " " + ticker)
    amt_str = crypto_format_amount(ticker, amount_units)
    msg = ("✅ КУПЛЕНО!\n\n"
           + coin["emoji"] + " " + amt_str + " " + ticker + "\n"
           "💵 Цена: " + format(price) + "\n"
           "💰 Итого: −" + format(total) + "\n"
           "💎 Поинты: " + format(new_bal))
    return True, msg, new_bal


def crypto_sell(user_id, ticker, amount_units):
    coin = crypto_get(ticker)
    if not coin:
        return False, "❌ Валюта не найдена!", get_balance(user_id)
    if amount_units <= 0:
        return False, "❌ Количество > 0!", get_balance(user_id)

    pos = crypto_get_position(user_id, ticker)
    if pos["amount"] < amount_units:
        have_str = crypto_format_amount(ticker, pos["amount"])
        return False, ("❌ Недостаточно " + ticker + "!\n"
                       "У тебя: " + have_str + " " + ticker), get_balance(user_id)

    price = big_load(coin["price"])
    unit = crypto_get_unit(ticker)
    if unit == 1:
        total = price * amount_units
    else:
        total = (price * amount_units) // unit

    if total <= 0:
        return False, "❌ Слишком маленькая сумма сделки!", get_balance(user_id)

    old_amt = 0
    old_earned = 0
    try:
        with CRYPTO_LOCK:
            with DB_LOCK:
                with _conn() as conn:
                    c = conn.cursor()
                    c.execute("""SELECT amount, total_earned FROM crypto_portfolio
                                 WHERE user_id = ? AND ticker = ?""", (user_id, ticker))
                    r = c.fetchone()
                    if not r:
                        return False, "❌ Ошибка портфеля!", get_balance(user_id)
                    old_amt = big_load(r["amount"])
                    if old_amt < amount_units:
                        return False, "❌ Ошибка портфеля!", get_balance(user_id)
                    new_amt = old_amt - amount_units
                    old_earned = big_load(r["total_earned"])
                    new_earned = old_earned + total
                    if new_earned > MAX_BALANCE:
                        new_earned = MAX_BALANCE
                    c.execute("""UPDATE crypto_portfolio
                                 SET amount = ?, total_earned = ?
                                 WHERE user_id = ? AND ticker = ?""",
                              (big_normalize(new_amt), big_normalize(new_earned),
                               user_id, ticker))
                    c.execute("""INSERT INTO crypto_history
                                 (user_id, ticker, action, amount, price, total)
                                 VALUES (?, ?, 'sell', ?, ?, ?)""",
                              (user_id, ticker, big_normalize(amount_units),
                               big_normalize(price), big_normalize(total)))
                    conn.commit()
    except Exception as e:
        return False, "❌ Ошибка БД: " + str(e), get_balance(user_id)

    ok, new_bal, reason = add_balance(user_id, total)
    if not ok:
        try:
            with DB_LOCK:
                with _conn() as conn:
                    c = conn.cursor()
                    c.execute("""UPDATE crypto_portfolio
                                 SET amount = ?, total_earned = ?
                                 WHERE user_id = ? AND ticker = ?""",
                              (big_normalize(old_amt), big_normalize(old_earned),
                               user_id, ticker))
                    conn.commit()
        except Exception:
            pass
        return False, reason, get_balance(user_id)

    add_transaction(user_id, total, "crypto_sell", "crypto",
                    "Продано " + crypto_format_amount(ticker, amount_units) + " " + ticker)
    amt_str = crypto_format_amount(ticker, amount_units)
    msg = ("✅ ПРОДАНО!\n\n"
           + coin["emoji"] + " " + amt_str + " " + ticker + "\n"
           "💵 Цена: " + format(price) + "\n"
           "💰 Итого: +" + format(total) + "\n"
           "💎 Поинты: " + format(new_bal))
    return True, msg, new_bal


def crypto_get_top(limit=10):
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("""SELECT user_id, total_spent, total_earned
                             FROM crypto_portfolio""")
                rows = c.fetchall()
        by_user = {}
        for r in rows:
            uid = r["user_id"]
            spent = big_load(r["total_spent"])
            earned = big_load(r["total_earned"])
            if uid not in by_user:
                by_user[uid] = {"profit": 0, "earned": 0, "spent": 0}
            by_user[uid]["profit"] += (earned - spent)
            by_user[uid]["earned"] += earned
            by_user[uid]["spent"] += spent
        sorted_users = sorted(by_user.items(), key=lambda x: x[1]["profit"], reverse=True)[:limit]
        return [(uid, d["profit"], d["earned"], d["spent"]) for uid, d in sorted_users]
    except Exception as e:
        print("⚠️ crypto_get_top: " + str(e))
        return []


def crypto_get_history(user_id, limit=20):
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("""SELECT ticker, action, amount, price, total, timestamp
                             FROM crypto_history
                             WHERE user_id = ?
                             ORDER BY id DESC LIMIT ?""",
                          (user_id, limit))
                rows = c.fetchall()
        result = []
        for r in rows:
            result.append({
                "ticker": r["ticker"],
                "action": r["action"],
                "amount": big_load(r["amount"]),
                "price": big_load(r["price"]),
                "total": big_load(r["total"]),
                "timestamp": r["timestamp"],
            })
        return result
    except Exception:
        return []


