def get_staff_role(user_id):
    try:
        if int(user_id) == BOSS_ADMIN_ID:
            return ROLE_ADMIN_7
        if int(user_id) == ADMIN_ID:
            return ROLE_ADMIN_7
    except Exception:
        pass
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT role FROM staff_roles WHERE user_id = ?", (int(user_id),))
                r = c.fetchone()
                if r and r["role"]:
                    return r["role"]
    except Exception as e:
        print("⚠️ get_staff_role: " + str(e))
    return None


def get_role_label(role):
    if not role:
        return "👤 Игрок"
    return ROLE_LABELS.get(role, role)


def get_role_level(role):
    if not role:
        return -1
    return ROLE_LEVELS.get(role, -1)


def is_owner(user_id):
    return get_role_level(get_staff_role(user_id)) >= 7


def is_staff(user_id):
    return get_staff_role(user_id) is not None


def is_helper(user_id):
    return get_staff_role(user_id) == ROLE_HELPER


def is_admin_level(user_id, min_level):
    lvl = get_role_level(get_staff_role(user_id))
    return lvl >= min_level


def is_admin_any(user_id):
    return get_role_level(get_staff_role(user_id)) >= 1


def can_modify_role(actor_id, target_id):
    if int(target_id) == BOSS_ADMIN_ID:
        return False, "❌ BOSS_ADMIN_ID защищён от изменения роли"
    if int(target_id) == ADMIN_ID and int(actor_id) != BOSS_ADMIN_ID:
        return False, "❌ ADMIN_ID защищён"
    actor_role = get_staff_role(actor_id)
    target_role = get_staff_role(target_id)
    actor_lvl = get_role_level(actor_role)
    target_lvl = get_role_level(target_role)
    if actor_lvl < 1:
        return False, "❌ У тебя нет админ-прав"
    if actor_lvl >= 7:
        return True, ""
    if target_role == ROLE_HELPER:
        if actor_lvl >= 6:
            return True, ""
        return False, "❌ Только ур. 6+ может трогать хелперов"
    if actor_lvl > target_lvl:
        return True, ""
    if actor_lvl == target_lvl:
        return False, "❌ Нельзя трогать равных по уровню"
    return False, "❌ Нельзя трогать тех, кто выше тебя"


def set_staff_role(user_id, role, added_by=0):
    if int(user_id) == BOSS_ADMIN_ID:
        return False, "❌ BOSS_ADMIN_ID нельзя менять (хардкод)"
    if int(user_id) == ADMIN_ID:
        return False, "❌ ADMIN_ID нельзя менять (env)"
    if role not in ROLE_LABELS:
        return False, "❌ Неизвестная роль: " + str(role)
    try:
        with STAFF_LOCK:
            with DB_LOCK:
                with _conn() as conn:
                    c = conn.cursor()
                    c.execute("""INSERT OR REPLACE INTO staff_roles
                                 (user_id, role, added_by, added_at)
                                 VALUES (?, ?, ?, ?)""",
                              (int(user_id), role, int(added_by), db_now()))
                    conn.commit()
        staff_log_write(added_by, "role_set", user_id,
                        "Роль: " + str(role) + " (" + get_role_label(role) + ")")
        return True, "✅ " + str(user_id) + " → " + get_role_label(role)
    except Exception as e:
        return False, "❌ " + str(e)


def remove_staff_role(user_id, removed_by=0):
    if int(user_id) == BOSS_ADMIN_ID:
        return False, "❌ BOSS_ADMIN_ID нельзя снять (хардкод)"
    if int(user_id) == ADMIN_ID:
        return False, "❌ ADMIN_ID нельзя снять (env)"
    try:
        with STAFF_LOCK:
            with DB_LOCK:
                with _conn() as conn:
                    c = conn.cursor()
                    c.execute("SELECT role FROM staff_roles WHERE user_id = ?", (int(user_id),))
                    r = c.fetchone()
                    old_role = r["role"] if r else None
                    c.execute("DELETE FROM staff_roles WHERE user_id = ?", (int(user_id),))
                    a = c.rowcount
                    conn.commit()
        if a > 0:
            staff_log_write(removed_by, "role_remove", user_id,
                            "Была роль: " + str(old_role))
            return True, "✅ Роль снята с " + str(user_id)
        return False, "❌ У него не было роли в staff_roles."
    except Exception as e:
        return False, "❌ " + str(e)


