def help_create_question(user_id, username, question):
    question = (question or "").strip()
    if not question:
        return False, "❌ Пустой вопрос!"
    if len(question) > HELP_MAX_QUESTION_LEN:
        question = question[:HELP_MAX_QUESTION_LEN]
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("""SELECT id, created_at FROM help_questions
                             WHERE user_id = ? AND status IN ('open','taken')
                             ORDER BY id DESC LIMIT 1""", (user_id,))
                active = c.fetchone()
                if active:
                    c.execute("""UPDATE help_questions SET status = 'cancelled_by_user'
                                 WHERE id = ?""", (active["id"],))
                c.execute("""SELECT created_at FROM help_questions
                             WHERE user_id = ?
                             ORDER BY id DESC LIMIT 1""", (user_id,))
                last = c.fetchone()
                if last and last["created_at"]:
                    dt = db_parse(last["created_at"])
                    if dt and (datetime.now() - dt).total_seconds() < HELP_QUESTION_COOLDOWN:
                        left = int(HELP_QUESTION_COOLDOWN - (datetime.now() - dt).total_seconds())
                        conn.commit()
                        return False, "⏰ Подожди " + str(left) + " сек."
                c.execute("""INSERT INTO help_questions (user_id, username, question, status)
                             VALUES (?, ?, ?, 'open')""",
                          (user_id, username or "", question))
                qid = c.lastrowid
                conn.commit()
        return True, qid
    except Exception as e:
        return False, "❌ " + str(e)


def help_take_question(qid, helper_id):
    try:
        with HELP_LOCK:
            with DB_LOCK:
                with _conn() as conn:
                    c = conn.cursor()
                    c.execute("""UPDATE help_questions
                                 SET status = 'taken',
                                     helper_id = ?,
                                     taken_at = ?
                                 WHERE id = ? AND status = 'open'""",
                              (helper_id, db_now(), qid))
                    if c.rowcount == 0:
                        conn.rollback()
                        return False, "❌ Вопрос уже взят или закрыт!"
                    conn.commit()
        helper_stats_inc(helper_id, "taken", 1)
        staff_log_write(helper_id, "help_take", 0, "Вопрос #" + str(qid))
        return True, "✅ Вопрос #" + str(qid) + " взят"
    except Exception as e:
        return False, "❌ " + str(e)


def help_answer_question(qid, helper_id, answer):
    answer = (answer or "").strip()
    if not answer:
        return False, "❌ Пустой ответ!"
    if len(answer) > HELP_MAX_ANSWER_LEN:
        answer = answer[:HELP_MAX_ANSWER_LEN]
    try:
        with HELP_LOCK:
            with DB_LOCK:
                with _conn() as conn:
                    c = conn.cursor()
                    c.execute("""SELECT user_id, taken_at FROM help_questions
                                 WHERE id = ? AND helper_id = ? AND status = 'taken'""",
                              (qid, helper_id))
                    row = c.fetchone()
                    if not row:
                        return False, "❌ Вопрос не твой или не в статусе 'taken'!"
                    c.execute("""UPDATE help_questions
                                 SET status = 'answered',
                                     answer = ?,
                                     answered_at = ?
                                 WHERE id = ?""",
                              (answer, db_now(), qid))
                    conn.commit()
                    user_id = row["user_id"]
                    taken_at = row["taken_at"]
        helper_stats_inc(helper_id, "answered", 1)
        if taken_at:
            dt = db_parse(taken_at)
            if dt:
                resp = int((datetime.now() - dt).total_seconds())
                if resp > 0:
                    helper_stats_add_response(helper_id, resp)
        staff_log_write(helper_id, "help_answer", user_id, "Вопрос #" + str(qid))
        return True, {"user_id": user_id, "answer": answer}
    except Exception as e:
        return False, "❌ " + str(e)


def help_cancel_question(qid, helper_id):
    try:
        with HELP_LOCK:
            with DB_LOCK:
                with _conn() as conn:
                    c = conn.cursor()
                    c.execute("""SELECT user_id FROM help_questions
                                 WHERE id = ? AND helper_id = ? AND status = 'taken'""",
                              (qid, helper_id))
                    row = c.fetchone()
                    if not row:
                        return False, "❌ Вопрос не твой или не в статусе 'taken'!"
                    c.execute("""UPDATE help_questions
                                 SET status = 'cancelled',
                                     answered_at = ?
                                 WHERE id = ?""",
                              (db_now(), qid))
                    conn.commit()
                    user_id = row["user_id"]
        helper_stats_inc(helper_id, "cancelled", 1)
        staff_log_write(helper_id, "help_cancel", user_id, "Вопрос #" + str(qid))
        return True, {"user_id": user_id}
    except Exception as e:
        return False, "❌ " + str(e)


def help_expire_old():
    expired = []
    try:
        now = datetime.now()
        with HELP_LOCK:
            with DB_LOCK:
                with _conn() as conn:
                    c = conn.cursor()
                    c.execute("""SELECT id, helper_id, taken_at FROM help_questions
                                 WHERE status = 'taken'""")
                    for r in c.fetchall():
                        taken = db_parse(r["taken_at"]) if r["taken_at"] else None
                        if taken and (now - taken).total_seconds() > HELP_TAKEOVER_TIMEOUT:
                            c.execute("""UPDATE help_questions
                                         SET status = 'open',
                                             helper_id = 0,
                                             taken_at = NULL
                                         WHERE id = ? AND status = 'taken'""",
                                      (r["id"],))
                            if c.rowcount > 0:
                                expired.append({"qid": r["id"], "helper_id": r["helper_id"]})
                    conn.commit()
        for e in expired:
            staff_log_write(0, "help_expire", e["helper_id"],
                            "Вопрос #" + str(e["qid"]) + " вернулся в очередь")
    except Exception as e:
        print("⚠️ help_expire_old: " + str(e))
    return expired


