def helper_stats_inc(helper_id, field, delta=1):
    if field not in ("answered", "cancelled", "taken"):
        return False
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("INSERT OR IGNORE INTO help_stats (helper_id) VALUES (?)", (helper_id,))
                c.execute("UPDATE help_stats SET " + field + " = " + field + " + ? WHERE helper_id = ?",
                          (int(delta), helper_id))
                conn.commit()
        return True
    except Exception:
        return False


def helper_stats_add_response(helper_id, seconds):
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("INSERT OR IGNORE INTO help_stats (helper_id) VALUES (?)", (helper_id,))
                c.execute("""UPDATE help_stats
                             SET total_response_sec = total_response_sec + ?
                             WHERE helper_id = ?""",
                          (int(seconds), helper_id))
                conn.commit()
        return True
    except Exception:
        return False


def helper_stats_get(helper_id):
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("""SELECT answered, cancelled, taken, total_response_sec, first_seen
                             FROM help_stats WHERE helper_id = ?""", (helper_id,))
                r = c.fetchone()
                if not r:
                    return {
                        "answered": 0, "cancelled": 0, "taken": 0,
                        "total_response_sec": 0, "first_seen": None,
                        "avg_response_sec": 0,
                    }
                answered = r["answered"] or 0
                total_resp = r["total_response_sec"] or 0
                avg = int(total_resp / answered) if answered > 0 else 0
                return {
                    "answered": answered,
                    "cancelled": r["cancelled"] or 0,
                    "taken": r["taken"] or 0,
                    "total_response_sec": total_resp,
                    "first_seen": r["first_seen"],
                    "avg_response_sec": avg,
                }
    except Exception:
        return {"answered": 0, "cancelled": 0, "taken": 0,
                "total_response_sec": 0, "first_seen": None, "avg_response_sec": 0}


