def title_give_check_cooldown(admin_id):
    lvl = get_role_level(get_staff_role(admin_id))
    if lvl >= 5:
        return True, ""
    if lvl < 2:
        return False, "❌ Нужен ур. 2+"
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT last_give FROM title_give_log WHERE admin_id = ?", (admin_id,))
                r = c.fetchone()
                if r and r["last_give"]:
                    dt = db_parse(r["last_give"])
                    if dt:
                        diff = (datetime.now() - dt).total_seconds()
                        if diff < TITLE_ADMIN2_COOLDOWN:
                            left = int(TITLE_ADMIN2_COOLDOWN - diff)
                            h = left // 3600
                            m = (left % 3600) // 60
                            return False, "⏰ Ур. 2-4: лимит 1 титул / 2 дня.\nОсталось: " + str(h) + "ч " + str(m) + "м"
    except Exception as e:
        print("⚠️ title_give_check_cooldown: " + str(e))
    return True, ""


