def title_give_validate_text(admin_id, text):
    lvl = get_role_level(get_staff_role(admin_id))
    text = (text or "").strip()
    if not text:
        return False, "❌ Пустой текст!"
    if lvl < 5:
        if len(text) > TITLE_ADMIN2_MAX_LEN:
            return False, "❌ Ур. 2-4: макс. " + str(TITLE_ADMIN2_MAX_LEN) + " символов.\nУ тебя: " + str(len(text))
    else:
        if len(text) > 50:
            return False, "❌ Максимум 50 символов."
    return True, ""


