def mafia_set_max(percent, admin_id):
    if admin_id != ADMIN_ID:
        return False, "❌ Только владелец может менять лимит"
    if percent < 0 or percent > 100:
        return False, "❌ 0-100"
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("UPDATE mafia_settings SET max_percent = ? WHERE id = 1", (percent,))
                conn.commit()
        return True, "✅ Лимит мафии: " + str(percent) + "%"
    except Exception as e:
        return False, "❌ " + str(e)


def mafia_set_current(percent, user_id):
    biz = biz_get("mafia")
    if not biz or biz["owner_id"] != user_id:
        return False, "❌ Ты не владелец мафии!"
    s = mafia_get_settings()
    if percent < 0 or percent > s["max"]:
        return False, "❌ 0-" + str(s["max"]) + "% (лимит владельца)"
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("UPDATE mafia_settings SET current_percent = ? WHERE id = 1", (percent,))
                conn.commit()
        return True, "✅ Мафия теперь берёт " + str(percent) + "%"
    except Exception as e:
        return False, "❌ " + str(e)


def mafia_collect():
    """✅ BIG-INT: biz.balance — TEXT, читаем через big_load, пишем big_normalize."""
    s = mafia_get_settings()
    pct = s["current"] or 0
    if pct <= 0:
        return
    mafia = biz_get("mafia")
    if not mafia or not mafia["owner_id"]:
        return
    mafia_owner = mafia["owner_id"]
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                total_taken = 0
                for bt in ["apteka1", "apteka2", "apteka3", "bolnitsa1", "bolnitsa2", "banda", "sud1", "sud2", "advokat"]:
                    c.execute("SELECT * FROM biz_businesses WHERE biz_type = ?", (bt,))
                    b = c.fetchone()
                    if not b:
                        continue
                    if b["status"] != "owned":
                        continue
                    bal = big_load(b["balance"])
                    if bal <= 0:
                        continue
                    take = int(bal * pct / 100)
                    if take <= 0:
                        continue
                    new_bal = bal - take
                    c.execute("UPDATE biz_businesses SET balance = ? WHERE biz_type = ?",
                              (big_normalize(new_bal), bt))
                    # Добавляем мафии
                    mafia_bal = big_load(mafia["balance"])
                    new_mafia = mafia_bal + take
                    if new_mafia > MAX_BALANCE:
                        new_mafia = MAX_BALANCE
                    c.execute("UPDATE biz_businesses SET balance = ? WHERE biz_type = 'mafia'",
                              (big_normalize(new_mafia),))
                    total_taken += take
                    owner_b = b["owner_id"]
                    if owner_b:
                        try:
                            send_message(owner_b,
                                         "🎩 Мафия взяла " + str(pct) + "% с твоего бизнеса\n−" + format(take))
                        except Exception:
                            pass
                c.execute("UPDATE mafia_settings SET last_collect = ? WHERE id = 1", (db_now(),))
                conn.commit()
        if total_taken > 0:
            try:
                send_message(mafia_owner,
                             "🎩 МАФИЯ СОБРАЛА ДАНЬ\n\n💰 Всего: " + format(total_taken) +
                             "\n📊 Ставка: " + str(pct) + "%")
            except Exception:
                pass
    except Exception as e:
        print("⚠️ mafia_collect: " + str(e))


