def biz_get_upgrade_mult(biz_type):
    if biz_type not in BIZ_UPGRADE_ALLOWED:
        return 1.0
    b = biz_get(biz_type)
    if not b:
        return 1.0
    try:
        lvl = b["upgrade_level"] or 0
    except Exception:
        lvl = 0
    return BIZ_UPGRADE_MULT if lvl >= 1 else 1.0


def biz_upgrade(biz_type, user_id):
    """✅ BIG-INT: апгрейд через sub_balance."""
    if biz_type not in BIZ_UPGRADE_ALLOWED:
        return False, "❌ Этот бизнес нельзя апгрейдить!"
    b = biz_get(biz_type)
    if not b:
        return False, "❌ Бизнес не найден!"
    if b["owner_id"] != user_id:
        return False, "❌ Ты не владелец!"
    lvl = b["upgrade_level"] or 0
    if lvl >= 1:
        return False, "❌ Уже апгрейжен!"

    ok, new_bal, reason = sub_balance(user_id, BIZ_UPGRADE_COST)
    if not ok:
        return False, "❌ Нужно " + format(BIZ_UPGRADE_COST) + "\n" + reason

    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("UPDATE biz_businesses SET upgrade_level = 1 WHERE biz_type = ?", (biz_type,))
                c.execute("""INSERT INTO biz_upgrades (biz_type, user_id, amount)
                             VALUES (?, ?, ?)""",
                          (biz_type, user_id, big_normalize(BIZ_UPGRADE_COST)))
                c.execute("""INSERT INTO transactions (user_id, amount, type, game, details)
                             VALUES (?, ?, ?, ?, ?)""",
                          (user_id, big_normalize(-BIZ_UPGRADE_COST), "biz_upgrade", "business",
                           "Апгрейд " + str(b["name"])))
                conn.commit()
    except Exception as e:
        add_balance(user_id, BIZ_UPGRADE_COST)
        return False, "❌ " + str(e)

    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT COUNT(*) as cnt FROM biz_upgrades WHERE user_id = ?", (user_id,))
                cnt = c.fetchone()["cnt"]
        if cnt >= 3 and not user_has_title(user_id, "upgrade_master"):
            award_title(user_id, "upgrade_master")
    except Exception:
        pass
    return True, ("✅ АПГРЕЙД КУПЛЕН!\n\n"
                  "🏢 " + str(b["name"]) + "\n"
                  "💰 −" + format(BIZ_UPGRADE_COST) + "\n"
                  "📈 Доход: x" + str(BIZ_UPGRADE_MULT))


def biz_stats_add(biz_type, amount):
    """✅ BIG-INT: biz_daily_stats.income → TEXT.
    ON CONFLICT не работает на TEXT для суммы → SELECT + UPDATE."""
    if amount <= 0:
        return
    try:
        today = datetime.now().strftime("%Y-%m-%d")
        with BIZ_STATS_LOCK:
            with DB_LOCK:
                with _conn() as conn:
                    c = conn.cursor()
                    c.execute("SELECT income FROM biz_daily_stats WHERE biz_type = ? AND date = ?",
                              (biz_type, today))
                    r = c.fetchone()
                    if r:
                        old_income = big_load(r["income"])
                        new_income = old_income + amount
                        if new_income > MAX_BALANCE:
                            new_income = MAX_BALANCE
                        c.execute("""UPDATE biz_daily_stats SET income = ?
                                     WHERE biz_type = ? AND date = ?""",
                                  (big_normalize(new_income), biz_type, today))
                    else:
                        new_income = amount
                        if new_income > MAX_BALANCE:
                            new_income = MAX_BALANCE
                        c.execute("""INSERT INTO biz_daily_stats (biz_type, date, income)
                                     VALUES (?, ?, ?)""",
                                  (biz_type, today, big_normalize(new_income)))
                    conn.commit()
    except Exception as e:
        print("⚠️ biz_stats_add: " + str(e))


def biz_stats_get(biz_type, days=BIZ_STATS_DAYS):
    """✅ BIG-INT: income через big_load."""
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("""SELECT date, income FROM biz_daily_stats
                             WHERE biz_type = ?
                             ORDER BY date DESC LIMIT ?""",
                          (biz_type, days))
                return [(r["date"], big_load(r["income"])) for r in c.fetchall()]
    except Exception:
        return []


def biz_stats_cleanup_worker():
    while not scheduler_stop.is_set():
        try:
            cutoff = (datetime.now() - timedelta(days=BIZ_STATS_DAYS)).strftime("%Y-%m-%d")
            with BIZ_STATS_LOCK:
                with DB_LOCK:
                    with _conn() as conn:
                        c = conn.cursor()
                        c.execute("DELETE FROM biz_daily_stats WHERE date < ?", (cutoff,))
                        conn.commit()
        except Exception as e:
            print("⚠️ biz_stats_cleanup: " + str(e))
        time.sleep(3600)


