# ========== ЧАСТЬ 6/25: BIZ_SCHEDULER_TICK + ПРОМОКОДЫ + КЕЙСЫ + ЛОМБАРД + UI БИРЖИ ==========

def biz_scheduler_tick():
    global _biz_last_penalty_date
    pending_stats = []
    try:
        now = datetime.now()
        today_str = now.strftime("%Y-%m-%d")
        now_msk = moscow_now()
        is_midnight_msk = (now_msk.hour == 0 and now_msk.minute == 0)
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT * FROM biz_businesses WHERE status = 'auction'")
                active_auctions = c.fetchall()
                for biz in active_auctions:
                    if biz["biz_type"] in ("mafia", "league", "lombard"):
                        if biz["biz_type"] in ("mafia", "league"):
                            c.execute("""UPDATE biz_businesses
                                         SET status = 'owned', owner_id = ?, auction_end = NULL
                                         WHERE id = ?""", (BOSS_ADMIN_ID, biz["id"]))
                        continue
                    ends = db_parse(biz["auction_end"])
                    if ends and now >= ends:
                        if biz["current_bidder"]:
                            winner = biz["current_bidder"]
                            bet = big_load(biz["current_bet"])
                            seller = biz["seller_id"] if "seller_id" in biz.keys() else 0
                            c.execute("""UPDATE biz_businesses
                                         SET owner_id = ?, status = 'owned',
                                             auction_end = NULL, current_bet = ?,
                                             current_bidder = 0, seller_id = 0,
                                             upgrade_level = 0, craft_locked = 0,
                                             last_payment = ?
                                         WHERE id = ?""",
                                      (winner, big_normalize(0), db_now(), biz["id"]))
                            try:
                                c.execute("""DELETE FROM lombard_block
                                             WHERE biz_type = ? AND user_id != ?""",
                                          (biz["biz_type"], winner))
                            except Exception:
                                pass
                            if seller and seller > 0:
                                add_balance(seller, bet)
                            try:
                                send_message(winner, "🏆 ТЫ КУПИЛ БИЗНЕС!\n\n" + str(biz["name"]) + "\nЗаплатил: " + format(bet))
                                if biz["biz_type"] == "lombard":
                                    award_title(winner, "lombardier")
                            except Exception:
                                pass
                            if seller and seller > 0:
                                try:
                                    send_message(seller, "💰 БИЗНЕС ПРОДАН!\n\n" + str(biz["name"]) + "\nТы получил: " + format(bet))
                                except Exception:
                                    pass
                        else:
                            seller = biz["seller_id"] if "seller_id" in biz.keys() else 0
                            locked = biz["craft_locked"] if "craft_locked" in biz.keys() else 0
                            if locked == 1:
                                new_end = (now + timedelta(hours=BIZ_AUCTION_HOURS)).strftime(DB_DATE_FMT)
                                c.execute("UPDATE biz_businesses SET auction_end = ? WHERE id = ?",
                                          (new_end, biz["id"]))
                            elif seller and seller > 0:
                                c.execute("""UPDATE biz_businesses
                                             SET owner_id = ?, status = 'owned',
                                                 auction_end = NULL, current_bet = ?,
                                                 current_bidder = 0, seller_id = 0,
                                                 upgrade_level = 0, craft_locked = 0
                                             WHERE id = ?""", (seller, big_normalize(0), biz["id"]))
                                try:
                                    send_message(seller, "❌ Бизнес не продан. Возвращён тебе.")
                                except Exception:
                                    pass
                            else:
                                new_end = (now + timedelta(hours=BIZ_AUCTION_HOURS)).strftime(DB_DATE_FMT)
                                c.execute("UPDATE biz_businesses SET auction_end = ? WHERE id = ?",
                                          (new_end, biz["id"]))

                c.execute("SELECT * FROM biz_businesses WHERE status = 'owned'")
                owned = c.fetchall()
                for biz in owned:
                    if biz["biz_type"] in ("mafia", "league"):
                        continue
                    owner = biz["owner_id"]
                    if not owner:
                        continue
                    last_pay = db_parse(biz["last_payment"]) if biz["last_payment"] else None
                    if not last_pay:
                        continue
                    diff_hours = (now - last_pay).total_seconds() / 3600
                    if diff_hours >= 24:
                        new_end = (now + timedelta(hours=BIZ_AUCTION_HOURS)).strftime(DB_DATE_FMT)
                        c.execute("""UPDATE biz_businesses
                                     SET status = 'auction', auction_end = ?,
                                         current_bet = ?, current_bidder = 0,
                                         seller_id = 0, upgrade_level = 0
                                     WHERE id = ?""",
                                  (new_end, big_normalize(0), biz["id"]))
                        try:
                            send_message(owner, "⚠️ Бизнес " + str(biz["name"]) + " не оплачен 24ч!\nВыставлен на аукцион.")
                        except Exception:
                            pass

                if is_midnight_msk:
                    penalty_key = now_msk.strftime("%Y-%m-%d")
                    with BIZ_PENALTY_LOCK:
                        if _biz_last_penalty_date != penalty_key:
                            _biz_last_penalty_date = penalty_key
                            print("💰 [" + db_now() + "] Штрафы " + penalty_key)
                            yesterday = (now - timedelta(days=1)).strftime("%Y-%m-%d")
                            c.execute("SELECT user_id FROM users WHERE last_active >= ? AND (is_left IS NULL OR is_left = 0)",
                                      ((now - timedelta(days=3)).strftime(DB_DATE_FMT),))
                            users = c.fetchall()
                            c.execute("SELECT user_id, count FROM biz_player_apteka WHERE date = ?", (yesterday,))
                            apteka_used = {}
                            for r in c.fetchall():
                                apteka_used[r["user_id"]] = r["count"]
                            c.execute("SELECT user_id, done FROM biz_player_bolnitsa WHERE date = ?", (yesterday,))
                            bolnitsa_done = {}
                            for r in c.fetchall():
                                bolnitsa_done[r["user_id"]] = r["done"]

                            c.execute("SELECT * FROM biz_businesses WHERE biz_type LIKE 'apteka%'")
                            aptekas_owned = [b for b in c.fetchall() if b["owner_id"] and b["status"] == "owned"]
                            c.execute("SELECT * FROM biz_businesses WHERE biz_type LIKE 'bolnitsa%'")
                            bolnitsas_owned = [b for b in c.fetchall() if b["owner_id"] and b["status"] == "owned"]

                            total_penalties = 0
                            for u_row in users:
                                uid = u_row["user_id"]
                                c.execute("SELECT * FROM users WHERE user_id = ?", (uid,))
                                u_data = c.fetchone()
                                if aptekas_owned:
                                    imm = None
                                    if u_data and "apteka_immunity_until" in u_data.keys() and u_data["apteka_immunity_until"]:
                                        imm = db_parse(u_data["apteka_immunity_until"])
                                    if not (imm and imm > datetime.now()):
                                        used = apteka_used.get(uid, 0)
                                        if used < BIZ_APTEKA_NEED:
                                            balance = get_balance(uid)
                                            penalty = int(balance * BIZ_PENALTY / 100)
                                            if penalty > 0:
                                                ok, _, _ = sub_balance(uid, penalty)
                                                if ok:
                                                    add_transaction(uid, -penalty, "biz_penalty_apteka", "business", "Штраф аптеки")
                                                    share = penalty // len(aptekas_owned)
                                                    remainder = penalty - share * len(aptekas_owned)
                                                    for i, ab in enumerate(aptekas_owned):
                                                        s = share + (1 if i < remainder else 0)
                                                        if s > 0:
                                                            cur_bal = big_load(ab["balance"])
                                                            new_bal = cur_bal + s
                                                            if new_bal > MAX_BALANCE:
                                                                new_bal = MAX_BALANCE
                                                            c.execute("UPDATE biz_businesses SET balance = ? WHERE biz_type = ?",
                                                                      (big_normalize(new_bal), ab["biz_type"]))
                                                            pending_stats.append((ab["biz_type"], s))
                                                    total_penalties += 1
                                                    try:
                                                        send_message(uid, "💊 ШТРАФ АПТЕКИ\n−" + format(penalty))
                                                    except Exception:
                                                        pass
                                if bolnitsas_owned:
                                    imm = None
                                    if u_data and "bolnitsa_immunity_until" in u_data.keys() and u_data["bolnitsa_immunity_until"]:
                                        imm = db_parse(u_data["bolnitsa_immunity_until"])
                                    if not (imm and imm > datetime.now()):
                                        if not bolnitsa_done.get(uid, 0):
                                            balance = get_balance(uid)
                                            penalty = int(balance * BIZ_PENALTY / 100)
                                            if penalty > 0:
                                                ok, _, _ = sub_balance(uid, penalty)
                                                if ok:
                                                    add_transaction(uid, -penalty, "biz_penalty_bolnitsa", "business", "Штраф больницы")
                                                    share = penalty // len(bolnitsas_owned)
                                                    remainder = penalty - share * len(bolnitsas_owned)
                                                    for i, bb in enumerate(bolnitsas_owned):
                                                        s = share + (1 if i < remainder else 0)
                                                        if s > 0:
                                                            cur_bal = big_load(bb["balance"])
                                                            new_bal = cur_bal + s
                                                            if new_bal > MAX_BALANCE:
                                                                new_bal = MAX_BALANCE
                                                            c.execute("UPDATE biz_businesses SET balance = ? WHERE biz_type = ?",
                                                                      (big_normalize(new_bal), bb["biz_type"]))
                                                            pending_stats.append((bb["biz_type"], s))
                                                    total_penalties += 1
                                                    try:
                                                        send_message(uid, "🩺 ШТРАФ БОЛЬНИЦЫ\n−" + format(penalty))
                                                    except Exception:
                                                        pass
                            print("💰 Штрафов: " + str(total_penalties))
                conn.commit()
    except Exception as e:
        print("⚠️ biz_scheduler_tick: " + str(e))
    for bt, amt in pending_stats:
        try:
            biz_stats_add(bt, amt)
        except Exception:
            pass


# ========== 🏪 ЛОМБАРД: ЗАЙМЫ ==========
def lombard_get_cooldown(user_id):
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT last_loan FROM lombard_cooldowns WHERE user_id = ?", (user_id,))
                r = c.fetchone()
                return db_parse(r["last_loan"]) if r else None
    except Exception:
        return None


def lombard_check_cooldown(user_id):
    last = lombard_get_cooldown(user_id)
    if not last:
        return True, 0
    diff = (datetime.now() - last).total_seconds()
    if diff >= LOMBARD_COOLDOWN:
        return True, 0
    return False, int(LOMBARD_COOLDOWN - diff)


def lombard_get_active_loan(user_id):
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("""SELECT id, biz_type, amount, return_amount, expires_at
                             FROM lombard_loans WHERE user_id = ? AND status = 'active'
                             ORDER BY id DESC LIMIT 1""", (user_id,))
                r = c.fetchone()
                if not r:
                    return None
                return {
                    "id": r["id"],
                    "biz_type": r["biz_type"],
                    "amount": big_load(r["amount"]),
                    "return_amount": big_load(r["return_amount"]),
                    "expires_at": r["expires_at"],
                }
    except Exception:
        return None


def lombard_create_loan(chat_id, user_id, biz_type, amount):
    if biz_type in ("mafia", "league", "lombard"):
        send_message(chat_id, "❌ Этот бизнес нельзя сдать в ломбард!")
        return False
    if amount < LOMBARD_MIN or amount > LOMBARD_MAX:
        send_message(chat_id, "❌ Сумма от " + format(LOMBARD_MIN) + " до " + format(LOMBARD_MAX))
        return False
    can, left = lombard_check_cooldown(user_id)
    if not can:
        m = left // 60
        s = left % 60
        send_message(chat_id, "⏰ Кулдаун: " + str(m) + "м " + str(s) + "с")
        return False
    active = lombard_get_active_loan(user_id)
    if active:
        send_message(chat_id, "❌ У тебя уже есть активный займ!")
        return False
    return_amount = int(amount * LOMBARD_MULT)
    expires_at = (datetime.now() + timedelta(hours=LOMBARD_HOURS)).strftime(DB_DATE_FMT)
    try:
        with LOMBARD_LOCK:
            with DB_LOCK:
                with _conn() as conn:
                    c = conn.cursor()
                    c.execute("SELECT owner_id, status, name FROM biz_businesses WHERE biz_type = ?", (biz_type,))
                    row = c.fetchone()
                    if not row:
                        send_message(chat_id, "❌ Бизнес не найден!")
                        return False
                    if row["owner_id"] != user_id:
                        send_message(chat_id, "❌ Не твой бизнес!")
                        return False
                    if row["status"] != "owned":
                        send_message(chat_id, "❌ Бизнес не в статусе 'owned'!")
                        return False
                    c.execute("""UPDATE biz_businesses
                                 SET status = 'lombard'
                                 WHERE biz_type = ?""", (biz_type,))
                    c.execute("""INSERT INTO lombard_loans
                                 (user_id, biz_type, amount, return_amount, expires_at, status)
                                 VALUES (?, ?, ?, ?, ?, 'active')""",
                              (user_id, biz_type, big_normalize(amount),
                               big_normalize(return_amount), expires_at))
                    loan_id = c.lastrowid
                    c.execute("""INSERT OR REPLACE INTO lombard_cooldowns (user_id, last_loan)
                                 VALUES (?, ?)""", (user_id, db_now()))
                    conn.commit()
                    with lombard_loans_lock:
                        lombard_loans[loan_id] = {
                            "user_id": user_id,
                            "biz_type": biz_type,
                            "return_amount": return_amount,
                            "expires_at": datetime.now() + timedelta(hours=LOMBARD_HOURS),
                        }
        ok, new_bal, reason = add_balance(user_id, amount)
        if not ok:
            with DB_LOCK:
                with _conn() as conn:
                    c = conn.cursor()
                    c.execute("UPDATE biz_businesses SET status = 'owned' WHERE biz_type = ?", (biz_type,))
                    c.execute("UPDATE lombard_loans SET status = 'cancelled' WHERE id = ?", (loan_id,))
                    conn.commit()
            with lombard_loans_lock:
                lombard_loans.pop(loan_id, None)
            send_message(chat_id, reason)
            return False
        add_transaction(user_id, amount, "lombard_loan", "lombard",
                        "Займ под " + str(row["name"]))
        msg = ("🏪 ЗАЙМ ВЫДАН!\n\n"
               "📦 Залог: " + str(row["name"]) + "\n"
               "💰 Получено: " + format(amount) + "\n"
               "💸 Вернуть: " + format(return_amount) + "\n"
               "⏰ До: " + expires_at[:16] + "\n\n"
               "⚠️ Не вернёшь — бизнес на аукцион!")
        send_message(chat_id, msg)
        return True
    except Exception as e:
        send_message(chat_id, "❌ " + str(e))
        return False


def lombard_return_loan(chat_id, user_id, loan_id=None):
    if not loan_id:
        active = lombard_get_active_loan(user_id)
        if not active:
            send_message(chat_id, "❌ У тебя нет активного займа!")
            return False
        loan_id = active["id"]
    try:
        with LOMBARD_LOCK:
            with DB_LOCK:
                with _conn() as conn:
                    c = conn.cursor()
                    c.execute("""SELECT user_id, biz_type, amount, return_amount, status
                                 FROM lombard_loans WHERE id = ?""", (loan_id,))
                    loan_row = c.fetchone()
                    if not loan_row or loan_row["status"] != "active":
                        send_message(chat_id, "❌ Займ неактивен!")
                        return False
                    if loan_row["user_id"] != user_id:
                        send_message(chat_id, "❌ Это не твой займ!")
                        return False
                    loan = {
                        "user_id": loan_row["user_id"],
                        "biz_type": loan_row["biz_type"],
                        "amount": big_load(loan_row["amount"]),
                        "return_amount": big_load(loan_row["return_amount"]),
                    }
        ok, new_bal, reason = sub_balance(user_id, loan["return_amount"])
        if not ok:
            send_message(chat_id, "❌ Нужно " + format(loan["return_amount"]) + "\n" + reason)
            return False
        try:
            with LOMBARD_LOCK:
                with DB_LOCK:
                    with _conn() as conn:
                        c = conn.cursor()
                        c.execute("""UPDATE biz_businesses
                                     SET status = 'owned', last_payment = ?
                                     WHERE biz_type = ?""",
                                  (db_now(), loan["biz_type"]))
                        c.execute("""UPDATE lombard_loans
                                     SET status = 'returned', resolved_at = ?
                                     WHERE id = ?""",
                                  (db_now(), loan_id))
                        profit = loan["return_amount"] - loan["amount"]
                        c.execute("SELECT balance FROM biz_businesses WHERE biz_type = 'lombard'")
                        lb = c.fetchone()
                        cur_lb = big_load(lb["balance"]) if lb else 0
                        new_lb = cur_lb + profit
                        if new_lb > MAX_BALANCE:
                            new_lb = MAX_BALANCE
                        c.execute("""UPDATE biz_businesses
                                     SET balance = ?
                                     WHERE biz_type = 'lombard'""", (big_normalize(new_lb),))
                        conn.commit()
                        c.execute("SELECT name FROM biz_businesses WHERE biz_type = ?", (loan["biz_type"],))
                        bn = c.fetchone()
                        biz_name = bn["name"] if bn else loan["biz_type"]
                        with lombard_loans_lock:
                            lombard_loans.pop(loan_id, None)
        except Exception as e:
            add_balance(user_id, loan["return_amount"])
            send_message(chat_id, "❌ " + str(e))
            return False
        add_transaction(user_id, -loan["return_amount"], "lombard_return", "lombard", "Возврат займа")
        biz_stats_add("lombard", profit)
        msg = ("✅ ЗАЙМ ЗАКРЫТ!\n\n"
               "📦 Бизнес: " + str(biz_name) + "\n"
               "💸 Возвращено: " + format(loan["return_amount"]) + "\n"
               "🏪 Ломбард заработал: " + format(profit))
        send_message(chat_id, msg)
        return True
    except Exception as e:
        send_message(chat_id, "❌ " + str(e))
        return False


def lombard_expire_worker():
    while not scheduler_stop.is_set():
        try:
            now = datetime.now()
            expired_ids = []
            with DB_LOCK:
                with _conn() as conn:
                    c = conn.cursor()
                    c.execute("""SELECT id, user_id, biz_type, amount, return_amount, expires_at
                                 FROM lombard_loans WHERE status = 'active'""")
                    rows = c.fetchall()
                    for r in rows:
                        exp = db_parse(r["expires_at"])
                        if exp and exp <= now:
                            expired_ids.append({
                                "id": r["id"],
                                "user_id": r["user_id"],
                                "biz_type": r["biz_type"],
                                "amount": big_load(r["amount"]),
                                "return_amount": big_load(r["return_amount"]),
                            })
            for loan in expired_ids:
                try:
                    with LOMBARD_LOCK:
                        with DB_LOCK:
                            with _conn() as conn:
                                c = conn.cursor()
                                new_end = (datetime.now() + timedelta(hours=BIZ_AUCTION_HOURS)).strftime(DB_DATE_FMT)
                                c.execute("""UPDATE biz_businesses
                                             SET status = 'auction', auction_end = ?,
                                                 current_bet = ?, current_bidder = 0,
                                                 seller_id = 0, min_bet = ?
                                             WHERE biz_type = ?""",
                                          (new_end, big_normalize(0),
                                           big_normalize(BIZ_MIN_PRICE), loan["biz_type"]))
                                block_until = (datetime.now() + timedelta(days=365)).strftime(DB_DATE_FMT)
                                c.execute("""INSERT OR REPLACE INTO lombard_block
                                             (user_id, biz_type, block_until)
                                             VALUES (?, ?, ?)""",
                                          (loan["user_id"], loan["biz_type"], block_until))
                                c.execute("""UPDATE lombard_loans
                                             SET status = 'expired', resolved_at = ?
                                             WHERE id = ?""",
                                          (db_now(), loan["id"]))
                                conn.commit()
                    try:
                        send_message(loan["user_id"],
                                     "⏰ ЗАЙМ ИСТЁК!\n\n"
                                     "📦 " + str(loan["biz_type"]) + " → на аукцион\n"
                                     "❌ Ты больше не можешь ставить на него")
                    except Exception:
                        pass
                except Exception as e:
                    print("⚠️ lombard expire: " + str(e))
        except Exception as e:
            print("⚠️ lombard_expire_worker: " + str(e))
        time.sleep(30)


def lombard_cancel_all_on_leave(owner_id):
    try:
        with LOMBARD_LOCK:
            with DB_LOCK:
                with _conn() as conn:
                    c = conn.cursor()
                    c.execute("""SELECT id, user_id, biz_type FROM lombard_loans
                                 WHERE status = 'active'""")
                    rows = c.fetchall()
                    for r in rows:
                        c.execute("""UPDATE biz_businesses
                                     SET status = 'owned', last_payment = ?
                                     WHERE biz_type = ?""",
                                  (db_now(), r["biz_type"]))
                        c.execute("""UPDATE lombard_loans
                                     SET status = 'cancelled', resolved_at = ?
                                     WHERE id = ?""",
                                  (db_now(), r["id"]))
                        try:
                            send_message(r["user_id"],
                                         "🏪 ЛОМБАРД УШЁЛ\n\nБизнес возвращён: " + str(r["biz_type"]))
                        except Exception:
                            pass
                    conn.commit()
    except Exception as e:
        print("⚠️ lombard_cancel_all_on_leave: " + str(e))


# ========== 💳 ОПЛАТА БИЗНЕСА ==========
def biz_pay(biz_type, user_id, days=1):
    if days not in (1, 7, 30):
        return False, "❌ Только 1, 7 или 30 дней!"
    if biz_type == "mafia" or biz_type == "league":
        return False, "❌ Этот бизнес не требует оплаты!"
    cost = BIZ_PAYMENT * days
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT owner_id, status, last_payment, name FROM biz_businesses WHERE biz_type = ?", (biz_type,))
                row = c.fetchone()
                if not row:
                    return False, "❌ Бизнес не найден!"
                if row["owner_id"] != user_id:
                    return False, "❌ Ты не владелец!"
                if row["status"] != "owned":
                    return False, "❌ Бизнес не у тебя (статус: " + str(row["status"]) + ")!"
                now = datetime.now()
                last = db_parse(row["last_payment"]) if row["last_payment"] else None
                if last and last > now:
                    new_pay = last + timedelta(days=days)
                else:
                    new_pay = now + timedelta(days=days)
                new_pay_str = new_pay.strftime(DB_DATE_FMT)
        ok, new_bal, reason = sub_balance(user_id, cost)
        if not ok:
            return False, "❌ Нужно " + format(cost) + "\n" + reason
        try:
            with DB_LOCK:
                with _conn() as conn:
                    c = conn.cursor()
                    c.execute("UPDATE biz_businesses SET last_payment = ? WHERE biz_type = ?",
                              (new_pay_str, biz_type))
                    conn.commit()
        except Exception as e:
            add_balance(user_id, cost)
            return False, "❌ " + str(e)
        add_transaction(user_id, -cost, "biz_payment", "business",
                        "Оплата " + str(row["name"]) + " на " + str(days) + "д")
        biz_log_by_type(biz_type, user_id, -cost, "payment", "Оплата " + str(days) + "д")
        return True, ("✅ Бизнес оплачен на " + str(days) + " дней!\n"
                      "💰 −" + format(cost) + "\n"
                      "📅 До: " + new_pay.strftime("%d.%m %H:%M"))
    except Exception as e:
        return False, "❌ " + str(e)


def biz_log_by_type(biz_type, user_id, amount, action, details=None):
    try:
        b = biz_get(biz_type)
        if b:
            biz_log(b["id"], user_id, amount, action, details)
    except Exception:
        pass


def biz_withdraw(biz_type, user_id):
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT owner_id, status, balance, name FROM biz_businesses WHERE biz_type = ?", (biz_type,))
                row = c.fetchone()
                if not row:
                    return False, "❌ Бизнес не найден!"
                if row["owner_id"] != user_id:
                    return False, "❌ Ты не владелец!"
                amount = big_load(row["balance"])
                if amount <= 0:
                    return False, "❌ На балансе бизнеса пусто!"
        ok, new_bal, reason = add_balance(user_id, amount)
        if not ok:
            return False, reason
        try:
            with DB_LOCK:
                with _conn() as conn:
                    c = conn.cursor()
                    c.execute("UPDATE biz_businesses SET balance = ? WHERE biz_type = ?",
                              (big_normalize(0), biz_type))
                    conn.commit()
        except Exception as e:
            add_balance(user_id, -amount)
            return False, "❌ " + str(e)
        add_transaction(user_id, amount, "biz_withdraw", "business",
                        "Снятие с " + str(row["name"]))
        biz_log_by_type(biz_type, user_id, amount, "withdraw", "Снятие с бизнеса")
        return True, "✅ Снято " + format(amount) + " с бизнеса!"
    except Exception as e:
        return False, "❌ " + str(e)


def biz_add_to_balance(biz_type, amount):
    if amount <= 0:
        return False
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT balance FROM biz_businesses WHERE biz_type = ?", (biz_type,))
                r = c.fetchone()
                if not r:
                    return False
                cur = big_load(r["balance"])
                new_val = cur + amount
                if new_val > MAX_BALANCE:
                    new_val = MAX_BALANCE
                c.execute("UPDATE biz_businesses SET balance = ? WHERE biz_type = ?",
                          (big_normalize(new_val), biz_type))
                conn.commit()
        biz_stats_add(biz_type, amount)
        return True
    except Exception:
        return False


def biz_list_for_sale(biz_type, user_id):
    if biz_is_protected(biz_type):
        return False, "❌ Этот бизнес нельзя продать!"
    ends_at = (datetime.now() + timedelta(hours=BIZ_AUCTION_HOURS)).strftime(DB_DATE_FMT)
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT owner_id, status, name FROM biz_businesses WHERE biz_type = ?", (biz_type,))
                row = c.fetchone()
                if not row:
                    return False, "❌ Бизнес не найден!"
                if row["owner_id"] != user_id:
                    return False, "❌ Ты не владелец!"
                if row["status"] == "auction":
                    return False, "❌ Бизнес уже на аукционе!"
                c.execute("""UPDATE biz_businesses
                             SET status = 'auction',
                                 auction_end = ?,
                                 current_bet = ?,
                                 current_bidder = 0,
                                 min_bet = ?,
                                 seller_id = ?
                             WHERE biz_type = ?""",
                          (ends_at, big_normalize(0), big_normalize(BIZ_MIN_PRICE),
                           user_id, biz_type))
                conn.commit()
        biz_log_by_type(biz_type, user_id, 0, "list_for_sale", "Выставил на продажу")
        return True, "✅ Бизнес выставлен на продажу!\nМинимум: " + format(BIZ_MIN_PRICE) + "\nДлительность: 5ч"
    except Exception as e:
        return False, "❌ " + str(e)


def biz_cancel_sale(biz_type, user_id):
    if biz_is_protected(biz_type):
        return False, "❌ Этот бизнес нельзя трогать!"
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT owner_id, seller_id, status, current_bidder, current_bet, name, craft_locked FROM biz_businesses WHERE biz_type = ?", (biz_type,))
                row = c.fetchone()
                if not row:
                    return False, "❌ Бизнес не найден!"
                if row["status"] != "auction":
                    return False, "❌ Бизнес не на аукционе!"
                locked = row["craft_locked"] if "craft_locked" in row.keys() else 0
                if locked == 1:
                    return False, "🚫 Бизнес ушёл из крафта — снять нельзя!\n⏰ Жди конца аукциона"
                if row["owner_id"] != user_id and row["seller_id"] != user_id:
                    return False, "❌ Ты не владелец и не продавец!"
                current_bidder = row["current_bidder"]
                current_bet = big_load(row["current_bet"])
                if current_bidder and current_bet > 0:
                    add_balance(current_bidder, current_bet)
                    add_transaction(current_bidder, current_bet, "biz_refund_cancel", "business",
                                    "Возврат при снятии лота")
                c.execute("""UPDATE biz_businesses
                             SET status = 'owned',
                                 auction_end = NULL,
                                 current_bet = ?,
                                 current_bidder = 0,
                                 seller_id = 0,
                                 last_payment = ?
                             WHERE biz_type = ?""",
                          (big_normalize(0), db_now(), biz_type))
                conn.commit()
        biz_log_by_type(biz_type, user_id, 0, "cancel_sale", "Снял с продажи")
        msg = "✅ Бизнес снят с продажи!"
        if current_bidder and current_bet > 0:
            msg += "\nВозврат лидеру: " + format(current_bet)
            try:
                send_message(current_bidder, "❌ Лот снят с аукциона!\nВозврат: " + format(current_bet))
            except Exception:
                pass
        return True, msg
    except Exception as e:
        return False, "❌ " + str(e)


def biz_auction_text(biz):
    ends_at = db_parse(biz["auction_end"])
    now = datetime.now()
    if ends_at:
        left = int((ends_at - now).total_seconds())
        if left < 0:
            left = 0
        h = left // 3600
        m = (left % 3600) // 60
        s = left % 60
        time_left = f"{h}ч {m}м {s}с" if h > 0 else f"{m}м {s}с"
    else:
        time_left = "?"
    owner_name = biz_get_owner_name(biz["owner_id"])
    seller_id = biz["seller_id"] if "seller_id" in biz.keys() else 0
    seller_name = biz_get_owner_name(seller_id) if seller_id else None
    bidder_name = biz_get_owner_name(biz["current_bidder"]) if biz["current_bidder"] else "нет"
    text = "🔨 АУКЦИОН БИЗНЕСА\n\n"
    text += "📦 " + str(biz["name"]) + "\n"
    text += "💰 Мин. ставка: " + format(big_load(biz["min_bet"])) + "\n"
    text += "📈 Макс. ставка: " + format(BIZ_MAX_BET) + "\n"
    text += "⏰ Осталось: " + time_left + "\n\n"
    if seller_name:
        text += "🔄 Продаёт: " + str(seller_name) + "\n"
    else:
        text += "👑 Владелец: " + str(owner_name) + "\n"
    text += "🏆 Лидер: " + str(bidder_name) + "\n"
    text += "💵 Текущая ставка: " + format(big_load(biz["current_bet"]))
    return text


# ========== 🎁 ПРОМОКОДЫ ==========
def create_promocode(code, reward, max_uses=100, expires_days=7):
    code = (code or "").strip().upper().replace(" ", "")
    if not code:
        return False, "❌ Пустой код!"
    if reward < 1_000_000:
        return False, "❌ Минимум 1,000,000!"
    try:
        with PROMO_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT id FROM promocodes WHERE code = ?", (code,))
                if c.fetchone():
                    return False, "❌ Такой промокод уже есть!"
                expires_at = (datetime.now() + timedelta(days=expires_days)).strftime(DB_DATE_FMT)
                c.execute("INSERT INTO promocodes (code, reward, max_uses, expires_at, created_by) VALUES (?, ?, ?, ?, ?)",
                          (code, big_normalize(reward), max_uses, expires_at, ADMIN_ID))
                conn.commit()
        return True, "✅ Промокод " + code + " создан! Награда: " + format(reward) + ", лимит: " + str(max_uses)
    except Exception as e:
        return False, "❌ " + str(e)


def use_promocode(user_id, code):
    code = (code or "").strip().upper().replace(" ", "")
    if not code:
        return False, "❌ Пустой промокод!"
    try:
        with PROMO_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT id, reward, max_uses, used_count, expires_at, is_active FROM promocodes WHERE code = ?", (code,))
                r = c.fetchone()
                if not r:
                    return False, "❌ Промокод не найден!"
                promo_id = r["id"]
                reward = big_load(r["reward"])
                max_uses = r["max_uses"]
                expires_at = r["expires_at"]
                is_active = r["is_active"]
                if not is_active:
                    return False, "❌ Промокод неактивен!"
                if expires_at:
                    dt = db_parse(expires_at)
                    if dt and dt < datetime.now():
                        return False, "❌ Промокод истёк!"
                try:
                    c.execute("INSERT INTO promo_uses (promo_id, user_id) VALUES (?, ?)", (promo_id, user_id))
                except sqlite3.IntegrityError:
                    conn.rollback()
                    return False, "❌ Ты уже использовал этот промокод!"
                c.execute("UPDATE promocodes SET used_count = used_count + 1 WHERE id = ? AND used_count < max_uses", (promo_id,))
                if c.rowcount == 0:
                    conn.rollback()
                    return False, "❌ Лимит исчерпан!"
                c.execute("SELECT user_id FROM users WHERE user_id = ?", (user_id,))
                if not c.fetchone():
                    conn.rollback()
                    return False, "❌ Пользователь не найден!"
                conn.commit()
        ok, new_bal, reason = add_balance(user_id, reward)
        if not ok:
            return False, reason
        add_transaction(user_id, reward, "promocode", "promo", "Промокод: " + code)
        return True, "🎉 ПРОМОКОД АКТИВИРОВАН!\nКод: " + code + "\n💰 +" + format(reward) + "\n💎 Поинты: " + format(new_bal)
    except Exception as e:
        return False, "❌ Ошибка: " + str(e)


def get_all_promocodes():
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT code, reward, max_uses, used_count, expires_at, is_active FROM promocodes ORDER BY id DESC")
                result = []
                for r in c.fetchall():
                    result.append((r["code"], big_load(r["reward"]),
                                   r["max_uses"], r["used_count"],
                                   r["expires_at"], r["is_active"]))
                return result
    except Exception:
        return []


def delete_promocode(code):
    code = (code or "").strip().upper()
    try:
        with PROMO_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("DELETE FROM promocodes WHERE code = ?", (code,))
                a = c.rowcount
                conn.commit()
        return a > 0
    except Exception:
        return False


def toggle_promocode(code):
    code = (code or "").strip().upper()
    try:
        with PROMO_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT is_active FROM promocodes WHERE code = ?", (code,))
                r = c.fetchone()
                if not r:
                    return False, "❌ Не найден!"
                new_status = 0 if r["is_active"] else 1
                c.execute("UPDATE promocodes SET is_active = ? WHERE code = ?", (new_status, code))
                conn.commit()
        return True, "✅ " + ("Активирован" if new_status else "Деактивирован")
    except Exception:
        return False, "❌ Ошибка!"


