def get_special_progress(user_id):
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT progress, opens_used FROM special_cases WHERE user_id = ?", (user_id,))
                r = c.fetchone()
                return (r["progress"], r["opens_used"]) if r else (0, 0)
    except Exception:
        return (0, 0)


def get_case_stats(user_id):
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT case_type, opens, total_spent, total_won, best_prize FROM case_stats WHERE user_id = ?", (user_id,))
                r = c.fetchall()
        total_opens = 0
        total_spent = 0
        total_won = 0
        by_type = []
        for row in r:
            opens = row["opens"] or 0
            spent = big_load(row["total_spent"])
            won = big_load(row["total_won"])
            best = big_load(row["best_prize"])
            total_opens += opens
            total_spent += spent
            total_won += won
            by_type.append((row["case_type"], opens, spent, won, best))
        return {"total_opens": total_opens, "total_spent": total_spent,
                "total_won": total_won, "total_profit": total_won - total_spent,
                "by_type": by_type}
    except Exception:
        return {"total_opens": 0, "total_spent": 0, "total_won": 0, "total_profit": 0, "by_type": []}


def get_case_top(limit=10):
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT user_id, total_won, total_spent, opens FROM case_stats")
                rows = c.fetchall()
        by_user = {}
        for r in rows:
            uid = r["user_id"]
            if uid not in by_user:
                by_user[uid] = {"profit": 0, "opens": 0}
            by_user[uid]["profit"] += big_load(r["total_won"]) - big_load(r["total_spent"])
            by_user[uid]["opens"] += r["opens"] or 0
        sorted_users = sorted(by_user.items(), key=lambda x: x[1]["profit"], reverse=True)[:limit]
        return [(uid, data["profit"], data["opens"]) for uid, data in sorted_users]
    except Exception:
        return []


def roll_case_reward(case_type):
    case = CASES.get(case_type)
    if not case:
        return None
    roll = random.randint(1, 100)
    cumulative = 0
    for reward in case["rewards"]:
        cumulative += reward["chance"]
        if roll <= cumulative:
            return reward
    return case["rewards"][-1]


def open_cases_batch(chat_id, message_id, user_id, case_type, count):
    case = CASES.get(case_type)
    if not case:
        send_message(chat_id, "❌ Кейс не найден!")
        return
    if count < 1 or count > 100:
        send_message(chat_id, "❌ 1-100!")
        return
    price = case["price"]
    rewards_list = []
    for _ in range(count):
        reward = roll_case_reward(case_type)
        if reward:
            rewards_list.append(reward["amount"])
    total_won = sum(rewards_list)
    best_prize = max(rewards_list) if rewards_list else 0
    progress_before, _ = get_special_progress(user_id)
    balance = get_balance(user_id)
    cost_text = ""
    stat_price = 0
    if case_type == "special":
        available = progress_before // 100
        if available < 1:
            send_message(chat_id, "❌ Нужно 100 открытий! У тебя: " + str(progress_before) + "/100")
            return
        if count > available:
            send_message(chat_id, "❌ Доступно только " + str(available) + "!")
            return
        try:
            with DB_LOCK:
                with _conn() as conn:
                    c = conn.cursor()
                    c.execute("UPDATE special_cases SET progress = progress - ?, opens_used = opens_used + ? WHERE user_id = ? AND progress >= ?",
                              (count * 100, count, user_id, count * 100))
                    if c.rowcount == 0:
                        conn.rollback()
                        send_message(chat_id, "❌ Ошибка прогресса!")
                        return
                    conn.commit()
        except Exception as e:
            send_message(chat_id, "❌ " + str(e))
            return
        cost_text = "Бесплатно"
    else:
        total_cost = price * count
        if balance < total_cost:
            send_message(chat_id, "❌ Мало! Нужно: " + format(total_cost) + ", есть: " + format(balance))
            return
        ok, _, reason = sub_balance(user_id, total_cost)
        if not ok:
            send_message(chat_id, "❌ " + reason)
            return
        add_transaction(user_id, -total_cost, "case_open", "case", case["name"] + " x" + str(count))
        stat_price = price
        cost_text = format(total_cost)
    ok, new_bal, reason = add_balance(user_id, total_won)
    if not ok:
        if stat_price > 0:
            add_balance(user_id, stat_price * count)
        send_message(chat_id, "❌ " + reason)
        return
    add_transaction(user_id, total_won, "case_win", "case", case["name"] + " x" + str(count))
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT opens, total_spent, total_won, best_prize FROM case_stats WHERE user_id = ? AND case_type = ?",
                          (user_id, case_type))
                exists = c.fetchone()
                if stat_price > 0:
                    cost_add = stat_price * count
                else:
                    cost_add = 0
                if exists:
                    old_opens = exists["opens"] or 0
                    old_spent = big_load(exists["total_spent"])
                    old_won = big_load(exists["total_won"])
                    old_best = big_load(exists["best_prize"])
                    new_opens = old_opens + count
                    new_spent = old_spent + cost_add
                    new_won = old_won + total_won
                    new_best = max(old_best, best_prize)
                    if new_spent > MAX_BALANCE:
                        new_spent = MAX_BALANCE
                    if new_won > MAX_BALANCE:
                        new_won = MAX_BALANCE
                    if new_best > MAX_BALANCE:
                        new_best = MAX_BALANCE
                    c.execute("""UPDATE case_stats
                                 SET opens = ?, total_spent = ?, total_won = ?, best_prize = ?
                                 WHERE user_id = ? AND case_type = ?""",
                              (new_opens, big_normalize(new_spent),
                               big_normalize(new_won), big_normalize(new_best),
                               user_id, case_type))
                else:
                    spent_val = cost_add if cost_add > 0 else 0
                    c.execute("""INSERT INTO case_stats
                                 (user_id, case_type, opens, total_spent, total_won, best_prize)
                                 VALUES (?, ?, ?, ?, ?, ?)""",
                              (user_id, case_type, count,
                               big_normalize(spent_val),
                               big_normalize(total_won),
                               big_normalize(best_prize)))
                if case_type != "special":
                    c.execute("SELECT progress FROM special_cases WHERE user_id = ?", (user_id,))
                    r = c.fetchone()
                    if r:
                        c.execute("UPDATE special_cases SET progress = progress + ?, last_open = ? WHERE user_id = ?",
                                  (count, db_now(), user_id))
                    else:
                        c.execute("INSERT INTO special_cases (user_id, progress, last_open) VALUES (?, ?, ?)",
                                  (user_id, count, db_now()))
                conn.commit()
    except Exception as e:
        print("⚠️ case stats: " + str(e))
    if message_id:
        try:
            edit_message(chat_id, message_id, case["name"] + "\nОткрываем " + str(count) + "...", None)
            time.sleep(0.5)
        except Exception:
            pass
    rewards_count = {}
    for amount in rewards_list:
        rewards_count[amount] = rewards_count.get(amount, 0) + 1
    if case_type == "special":
        profit = total_won
    else:
        profit = total_won - (price * count)
    sign = "+" if profit > 0 else ""
    breakdown = ""
    for amount in sorted(rewards_count.keys(), reverse=True):
        cnt = rewards_count[amount]
        breakdown += str(amount) + " x" + str(cnt) + "\n"
    progress, used = get_special_progress(user_id)
    msg = case["name"] + " x" + str(count) + "\n\n"
    msg += "Выпало:\n" + breakdown + "\n"
    msg += "Потрачено: " + cost_text + "\n"
    msg += "Получено: " + format(total_won) + "\n"
    msg += "Профит: " + sign + format(profit) + "\n"
    msg += "Лучший: " + format(best_prize) + "\n\n"
    msg += "Поинты: " + format(get_balance(user_id))
    keyboard = {"inline_keyboard": [[{"text": "ВСЕ КЕЙСЫ", "callback_data": "cases_menu"}]]}
    if message_id:
        edit_message(chat_id, message_id, msg, keyboard)
    else:
        send_message(chat_id, msg, keyboard)


