def crypto_format_countdown(interval_sec, last_update_str):
    last = db_parse(last_update_str) if last_update_str else None
    if not last:
        return "?"
    left = int(interval_sec - (datetime.now() - last).total_seconds())
    if left < 0:
        left = 0
    h = left // 3600
    m = (left % 3600) // 60
    if h > 0:
        return str(h) + "ч " + str(m) + "м"
    return str(m) + "м"


