    text += "💰 Поинты: " + format(bal) + "\n\n"
    text += "📊 <b>Цены:</b>\n"
    for coin in coins:
        ticker = coin["ticker"]
        emoji = coin["emoji"]
        price = big_load(coin["price"])
        prev = big_load(coin["prev_price"])
        if prev == 0:
            prev = price
        if price > prev:
            arrow = "🟢"
        elif price < prev:
            arrow = "🔴"
        else:
            arrow = "⚪"
        cd = crypto_format_countdown(coin["interval_sec"] or 300, coin["last_update"])
        label = ticker.ljust(3)
        text += arrow + " " + emoji + " " + label + " " + format(price) + "  ⏰ " + cd + "\n"
