# ========== ЧАСТЬ 7/25: АУКЦИОНЫ ЛОТОВ ==========

def create_auction(title, description, lot_type, lot_value, min_bet, step, duration_min, chat_id, created_by):
    """✅ BIG-INT: min_bet/step → TEXT."""
    try:
        ends_at = (datetime.now() + timedelta(minutes=duration_min)).strftime(DB_DATE_FMT)
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("""INSERT INTO auctions
                             (title, description, lot_type, lot_value, min_bet, step,
                              created_by, chat_id, ends_at, status)
                             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 'active')""",
                          (title, description, lot_type, lot_value,
                           big_normalize(min_bet), big_normalize(step),
                           created_by, chat_id, ends_at))
                auction_id = c.lastrowid
                conn.commit()
        return True, auction_id
    except Exception as e:
        return False, "❌ " + str(e)


def get_auction(auction_id):
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT * FROM auctions WHERE id = ?", (auction_id,))
                return c.fetchone()
    except Exception:
        return None


def get_active_auctions():
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT * FROM auctions WHERE status = 'active' ORDER BY ends_at ASC")
                return c.fetchall()
    except Exception:
        return []


def get_auction_bets(auction_id):
    """✅ BIG-INT: amount через big_load. ORDER BY не работает на TEXT корректно для больших чисел → сортируем в Python."""
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("""SELECT user_id, amount, timestamp FROM auction_bets
                             WHERE auction_id = ?""", (auction_id,))
                rows = c.fetchall()
        result = []
        for r in rows:
            result.append({
                "user_id": r["user_id"],
                "amount": big_load(r["amount"]),
                "timestamp": r["timestamp"],
            })
        result.sort(key=lambda x: x["amount"], reverse=True)
        return result
    except Exception:
        return []


def auction_message_text(a):
    ends_at = db_parse(a["ends_at"])
    now = datetime.now()
    if ends_at:
        left = int((ends_at - now).total_seconds())
        if left < 0:
            left = 0
        h = left // 3600
        m = (left % 3600) // 60
        s = left % 60
        time_left = f"{h}ч {m}м {s}с" if h > 0 else f"{m}м {s}с"
    else:
        time_left = "?"
    lot_type = a["lot_type"]
    if lot_type == "title":
        type_name = "🏆 Титул"
    elif lot_type == "custom_title":
        type_name = "✨ Кастомный титул"
    elif lot_type == "money":
        type_name = "💰 Поинты"
    elif lot_type == "phone":
        type_name = "📱 Номер телефона"
    else:
        type_name = lot_type
    winner = a["current_winner"]
    current_bet = big_load(a["current_bet"])
    if winner and current_bet > 0:
        wname = get_display_name(winner)
        bid_info = "🏆 Лидер: " + str(wname) + "\n💰 Ставка: " + format(current_bet)
    else:
        bid_info = "❌ Ставок пока нет"
    text = "🔨 АУКЦИОН #" + str(a["id"]) + "\n\n"
    text += "📦 " + str(a["title"]) + "\n"
    text += type_name + ": " + str(a["lot_value"]) + "\n"
    if a["description"]:
        text += "📝 " + str(a["description"]) + "\n"
    text += "\n💰 Мин. ставка: " + format(big_load(a["min_bet"])) + "\n"
    text += "📈 Шаг: " + format(big_load(a["step"])) + "\n"
    text += "⏰ Осталось: " + time_left + "\n\n"
    text += bid_info
    return text


def refresh_auction_message(auction_id):
    a = get_auction(auction_id)
    if not a or not a["message_id"]:
        return
    text = auction_message_text(a)
    try:
        edit_message(a["chat_id"], a["message_id"], text, None)
    except Exception:
        pass


def post_auction_to_chat(chat_id, auction_id):
    a = get_auction(auction_id)
    if not a:
        return
    text = auction_message_text(a)
    res = send_message(chat_id, text)
    if res and res.get("ok"):
        mid = res["result"]["message_id"]
        try:
            with DB_LOCK:
                with _conn() as conn:
                    conn.execute("UPDATE auctions SET message_id = ? WHERE id = ?", (mid, auction_id))
                    conn.commit()
        except Exception:
            pass


def finish_auction(auction_id):
    """✅ BIG-INT: все суммы через big_load/big_normalize."""
    a = get_auction(auction_id)
    if not a or a["status"] != "active":
        return
    winner = a["current_winner"]
    win_amount = big_load(a["current_bet"])
    lot_type = a["lot_type"]
    lot_value = a["lot_value"]
    creator = a["created_by"]
    chat_id = a["chat_id"]
    phone_returned_to_owner = None
    restarted = False
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("UPDATE auctions SET status = 'finished' WHERE id = ?", (auction_id,))
                if winner and win_amount > 0:
                    if lot_type == "money":
                        add_balance(winner, int(lot_value))
                        add_balance(creator, win_amount)
                    elif lot_type == "phone":
                        phone_num = str(lot_value).strip()
                        c.execute("""INSERT OR REPLACE INTO phones
                                     (number, owner_id, is_pretty, bought_at)
                                     VALUES (?, ?, ?, ?)""",
                                  (phone_num, winner,
                                   1 if phone_num in PHONE_PRETTY_SET else 0,
                                   db_now()))
                        add_balance(creator, win_amount)
                        try:
                            send_message(winner,
                                         "📱 ТЫ ВЫИГРАЛ НОМЕР!\n\n"
                                         "📞 +" + phone_num + "\n"
                                         "💰 Ставка: " + format(win_amount))
                        except Exception:
                            pass
                    else:
                        title_key = "custom_" + lot_value[:30] if lot_type == "custom_title" else lot_value
                        try:
                            c.execute("""INSERT OR IGNORE INTO titles (user_id, title_key, custom_text, awarded_by)
                                         VALUES (?, ?, ?, ?)""",
                                      (winner, title_key, lot_value if lot_type == "custom_title" else None, creator))
                        except Exception:
                            pass
                        add_balance(creator, win_amount)
                else:
                    if lot_type == "phone":
                        phone_num = str(lot_value).strip()
                        c.execute("SELECT owner_id FROM phones WHERE number = ?", (phone_num,))
                        row = c.fetchone()
                        if row:
                            phone_returned_to_owner = row["owner_id"]
                conn.commit()
    except Exception as e:
        print("⚠️ finish_auction: " + str(e))
        return
    text = "🔨 АУКЦИОН ЗАВЕРШЁН!\n\n📦 Лот: " + str(a["title"]) + "\n"
    if winner and win_amount > 0:
        name = get_display_name(winner)
        text += "🏆 Победитель: " + str(name) + "\n💰 Ставка: " + format(win_amount)
        try:
            send_message(winner, "🏆 ТЫ ВЫИГРАЛ АУКЦИОН!\n\n" + str(a["title"]) + "\n💰 " + format(win_amount))
        except Exception:
            pass
    else:
        if lot_type == "phone":
            text += "❌ Ставок не было. Номер возвращён владельцу."
            try:
                if phone_returned_to_owner:
                    with DB_LOCK:
                        with _conn() as conn2:
                            c2 = conn2.cursor()
                            one_hour_ago = (datetime.now() - timedelta(hours=1)).strftime(DB_DATE_FMT)
                            c2.execute("""SELECT COUNT(*) as cnt FROM auctions
                                          WHERE lot_type = 'phone'
                                          AND lot_value = ?
                                          AND created_at >= ?""",
                                       (str(lot_value), one_hour_ago))
                            cnt = c2.fetchone()["cnt"]
                            if cnt >= 2:
                                restarted = True
                    if not restarted:
                        new_end = (datetime.now() + timedelta(hours=PHONE_AUCTION_HOURS)).strftime(DB_DATE_FMT)
                        with DB_LOCK:
                            with _conn() as conn2:
                                c2 = conn2.cursor()
                                c2.execute("""INSERT INTO auctions
                                             (title, description, lot_type, lot_value,
                                              min_bet, step, created_by, chat_id, ends_at, status)
                                             VALUES (?, ?, 'phone', ?, ?, ?, ?, ?, ?, 'active')""",
                                          ("📱 Красивый номер +" + str(lot_value),
                                           "Красивый номер. Ставка: " + format(PHONE_AUCTION_MIN) + " – " + format(PHONE_AUCTION_MAX),
                                           str(lot_value),
                                           big_normalize(PHONE_AUCTION_MIN),
                                           big_normalize(10_000_000),
                                           phone_returned_to_owner, chat_id, new_end))
                                conn2.commit()
                        try:
                            new_auc = get_active_auctions()
                            for na in new_auc:
                                if na["lot_type"] == "phone" and str(na["lot_value"]) == str(lot_value):
                                    post_auction_to_chat(chat_id, na["id"])
                                    break
                        except Exception as e:
                            print("⚠️ phone auction restart post: " + str(e))
            except Exception as e:
                print("⚠️ phone auction restart: " + str(e))
        else:
            text += "❌ Никто не поставил."
    try:
        send_message(chat_id, text)
    except Exception:
        pass


