def save_last_bets(user_id, bets):
    """✅ BIG-INT: total_bet через big_normalize."""
    try:
        clean = []
        for b in bets:
            item = {"amount": b["amount"], "type": b["type"], "label": b.get("label", "?")}
            if b["type"] == "range":
                item["from"] = b.get("from")
                item["to"] = b.get("to")
            elif b["type"] == "number":
                item["number"] = b.get("number")
            clean.append(item)
        total = sum(b["amount"] for b in clean)
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("""INSERT INTO roulette_last_bets (user_id, bets_json, total_bet, updated_at)
                             VALUES (?, ?, ?, ?)
                             ON CONFLICT(user_id) DO UPDATE SET
                               bets_json = excluded.bets_json,
                               total_bet = excluded.total_bet,
                               updated_at = excluded.updated_at""",
                          (user_id, json.dumps(clean, ensure_ascii=False),
                           big_normalize(total), db_now()))
                conn.commit()
        return True
    except Exception as e:
        print("⚠️ save_last_bets: " + str(e))
        return False


