def get_user_house_bonus(user_id):
    try:
        fam = get_user_family(user_id)
        if not fam:
            return (0, None)
        try:
            house_type = fam["house_type"] if "house_type" in fam.keys() else ""
        except Exception:
            house_type = ""
        if not house_type or house_type not in FAMILY_HOUSES:
            return (0, None)
        house = FAMILY_HOUSES[house_type]
        slots = house["slots"]
        bonus = house["bonus"]
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("""SELECT user_id FROM family_members
                             WHERE family_id = ?
                             ORDER BY joined_at ASC, user_id ASC
                             LIMIT ?""", (fam["id"], slots))
                allowed = [r["user_id"] for r in c.fetchall()]
        if user_id in allowed:
            return (bonus, house_type)
        return (0, house_type)
    except Exception as e:
        print("⚠️ get_user_house_bonus: " + str(e))
        return (0, None)


