def rl_cancel_expired_bets_worker():
    """✅ BIG-INT: возврат через add_balance."""
    while not scheduler_stop.is_set():
        try:
            now = time.time()
            to_cancel = []
            with roulette_pending_lock:
                for key, info in list(roulette_pending_expire.items()):
                    if info["expires_at"] <= now:
                        to_cancel.append(key)
                        roulette_pending_expire.pop(key, None)
            for key in to_cancel:
                try:
                    if isinstance(key, tuple):
                        uid, cid = key
                    else:
                        uid, cid = key, None
                    if cid is None:
                        continue
                    bets = get_user_bets_in_chat(uid, cid)
                    if not bets:
                        continue
                    total_refund = sum(b["amount"] for b in bets)
                    with DB_LOCK:
                        with _conn() as conn:
                            c = conn.cursor()
                            c.execute("DELETE FROM roulette_bets WHERE user_id = ? AND chat_id = ?",
                                      (uid, cid))
                            conn.commit()
                    ok, _, _ = add_balance(uid, total_refund)
                    if ok:
                        add_transaction(uid, total_refund, "roulette_expire_refund", "roulette", "Отмена ставок (5 мин)")
                    with player_bet_cooldown_lock:
                        cd = player_bet_cooldown.get(uid)
                        if cd and cd.get("chat_id") == cid:
                            player_bet_cooldown.pop(uid, None)
                    try:
                        send_message(uid, "⏰ Ставки отменены (5 мин без «Го»).\n💰 Возврат: " + format(total_refund))
                    except Exception:
                        pass
                except Exception as e:
                    print("⚠️ cancel expired: " + str(e))
        except Exception as e:
            print("⚠️ rl_cancel_expired: " + str(e))
        time.sleep(30)


