def handle_roulette(chat_id, message_id, user_id):
    if not is_roulette_enabled():
        send_message(chat_id, "Рулетка отключена.")
        return
    if rl_is_blocked(user_id):
        send_message(chat_id, "Тебе заблокирован доступ!")
        return
    update_last_active(user_id)
    history = get_roulette_history(chat_id, 7)
    colors = {"red": "R", "black": "B", "green": "G"}
    if history:
        ht = "История: " + " ".join([colors.get(c, "?") + str(n) for n, c in history])
    else:
        ht = "История: пусто"
    bets = get_user_bets_in_chat(user_id, chat_id)
    balance = get_balance(user_id)
    if bets:
        total = sum(b["amount"] for b in bets)
        bets_text = "Твои ставки в этом чате (" + str(len(bets)) + "/" + str(MAX_ROULETTE_BETS) + "):\n"
        for b in bets[:15]:
            bets_text += "  " + format(b["amount"]) + " → " + b["label"] + "\n"
        if len(bets) > 15:
            bets_text += "  ... и ещё " + str(len(bets) - 15) + "\n"
        bets_text += "\nВсего: " + format(total) + "\nПоинты: " + format(balance)
    else:
        bets_text = "Ставок нет (0/" + str(MAX_ROULETTE_BETS) + ")\n\nПоинты: " + format(balance)
    wins, losses, won_amount, lost_amount = get_title_stats(user_id)
    text = "<b>🎰 РУЛЕТКА</b>\n\n" + ht + "\n\n" + bets_text + "\n\n🎯 Побед: " + str(wins) + " | 💰 Выиграно: " + format(won_amount)
    text += "\n\n📝 Ставки:\n1000 30-36 — диапазон\n500 красное — цвет\n300 17 — число\n200 четное — чёт/нечет"
    text += "\n\n📊 Максимум: " + str(MAX_ROULETTE_BETS) + "\n🎰 Затем: Го\n💎 ДЖЕКПОТ: 1% на 1,000,000,000!"
    try:
        hb, ht2 = get_user_house_bonus(user_id)
        if hb > 0:
            text += "\n🏠 Бонус дома: +" + str(hb) + "%"
    except Exception:
        pass
    try:
        buffs = craft_get_buffs(user_id)
        if buffs["win_boost_percent"] > 0:
            text += "\n💎 Буст выигрыша: +" + str(buffs["win_boost_percent"]) + "%"
    except Exception:
        pass
    try:
        rboost = get_roulette_boost(user_id)
        if rboost["percent"] > 0:
            until_str = rboost["until"].strftime("%d.%m %H:%M") if rboost["until"] else "?"
            text += "\n🎯 Буст +" + str(rboost["percent"]) + "% до " + until_str
    except Exception:
        pass
    # ✅ ФИКС: используем send_long_message вместо send_message
    if message_id:
        edit_message(chat_id, message_id, text, roulette_keyboard(user_id))
    else:
        send_long_message(chat_id, text, roulette_keyboard(user_id))


def add_roulette_bet(chat_id, user_id, text):
    """✅ BIG-INT: amount через big_normalize в БД, big_load при чтении.
    ✅ НОВОЕ: после успешной ставки — хук FRIK PASS (если >= 10KKK)."""
    with player_bet_cooldown_lock:
        existing_cd = player_bet_cooldown.get(user_id)
        if existing_cd and existing_cd.get("chat_id") == chat_id and existing_cd.get("until", 0) <= time.time():
            player_bet_cooldown.pop(user_id, None)
            existing_cd = None
        if existing_cd is None or existing_cd.get("chat_id") != chat_id:
            player_bet_cooldown[user_id] = {
                "until": time.time() + 15,
                "chat_id": chat_id
            }
        else:
            player_bet_cooldown[user_id]["until"] = time.time() + 15

    update_last_active(user_id)
    if not is_roulette_enabled():
        send_message(chat_id, "❌ Рулетка отключена!")
        return
    if rl_is_blocked(user_id):
        send_message(chat_id, "❌ Тебе заблокирован доступ!")
        return
    bets = parse_roulette_bets(text)
    if not bets:
        send_message(chat_id, "❌ Не понял ставку!\n\nПример: 1000 30-36")
        return
    new_total = sum(b["amount"] for b in bets)
    # Получаем текущее состояние
    current_count = get_bets_count_in_chat(user_id, chat_id)
    existing_total = get_bets_total_in_chat(user_id, chat_id)
    if current_count + len(bets) > MAX_ROULETTE_BETS:
        send_message(chat_id, "❌ Лимит " + str(MAX_ROULETTE_BETS) + " ставок!")
        return
    balance = get_balance(user_id)
    if existing_total + new_total > balance:
        send_message(chat_id, "❌ Превышен баланс! " + format(balance))
        return
    # Списание через big-int
    ok, new_bal, reason = sub_balance(user_id, new_total)
    if not ok:
        send_message(chat_id, "❌ " + reason)
        return
    # Записываем ставки в БД (amount → TEXT)
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                for b in bets:
                    c.execute("""INSERT INTO roulette_bets
                                 (user_id, amount, bet_type, bet_from, bet_to, bet_number, label, chat_id)
                                 VALUES (?, ?, ?, ?, ?, ?, ?, ?)""",
                              (user_id, big_normalize(b["amount"]), b["type"], b.get("from"), b.get("to"),
                               b.get("number"), b.get("label", "?"), chat_id))
                conn.commit()
    except Exception as e:
        add_balance(user_id, new_total)
        send_message(chat_id, "❌ " + str(e))
        return
    add_transaction(user_id, -new_total, "roulette_bet_reserve", "roulette",
                    "Резерв под ставку (chat " + str(chat_id) + ")")
    rl_save_pending_expire(user_id, chat_id, ROULETTE_PENDING_SEC)

    # ✅ НОВОЕ: хук FRIK PASS — считаем ставку, если она >= 10KKK
    try:
        rl_try_fp_hook(user_id, new_total)
    except Exception as _e:
        print("⚠️ fp hook: " + str(_e))

    # ✅ ФИКС: урезаем вывод до 20 ставок + "и ещё N" + используем send_long_message
    shown = bets[:20]
    added = "\n".join(["  " + format(b["amount"]) + " → " + b["label"] for b in shown])
    if len(bets) > 20:
        added += "\n  ... и ещё " + str(len(bets) - 20) + " ставок"
    total_count = get_bets_count_in_chat(user_id, chat_id)
    total_sum = get_bets_total_in_chat(user_id, chat_id)
    new_balance = get_balance(user_id)
    msg_text = ("✅ Ставка принята!\n\n" + added +
                "\n\nВсего: " + str(total_count) + "/" + str(MAX_ROULETTE_BETS) +
                "\nСумма: " + format(total_sum) +
                "\n💎 Поинты: " + format(new_balance) +
                "\n\n⏳ 5 мин до сгорания\nНапиши: Го")
    send_long_message(chat_id, msg_text)


def go_roulette(chat_id, message_id, user_id):
    if not is_roulette_enabled():
        send_message(chat_id, "❌ Рулетка отключена!")
        return
    if rl_is_blocked(user_id):
        send_message(chat_id, "❌ Тебе заблокирован доступ!")
        return
    bets = get_user_bets_in_chat(user_id, chat_id)
    if not bets:
        send_message(chat_id, "❌ У тебя нет ставок в этом чате!")
        return
    now_ts = time.time()
    with player_bet_cooldown_lock:
        cd = player_bet_cooldown.get(user_id)
        if cd and cd.get("chat_id") == chat_id:
            left = int(cd["until"] - now_ts)
            if left > 0:
                send_message(chat_id, "⏳ Жди " + str(left) + " сек. (15 сек с первой ставки)")
                return
            else:
                player_bet_cooldown.pop(user_id, None)
    active = rl_get_active_round(chat_id)
    if active:
        left = int(active["ends_at"] - now_ts)
        if left > 0:
            send_message(chat_id, "⚠️ Раунд уже идёт, подожди " + str(left) + " сек")
            return
    rl_spin_common(chat_id, None)


def rl_spin_common(chat_id, message_id):
    """✅ BIG-INT: все суммы через add_balance / save_balance."""
    all_bets = get_all_bets_in_chat(chat_id)
    if not all_bets:
        try:
            send_message(chat_id, "❌ Ставок нет.")
        except Exception:
            pass
        rl_clear_active_round(chat_id)
        return
    rig = rl_consume_rig(chat_id)
    number = rig if (rig is not None and 0 <= rig <= 36) else random.randint(0, 36)
    color = get_roulette_color(number)
    color_emoji = {"red": "🔴", "black": "⚫", "green": "🟢"}.get(color, "⚪")
    user_results = []
    boost_msgs = []
    jackpot_winner = None
    jackpot_amount = 0
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                for uid, name, bets in all_bets:
                    user_bet = sum(b["amount"] for b in bets)
                    user_win = 0
                    for b in bets:
                        mult = get_bet_multiplier(b, number)
                        if mult > 0:
                            user_win += b["amount"] * mult
                    # Бусты
                    total_boost = 0
                    boost_parts = []
                    if user_win > 0:
                        try:
                            craft_boost = craft_get_win_boost(uid)
                            if craft_boost > 0:
                                total_boost += craft_boost
                                boost_parts.append("крафт +" + str(craft_boost) + "%")
                        except Exception as e:
                            print("⚠️ craft win boost: " + str(e))
                        house_bonus, _house = get_user_house_bonus(uid)
                        if house_bonus > 0:
                            total_boost += house_bonus
                            boost_parts.append("дом +" + str(house_bonus) + "%")
                        try:
                            rboost = get_roulette_boost(uid)
                            if rboost["percent"] > 0:
                                total_boost += rboost["percent"]
                                boost_parts.append("магазин +" + str(rboost["percent"]) + "%")
                        except Exception as e:
                            print("⚠️ fcshop roulette boost: " + str(e))
                        if total_boost > 0:
                            user_win = int(user_win * (100 + total_boost) / 100)
                            boost_msgs.append("💎 " + get_display_name(uid) + ": " + " + ".join(boost_parts) + " = +" + str(total_boost) + "%")
                    # Джекпот
                    with JACKPOT_LOCK:
                        if random.random() < JACKPOT_CHANCE:
                            ok_jp, _, _ = add_balance(uid, JACKPOT_AMOUNT)
                            if ok_jp:
                                c.execute("UPDATE users SET jackpot_won = COALESCE(jackpot_won, 0) + 1 WHERE user_id = ?",
                                          (uid,))
                                add_transaction(uid, JACKPOT_AMOUNT, "jackpot_win", "roulette", "💎 ДЖЕКПОТ")
                                jackpot_winner = uid
                                jackpot_amount = JACKPOT_AMOUNT
                                try:
                                    send_message(uid,
                                                 "💎💎💎 <b>ДЖЕКПОТ!</b>\n\n"
                                                 "🎰 Ты выиграл ДЖЕКПОТ в рулетке!\n"
                                                 "💰 +" + format(JACKPOT_AMOUNT) + "\n\n"
                                                 "🏆 Поздравляем!")
                                except Exception:
                                    pass
                    # Начисление выигрыша (обрезаем до MAX_BALANCE)
                    if user_win > 0:
                        cur_bal = get_balance(uid)
                        new_val = cur_bal + user_win
                        if new_val > MAX_BALANCE:
                            new_val = MAX_BALANCE
                            user_win = new_val - cur_bal
                        save_balance(uid, new_val)
                        add_transaction(uid, user_win, "roulette_win", "roulette", "chat " + str(chat_id))
                    per_bet_results = []
                    for b in bets:
                        mult = get_bet_multiplier(b, number)
                        if mult > 0:
                            win_amt = b["amount"] * mult
                            per_bet_results.append((b, win_amt))
                        else:
                            per_bet_results.append((b, 0))
                    user_results.append((uid, name, bets, per_bet_results, user_bet, user_win))
                c.execute("DELETE FROM roulette_bets WHERE chat_id = ?", (chat_id,))
                conn.commit()
    except Exception as e:
        print("⚠️ rl_spin_common: " + str(e))
    add_roulette_result(chat_id, number, color)
    for uid, name, bets, per_bet_results, user_bet, user_win in user_results:
        if user_win > 0:
            update_title_stats(uid, wins=1, won_amount=user_win)
        if user_win < user_bet:
            update_title_stats(uid, losses=1 if user_win == 0 else 0, lost_amount=user_bet - user_win)
        try:
            save_last_bets(uid, bets)
        except Exception:
            pass
        with player_bet_cooldown_lock:
            cd = player_bet_cooldown.get(uid)
            if cd and cd.get("chat_id") == chat_id:
                player_bet_cooldown.pop(uid, None)
        with roulette_pending_lock:
            roulette_pending_expire.pop((uid, chat_id), None)

    # Дроп ресурсов
    craft_drop_msgs = []
    for uid, name, bets, per_bet_results, user_bet, user_win in user_results:
        try:
            dropped = craft_roll_drop(uid, user_win > 0)
            if dropped:
                parts = []
                if dropped.get("wood"):
                    parts.append("🪵 " + str(dropped["wood"]))
                if dropped.get("iron"):
                    parts.append("⛏ " + str(dropped["iron"]))
                if dropped.get("diamond"):
                    parts.append("💎 " + str(dropped["diamond"]))
                if parts:
                    craft_drop_msgs.append("🎁 " + get_display_name(uid) + ": " + " | ".join(parts))
        except Exception as e:
            print("⚠️ craft drop: " + str(e))

    def user_link(uid, name):
        safe_name = esc(name)
        return '<a href="tg://user?id=' + str(uid) + '">' + safe_name + '</a>'

    lines = ["🎰 Рулетка " + str(number) + color_emoji, ""]
    for uid, name, bets, per_bet_results, user_bet, user_win in user_results:
        link = user_link(uid, name)
        for b in bets:
            lines.append(link + " ставка " + format(b["amount"]) + " на " + b["label"])
    lines.append("")
    for uid, name, bets, per_bet_results, user_bet, user_win in user_results:
        link = user_link(uid, name)
        for b, win_amt in per_bet_results:
            if win_amt > 0:
                lines.append(link + " ставка " + format(b["amount"]) + " выиграл " + format(win_amt) + " на " + b["label"])
    if jackpot_winner:
        lines.append("")
        lines.append("💎💎💎 ДЖЕКПОТ! " + user_link(jackpot_winner, get_display_name(jackpot_winner)) +
                     " выиграл " + format(jackpot_amount) + "!!!")
    if boost_msgs:
        lines.append("")
        lines.append("💎 БУСТЫ:")
        for bm in boost_msgs:
            lines.append(bm)
    if craft_drop_msgs:
        lines.append("")
        lines.append("🛠 РЕСУРСЫ:")
        for dm in craft_drop_msgs:
            lines.append(dm)

    MAX_LEN = 3800
    chunks = []
    current_chunk = []
    current_len = 0
    for line in lines:
        line_len = len(line) + 1
        if current_len + line_len > MAX_LEN and current_chunk:
            chunks.append("\n".join(current_chunk))
            current_chunk = [line]
            current_len = line_len
        else:
            current_chunk.append(line)
            current_len += line_len
    if current_chunk:
        chunks.append("\n".join(current_chunk))

    total_chunks = len(chunks)
    for i, chunk in enumerate(chunks):
        if i == total_chunks - 1:
            kb = {"inline_keyboard": [[
                {"text": "🔁 ПОВТОРИТЬ", "callback_data": "rl_rep_" + str(chat_id)},
                {"text": "x2", "callback_data": "rl_rep2_" + str(chat_id)}
            ]]}
            send_message(chat_id, chunk, kb)
        else:
            send_message(chat_id, chunk, None)
            time.sleep(0.3)

    rl_clear_active_round(chat_id)


def rl_repeat_in_chat(chat_id, user_id, multiplier=1):
    """✅ BIG-INT: amount пишется через big_normalize.
    ✅ НОВОЕ: хук FRIK PASS на повторные ставки."""
    last_bets, _ = get_last_bets(user_id)
    if not last_bets:
        send_message(chat_id, "❌ Нет последних ставок!")
        return
    current_count = get_bets_count_in_chat(user_id, chat_id)
    if current_count + len(last_bets) > MAX_ROULETTE_BETS:
        send_message(chat_id, "❌ Лимит ставок!")
        return
    new_bets = []
    total_new = 0
    for b in last_bets:
        amt = int(b["amount"] * multiplier)
        if amt < 100:
            amt = 100
        nb = dict(b)
        nb["amount"] = amt
        new_bets.append(nb)
        total_new += amt
    balance = get_balance(user_id)
    if total_new > balance:
        send_message(chat_id, "❌ Недостаточно! Поинты: " + format(balance))
        return
    ok, new_bal, reason = sub_balance(user_id, total_new)
    if not ok:
        send_message(chat_id, "❌ " + reason)
        return
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                for b in new_bets:
                    c.execute("""INSERT INTO roulette_bets
                                 (user_id, amount, bet_type, bet_from, bet_to, bet_number, label, chat_id)
                                 VALUES (?, ?, ?, ?, ?, ?, ?, ?)""",
                              (user_id, big_normalize(b["amount"]), b["type"], b.get("from"), b.get("to"),
                               b.get("number"), b.get("label", "?"), chat_id))
                conn.commit()
    except Exception as e:
        add_balance(user_id, total_new)
        send_message(chat_id, "❌ Ошибка: " + str(e))
        return
    add_transaction(user_id, -total_new, "roulette_bet_reserve", "roulette",
                    "Резерв под повтор (chat " + str(chat_id) + ")")
    rl_save_pending_expire(user_id, chat_id, ROULETTE_PENDING_SEC)

    # ✅ НОВОЕ: хук FRIK PASS на повтор
    try:
        rl_try_fp_hook(user_id, total_new)
    except Exception as _e:
        print("⚠️ fp hook repeat: " + str(_e))

    # ✅ ФИКС: урезаем + send_long_message
    shown = new_bets[:20]
    lines = "\n".join(["  " + format(b["amount"]) + " → " + b["label"] for b in shown])
    if len(new_bets) > 20:
        lines += "\n  ... и ещё " + str(len(new_bets) - 20) + " ставок"
    msg_text = ("🔁 Ставки x" + str(multiplier) + "!\n\n" + lines +
                "\n\n💎 Поинты: " + format(get_balance(user_id)) +
                "\n\nНапиши: Го")
    send_long_message(chat_id, msg_text)


def repeat_bets(chat_id, user_id, multiplier=1):
    rl_repeat_in_chat(chat_id, user_id, multiplier)


def clear_roulette_bets(chat_id, user_id):
    """✅ BIG-INT: возврат через add_balance."""
    try:
        bets = get_user_bets_in_chat(user_id, chat_id)
        total_refund = sum(b["amount"] for b in bets)
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("DELETE FROM roulette_bets WHERE user_id = ? AND chat_id = ?",
                          (user_id, chat_id))
                conn.commit()
        if total_refund > 0:
            add_balance(user_id, total_refund)
            add_transaction(user_id, total_refund, "roulette_clear_refund", "roulette",
                            "Возврат при очистке ставок")
        with roulette_pending_lock:
            roulette_pending_expire.pop((user_id, chat_id), None)
        with player_bet_cooldown_lock:
            cd = player_bet_cooldown.get(user_id)
            if cd and cd.get("chat_id") == chat_id:
                player_bet_cooldown.pop(user_id, None)
        msg = "🧹 Ставки очищены!"
        if total_refund > 0:
            msg += "\n💰 Возврат: " + format(total_refund)
        send_message(chat_id, msg, roulette_keyboard(user_id))
    except Exception as e:
        send_message(chat_id, "❌ " + str(e))


def show_my_bets(chat_id, user_id):
    bets = get_user_bets_in_chat(user_id, chat_id)
    if not bets:
        send_message(chat_id, "Ставок нет (0/" + str(MAX_ROULETTE_BETS) + ")", roulette_keyboard(user_id))
        return
    total = sum(b["amount"] for b in bets)
    text = "📋 ТВОИ СТАВКИ (" + str(len(bets)) + "/" + str(MAX_ROULETTE_BETS) + ")\n\n"
    for i, b in enumerate(bets, 1):
        text += str(i) + ". " + format(b["amount"]) + " → " + b["label"] + "\n"
    text += "\n💰 Итого: " + format(total)
    # ✅ ФИКС: send_long_message вместо send_message
    send_long_message(chat_id, text, roulette_keyboard(user_id))


def handle_log(chat_id, message_id, user_id):
    history = get_roulette_history(chat_id, 17)
    if not history:
        text = "🎰 ЛОГ\n\nПусто."
        if message_id:
            edit_message(chat_id, message_id, text, back_keyboard())
        else:
            send_message(chat_id, text, back_keyboard())
        return
    colors = {"red": "🔴", "black": "⚫", "green": "🟢"}
    lines = ["🎰 ЛОГ (последние 17):", ""]
    for n, c in reversed(history):
        lines.append(colors.get(c, "⚪") + " " + str(n))
    text = "\n".join(lines)
    if message_id:
        edit_message(chat_id, message_id, text, back_keyboard())
    else:
        send_message(chat_id, text, back_keyboard())


