def fp_format_time_left(ends_at_str):
    ends = db_parse(ends_at_str)
    if not ends:
        return "?"
    left = int((ends - datetime.now()).total_seconds())
    if left < 0:
        left = 0
    d = left // 86400
    h = (left % 86400) // 3600
    m = (left % 3600) // 60
    if d > 0:
        return str(d) + "д " + str(h) + "ч " + str(m) + "м"
    if h > 0:
        return str(h) + "ч " + str(m) + "м"
    return str(m) + "м"


def fp_pass_label(pass_type):
    if pass_type == "deluxe":
        return "🌟 DELUXE"
    if pass_type == "donate":
        return "💎 DONATE"
    return "🎫 FREE"


def fp_menu_keyboard(user_id=None):
    progress = fp_get_progress(user_id) if user_id else None
    rows = []
    if progress:
        # если есть >= 10 жетонов и уровень <= 30 — кнопка открыть уровень
        if progress["tokens"] >= FP_TOKENS_PER_LEVEL and progress["level"] <= FP_MAX_LEVEL:
            rows.append([{"text": "🔓 ОТКРЫТЬ УРОВЕНЬ (10 🎟)", "callback_data": "fp_open_level"}])
        # забрать всё доступное
        claimed = progress["claimed_levels"].split(",") if progress["claimed_levels"] else []
        claimed = [c for c in claimed if c]
        has_unclaimed = False
        for lvl in range(1, progress["level"] + 1):
            if str(lvl) not in claimed:
                has_unclaimed = True
                break
        if has_unclaimed:
            rows.append([{"text": "🎁 ЗАБРАТЬ ВСЁ", "callback_data": "fp_claim_all"}])
        # покупка пасса
        pt = progress["pass_type"]
        if pt == "free":
            rows.append([{"text": "👑 КУПИТЬ DONATE — " + str(FP_DONATE_PRICE) + " FC",
                          "callback_data": "fp_buy_donate"}])
            rows.append([{"text": "🌟 КУПИТЬ DELUXE — " + str(FP_DELUXE_PRICE) + " FC",
                          "callback_data": "fp_buy_deluxe"}])
        elif pt == "donate":
            rows.append([{"text": "🌟 АПГРЕЙД В DELUXE — " + str(FP_UPGRADE_PRICE) + " FC",
                          "callback_data": "fp_upgrade"}])
    rows.append([{"text": "📋 НАГРАДЫ", "callback_data": "fp_rewards"},
                 {"text": "🏆 ТОП", "callback_data": "fp_top"}])
    rows.append([{"text": "📜 ИСТОРИЯ", "callback_data": "fp_history"},
                 {"text": "🔄 ОБНОВИТЬ", "callback_data": "fp_menu"}])
    rows.append([{"text": "⬅️ НАЗАД", "callback_data": "back"}])
    return {"inline_keyboard": rows}


def fp_rewards_keyboard(user_id=None):
    """Список уровней 1..30 + пост-гейм."""
    progress = fp_get_progress(user_id) if user_id else None
    claimed = []
    cur_level = 0
    if progress:
        claimed = progress["claimed_levels"].split(",") if progress["claimed_levels"] else []
        claimed = [c for c in claimed if c]
        cur_level = progress["level"]
    rows = []
    line = []
    for lvl in range(1, FP_MAX_LEVEL + 1):
        mark = "✅" if str(lvl) in claimed else ("🟢" if lvl <= cur_level else "🔒")
        label = mark + " " + str(lvl)
        line.append({"text": label, "callback_data": "fp_view_lvl_" + str(lvl)})
        if len(line) == 5:
            rows.append(line)
            line = []
    if line:
        rows.append(line)
    # пост-гейм
    if progress and progress["level"] > FP_MAX_LEVEL:
        rows.append([{"text": "🌟 ПОСТ-ГЕЙМ (50 🎟 = +1)", "callback_data": "fp_post_game"}])
    rows.append([{"text": "⬅️ НАЗАД", "callback_data": "fp_menu"}])
    return {"inline_keyboard": rows}


def fp_reward_view_keyboard(user_id, level):
    progress = fp_get_progress(user_id) if user_id else None
    claimed = []
    cur_level = 0
    if progress:
        claimed = progress["claimed_levels"].split(",") if progress["claimed_levels"] else []
        claimed = [c for c in claimed if c]
        cur_level = progress["level"]
    rows = []
    if (str(level) not in claimed) and level <= cur_level and level <= FP_MAX_LEVEL:
        rows.append([{"text": "🎁 ЗАБРАТЬ", "callback_data": "fp_claim_lvl_" + str(level)}])
    rows.append([{"text": "⬅️ НАЗАД", "callback_data": "fp_rewards"}])
    return {"inline_keyboard": rows}


def fp_menu(chat_id, message_id, user_id):
    progress = fp_get_progress(user_id)
    if not progress:
        send_message(chat_id, "❌ FRIK PASS сейчас недоступен (нет активного сезона).", back_keyboard())
        return
    level = progress["level"]
    tokens = progress["tokens"]
    tokens_total = progress["tokens_total"]
    bets = progress["bets_count"]
    pass_type = progress["pass_type"]
    claimed = progress["claimed_levels"].split(",") if progress["claimed_levels"] else []
    claimed = [c for c in claimed if c]

    # прогресс-бар
    if level <= FP_MAX_LEVEL:
        needed = FP_TOKENS_PER_LEVEL
        cur = min(tokens, needed)
        bar_len = 12
        filled = int(bar_len * cur / needed) if needed > 0 else 0
        bar = "█" * filled + "░" * (bar_len - filled)
        pct = int(100 * cur / needed) if needed > 0 else 100
        level_line = "📊 Уровень: " + str(level) + " / " + str(FP_MAX_LEVEL)
        bar_line = "[" + bar + "] " + str(pct) + "%"
    else:
        # пост-гейм
        bonus = progress["bonus_levels"]
        till_next = FP_POST_GAME_TOKEN_STEP - (tokens_total % FP_POST_GAME_TOKEN_STEP)
        if till_next == FP_POST_GAME_TOKEN_STEP:
            till_next = 0
        level_line = "📊 Уровень: " + str(level) + " (пост-гейм)"
        bar_line = "🌟 Бонусных уровней: " + str(bonus) + " | до след.: " + str(till_next) + " 🎟"

    # доступно наград
    available = 0
    for lvl in range(1, min(level, FP_MAX_LEVEL) + 1):
        if str(lvl) not in claimed:
            available += 1

    text = "🎫 <b>FRIK PASS — СЕЗОН " + str(progress["season_number"]) + "</b>\n"
    text += "⏰ До конца: " + fp_format_time_left(progress["ends_at"]) + "\n"
    text += level_line + "\n"
    text += "🎟 Жетоны: " + str(tokens) + " / " + str(FP_TOKENS_PER_LEVEL) + "\n"
    text += "📈 Ставок ≥10KKK: " + str(bets) + "\n"
