def fp_view_level(chat_id, message_id, user_id, level):
    progress = fp_get_progress(user_id)
    if not progress:
        send_message(chat_id, "❌ FRIK PASS недоступен.", back_keyboard())
        return
    if level < 1 or level > FP_MAX_LEVEL:
        send_message(chat_id, "❌ Уровень 1-30.")
        return
    rewards = FP_REWARDS.get(level, {})
    free_r = rewards.get("free", {})
    donate_r = rewards.get("donate", {})

    def fmt_reward(r):
        if not r:
            return "  —"
        parts = []
        if r.get("points"):
            parts.append("💰 " + format(r["points"]))
        if r.get("frik"):
            parts.append("💎 " + str(r["frik"]) + " FC")
        if r.get("reputation"):
            parts.append("⭐ " + str(r["reputation"]))
        if r.get("wood"):
            parts.append("🪵 " + str(r["wood"]))
        if r.get("iron"):
            parts.append("⛏ " + str(r["iron"]))
        if r.get("diamond"):
            parts.append("💎 " + str(r["diamond"]))
        if r.get("title"):
            t = TITLES.get(r["title"], {})
            parts.append(t.get("name", r["title"]))
        if r.get("title_custom"):
            parts.append("✨ " + str(r["title_custom"]))
        if r.get("boost_percent"):
            parts.append("🎯 +" + str(r["boost_percent"]) + "% / " + str(r.get("boost_days", 0)) + "д")
        if r.get("immunity_apteka_days"):
            parts.append("💊 " + str(r["immunity_apteka_days"]) + "д")
        if r.get("immunity_bolnitsa_days"):
            parts.append("🩺 " + str(r["immunity_bolnitsa_days"]) + "д")
        if r.get("case"):
            parts.append("🎁 " + str(r["case"]))
        if r.get("deluxe_points"):
            parts.append("🌟 +" + format(r["deluxe_points"]))
        return "\n     ".join(parts) if parts else "  —"

    claimed = progress["claimed_levels"].split(",") if progress["claimed_levels"] else []
    claimed = [c for c in claimed if c]
    is_claimed = str(level) in claimed

    text = "🎫 <b>НАГРАДА — УРОВЕНЬ " + str(level) + "</b>\n\n"
    text += "🎫 <b>FREE:</b>\n     " + fmt_reward(free_r) + "\n\n"
    text += "👑 <b>DONATE / DELUXE:</b>\n     " + fmt_reward(donate_r) + "\n\n"
    if is_claimed:
        text += "✅ Уже получена"
    elif level > progress["level"]:
        text += "🔒 Ещё закрыта (нужен уровень " + str(level) + ")"
    else:
        text += "🟢 Можно забрать!"

    kb = fp_reward_view_keyboard(user_id, level)
    if message_id:
        edit_message(chat_id, message_id, text, kb)
    else:
        send_long_message(chat_id, text, kb)


