def spam_check(user_id):
    if user_id == ADMIN_ID:
        return False
    try:
        with SPAM_LOCK:
            now = time.time()
            data = user_spam.get(user_id)
            if not data:
                data = {"messages": [], "banned_until": 0}
                user_spam[user_id] = data
            if data.get("banned_until", 0) > now:
                return True
            if data.get("banned_until", 0) > 0 and data["banned_until"] <= now:
                data["banned_until"] = 0
                data["messages"] = []
            data["messages"] = [t for t in data["messages"] if now - t < SPAM_WINDOW_SEC]
            data["messages"].append(now)
            if len(data["messages"]) > SPAM_LIMIT:
                data["banned_until"] = now + SPAM_BAN_MIN * 60
                data["messages"] = []
                print("🚨 АНТИСПАМ: " + str(user_id))
                return True
            return False
    except Exception as e:
        print("⚠️ spam_check: " + str(e))
        return False


def spam_cleanup_worker():
    while not scheduler_stop.is_set():
        try:
            now = time.time()
            with SPAM_LOCK:
                to_del = []
                for uid, data in user_spam.items():
                    ban = data.get("banned_until", 0)
                    msgs = data.get("messages", [])
                    if ban and ban > now:
                        continue
                    if not msgs and not ban:
                        to_del.append(uid)
                        continue
                    recent = [t for t in msgs if now - t < SPAM_WINDOW_SEC]
                    if not recent and not ban:
                        to_del.append(uid)
                for uid in to_del:
                    user_spam.pop(uid, None)
        except Exception as e:
            print("⚠️ spam_cleanup: " + str(e))
        time.sleep(300)


def fake_get_status(user_id):
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT last_try, fake_banned_until FROM fake_money_log WHERE user_id = ?", (user_id,))
                r = c.fetchone()
                if r:
                    return (db_parse(r["last_try"]), db_parse(r["fake_banned_until"]))
                return (None, None)
    except Exception:
        return (None, None)


def fake_is_banned(user_id):
    try:
        _, banned_until = fake_get_status(user_id)
        if banned_until and banned_until > datetime.now():
            return True
        return False
    except Exception:
        return False


def fake_get_ban_time_left(user_id):
    try:
        _, banned_until = fake_get_status(user_id)
        if banned_until and banned_until > datetime.now():
            return int((banned_until - datetime.now()).total_seconds())
        return 0
    except Exception:
        return 0


def fake_unban(user_id):
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("UPDATE fake_money_log SET fake_banned_until = NULL WHERE user_id = ?",
                          (user_id,))
                conn.commit()
        return True
    except Exception:
        return False


def handle_fake_money(chat_id, message_id, user_id):
    if is_left(user_id):
        send_message(chat_id, "❌ Ты ушёл!")
        return
    if fake_is_banned(user_id):
        left = fake_get_ban_time_left(user_id)
        m = left // 60
        s = left % 60
        send_message(chat_id, "🚔 ТЫ В РОЗЫСКЕ!\n\nОсталось: " + str(m) + "м " + str(s) + "с")
        return
    last_try, _ = fake_get_status(user_id)
    if last_try:
        diff = (datetime.now() - last_try).total_seconds()
        if diff < FAKE_COOLDOWN:
            left = FAKE_COOLDOWN - int(diff)
            m = left // 60
            s = left % 60
            send_message(chat_id, "⏰ Подожди: " + str(m) + "м " + str(s) + "с")
            return
    # Списание через big-int
    ok, new_bal, reason = sub_balance(user_id, FAKE_COST)
    if not ok:
        send_message(chat_id, "❌ Нужно " + format(FAKE_COST) + "!\n" + reason)
        return
    add_transaction(user_id, -FAKE_COST, "fake_money_cost", "fake", "Взнос")
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("INSERT OR REPLACE INTO fake_money_log (user_id, last_try, fake_banned_until) VALUES (?, ?, ?)",
                          (user_id, db_now(), None))
                conn.commit()
    except Exception as e:
        add_balance(user_id, FAKE_COST)
        send_message(chat_id, "❌ " + str(e))
        return
    success = random.randint(1, 100) <= FAKE_CHANCE
    if success:
        reward = random.randint(FAKE_MIN, FAKE_MAX)
        ok, new_bal, reason = add_balance(user_id, reward)
        if not ok:
            # Превышен лимит — обрезаем до максимума
            reward = MAX_BALANCE - get_balance(user_id)
            if reward > 0:
                save_balance(user_id, MAX_BALANCE)
            send_message(chat_id, "🖨 ФАЛЬШИВКИ!\n\n💰 Баланс достиг максимума")
            return
        add_transaction(user_id, reward, "fake_money_win", "fake", "Успех")
        send_message(chat_id, "🖨 ФАЛЬШИВКИ!\n\n💰 +" + format(reward) + "\n💎 " + format(new_bal))
    else:
        ban_until = (datetime.now() + timedelta(minutes=FAKE_BAN_MIN)).strftime(DB_DATE_FMT)
        try:
            with DB_LOCK:
                with _conn() as conn:
                    c = conn.cursor()
                    c.execute("UPDATE fake_money_log SET fake_banned_until = ? WHERE user_id = ?",
                              (ban_until, user_id))
                    conn.commit()
        except Exception as e:
            send_message(chat_id, "❌ " + str(e))
            return
        send_message(chat_id, "🚔 ТЕБЯ ПОЙМАЛИ!\n\n⛔ Игры заблокированы на " + str(FAKE_BAN_MIN) + " минут")
        try:
            send_message(ADMIN_ID, "🚔 ФАЛЬШИВКИ ПРОВАЛ\n" + get_display_name(user_id) + " (ID:" + str(user_id) + ")")
        except Exception:
            pass


def handle_unban_fake_cmd(chat_id, user_id, args):
    if not is_admin(user_id):
        send_message(chat_id, "❌ Нет прав!")
        return
    if len(args) != 1:
        send_message(chat_id, "❌ Формат: /unban_fake ID|@username")
        return
    target_id = shield_resolve_id(args[0])
    if not target_id:
        send_message(chat_id, "❌ Игрок не найден!")
        return
    if get_user(target_id) is None:
        send_message(chat_id, "❌ Игрок не писал /start")
        return
    was_banned = fake_is_banned(target_id)
    if fake_unban(target_id):
        name = get_display_name(target_id)
        if was_banned:
            send_message(chat_id, "✅ Снят бан фальшивок с " + str(name) + " (" + str(target_id) + ")")
        else:
            send_message(chat_id, "ℹ️ Игрок " + str(name) + " не был в бане. Запись сброшена.")
    else:
        send_message(chat_id, "❌ Ошибка!")


