def family_buy_house(chat_id, user_id, house_key):
    if house_key not in FAMILY_HOUSES:
        send_message(chat_id, "❌ Неверный дом!")
        return
    fam = get_user_family(user_id)
    if not fam:
        send_message(chat_id, "❌ Ты не в семье!")
        return
    if fam["owner_id"] != user_id:
        send_message(chat_id, "❌ Только владелец может купить дом!")
        return
    house = FAMILY_HOUSES[house_key]
    price = house["price"]
    cur_ht = fam["house_type"] if "house_type" in fam.keys() else ""
    if cur_ht == house_key:
        send_message(chat_id, "❌ У тебя уже этот дом!")
        return
    ok, new_bal, reason = sub_balance(user_id, price)
    if not ok:
        send_message(chat_id, "❌ Нужно " + format(price) + "\n" + reason)
        return
    try:
        with HOUSE_LOCK:
            with DB_LOCK:
                with _conn() as conn:
                    c = conn.cursor()
                    c.execute("""UPDATE families SET house_type = ?, house_bought_at = ?
                                 WHERE id = ?""",
                              (house_key, db_now(), fam["id"]))
                    conn.commit()
        add_transaction(user_id, -price, "family_house_buy", "family",
                        "Дом " + house["name"])
        msg = ("✅ ДОМ КУПЛЕН!\n\n"
               "🏠 " + house["name"] + "\n"
               "💰 −" + format(price) + "\n"
               "🎁 Бонус: +" + str(house["bonus"]) + "% к рулетке (первым " + str(house["slots"]) + ")\n")
        if house["star_mult"] > 1.0:
            msg += "⭐ x" + str(house["star_mult"]) + " к репутации/час\n"
        msg += "\n💎 Поинты: " + format(new_bal)
        send_message(chat_id, msg)
        if house_key == "otel":
            try:
                award_title(user_id, "domovoy")
            except Exception:
                pass
        try:
            members = get_family_members(fam["id"])
            for m in members:
                if m != user_id:
                    try:
                        send_message(m, "🏠 Семья купила дом: " + house["name"])
                    except Exception:
                        pass
        except Exception:
            pass
    except Exception as e:
        add_balance(user_id, price)
        send_message(chat_id, "❌ " + str(e))


def handle_family_house_menu(chat_id, message_id, user_id):
    fam = get_user_family(user_id)
    if not fam:
        send_message(chat_id, "❌ Ты не в семье!")
        return
    cur_ht = fam["house_type"] if "house_type" in fam.keys() else ""
    cur_house = FAMILY_HOUSES.get(cur_ht) if cur_ht else None
    text = "🏠 СЕМЕЙНЫЙ ДОМ\n\n"
    if cur_house:
        text += "Текущий: " + cur_house["name"] + "\n"
        text += "🎁 Бонус: +" + str(cur_house["bonus"]) + "% к рулетке\n"
        text += "👥 Слотов: " + str(cur_house["slots"]) + "\n"
        if cur_house["star_mult"] > 1.0:
            text += "⭐ x" + str(cur_house["star_mult"]) + " к репутации/час\n"
    else:
        text += "У семьи нет дома.\n\n"
    text += "\n📋 ДОСТУПНЫЕ ДОМА:\n\n"
    for k, h in FAMILY_HOUSES.items():
        text += h["name"] + " — " + format(h["price"]) + "\n"
        text += "  🎁 +" + str(h["bonus"]) + "% к рулетке (первым " + str(h["slots"]) + ")\n"
        if h["star_mult"] > 1.0:
            text += "  ⭐ x" + str(h["star_mult"]) + " к репутации/час\n"
        text += "\n"
    text += "⚠️ Купить дом может только владелец."
    rows = []
    if fam["owner_id"] == user_id:
        for k, h in FAMILY_HOUSES.items():
            if k == cur_ht:
                continue
            rows.append([{"text": h["name"] + " — " + format(h["price"]),
                          "callback_data": "fam_house_buy_" + k}])
    rows.append([{"text": "⬅️ НАЗАД", "callback_data": "family_menu"}])
    kb = {"inline_keyboard": rows}
    if message_id:
        edit_message(chat_id, message_id, text, kb)
    else:
        send_message(chat_id, text, kb)


def invite_to_family(chat_id, inviter_id, invited_id):
    fam = get_user_family(inviter_id)
    if not fam:
        return False, "❌ Ты не в семье!"
    if fam["owner_id"] != inviter_id:
        return False, "❌ Только владелец!"
    if get_user_family(invited_id):
        return False, "❌ Игрок уже в семье!"
    if get_family_member_count(fam["id"]) >= FAMILY_MAX_MEMBERS:
        return False, "❌ Максимум " + str(FAMILY_MAX_MEMBERS) + "!"
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("""SELECT id FROM family_invites
                             WHERE family_id = ? AND invited = ? AND status = 'pending'""",
                          (fam["id"], invited_id))
                if c.fetchone():
                    return False, "❌ Уже приглашён!"
                c.execute("""INSERT INTO family_invites (family_id, inviter, invited, status)
                             VALUES (?, ?, ?, 'pending')""",
                          (fam["id"], inviter_id, invited_id))
                invite_id = c.lastrowid
                conn.commit()
        kb = {"inline_keyboard": [
            [{"text": "✅ ПРИНЯТЬ", "callback_data": "fam_inv_accept_" + str(invite_id)}],
            [{"text": "❌ ОТКАЗАТЬ", "callback_data": "fam_inv_decline_" + str(invite_id)}],
        ]}
        text = ("🏠 ПРИГЛАШЕНИЕ\n\n" + "📛 " + str(fam["name"]) + "\n" +
                "👤 " + get_display_name(inviter_id) + "\n\n" +
                "👥 " + str(get_family_member_count(fam["id"])) + "/" + str(FAMILY_MAX_MEMBERS))
        try:
            send_message(invited_id, text, kb)
        except Exception:
            pass
        return True, "✅ Отправлено!"
    except Exception as e:
        return False, "❌ " + str(e)


def accept_family_invite(chat_id, user_id, invite_id):
    try:
        with FAMILY_LOCK:
            with DB_LOCK:
                with _conn() as conn:
                    c = conn.cursor()
                    c.execute("""SELECT family_id, invited, status FROM family_invites WHERE id = ?""", (invite_id,))
                    r = c.fetchone()
                    if not r:
                        return False, "❌ Не найдено!"
                    if r["invited"] != user_id:
                        return False, "❌ Не твоё!"
                    if r["status"] != "pending":
                        return False, "❌ Уже обработано!"
                    fam = get_family_by_id(r["family_id"])
                    if not fam:
                        return False, "❌ Семьи нет!"
                    if get_user_family(user_id):
                        return False, "❌ Ты уже в семье!"
                    if get_family_member_count(fam["id"]) >= FAMILY_MAX_MEMBERS:
                        return False, "❌ Заполнено!"
                    c.execute("UPDATE family_invites SET status = 'accepted' WHERE id = ?", (invite_id,))
                    c.execute("INSERT OR REPLACE INTO family_members (user_id, family_id) VALUES (?, ?)",
                              (user_id, fam["id"]))
                    conn.commit()
        try:
            send_message(fam["owner_id"], "✅ " + get_display_name(user_id) + " в семье " + str(fam["name"]))
        except Exception:
            pass
        return True, "✅ Ты в семье " + str(fam["name"]) + "!"
    except Exception as e:
        return False, "❌ " + str(e)


