def create_family_duel(chat_id, challenger_owner, opponent_owner, stake):
    if challenger_owner == opponent_owner:
        return False, "❌ Себя нельзя!"
    if stake < 1:
        return False, "❌ Минимум 1!"
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT id, name, reputation, last_duel FROM families WHERE owner_id = ?", (challenger_owner,))
                fam1 = c.fetchone()
                if not fam1:
                    return False, "❌ Ты не владелец!"
                c.execute("SELECT id, name, reputation FROM families WHERE owner_id = ?", (opponent_owner,))
                fam2 = c.fetchone()
                if not fam2:
                    return False, "❌ Он не владелец!"
                if (fam1["reputation"] or 0) < stake:
                    return False, "❌ У тебя мало репутации!"
                if (fam2["reputation"] or 0) < stake:
                    return False, "❌ У него мало репутации!"
                last = db_parse(fam1["last_duel"]) if fam1["last_duel"] else None
                if last and (datetime.now() - last).total_seconds() < FAMILY_DUEL_COOLDOWN:
                    left = FAMILY_DUEL_COOLDOWN - int((datetime.now() - last).total_seconds())
                    return False, "❌ Кулдаун: " + str(left) + "с"
                c.execute("""SELECT id FROM family_duels
                             WHERE status IN ('pending','processing')
                             AND (challenger_family IN (?, ?) OR opponent_family IN (?, ?))""",
                          (fam1["id"], fam2["id"], fam1["id"], fam2["id"]))
                if c.fetchone():
                    return False, "❌ Уже есть активная дуэль!"
                c.execute("""INSERT INTO family_duels
                             (challenger_family, opponent_family, challenger_owner, opponent_owner, stake, status)
                             VALUES (?, ?, ?, ?, ?, 'pending')""",
                          (fam1["id"], fam2["id"], challenger_owner, opponent_owner, stake))
                duel_id = c.lastrowid
                conn.commit()
        kb = {"inline_keyboard": [
            [{"text": "✅ ПРИНЯТЬ", "callback_data": "fam_duel_accept_" + str(duel_id)}],
            [{"text": "❌ ОТКАТЬ", "callback_data": "fam_duel_decline_" + str(duel_id)}],
        ]}
        text = ("⚔️ ВЫЗОВ!\n\n" + "🏠 " + str(fam1["name"]) + " vs " + str(fam2["name"]) +
                "\n⭐ " + str(stake) + " репутации")
        try:
            send_message(opponent_owner, text, kb)
        except Exception:
            pass
        return True, "✅ Вызов отправлен!"
    except Exception as e:
        return False, "❌ " + str(e)


def accept_family_duel(chat_id, user_id, duel_id):
    try:
        with FAMILY_LOCK:
            with DB_LOCK:
                with _conn() as conn:
                    c = conn.cursor()
                    c.execute("UPDATE family_duels SET status = 'processing' WHERE id = ? AND status = 'pending'", (duel_id,))
                    if c.rowcount == 0:
                        conn.rollback()
                        return False, "❌ Не найдено!"
                    c.execute("SELECT * FROM family_duels WHERE id = ?", (duel_id,))
                    d = c.fetchone()
                    if d["opponent_owner"] != user_id:
                        conn.rollback()
                        return False, "❌ Не твой вызов!"
                    fam1 = get_family_by_id(d["challenger_family"])
                    fam2 = get_family_by_id(d["opponent_family"])
                    if not fam1 or not fam2:
                        conn.rollback()
                        return False, "❌ Семья исчезла!"
                    stake = d["stake"]
                    if (fam1["reputation"] or 0) < stake or (fam2["reputation"] or 0) < stake:
                        c.execute("UPDATE family_duels SET status = 'cancelled' WHERE id = ?", (duel_id,))
                        conn.commit()
                        return False, "❌ Недостаточно репутации!"
                    winner_family = random.choice([fam1["id"], fam2["id"]])
                    if winner_family == fam1["id"]:
                        c.execute("UPDATE families SET reputation = reputation - ? WHERE id = ?", (stake, fam2["id"]))
                        c.execute("UPDATE families SET reputation = reputation + ? WHERE id = ?", (stake, fam1["id"]))
                        winner_name = fam1["name"]
                    else:
                        c.execute("UPDATE families SET reputation = reputation - ? WHERE id = ?", (stake, fam1["id"]))
                        c.execute("UPDATE families SET reputation = reputation + ? WHERE id = ?", (stake, fam2["id"]))
                        winner_name = fam2["name"]
                    c.execute("UPDATE family_duels SET status = 'finished', winner_family = ?, ended_at = ? WHERE id = ?",
                              (winner_family, db_now(), duel_id))
                    c.execute("UPDATE families SET last_duel = ? WHERE id IN (?, ?)",
                              (db_now(), fam1["id"], fam2["id"]))
                    conn.commit()
        text = ("⚔️ ДУЭЛЬ ЗАВЕРШЕНА!\n\n" + str(fam1["name"]) + " vs " + str(fam2["name"]) +
                "\n⭐ " + str(stake) + "\n🏆 Победитель: " + str(winner_name))
        try:
            send_message(fam1["owner_id"], text)
            send_message(fam2["owner_id"], text)
        except Exception:
            pass
        return True, text
    except Exception as e:
        return False, "❌ " + str(e)


def decline_family_duel(chat_id, user_id, duel_id):
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("""SELECT opponent_owner, status FROM family_duels WHERE id = ?""", (duel_id,))
                r = c.fetchone()
                if not r:
                    return False, "❌ Не найдено!"
                if r["opponent_owner"] != user_id:
                    return False, "❌ Не твоё!"
                if r["status"] != "pending":
                    return False, "❌ Уже обработано!"
                c.execute("UPDATE family_duels SET status = 'declined' WHERE id = ?", (duel_id,))
                conn.commit()
        return True, "❌ Отклонено"
    except Exception as e:
        return False, "❌ " + str(e)


