def is_left(user_id):
    try:
        u = get_user(user_id)
        if u and "is_left" in u.keys() and u["is_left"] == 1:
            return True
        return False
    except Exception:
        return False


def leave_bot(chat_id, user_id):
    if is_left(user_id):
        send_message(chat_id, "❌ Ты уже ушёл!")
        return False
    user = get_user(user_id)
    if not user:
        send_message(chat_id, "❌ Напиши /start")
        return False
    balance = get_balance(user_id) or 0
    username = get_display_name(user_id)
    try:
        fam = get_user_family(user_id)
        if fam:
            if fam["owner_id"] == user_id:
                members = get_family_members(fam["id"])
                delete_family(fam["id"])
                for m in members:
                    if m != user_id:
                        try:
                            send_message(m, "❌ Семья " + str(fam["name"]) + " распущена")
                        except Exception:
                            pass
            else:
                try:
                    leave_family(chat_id, user_id)
                except Exception:
                    pass
    except Exception as e:
        print("⚠️ leave_bot family: " + str(e))
    # Бизнесы на аукцион
    try:
        my_biz = biz_get_by_owner(user_id)
        for b in my_biz:
            if b["biz_type"] in ("mafia", "league"):
                continue
            if b["biz_type"] == "lombard":
                lombard_cancel_all_on_leave(user_id)
            new_end = (datetime.now() + timedelta(hours=BIZ_AUCTION_HOURS)).strftime(DB_DATE_FMT)
            with DB_LOCK:
                with _conn() as conn:
                    c = conn.cursor()
                    c.execute("""UPDATE biz_businesses
                                 SET status = 'auction', auction_end = ?,
                                     current_bet = ?, current_bidder = 0,
                                     seller_id = 0, upgrade_level = 0, min_bet = ?
                                 WHERE id = ?""",
                              (new_end, big_normalize(0), big_normalize(BIZ_MIN_PRICE), b["id"]))
                    conn.commit()
    except Exception as e:
        print("⚠️ leave_bot biz: " + str(e))
    try:
        active = lombard_get_active_loan(user_id)
        if active:
            with DB_LOCK:
                with _conn() as conn:
                    c = conn.cursor()
                    new_end = (datetime.now() + timedelta(hours=BIZ_AUCTION_HOURS)).strftime(DB_DATE_FMT)
                    c.execute("""UPDATE biz_businesses
                                 SET status = 'auction', auction_end = ?,
                                     current_bet = ?, current_bidder = 0,
                                     seller_id = 0, min_bet = ?
                                 WHERE biz_type = ?""",
                              (new_end, big_normalize(0),
                               big_normalize(BIZ_MIN_PRICE), active["biz_type"]))
                    c.execute("""UPDATE lombard_loans
                                 SET status = 'expired', resolved_at = ?
                                 WHERE id = ?""",
                              (db_now(), active["id"]))
                    conn.commit()
    except Exception as e:
        print("⚠️ leave_bot lombard: " + str(e))
    # Освобождаем номера игрока
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("DELETE FROM phones WHERE owner_id = ?", (user_id,))
                conn.commit()
    except Exception as e:
        print("⚠️ leave_bot phones: " + str(e))
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("""INSERT OR REPLACE INTO users_left
                             (user_id, username, balance_at_left, left_at)
                             VALUES (?, ?, ?, ?)""",
                          (user_id, username, big_normalize(balance), db_now()))
                c.execute("UPDATE users SET is_left = 1 WHERE user_id = ?", (user_id,))
                conn.commit()
    except Exception as e:
        print("⚠️ leave_bot db: " + str(e))
    try:
        with TITLE_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("DELETE FROM titles WHERE user_id = ? AND title_key = 'vernuvshiy'", (user_id,))
                c.execute("""INSERT OR IGNORE INTO titles (user_id, title_key)
                             VALUES (?, 'ushliy')""", (user_id,))
                conn.commit()
    except Exception as e:
        print("⚠️ leave_bot title: " + str(e))
    try:
        admin_remove(user_id)
    except Exception as e:
        print("⚠️ leave_bot admin: " + str(e))
    text = ("🍂 " + str(username) + " ПОКИНУЛ ИГРУ\n\n" +
            "💰 Поинты: " + format(balance) + "\n" +
            "🏆 Титул: 🍂 Ушедший\n" +
            "📅 " + datetime.now().strftime("%d.%m.%Y %H:%M"))
    try:
        send_message(chat_id, text)
    except Exception:
        pass
    try:
        t = threading.Thread(target=leave_broadcast, args=(user_id, username, balance), daemon=True)
        t.start()
    except Exception as e:
        print("⚠️ leave_bot broadcast: " + str(e))
    return True


def leave_broadcast(left_user_id, left_username, left_balance):
    try:
        threshold = (datetime.now() - timedelta(days=30)).strftime(DB_DATE_FMT)
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT user_id FROM users WHERE last_active >= ? AND user_id != ?",
                          (threshold, left_user_id))
                users = c.fetchall()
        text = ("🍂 ИГРОК УШЁЛ\n\n" + "👤 " + str(left_username) + "\n" +
                "💰 Поинты: " + format(left_balance) + "\n" +
                "🏆 Титул: 🍂 Ушедший\n\nОн покинул игру.")
        count = 0
        for u_row in users:
            uid = u_row["user_id"]
            try:
                send_message(uid, text)
                count += 1
                time.sleep(0.3)
            except Exception:
                pass
        print("🍂 Рассылка: " + str(count))
    except Exception as e:
        print("⚠️ leave_broadcast: " + str(e))


def unleave_bot(chat_id, admin_id, target_id):
    if not is_admin(admin_id):
        send_message(chat_id, "❌ Нет прав!")
        return False
    if not is_left(target_id):
        send_message(chat_id, "❌ Не ушёл!")
        return False
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("DELETE FROM users_left WHERE user_id = ?", (target_id,))
                c.execute("UPDATE users SET balance = ?, is_left = 0 WHERE user_id = ?",
                          (big_normalize(0), target_id))
                c.execute("DELETE FROM titles WHERE user_id = ? AND title_key = 'ushliy'", (target_id,))
                c.execute("""INSERT OR IGNORE INTO titles (user_id, title_key)
                             VALUES (?, 'vernuvshiy')""", (target_id,))
                conn.commit()
    except Exception as e:
        send_message(chat_id, "❌ " + str(e))
        return False
    send_message(chat_id, "✅ Игрок " + str(target_id) + " возвращён!")
    try:
        send_message(target_id, "⭐ ТЕБЯ ВЕРНУЛИ!\n\nНапиши /start")
    except Exception:
        pass
    return True


def get_top_left(limit=20):
    """✅ BIG-INT: balance_at_left через big_load. Сортировка в Python."""
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("""SELECT user_id, username, balance_at_left, left_at
                             FROM users_left""")
                rows = c.fetchall()
        result = []
        for r in rows:
            result.append({
                "user_id": r["user_id"],
                "username": r["username"],
                "balance_at_left": big_load(r["balance_at_left"]),
                "left_at": r["left_at"],
            })
        result.sort(key=lambda x: x["balance_at_left"], reverse=True)
        return result[:limit]
    except Exception as e:
        print("⚠️ get_top_left: " + str(e))
        return []


