def handle_lombard_owner_stats(chat_id, message_id, user_id):
    """✅ BIG-INT: SUM не работает на TEXT → считаем в Python."""
    biz = biz_get("lombard")
    if not biz or biz["owner_id"] != user_id:
        send_message(chat_id, "❌ Ты не владелец ломбарда!")
        return
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT COUNT(*) as cnt FROM lombard_loans WHERE status = 'active'")
                active_cnt = c.fetchone()["cnt"]
                c.execute("SELECT amount, return_amount, status FROM lombard_loans")
                all_loans = c.fetchall()
        total_cnt = len(all_loans)
        total_amount = 0
        returned_cnt = 0
        profit = 0
        expired_cnt = 0
        for r in all_loans:
            amt = big_load(r["amount"])
            ret = big_load(r["return_amount"])
            total_amount += amt
            if r["status"] == "returned":
                returned_cnt += 1
                profit += (ret - amt)
            elif r["status"] == "expired":
                expired_cnt += 1
        biz_bal = big_load(biz["balance"])
        text = "📊 СТАТИСТИКА ЛОМБАРДА\n\n"
        text += "💰 Поинты бизнеса: " + format(biz_bal) + "\n\n"
        text += "📋 Всего займов: " + str(total_cnt) + "\n"
        text += "💰 Выдано: " + format(total_amount) + "\n"
        text += "✅ Возвращено: " + str(returned_cnt) + "\n"
        text += "💸 Профит: " + format(profit) + "\n"
        text += "⏳ Активных: " + str(active_cnt) + "\n"
        text += "❌ Просрочено: " + str(expired_cnt)
    except Exception as e:
        text = "❌ " + str(e)
    kb = {"inline_keyboard": [[{"text": "⬅️ НАЗАД", "callback_data": "biz_view_lombard"}]]}
    if message_id:
        edit_message(chat_id, message_id, text, kb)
    else:
        send_message(chat_id, text, kb)


