# ========== ЧАСТЬ 13/25: АДВОКАТ + ОБМЕН + ЗАХВАТ + СТАТИСТИКА + 🏠 ДОМА ==========

def advokat_add(owner_id, advokat_id):
    try:
        with ADVOKAT_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT COUNT(*) as cnt FROM advokats WHERE owner_id = ?", (owner_id,))
                cnt = c.fetchone()["cnt"]
                if cnt >= ADVOKAT_MAX:
                    return False, "❌ Максимум " + str(ADVOKAT_MAX) + " адвокатов!"
                c.execute("SELECT user_id FROM advokats WHERE user_id = ?", (advokat_id,))
                if c.fetchone():
                    return False, "❌ Уже адвокат!"
                c.execute("INSERT INTO advokats (user_id, owner_id) VALUES (?, ?)",
                          (advokat_id, owner_id))
                conn.commit()
        return True, "✅ Адвокат нанят!"
    except Exception as e:
        return False, "❌ " + str(e)


def advokat_remove(owner_id, advokat_id):
    try:
        with ADVOKAT_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("DELETE FROM advokats WHERE user_id = ? AND owner_id = ?",
                          (advokat_id, owner_id))
                a = c.rowcount
                conn.commit()
        if a > 0:
            return True, "✅ Адвокат уволен"
        return False, "❌ Не найден!"
    except Exception as e:
        return False, "❌ " + str(e)


def advokat_is_advokat(user_id):
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT owner_id FROM advokats WHERE user_id = ?", (user_id,))
                r = c.fetchone()
                return r["owner_id"] if r else None
    except Exception:
        return None


def advokat_get_owner_advokats(owner_id):
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT user_id, busy_until FROM advokats WHERE owner_id = ?", (owner_id,))
                rows = c.fetchall()
        result = []
        now = datetime.now()
        for r in rows:
            uid = r["user_id"]
            busy = r["busy_until"]
            u = get_user(uid)
            online = False
            if u and u["last_active"]:
                dt = db_parse(u["last_active"])
                if dt and (now - dt).total_seconds() < 300:
                    online = True
            result.append((uid, get_display_name(uid), busy, online))
        return result
    except Exception as e:
        print("⚠️ advokat_get_owner_advokats: " + str(e))
        return []


def advokat_set_busy(advokat_id, seconds=ADVOKAT_BUSY_SEC):
    try:
        until = (datetime.now() + timedelta(seconds=seconds)).strftime(DB_DATE_FMT)
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("UPDATE advokats SET busy_until = ? WHERE user_id = ?", (until, advokat_id))
                conn.commit()
        return True
    except Exception:
        return False


def advokat_is_busy(advokat_id):
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT busy_until FROM advokats WHERE user_id = ?", (advokat_id,))
                r = c.fetchone()
                if not r or not r["busy_until"]:
                    return False
                dt = db_parse(r["busy_until"])
                if dt and dt > datetime.now():
                    return True
                return False
    except Exception:
        return False


def advokat_get_biz():
    return biz_get("advokat")


def advokat_owner():
    biz = advokat_get_biz()
    if not biz:
        return None
    if biz["status"] != "owned":
        return None
    return biz["owner_id"]


def start_advokat_deal_for_thief(thief_id, victim_id, stolen_amount):
    """✅ BIG-INT: frozen_amount → big_normalize."""
    try:
        with ADVOKAT_LOCK:
            with advokat_deals_lock:
                expires_at = (datetime.now() + timedelta(seconds=ADVOKAT_HIRE_WINDOW_SEC)).strftime(DB_DATE_FMT)
                with DB_LOCK:
                    with _conn() as conn:
                        c = conn.cursor()
                        c.execute("""INSERT INTO advokat_deals
                                     (thief_id, victim_id, frozen_amount, status, expires_at)
                                     VALUES (?, ?, ?, 'pending', ?)""",
                                  (thief_id, victim_id, big_normalize(stolen_amount), expires_at))
                        deal_id = c.lastrowid
                        conn.commit()
                advokat_deals[deal_id] = {
                    "thief_id": thief_id,
                    "victim_id": victim_id,
                    "amount": stolen_amount,
                    "expires_at": time.time() + ADVOKAT_HIRE_WINDOW_SEC,
                }
        text = ("⚖️ НА ТЕБЯ ПОДАН ИСК В СУД!\n\n"
                "💰 Украдено: " + format(stolen_amount) + "\n"
                "⏰ У тебя " + str(ADVOKAT_HIRE_WINDOW_SEC // 60) + " мин, чтобы нанять адвоката.\n"
                "💸 Стоимость услуги: " + format(ADVOKAT_HIRE_COST) + "\n\n"
                "Если не наймёшь — деньги вернутся жертве.")
        send_message(thief_id, text, advokat_hire_prompt_keyboard())
        return deal_id
    except Exception as e:
        print("⚠️ start_advokat_deal_for_thief: " + str(e))
        return None


def get_deal(deal_id):
    with advokat_deals_lock:
        return advokat_deals.get(deal_id)


def advokat_show_list(chat_id, message_id, user_id, deal_id):
    deal = get_deal(deal_id)
    if not deal:
        send_message(chat_id, "❌ Дело истекло!")
        return
    if deal["thief_id"] != user_id:
        send_message(chat_id, "❌ Это не твоё дело!")
        return
    owner_id = advokat_owner()
    if not owner_id:
        send_message(chat_id, "❌ Адвокатская контора не выкуплена!")
        return
    advokats = advokat_get_owner_advokats(owner_id)
    if not advokats:
        kb = {"inline_keyboard": [
            [{"text": "⚖️ НАНЯТЬ ВЛАДЕЛЬЦА (" + format(ADVOKAT_OWNER_COST) + ")",
              "callback_data": "advokat_pick_owner_" + str(deal_id)}],
            [{"text": "❌ ОТМЕНА", "callback_data": "advokat_cancel"}],
        ]}
        text = ("⚖️ СПИСОК АДВОКАТОВ\n\n"
                "😔 Адвокатов нет онлайн.\n\n"
                "Можешь нанять ВЛАДЕЛЬЦА за " + format(ADVOKAT_OWNER_COST) + ".")
        if message_id:
            edit_message(chat_id, message_id, text, kb)
        else:
            send_message(chat_id, text, kb)
        return
    text = ("⚖️ СПИСОК АДВОКАТОВ\n\n"
            "🟢 — онлайн, 🔴 — оффлайн, ⏳ — занят\n"
            "💸 Услуга: " + format(ADVOKAT_HIRE_COST) + "\n\n"
            "Выбери адвоката:")
    kb = advokat_list_keyboard(advokats)
    if message_id:
        edit_message(chat_id, message_id, text, kb)
    else:
        send_message(chat_id, text, kb)


def advokat_handle_pick(chat_id, user_id, deal_id, advokat_id):
    deal = get_deal(deal_id)
    if not deal:
        send_message(chat_id, "❌ Дело истекло!")
        return
    if deal["thief_id"] != user_id:
        send_message(chat_id, "❌ Это не твоё дело!")
        return
    if advokat_is_busy(advokat_id):
        send_message(chat_id, "⏳ Адвокат занят, выбери другого")
        advokat_show_list(chat_id, None, user_id, deal_id)
        return
    thief_balance = get_balance(user_id)
    if thief_balance < ADVOKAT_HIRE_COST:
        send_message(chat_id, "❌ Недостаточно! Нужно " + format(ADVOKAT_HIRE_COST))
        return
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("""INSERT INTO advokat_requests (deal_id, advokat_id, status)
                             VALUES (?, ?, 'pending')""",
                          (deal_id, advokat_id))
                req_id = c.lastrowid
                conn.commit()
    except Exception as e:
        send_message(chat_id, "❌ " + str(e))
        return
    text = ("⚖️ ЗАЯВКА НА ДЕЛО #" + str(deal_id) + "\n\n"
            "👤 Обвиняемый: " + get_display_name(user_id) + "\n"
            "💰 Украдено: " + format(deal["amount"]) + "\n"
            "🎁 Тебе: " + format(ADVOKAT_FEE) + "\n\n"
            "Взять дело?")
    kb = advokat_deal_request_keyboard(req_id)
    try:
        send_message(advokat_id, text, kb)
        send_message(chat_id, "✅ Заявка отправлена адвокату!")
    except Exception:
        send_message(chat_id, "❌ Адвокат недоступен")


def advokat_handle_pick_owner(chat_id, user_id, deal_id):
    deal = get_deal(deal_id)
    if not deal:
        send_message(chat_id, "❌ Дело истекло!")
        return
    owner_id = advokat_owner()
    if not owner_id:
        send_message(chat_id, "❌ Конторы нет!")
        return
    thief_balance = get_balance(user_id)
    if thief_balance < ADVOKAT_OWNER_COST:
        send_message(chat_id, "❌ Недостаточно! Нужно " + format(ADVOKAT_OWNER_COST))
        return
    ok, result = advokat_resolve_deal(deal_id, user_id, owner_id, is_owner=True)
    send_message(chat_id, str(result))
    if ok:
        with advokat_deals_lock:
            advokat_deals.pop(deal_id, None)


def advokat_handle_deal_accept(chat_id, user_id, req_id):
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT deal_id, advokat_id, status FROM advokat_requests WHERE id = ?", (req_id,))
                r = c.fetchone()
                if not r or r["advokat_id"] != user_id or r["status"] != "pending":
                    send_message(chat_id, "❌ Заявка неактивна!")
                    return
                deal_id = r["deal_id"]
                c.execute("UPDATE advokat_requests SET status = 'accepted', resolved_at = ? WHERE id = ?",
                          (db_now(), req_id))
                conn.commit()
    except Exception as e:
        send_message(chat_id, "❌ " + str(e))
        return
    deal = get_deal(deal_id)
    if not deal:
        send_message(chat_id, "❌ Дело истекло!")
        return
    ok, result = advokat_resolve_deal(deal_id, deal["thief_id"], user_id, is_owner=False)
    send_message(chat_id, str(result))
    if ok:
        advokat_set_busy(user_id, ADVOKAT_BUSY_SEC)
        with advokat_deals_lock:
            advokat_deals.pop(deal_id, None)


def advokat_handle_deal_decline(chat_id, user_id, req_id):
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT deal_id, advokat_id, status FROM advokat_requests WHERE id = ?", (req_id,))
                r = c.fetchone()
                if not r or r["advokat_id"] != user_id or r["status"] != "pending":
                    send_message(chat_id, "❌ Заявка неактивна!")
                    return
                c.execute("UPDATE advokat_requests SET status = 'declined', resolved_at = ? WHERE id = ?",
                          (db_now(), req_id))
                conn.commit()
        send_message(chat_id, "❌ Отклонено")
    except Exception as e:
        send_message(chat_id, "❌ " + str(e))


def advokat_resolve_deal(deal_id, thief_id, advokat_id, is_owner=False):
    """✅ BIG-INT: все суммы через big_load/add_balance."""
    deal = get_deal(deal_id)
    if not deal:
        try:
            with DB_LOCK:
                with _conn() as conn:
                    c = conn.cursor()
                    c.execute("SELECT * FROM advokat_deals WHERE id = ? AND status = 'pending'", (deal_id,))
                    row = c.fetchone()
                    if row:
                        deal = {
                            "thief_id": row["thief_id"],
                            "victim_id": row["victim_id"],
                            "amount": big_load(row["frozen_amount"]),
                        }
        except Exception:
            pass
    if not deal:
        return False, "❌ Дело не найдено!"
    thief_id_db = deal["thief_id"]
    victim_id = deal["victim_id"]
    stolen_amount = deal["amount"]
    if thief_id_db != thief_id:
        return False, "❌ Не твоё дело!"
    cost = ADVOKAT_OWNER_COST if is_owner else ADVOKAT_HIRE_COST
    advokat_biz = advokat_get_biz()
    if not advokat_biz:
        return False, "❌ Конторы нет!"
    if is_owner:
        to_advokat = 0
        to_biz = ADVOKAT_OWNER_COST
    else:
        to_advokat = ADVOKAT_FEE
        up_mult = biz_get_upgrade_mult("advokat")
        to_biz = int(ADVOKAT_BIZ_CUT * up_mult)
    to_victim = int(stolen_amount * ADVOKAT_VICTIM_PERCENT / 100)
    to_thief = int(stolen_amount * ADVOKAT_THIEF_PERCENT / 100)
    to_court = stolen_amount - to_victim - to_thief
    # Списание с вора
    ok, _, reason = sub_balance(thief_id, cost)
    if not ok:
        return False, "❌ " + reason
    # Начисления
    if to_advokat > 0:
        add_balance(advokat_id, to_advokat)
        add_transaction(advokat_id, to_advokat, "advokat_fee", "advokat", "Дело #" + str(deal_id))
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT balance FROM biz_businesses WHERE biz_type = 'advokat'")
                ab = c.fetchone()
                cur = big_load(ab["balance"]) if ab else 0
                new_val = cur + to_biz
                if new_val > MAX_BALANCE:
                    new_val = MAX_BALANCE
                c.execute("UPDATE biz_businesses SET balance = ? WHERE biz_type = 'advokat'",
                          (big_normalize(new_val),))
                conn.commit()
    except Exception as e:
        print("⚠️ advokat biz balance: " + str(e))
    if to_victim > 0:
        add_balance(victim_id, to_victim)
        add_transaction(victim_id, to_victim, "advokat_victim_refund", "advokat", "Возврат украденного")
    if to_thief > 0:
        add_balance(thief_id, to_thief)
    if to_court > 0:
        try:
            with DB_LOCK:
                with _conn() as conn:
                    c = conn.cursor()
                    c.execute("SELECT * FROM biz_businesses WHERE biz_type LIKE 'sud%'")
                    suds_owned = [s for s in c.fetchall() if s["owner_id"] and s["status"] == "owned"]
                    if suds_owned:
                        share = to_court // len(suds_owned)
                        rem = to_court - share * len(suds_owned)
                        for i, s in enumerate(suds_owned):
                            amt = share + (1 if i < rem else 0)
                            if amt > 0:
                                cur_sb = big_load(s["balance"])
                                new_sb = cur_sb + amt
                                if new_sb > MAX_BALANCE:
                                    new_sb = MAX_BALANCE
                                c.execute("UPDATE biz_businesses SET balance = ? WHERE biz_type = ?",
                                          (big_normalize(new_sb), s["biz_type"]))
                    conn.commit()
        except Exception:
            pass
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("UPDATE advokat_deals SET status = 'resolved', resolved_at = ? WHERE id = ?",
                          (db_now(), deal_id))
                c.execute("DELETE FROM frozen_money WHERE victim_id = ?", (victim_id,))
                conn.commit()
    except Exception:
        pass
    biz_stats_add("advokat", to_biz)
    return True, ("⚖️ ДЕЛО РЕШЕНО!\n\n"
                  "💸 С вора: −" + format(cost) + "\n"
                  "👨‍⚖️ Адвокату: +" + format(to_advokat) + "\n"
                  "🏢 В бизнес: +" + format(to_biz) + "\n\n"
                  "📊 Распределение украденного:\n"
                  "  🎯 Жертве: " + format(to_victim) + "\n"
                  "  🦹 Вору: " + format(to_thief) + "\n"
                  "  ⚖️ Суду: " + format(to_court))


def advokat_expire_worker():
    while not scheduler_stop.is_set():
        try:
            now = time.time()
            with advokat_deals_lock:
                expired = [did for did, d in advokat_deals.items() if d["expires_at"] <= now]
            for deal_id in expired:
                deal = get_deal(deal_id)
                if not deal:
                    continue
                try:
                    with DB_LOCK:
                        with _conn() as conn:
                            c = conn.cursor()
                            c.execute("SELECT status FROM advokat_deals WHERE id = ?", (deal_id,))
                            r = c.fetchone()
                            if r and r["status"] == "pending":
                                add_balance(deal["victim_id"], deal["amount"])
                                add_transaction(deal["victim_id"], deal["amount"], "advokat_expire_refund",
                                                "advokat", "Возврат (дело истекло)")
                                c.execute("UPDATE advokat_deals SET status = 'expired', resolved_at = ? WHERE id = ?",
                                          (db_now(), deal_id))
                                c.execute("DELETE FROM frozen_money WHERE victim_id = ?", (deal["victim_id"],))
                                conn.commit()
                    try:
                        send_message(deal["victim_id"],
                                     "💰 Возврат украденного: " + format(deal["amount"]))
                    except Exception:
                        pass
                except Exception as e:
                    print("⚠️ advokat_expire: " + str(e))
                with advokat_deals_lock:
                    advokat_deals.pop(deal_id, None)
        except Exception as e:
            print("⚠️ advokat_expire_worker: " + str(e))
        time.sleep(30)


def advokat_hire_cmd(chat_id, user_id, args, cmd):
    if len(args) != 1:
        send_message(chat_id, "❌ Формат: " + cmd + " @user|ID")
        return
    biz = advokat_get_biz()
    if not biz or biz["owner_id"] != user_id:
        send_message(chat_id, "❌ Ты не владелец адвокатской конторы!")
        return
    t = args[0].strip()
    if t.startswith("@"):
        target = get_user_id_by_username(t[1:])
    else:
        try:
            target = int(t)
        except ValueError:
            send_message(chat_id, "❌ @user или ID!")
            return
    if not target or get_user(target) is None:
        send_message(chat_id, "❌ Игрок не найден!")
        return
    if target == user_id:
        send_message(chat_id, "❌ Себя нельзя!")
        return
    if cmd == "/add_advokat":
        ok, result = advokat_add(user_id, target)
        send_message(chat_id, str(result))
        if ok:
            try:
                send_message(target, "⚖️ Тебя наняли адвокатом!\nВладелец: " + get_display_name(user_id))
            except Exception:
                pass
    else:
        ok, result = advokat_remove(user_id, target)
        send_message(chat_id, str(result))
        if ok:
            try:
                send_message(target, "❌ Тебя уволили с должности адвоката.")
            except Exception:
                pass


