# ========== 🔄 ОБМЕН ==========
def trade_get(deal_id):
    with biz_trades_lock:
        d = biz_trades.get(deal_id)
        if d:
            return d
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT * FROM biz_trades WHERE id = ? AND status = 'pending'", (deal_id,))
                r = c.fetchone()
                if not r:
                    return None
                return {
                    "id": r["id"],
                    "from_user": r["from_user"],
                    "to_user": r["to_user"],
                    "from_biz_type": r["from_biz_type"],
                    "to_biz_type": r["to_biz_type"],
                    "extra_amount": big_load(r["extra_amount"]),
                    "extra_from": r["extra_from"] or 0,
                    "expires_at": r["expires_at"],
                }
    except Exception:
        return None


def trade_create(from_user, to_user, from_biz_type, to_biz_type, extra_amount=0, extra_from=0):
    if from_user == to_user:
        return False, "❌ Себя нельзя!"
    if from_biz_type in TRADE_FORBIDDEN_BIZ or to_biz_type in TRADE_FORBIDDEN_BIZ:
        return False, "❌ Этот бизнес нельзя менять (мафия)"
    if from_biz_type == "lombard" or to_biz_type == "lombard":
        return False, "❌ Ломбард нельзя менять!"
    if from_biz_type in ("league",) or to_biz_type in ("league",):
        return False, "❌ Лигу нельзя менять!"
    expires_at = (datetime.now() + timedelta(seconds=TRADE_OFFER_TTL_SEC)).strftime(DB_DATE_FMT)
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT owner_id, status, last_payment, name FROM biz_businesses WHERE biz_type = ?", (from_biz_type,))
                b1 = c.fetchone()
                if not b1 or b1["owner_id"] != from_user:
                    return False, "❌ У тебя нет такого бизнеса!"
                if b1["status"] != "owned":
                    return False, "❌ Твой бизнес не в статусе 'owned'!"
                c.execute("SELECT owner_id, status, last_payment, name FROM biz_businesses WHERE biz_type = ?", (to_biz_type,))
                b2 = c.fetchone()
                if not b2 or b2["owner_id"] != to_user:
                    return False, "❌ У него нет такого бизнеса!"
                if b2["status"] != "owned":
                    return False, "❌ Его бизнес не в статусе 'owned'!"
                now = datetime.now()
                for b, who in ((b1, "Твой"), (b2, "Его")):
                    last = db_parse(b["last_payment"]) if b["last_payment"] else None
                    if last and (now - last).total_seconds() > 24 * 3600:
                        return False, "❌ " + who + " бизнес просрочен!"
                if extra_amount > 0:
                    bal = get_balance(extra_from)
                    if bal < extra_amount:
                        return False, "❌ Недостаточно для доплаты! Поинты: " + format(bal)
                c.execute("""INSERT INTO biz_trades
                             (from_user, to_user, from_biz_type, to_biz_type,
                              extra_amount, extra_from, status, expires_at)
                             VALUES (?, ?, ?, ?, ?, ?, 'pending', ?)""",
                          (from_user, to_user, from_biz_type, to_biz_type,
                           big_normalize(extra_amount), extra_from, expires_at))
                trade_id = c.lastrowid
                conn.commit()
        with biz_trades_lock:
            biz_trades[trade_id] = {
                "id": trade_id,
                "from_user": from_user,
                "to_user": to_user,
                "from_biz_type": from_biz_type,
                "to_biz_type": to_biz_type,
                "extra_amount": extra_amount,
                "extra_from": extra_from,
                "expires_at": expires_at,
            }
        return True, trade_id
    except Exception as e:
        return False, "❌ " + str(e)


def trade_resolve(trade_id, accepted_by):
    t = trade_get(trade_id)
    if not t:
        return False, "❌ Обмен не найден или уже обработан!"
    if t["to_user"] != accepted_by:
        return False, "❌ Не твоё!"
    expires_at = db_parse(t["expires_at"]) if isinstance(t["expires_at"], str) else None
    if expires_at and expires_at < datetime.now():
        return False, "⏰ Обмен истёк!"
    from_user = t["from_user"]
    to_user = t["to_user"]
    from_biz = t["from_biz_type"]
    to_biz = t["to_biz_type"]
    extra_amount = t["extra_amount"] or 0
    extra_from = t["extra_from"] or 0
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT owner_id, status, last_payment, name FROM biz_businesses WHERE biz_type = ?", (from_biz,))
                b1 = c.fetchone()
                if not b1 or b1["owner_id"] != from_user or b1["status"] != "owned":
                    return trade_cancel_and_return(trade_id, "❌ Твой бизнес больше не доступен!")
                c.execute("SELECT owner_id, status, last_payment, name FROM biz_businesses WHERE biz_type = ?", (to_biz,))
                b2 = c.fetchone()
                if not b2 or b2["owner_id"] != to_user or b2["status"] != "owned":
                    return trade_cancel_and_return(trade_id, "❌ Его бизнес больше не доступен!")
                now = datetime.now()
                for b, who in ((b1, "Твой"), (b2, "Его")):
                    last = db_parse(b["last_payment"]) if b["last_payment"] else None
                    if last and (now - last).total_seconds() > 24 * 3600:
                        return trade_cancel_and_return(trade_id, "❌ " + who + " бизнес просрочен!")
                if extra_amount > 0:
                    bal = get_balance(extra_from)
                    if bal < extra_amount:
                        return trade_cancel_and_return(trade_id, "❌ Недостаточно для доплаты!")
                c.execute("UPDATE biz_businesses SET owner_id = ? WHERE biz_type = ?", (to_user, from_biz))
                c.execute("UPDATE biz_businesses SET owner_id = ? WHERE biz_type = ?", (from_user, to_biz))
                c.execute("UPDATE biz_businesses SET last_payment = ? WHERE biz_type IN (?, ?)",
                          (db_now(), from_biz, to_biz))
                c.execute("UPDATE biz_trades SET status = 'accepted', resolved_at = ? WHERE id = ?",
                          (db_now(), trade_id))
                conn.commit()
        # Доплата через big-int
        if extra_amount > 0:
            receiver = to_user if extra_from == from_user else from_user
            ok, _, reason = sub_balance(extra_from, extra_amount)
            if not ok:
                # Откат бирж
                try:
                    with DB_LOCK:
                        with _conn() as conn:
                            c = conn.cursor()
                            c.execute("UPDATE biz_businesses SET owner_id = ? WHERE biz_type = ?", (from_user, from_biz))
                            c.execute("UPDATE biz_businesses SET owner_id = ? WHERE biz_type = ?", (to_user, to_biz))
                            c.execute("UPDATE biz_trades SET status = 'pending', resolved_at = NULL WHERE id = ?", (trade_id,))
                            conn.commit()
                except Exception:
                    pass
                return False, "❌ " + reason
            add_balance(receiver, extra_amount)
            add_transaction(extra_from, -extra_amount, "trade_extra_out", "trade", "Обмен #" + str(trade_id))
            add_transaction(receiver, extra_amount, "trade_extra_in", "trade", "Обмен #" + str(trade_id))
    except Exception as e:
        return False, "❌ " + str(e)
    with biz_trades_lock:
        biz_trades.pop(trade_id, None)
    msg = ("✅ ОБМЕН ЗАВЕРШЁН!\n\n"
           "📦 " + str(get_display_name(from_user)) + " отдал " + from_biz + " и получил " + to_biz + "\n"
           "📦 " + str(get_display_name(to_user)) + " отдал " + to_biz + " и получил " + from_biz)
    if extra_amount > 0:
        if extra_from == from_user:
            msg += "\n💰 Доплата: " + format(extra_amount) + " от " + get_display_name(from_user)
        else:
            msg += "\n💰 Доплата: " + format(extra_amount) + " от " + get_display_name(to_user)
    try:
        send_message(to_user, msg)
    except Exception:
        pass
    try:
        send_message(from_user, "✅ ОБМЕН ПРИНЯТ " + get_display_name(to_user) + "!\n\n" + msg)
    except Exception:
        pass
    return True, msg


def trade_cancel_and_return(trade_id, reason, notify_from=True):
    t = trade_get(trade_id)
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("UPDATE biz_trades SET status = 'cancelled', resolved_at = ? WHERE id = ?",
                          (db_now(), trade_id))
                conn.commit()
    except Exception as e:
        print("⚠️ trade_cancel: " + str(e))
    with biz_trades_lock:
        biz_trades.pop(trade_id, None)
    if notify_from and t and t.get("from_user"):
        try:
            send_message(t["from_user"], "❌ Обмен #" + str(trade_id) + " отменён.\nПричина: " + str(reason))
        except Exception:
            pass
    return False, reason


def trade_decline(trade_id, user_id):
    t = trade_get(trade_id)
    if not t:
        return False, "❌ Уже обработан!"
    if t["to_user"] != user_id:
        return False, "❌ Не твоё!"
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("UPDATE biz_trades SET status = 'declined', resolved_at = ? WHERE id = ?",
                          (db_now(), trade_id))
                conn.commit()
    except Exception as e:
        return False, "❌ " + str(e)
    try:
        send_message(t["from_user"], "❌ Обмен #" + str(trade_id) + " отклонён игроком " + get_display_name(user_id))
    except Exception:
        pass
    with biz_trades_lock:
        biz_trades.pop(trade_id, None)
    return True, "❌ Обмен отклонён"


def trade_expire_worker():
    while not scheduler_stop.is_set():
        try:
            with biz_trades_lock:
                expired = []
                now = datetime.now()
                for tid, t in list(biz_trades.items()):
                    exp = t.get("expires_at")
                    if isinstance(exp, str):
                        exp_dt = db_parse(exp)
                    else:
                        exp_dt = exp
                    if exp_dt and exp_dt <= now:
                        expired.append(tid)
            for tid in expired:
                trade_cancel_and_return(tid, "⏰ Обмен истёк (1 час)", notify_from=True)
        except Exception as e:
            print("⚠️ trade_expire: " + str(e))
        time.sleep(30)


