def handle_trade_start(chat_id, user_id, target_id):
    if not target_id:
        send_message(chat_id, "❌ Игрок не найден!")
        return
    if target_id == user_id:
        send_message(chat_id, "❌ Себя нельзя!")
        return
    my_biz = biz_get_by_owner(user_id)
    their_biz = biz_get_by_owner(target_id)
    my_biz = [b for b in my_biz if b["biz_type"] not in TRADE_FORBIDDEN_BIZ and b["biz_type"] not in ("lombard", "league") and b["status"] == "owned"]
    their_biz = [b for b in their_biz if b["biz_type"] not in TRADE_FORBIDDEN_BIZ and b["biz_type"] not in ("lombard", "league") and b["status"] == "owned"]
    if not my_biz:
        send_message(chat_id, "❌ У тебя нет подходящего бизнеса для обмена!")
        return
    if not their_biz:
        send_message(chat_id, "❌ У него нет подходящего бизнеса для обмена!")
        return
    user_states[user_id] = {
        "action": "trade_from",
        "target_id": target_id,
        "my_biz": [b["biz_type"] for b in my_biz],
        "their_biz": [b["biz_type"] for b in their_biz],
    }
    text = ("🔄 ОБМЕН С " + get_display_name(target_id) + "\n\n"
            "📦 ШАГ 1: Выбери СВОЙ бизнес для обмена:")
    send_message(chat_id, text, trade_my_biz_keyboard(my_biz))


