def process_trade_extra_amount(chat_id, user_id, text):
    if user_id not in user_states:
        return
    state = user_states[user_id]
    if state.get("action") != "trade_extra_amount":
        return
    if text.strip().lower() in ("/cancel", "отмена"):
        user_states.pop(user_id, None)
        send_message(chat_id, "❌ Отменено.")
        return
    try:
        amount = int(text.strip())
        if amount < 0:
            send_message(chat_id, "❌ Не может быть отрицательной!")
            return
    except ValueError:
        send_message(chat_id, "❌ Число!")
        return
    target_id = state.get("target_id")
    from_biz_type = state.get("from_biz_type")
    to_biz_type = state.get("to_biz_type")
    extra_from = state.get("extra_from", 0)
    user_states.pop(user_id, None)
    if amount == 0:
        extra_from = 0
    trade_finalize(chat_id, user_id, target_id, from_biz_type, to_biz_type, amount, extra_from)


def trade_finalize(chat_id, user_id, target_id, from_biz_type, to_biz_type, extra_amount, extra_from):
    ok, result = trade_create(user_id, target_id, from_biz_type, to_biz_type,
                              extra_amount, extra_from)
    if not ok:
        send_message(chat_id, str(result))
        return
    trade_id = result
    b1 = biz_get(from_biz_type)
    b2 = biz_get(to_biz_type)
    extra_text = ""
    if extra_amount > 0:
        from_name = get_display_name(extra_from)
        extra_text = "\n💰 Доплата: " + format(extra_amount) + " от " + str(from_name)
    text_to_a = ("✅ ПРЕДЛОЖЕНИЕ ОТПРАВЛЕНО #" + str(trade_id) + "\n\n"
                 "👤 Кому: " + get_display_name(target_id) + "\n\n"
                 "📦 Твой: " + str(b1["name"]) + "\n"
                 "📦 Его: " + str(b2["name"]) + extra_text + "\n\n"
                 "⏰ 1 час на ответ.")
    text_to_b = ("🔄 ПРЕДЛОЖЕНИЕ ОБМЕНА #" + str(trade_id) + "\n\n"
                 "👤 От: " + get_display_name(user_id) + "\n\n"
                 "📦 Твой: " + str(b2["name"]) + "\n"
                 "📦 Его: " + str(b1["name"]) + extra_text + "\n\n"
                 "⏰ 1 час на ответ.")
    try:
        send_message(target_id, text_to_b, trade_offer_keyboard(trade_id))
    except Exception as e:
        send_message(chat_id, "❌ Не удалось отправить: " + str(e))
        trade_cancel_and_return(trade_id, "❌ Ошибка отправки", notify_from=False)
        return
    send_message(chat_id, text_to_a)


