def rob_biz_count_stealable_owned(user_id):
    try:
        all_biz = biz_get_all()
        cnt = 0
        for b in all_biz:
            if b["biz_type"] in ROB_BIZ_STEALABLE and b["owner_id"] == user_id and b["status"] == "owned":
                cnt += 1
        return cnt
    except Exception:
        return 0


def rob_biz_attempt(chat_id, user_id, my_biz_type, their_biz_type):
    if my_biz_type in ROB_BIZ_FORBIDDEN or their_biz_type in ROB_BIZ_FORBIDDEN:
        send_message(chat_id, "❌ Этот бизнес нельзя захватить (мафия/лига/ломбард)")
        return
    my_biz = biz_get(my_biz_type)
    their_biz = biz_get(their_biz_type)
    if not my_biz or my_biz["owner_id"] != user_id:
        send_message(chat_id, "❌ У тебя нет такого бизнеса!")
        return
    if my_biz["status"] != "owned":
        send_message(chat_id, "❌ Твой бизнес не доступен (не owned)!")
        return
    if not their_biz or not their_biz["owner_id"]:
        send_message(chat_id, "❌ У него нет такого бизнеса!")
        return
    if their_biz["owner_id"] == user_id:
        send_message(chat_id, "❌ Это твой бизнес!")
        return
    if their_biz["status"] != "owned":
        send_message(chat_id, "❌ Его бизнес не доступен (на аукционе)!")
        return
    their_owner = their_biz["owner_id"]
    success = random.randint(1, 100) <= ROB_BIZ_CHANCE
    if success:
        try:
            with ROB_BIZ_LOCK:
                with DB_LOCK:
                    with _conn() as conn:
                        c = conn.cursor()
                        c.execute("SELECT owner_id, status FROM biz_businesses WHERE biz_type = ?", (their_biz_type,))
                        chk1 = c.fetchone()
                        if not chk1 or chk1["owner_id"] != their_owner or chk1["status"] != "owned":
                            send_message(chat_id, "❌ Бизнес больше не доступен!")
                            return
                        c.execute("""UPDATE biz_businesses
                                     SET owner_id = ?, last_payment = ?, upgrade_level = 0
                                     WHERE biz_type = ?""",
                                  (user_id, db_now(), their_biz_type))
                        conn.commit()
            try:
                send_message(chat_id, "✅ ЗАХВАТ УДАЧЕН!\n\n🏴‍☠️ Ты украл бизнес: " + str(their_biz["name"]))
            except Exception:
                pass
            try:
                send_message(their_owner, "🚨 ТВОЙ БИЗНЕС УКРАЛИ!\n\n🏴‍☠️ " + get_display_name(user_id) +
                             " забрал " + str(their_biz["name"]))
            except Exception:
                pass
            try:
                send_message(ADMIN_ID, "🏴‍☠️ ЗАХВАТ\n\n" + get_display_name(user_id) + " (" + str(user_id) + ")\n" +
                             "забрал " + str(their_biz["name"]) + " у " + get_display_name(their_owner))
            except Exception:
                pass
        except Exception as e:
            send_message(chat_id, "❌ " + str(e))
    else:
        try:
            with ROB_BIZ_LOCK:
                with DB_LOCK:
                    with _conn() as conn:
                        c = conn.cursor()
                        c.execute("SELECT owner_id, status FROM biz_businesses WHERE biz_type = ?", (my_biz_type,))
                        chk = c.fetchone()
                        if not chk or chk["owner_id"] != user_id or chk["status"] != "owned":
                            send_message(chat_id, "❌ Твой бизнес больше не доступен!")
                            return
                        new_end = (datetime.now() + timedelta(hours=BIZ_AUCTION_HOURS)).strftime(DB_DATE_FMT)
                        c.execute("""UPDATE biz_businesses
                                     SET status = 'auction', auction_end = ?,
                                         current_bet = ?, current_bidder = 0,
                                         seller_id = 0, upgrade_level = 0, min_bet = ?
                                     WHERE biz_type = ?""",
                                  (new_end, big_normalize(0),
                                   big_normalize(BIZ_MIN_PRICE), my_biz_type))
                        conn.commit()
            try:
                send_message(chat_id, "❌ ЗАХВАТ ПРОВАЛЕН!\n\n💀 Твой бизнес ушёл на аукцион:\n" + str(my_biz["name"]))
            except Exception:
                pass
            try:
                send_message(their_owner, "🛡 Твой бизнес пытались украсть!\nНо захват провалился.")
            except Exception:
                pass
        except Exception as e:
            send_message(chat_id, "❌ " + str(e))


