# ========== 📊 СТАТИСТИКА БИЗНЕСА ==========
def handle_biz_stats(chat_id, message_id, user_id, biz_type):
    biz = biz_get(biz_type)
    if not biz:
        send_message(chat_id, "❌ Не найден!")
        return
    if biz["owner_id"] != user_id:
        send_message(chat_id, "❌ Только владелец видит статистику!")
        return
    stats = biz_stats_get(biz_type, BIZ_STATS_DAYS)
    total = sum(x[1] for x in stats)
    today = datetime.now().strftime("%Y-%m-%d")
    today_income = 0
    for d, inc in stats:
        if d == today:
            today_income = inc
            break
    text = "📊 СТАТИСТИКА " + str(biz["name"]) + "\n\n"
    text += "💰 За " + str(BIZ_STATS_DAYS) + " дней: " + format(total) + "\n"
    text += "📅 Сегодня: " + format(today_income) + "\n"
    lvl = biz["upgrade_level"] if "upgrade_level" in biz.keys() else 0
    if lvl and lvl >= 1:
        text += "🏗 Апгрейд: ✅ (x" + str(BIZ_UPGRADE_MULT) + ")\n"
    text += "\n"
    if not stats:
        text += "📭 Пока пусто."
    else:
        text += "📅 Дни:\n"
        for d, inc in stats:
            try:
                dt = datetime.strptime(d, "%Y-%m-%d")
                date_str = dt.strftime("%d.%m")
            except Exception:
                date_str = d
            text += "  " + date_str + " — " + format(inc) + "\n"
    kb = {"inline_keyboard": [[{"text": "⬅️ НАЗАД", "callback_data": "biz_view_" + biz_type}]]}
    if message_id:
        edit_message(chat_id, message_id, text, kb)
    else:
        send_message(chat_id, text, kb)


