def house_get(hid):
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT * FROM houses WHERE id = ?", (hid,))
                return c.fetchone()
    except Exception:
        return None


def house_get_all():
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT * FROM houses ORDER BY id ASC")
                return c.fetchall()
    except Exception:
        return []


def house_get_by_owner(user_id):
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT * FROM houses WHERE owner_id = ? LIMIT 1", (user_id,))
                return c.fetchone()
    except Exception:
        return None


def house_title_key(hid):
    h = HOUSES.get(hid)
    if not h:
        return None
    return "custom_🏠 " + h["name"].replace("🏠 ", "").strip()


def house_title_text(hid):
    h = HOUSES.get(hid)
    if not h:
        return ""
    return "🏠 " + h["name"].replace("🏠 ", "").strip()


def house_buy(chat_id, user_id, hid):
    h = HOUSES.get(hid)
    if not h:
        send_message(chat_id, "❌ Дом не найден!")
        return False
    hrow = house_get(hid)
    if not hrow:
        send_message(chat_id, "❌ Дом не найден в БД!")
        return False
    if hrow["owner_id"] and hrow["owner_id"] != 0:
        send_message(chat_id, "❌ Дом занят! Владелец: " + str(get_display_name(hrow["owner_id"])))
        return False
    exist = house_get_by_owner(user_id)
    if exist:
        send_message(chat_id, "❌ У тебя уже есть дом: " + str(exist["name"]) +
                     "\nСначала продай его (/sellhouse).")
        return False
    currency = h["currency"]
    price = h["price"]
    if currency == "points":
        ok, new_bal, reason = sub_balance(user_id, price)
        if not ok:
            send_message(chat_id, "❌ Нужно " + format(price) + " поинтов!\n" + reason)
            return False
        add_transaction(user_id, -price, "house_buy", "house",
                        "Покупка дома: " + str(h["name"]))
    elif currency == "frik":
        if get_frik(user_id) < price:
            send_message(chat_id, "❌ Нужно " + str(price) + " FrikCoins!\nУ тебя: " + str(get_frik(user_id)))
            return False
        if not add_frik(user_id, -price):
            send_message(chat_id, "❌ Ошибка списания FrikCoins!")
            return False
        add_transaction(user_id, 0, "house_buy_frik", "house",
                        "Покупка дома за " + str(price) + " FrikCoins: " + str(h["name"]))
    else:
        send_message(chat_id, "❌ Неизвестная валюта!")
        return False
    try:
        with HOUSE_LOCK:
            with DB_LOCK:
                with _conn() as conn:
                    c = conn.cursor()
                    c.execute("UPDATE houses SET owner_id = ?, bought_at = ? WHERE id = ? AND (owner_id = 0 OR owner_id IS NULL)",
                              (user_id, db_now(), hid))
                    if c.rowcount == 0:
                        conn.rollback()
                        if currency == "points":
                            add_balance(user_id, price)
                        elif currency == "frik":
                            add_frik(user_id, price)
                        send_message(chat_id, "❌ Дом уже занят!")
                        return False
                    conn.commit()
    except Exception as e:
        if currency == "points":
            add_balance(user_id, price)
        elif currency == "frik":
            add_frik(user_id, price)
        send_message(chat_id, "❌ " + str(e))
        return False
    tk = house_title_key(hid)
    if tk:
        award_title(user_id, "custom", custom_text=house_title_text(hid))
    send_message(chat_id,
                 "✅ ДОМ КУПЛЕН!\n\n" +
                 str(h["name"]) + "\n💰 −" +
                 (format(price) + " поинтов" if currency == "points" else str(price) + " FrikCoins") +
                 "\n\n🏆 Титул выдан!")
    try:
        send_message(ADMIN_ID, "🏠 ПОКУПКА ДОМА\n\n" + get_display_name(user_id) +
                     " (" + str(user_id) + ")\n" + str(h["name"]))
    except Exception:
        pass
    return True


def house_reset(hid, admin_id=0):
    hrow = house_get(hid)
    if not hrow:
        return False, "❌ Дом не найден!"
    old_owner = hrow["owner_id"] or 0
    try:
        with HOUSE_LOCK:
            with DB_LOCK:
                with _conn() as conn:
                    c = conn.cursor()
                    c.execute("UPDATE houses SET owner_id = 0, bought_at = NULL WHERE id = ?", (hid,))
                    c.execute("""UPDATE house_trades
                                 SET status = 'cancelled', resolved_at = ?
                                 WHERE house_id = ? AND status = 'pending'""",
                              (db_now(), hid))
                    conn.commit()
    except Exception as e:
        return False, "❌ " + str(e)
    if old_owner:
        tk = house_title_key(hid)
        if tk:
            remove_title(old_owner, tk)
        try:
            send_message(old_owner, "❌ Твой дом " + str(hrow["name"]) + " сброшен админом.")
        except Exception:
            pass
    return True, "✅ Дом " + str(hrow["name"]) + " освобождён!"


def house_give(user_id, hid, admin_id=0):
    h = HOUSES.get(hid)
    if not h:
        return False, "❌ Дом не найден!"
    exist = house_get_by_owner(user_id)
    if exist:
        return False, "❌ У игрока уже есть дом: " + str(exist["name"])
    hrow = house_get(hid)
    if not hrow:
        return False, "❌ Дом не найден в БД!"
    old_owner = hrow["owner_id"] or 0
    if old_owner:
        tk_old = house_title_key(hid)
        if tk_old:
            remove_title(old_owner, tk_old)
    try:
        with HOUSE_LOCK:
            with DB_LOCK:
                with _conn() as conn:
                    c = conn.cursor()
                    c.execute("UPDATE houses SET owner_id = ?, bought_at = ? WHERE id = ?",
                              (user_id, db_now(), hid))
                    c.execute("""UPDATE house_trades
                                 SET status = 'cancelled', resolved_at = ?
                                 WHERE house_id = ? AND status = 'pending'""",
                              (db_now(), hid))
                    conn.commit()
    except Exception as e:
        return False, "❌ " + str(e)
    tk = house_title_key(hid)
    if tk:
        award_title(user_id, "custom", custom_text=house_title_text(hid), awarded_by=admin_id)
    return True, "✅ Дом " + str(h["name"]) + " выдан " + get_display_name(user_id)


def house_sell_start(seller_id, buyer_id, price):
    if seller_id == buyer_id:
        return False, "❌ Себе продать нельзя!"
    if price <= 0:
        return False, "❌ Цена должна быть > 0!"
    if price > HOUSE_SELL_MAX:
        return False, "❌ Максимум " + format(HOUSE_SELL_MAX) + "!"
    seller_house = house_get_by_owner(seller_id)
    if not seller_house:
        return False, "❌ У тебя нет дома!"
    buyer_house = house_get_by_owner(buyer_id)
    if buyer_house:
        return False, "❌ У покупателя уже есть дом!"
    if get_user(buyer_id) is None:
        return False, "❌ Игрок не найден!"
    if get_balance(buyer_id) < price:
        return False, "❌ У покупателя недостаточно поинтов!"
    try:
        with HOUSE_TRADE_LOCK:
            with DB_LOCK:
                with _conn() as conn:
                    c = conn.cursor()
                    c.execute("""SELECT id FROM house_trades
                                 WHERE house_id = ? AND status = 'pending'""",
                              (seller_house["id"],))
                    if c.fetchone():
                        return False, "❌ Уже есть активное предложение по этому дому!"
                    expires_at = (datetime.now() + timedelta(seconds=HOUSE_TRADE_TTL_SEC)).strftime(DB_DATE_FMT)
                    c.execute("""INSERT INTO house_trades
                                 (house_id, seller_id, buyer_id, price, status, expires_at)
                                 VALUES (?, ?, ?, ?, 'pending', ?)""",
                              (seller_house["id"], seller_id, buyer_id,
                               big_normalize(price), expires_at))
                    tid = c.lastrowid
                    conn.commit()
        with house_trades_lock:
            house_trades[tid] = {
                "id": tid,
                "house_id": seller_house["id"],
                "seller_id": seller_id,
                "buyer_id": buyer_id,
                "price": price,
                "expires_at": expires_at,
            }
        return True, tid
    except Exception as e:
        return False, "❌ " + str(e)


def house_trade_get(tid):
    with house_trades_lock:
        d = house_trades.get(tid)
        if d:
            return d
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT * FROM house_trades WHERE id = ? AND status = 'pending'", (tid,))
                r = c.fetchone()
                if not r:
                    return None
                return {
                    "id": r["id"],
                    "house_id": r["house_id"],
                    "seller_id": r["seller_id"],
                    "buyer_id": r["buyer_id"],
                    "price": big_load(r["price"]),
                    "expires_at": r["expires_at"],
                }
    except Exception:
        return None


def house_trade_accept(chat_id, user_id, tid):
    t = house_trade_get(tid)
    if not t:
        send_message(chat_id, "❌ Предложение не найдено!")
        return False
    if t["buyer_id"] != user_id:
        send_message(chat_id, "❌ Это не твоё предложение!")
        return False
    exp = db_parse(t["expires_at"])
    if exp and exp < datetime.now():
        send_message(chat_id, "⏰ Предложение истекло!")
        return False
    hid = t["house_id"]
    seller_id = t["seller_id"]
    buyer_id = t["buyer_id"]
    price = t["price"]
    hrow = house_get(hid)
    if not hrow:
        send_message(chat_id, "❌ Дом не найден!")
        return False
    if (hrow["owner_id"] or 0) != seller_id:
        send_message(chat_id, "❌ Продавец больше не владеет домом!")
        return False
    buyer_house = house_get_by_owner(buyer_id)
    if buyer_house:
        send_message(chat_id, "❌ У тебя уже есть дом!")
        return False
    if get_balance(buyer_id) < price:
        send_message(chat_id, "❌ Недостаточно поинтов!")
        return False
    ok, _, reason = sub_balance(buyer_id, price)
    if not ok:
        send_message(chat_id, "❌ " + reason)
        return False
    try:
        with HOUSE_LOCK:
            with DB_LOCK:
                with _conn() as conn:
                    c = conn.cursor()
                    c.execute("UPDATE houses SET owner_id = ?, bought_at = ? WHERE id = ?",
                              (buyer_id, db_now(), hid))
                    c.execute("""UPDATE house_trades
                                 SET status = 'accepted', resolved_at = ?
                                 WHERE id = ?""",
                              (db_now(), tid))
                    conn.commit()
    except Exception as e:
        add_balance(buyer_id, price)
        send_message(chat_id, "❌ " + str(e))
        return False
    add_balance(seller_id, price)
    add_transaction(buyer_id, -price, "house_buy_from_player", "house", "Покупка дома: " + str(hrow["name"]))
    add_transaction(seller_id, price, "house_sell_to_player", "house", "Продажа дома: " + str(hrow["name"]))
    tk = house_title_key(hid)
    if tk:
        remove_title(seller_id, tk)
        award_title(buyer_id, "custom", custom_text=house_title_text(hid))
    with house_trades_lock:
        house_trades.pop(tid, None)
    send_message(chat_id, "✅ ДОМ КУПЛЕН!\n\n" + str(hrow["name"]) + "\n💰 −" + format(price))
    try:
        send_message(seller_id, "✅ ВЫ ПРОДАЛИ ДОМ ЗА " + format(price) + "\n\n" + str(hrow["name"]))
    except Exception:
        pass
    return True


def house_trade_decline(chat_id, user_id, tid):
    t = house_trade_get(tid)
    if not t:
        send_message(chat_id, "❌ Уже обработано!")
        return False
    if t["buyer_id"] != user_id:
        send_message(chat_id, "❌ Не твоё!")
        return False
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("UPDATE house_trades SET status = 'declined', resolved_at = ? WHERE id = ?",
                          (db_now(), tid))
                conn.commit()
    except Exception as e:
        send_message(chat_id, "❌ " + str(e))
        return False
    with house_trades_lock:
        house_trades.pop(tid, None)
    send_message(chat_id, "❌ Отказано.")
    try:
        send_message(t["seller_id"], "❌ Покупатель отказался от дома.")
    except Exception:
        pass
    return True


def house_trade_expire_worker():
    while not scheduler_stop.is_set():
        try:
            with house_trades_lock:
                expired = []
                now = datetime.now()
                for tid, t in list(house_trades.items()):
                    exp = t.get("expires_at")
                    exp_dt = db_parse(exp) if isinstance(exp, str) else exp
                    if exp_dt and exp_dt <= now:
                        expired.append(tid)
            for tid in expired:
                t = house_trade_get(tid)
                if not t:
                    with house_trades_lock:
                        house_trades.pop(tid, None)
                    continue
                try:
                    with DB_LOCK:
                        with _conn() as conn:
                            c = conn.cursor()
                            c.execute("UPDATE house_trades SET status = 'expired', resolved_at = ? WHERE id = ?",
                                      (db_now(), tid))
                            conn.commit()
                except Exception as e:
                    print("⚠️ house_trade_expire: " + str(e))
                try:
                    send_message(t["seller_id"], "⏰ Предложение продажи дома истекло (1 час).")
                except Exception:
                    pass
                with house_trades_lock:
                    house_trades.pop(tid, None)
        except Exception as e:
            print("⚠️ house_trade_expire_worker: " + str(e))
        time.sleep(30)


def handle_buyhouse(chat_id, message_id, user_id):
    if is_left(user_id):
        send_message(chat_id, "❌ Ты ушёл!")
        return
    my_house = house_get_by_owner(user_id)
    text = "🏠 ЛИЧНЫЕ ДОМА\n\n"
    text += "💎 FrikCoins: " + str(get_frik(user_id)) + "\n"
    text += "💰 Поинты: " + format(get_balance(user_id)) + "\n\n"
    if my_house:
        text += "🏆 Твой дом: " + str(my_house["name"]) + "\n"
        text += "💸 Продать: /sellhouse ID|@user СУММА (макс " + format(HOUSE_SELL_MAX) + ")\n\n"
    else:
        text += "❌ У тебя нет дома\n\n"
    text += "📋 Список (всего 10):\n\n"
    houses = house_get_all()
    for h in houses:
        hid = h["id"]
        hinfo = HOUSES.get(hid, {})
        owner = h["owner_id"] or 0
        status = "🔓 свободен"
        if owner:
            status = "🔒 " + get_display_name(owner)
        currency = h["currency"]
        price_int = big_load(h["price"])
        price_str = format(price_int) + " 💰" if currency == "points" else str(price_int) + " 💎"
        text += str(hid) + ". " + str(h["name"]) + " — " + price_str + "\n   " + status + "\n"
    if message_id:
        edit_message(chat_id, message_id, text, house_menu_keyboard(user_id))
    else:
        send_message(chat_id, text, house_menu_keyboard(user_id))


def handle_sellhouse_cmd(chat_id, user_id, args):
    if is_left(user_id):
        send_message(chat_id, "❌ Ты ушёл!")
        return
    if len(args) != 2:
        send_message(chat_id,
                     "❌ Формат: /sellhouse ID|@user СУММА\n"
                     "Максимум: " + format(HOUSE_SELL_MAX))
        return
    my_house = house_get_by_owner(user_id)
    if not my_house:
        send_message(chat_id, "❌ У тебя нет дома!")
        return
    t = args[0].strip()
    if t.startswith("@"):
        buyer_id = get_user_id_by_username(t[1:])
    else:
        try:
            buyer_id = int(t)
        except ValueError:
            send_message(chat_id, "❌ ID или @username!")
            return
    if not buyer_id:
        send_message(chat_id, "❌ Игрок не найден!")
        return
    try:
        price = int(args[1])
    except ValueError:
        send_message(chat_id, "❌ Сумма числом!")
        return
    ok, result = house_sell_start(user_id, buyer_id, price)
    if not ok:
        send_message(chat_id, str(result))
        return
    tid = result
    text_offer = ("🏠 ПРЕДЛОЖЕНИЕ ДОМА #" + str(tid) + "\n\n"
                  "👤 От: " + get_display_name(user_id) + "\n"
                  "📦 Дом: " + str(my_house["name"]) + "\n"
                  "💰 Цена: " + format(price) + "\n\n"
                  "⏰ 1 час на ответ.")
    try:
        send_message(buyer_id, text_offer, house_trade_offer_keyboard(tid))
    except Exception as e:
        send_message(chat_id, "❌ Не удалось отправить покупателю: " + str(e))
        try:
            with DB_LOCK:
                with _conn() as conn:
                    c = conn.cursor()
                    c.execute("UPDATE house_trades SET status = 'cancelled', resolved_at = ? WHERE id = ?",
                              (db_now(), tid))
                    conn.commit()
        except Exception:
            pass
        with house_trades_lock:
            house_trades.pop(tid, None)
        return
    send_message(chat_id, "✅ Предложение отправлено покупателю #" + str(tid))


def handle_admin_cmd_frik(chat_id, user_id, args, mode):
    if user_id != ADMIN_ID:
        send_message(chat_id, "❌ Только главный админ!")
        return
    if len(args) < 1:
        if mode == "give":
            send_message(chat_id, "❌ /give_frik ID|@user СУММА")
        else:
            send_message(chat_id, "❌ /reset_frik ID|@user")
        return
    t = args[0].strip()
    if t.startswith("@"):
        target_id = get_user_id_by_username(t[1:])
    else:
        try:
            target_id = int(t)
        except ValueError:
            send_message(chat_id, "❌ ID или @username!")
            return
    if not target_id or get_user(target_id) is None:
        send_message(chat_id, "❌ Игрок не найден!")
        return
    if mode == "give":
        if len(args) != 2:
            send_message(chat_id, "❌ /give_frik ID|@user СУММА")
            return
        try:
            amount = int(args[1])
        except ValueError:
            send_message(chat_id, "❌ Сумма числом!")
            return
        if amount == 0:
            send_message(chat_id, "❌ Сумма не может быть 0!")
            return
        add_frik(target_id, amount)
        new_bal = get_frik(target_id)
        send_message(chat_id, "✅ " + get_display_name(target_id) + ": " +
                     ("+" if amount > 0 else "") + str(amount) + " 💎\nБаланс: " + str(new_bal))
        try:
            send_message(target_id, "💎 Изменение FrikCoins: " +
                         ("+" if amount > 0 else "") + str(amount) + "\nБаланс: " + str(new_bal))
        except Exception:
            pass
    elif mode == "reset":
        reset_frik(target_id)
        send_message(chat_id, "✅ FrikCoins обнулены у " + get_display_name(target_id))
        try:
            send_message(target_id, "💎 Твои FrikCoins обнулены админом.")
        except Exception:
            pass


def handle_admin_cmd_house(chat_id, user_id, args, mode):
    if user_id != ADMIN_ID:
        send_message(chat_id, "❌ Только главный админ!")
        return
    if mode == "list":
        houses = house_get_all()
        text = "🏠 ВСЕ ДОМА\n\n"
        for h in houses:
            owner = h["owner_id"] or 0
            owner_name = get_display_name(owner) if owner else "свободен"
            text += str(h["id"]) + ". " + str(h["name"]) + " — " + str(owner_name) + "\n"
        send_message(chat_id, text)
        return
    if mode == "give":
        if len(args) != 2:
            send_message(chat_id, "❌ /givehouse ID|@user НОМЕР")
            return
        t = args[0].strip()
        if t.startswith("@"):
            target_id = get_user_id_by_username(t[1:])
        else:
            try:
                target_id = int(t)
            except ValueError:
                send_message(chat_id, "❌ ID или @username!")
                return
        if not target_id or get_user(target_id) is None:
            send_message(chat_id, "❌ Игрок не найден!")
            return
        try:
            hid = int(args[1])
        except ValueError:
            send_message(chat_id, "❌ Номер дома числом!")
            return
        ok, result = house_give(target_id, hid, admin_id=user_id)
        send_message(chat_id, str(result))
        if ok:
            try:
                send_message(target_id, "🏠 Тебе выдали дом: " + str(HOUSES[hid]["name"]))
            except Exception:
                pass
        return
    if mode == "reset":
        if len(args) != 1:
            send_message(chat_id, "❌ /resethouse НОМЕР")
            return
        try:
            hid = int(args[0])
        except ValueError:
            send_message(chat_id, "❌ Номер числом!")
            return
        ok, result = house_reset(hid, admin_id=user_id)
        send_message(chat_id, str(result))


