def process_admin_biz_give(chat_id, user_id, text):
    if not is_admin(user_id):
        return
    if user_id in user_states:
        del user_states[user_id]
    if text.strip().lower() in ("/cancel", "отмена"):
        send_message(chat_id, "❌ Отменено.")
        handle_admin_biz_menu(chat_id, None, user_id)
        return
    try:
        parts = text.strip().split()
        if len(parts) != 2:
            send_message(chat_id, "❌ Формат: ID ТИП")
            return
        target_id = int(parts[0])
        biz_type = parts[1].lower().strip()
        if biz_type not in ("apteka1", "apteka2", "apteka3", "bolnitsa1", "bolnitsa2", "banda", "sud1", "sud2", "advokat", "lombard"):
            send_message(chat_id, "❌ Неверный тип")
            return
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("""UPDATE biz_businesses
                             SET owner_id = ?, status = 'owned', last_payment = ?,
                                 auction_end = NULL, current_bet = ?, current_bidder = 0,
                                 seller_id = 0, upgrade_level = 0
                             WHERE biz_type = ?""",
                          (target_id, db_now(), big_normalize(0), biz_type))
                conn.commit()
        biz = biz_get(biz_type)
        send_message(chat_id, "✅ " + str(biz["name"]) + " выдан " + str(target_id))
        try:
            send_message(target_id, "🎁 Бизнес: " + str(biz["name"]) + "!")
        except Exception:
            pass
        if biz_type == "lombard":
            award_title(target_id, "lombardier")
        handle_admin_biz_menu(chat_id, None, user_id)
    except ValueError:
        send_message(chat_id, "❌ ID числом!")


