# ========== 📊 ОПРОСЫ ==========
def poll_get_active():
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT * FROM polls WHERE status = 'active' ORDER BY id DESC LIMIT 1")
                return c.fetchone()
    except Exception:
        return None


def poll_get_by_id(poll_id):
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT * FROM polls WHERE id = ?", (poll_id,))
                return c.fetchone()
    except Exception:
        return None


def poll_parse_options(raw):
    try:
        return json.loads(raw) if raw else []
    except Exception:
        return []


def poll_create(question, options, duration_min):
    try:
        ends_at = (datetime.now() + timedelta(minutes=duration_min)).strftime(DB_DATE_FMT)
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("UPDATE polls SET status = 'cancelled' WHERE status = 'active'")
                c.execute("""INSERT INTO polls (question, options, ends_at, status)
                             VALUES (?, ?, ?, 'active')""",
                          (question, json.dumps(options, ensure_ascii=False), ends_at))
                poll_id = c.lastrowid
                conn.commit()
        return True, poll_id
    except Exception as e:
        return False, str(e)


def poll_save_message(poll_id, chat_id, message_id):
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("INSERT INTO poll_messages (poll_id, chat_id, message_id) VALUES (?, ?, ?)",
                          (poll_id, chat_id, message_id))
                conn.commit()
        return True
    except Exception:
        return False


def poll_get_messages(poll_id):
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT chat_id, message_id FROM poll_messages WHERE poll_id = ?", (poll_id,))
                return [tuple(x) for x in c.fetchall()]
    except Exception:
        return []


def poll_get_votes(poll_id):
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT user_id, option_idx FROM poll_votes WHERE poll_id = ?", (poll_id,))
                return [tuple(x) for x in c.fetchall()]
    except Exception:
        return []


def poll_build_text(poll_id, closed=False):
    p = poll_get_by_id(poll_id)
    if not p:
        return "❌ Опрос не найден."
    options = poll_parse_options(p["options"])
    text = "📊 <b>ОПРОС</b>\n\n" + str(p["question"]) + "\n\n"
    if closed:
        votes = poll_get_votes(poll_id)
        counts = [0] * len(options)
        for _uid, idx in votes:
            if 0 <= idx < len(counts):
                counts[idx] += 1
        best = -1
        best_i = 0
        for i, cnt in enumerate(counts):
            mark = "🟢" if cnt > best else "⚪"
            if cnt > best:
                best = cnt
                best_i = i
            text += mark + " " + str(i + 1) + ". " + str(options[i]) + " — " + str(cnt) + "\n"
        text += "\n🏆 Победил вариант: " + str(options[best_i]) + " (" + str(best) + " голосов)"
    else:
        for i, opt in enumerate(options):
            text += str(i + 1) + ". " + str(opt) + "\n"
        ends_at = db_parse(p["ends_at"])
        if ends_at:
            left = int((ends_at - datetime.now()).total_seconds())
            if left < 0:
                left = 0
            m = left // 60
            s = left % 60
            text += "\n⏰ Осталось: " + str(m) + "м " + str(s) + "с"
    return text


def poll_build_keyboard(poll_id, closed=False):
    p = poll_get_by_id(poll_id)
    if not p or closed:
        return {"inline_keyboard": []}
    options = poll_parse_options(p["options"])
    rows = []
    for i in range(len(options)):
        rows.append([{"text": str(i + 1) + ". " + str(options[i]), "callback_data": "poll_vote_" + str(poll_id) + "_" + str(i)}])
    return {"inline_keyboard": rows}


def poll_broadcast(poll_id):
    p = poll_get_by_id(poll_id)
    if not p:
        return
    text = poll_build_text(poll_id, closed=False)
    kb = poll_build_keyboard(poll_id, closed=False)
    users = get_all_user_ids(active_only=True)
    sent = 0
    for uid in users:
        try:
            res = send_message(uid, text, kb)
            if res and res.get("ok"):
                mid = res["result"]["message_id"]
                poll_save_message(poll_id, uid, mid)
                sent += 1
            time.sleep(0.3)
        except Exception:
            pass
    try:
        res = send_message(CHAT_ID, text, kb)
        if res and res.get("ok"):
            mid = res["result"]["message_id"]
            poll_save_message(poll_id, CHAT_ID, mid)
    except Exception:
        pass
    try:
        send_message(ADMIN_ID, "📊 Опрос запущен, разослан " + str(sent) + " игрокам.")
    except Exception:
        pass


def poll_close(poll_id, by_manual=False):
    p = poll_get_by_id(poll_id)
    if not p or p["status"] != "active":
        return
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("UPDATE polls SET status = 'closed' WHERE id = ?", (poll_id,))
                conn.commit()
    except Exception as e:
        print("⚠️ poll_close: " + str(e))
        return
    final_text = poll_build_text(poll_id, closed=True)
    votes = poll_get_votes(poll_id)
    options = poll_parse_options(p["options"])
    counts = [0] * len(options)
    for _uid, idx in votes:
        if 0 <= idx < len(counts):
            counts[idx] += 1
    best_i = 0
    best = -1
    for i, cnt in enumerate(counts):
        if cnt > best:
            best = cnt
            best_i = i
    try:
        admin_msg = ("📊 ОПРОС #" + str(poll_id) + " ЗАВЕРШЁН\n\n" +
                     "❓ " + str(p["question"]) + "\n\n")
        for i, opt in enumerate(options):
            admin_msg += str(i + 1) + ". " + str(opt) + " — " + str(counts[i]) + " голосов\n"
        admin_msg += "\n🏆 Победил: " + str(options[best_i]) + " (" + str(best) + ")"
        send_message(ADMIN_ID, admin_msg)
    except Exception:
        pass
    for uid, _idx in votes:
        try:
            send_message(uid, "📊 Опрос #" + str(poll_id) + " закрыт.\n" + final_text)
            time.sleep(0.3)
        except Exception:
            pass
    msgs = poll_get_messages(poll_id)
    for cid, mid in msgs:
        try:
            edit_message(cid, mid, final_text, None)
        except Exception:
            pass


def poll_watcher_worker():
    while not scheduler_stop.is_set():
        try:
            p = poll_get_active()
            if p:
                ends_at = db_parse(p["ends_at"])
                if ends_at and ends_at <= datetime.now():
                    poll_close(p["id"])
        except Exception as e:
            print("⚠️ poll_watcher: " + str(e))
        time.sleep(20)


def handle_poll_vote(callback_id, user_id, chat_id, message_id, poll_id, opt_idx):
    p = poll_get_by_id(poll_id)
    if not p or p["status"] != "active":
        answer_callback(callback_id, "❌ Опрос закрыт", True)
        return
    options = poll_parse_options(p["options"])
    if opt_idx < 0 or opt_idx >= len(options):
        answer_callback(callback_id, "❌ Неверный вариант", True)
        return
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT id FROM poll_votes WHERE poll_id = ? AND user_id = ?", (poll_id, user_id))
                if c.fetchone():
                    answer_callback(callback_id, "❌ Ты уже голосовал", True)
                    return
                c.execute("INSERT INTO poll_votes (poll_id, user_id, option_idx) VALUES (?, ?, ?)",
                          (poll_id, user_id, opt_idx))
                conn.commit()
    except Exception as e:
        print("⚠️ poll_vote: " + str(e))
        answer_callback(callback_id, "❌ Ошибка", True)
        return
    answer_callback(callback_id, "✅ Голос учтён", False)


