def handle_admin_poll_create(chat_id, message_id, user_id):
    if not is_admin(user_id):
        return
    if poll_get_active():
        send_message(chat_id, "❌ Уже есть активный опрос. Сначала отмените.")
        handle_admin_poll_menu(chat_id, None, user_id)
        return
    user_states[user_id] = {"action": "admin_poll_create", "step": "question", "options": []}
    send_message(chat_id, "📊 СОЗДАНИЕ ОПРОСА (1/4)\n\nНапиши ВОПРОС:\n\n/cancel", back_keyboard())


def process_admin_poll_create(chat_id, user_id, text):
    if user_id not in user_states:
        return
    state = user_states[user_id]
    if state.get("action") != "admin_poll_create":
        return
    step = state.get("step")
    if text.strip().lower() in ("/cancel", "отмена"):
        user_states.pop(user_id, None)
        send_message(chat_id, "❌ Отменено.")
        handle_admin_poll_menu(chat_id, None, user_id)
        return
    if step == "question":
        state["question"] = text.strip()[:200]
        state["step"] = "options"
        state["options"] = []
        user_states[user_id] = state
        send_message(chat_id, "📊 Шаг 2/4\n\nОтправь варианты (от 2 до 5), каждый с новой строки.\nКогда закончишь — /done\n\n/cancel", back_keyboard())
        return
    if step == "options":
        new_opts = [o.strip() for o in text.split("\n") if o.strip()]
        if len(new_opts) == 0:
            send_message(chat_id, "❌ Пусто. Отправь вариант или /done")
            return
        existing = state.get("options", [])
        existing.extend(new_opts)
        if len(existing) > 5:
            existing = existing[:5]
        state["options"] = existing
        user_states[user_id] = state
        send_message(chat_id, "✅ Сейчас " + str(len(existing)) + "/5.\nОтправь ещё или /done.", back_keyboard())
        return
    if step == "duration":
        try:
            dur = int(text.strip())
            if dur < 1 or dur > 10080:
                send_message(chat_id, "❌ 1-10080!")
                return
        except ValueError:
            send_message(chat_id, "❌ Число!")
            return
        q = state.get("question", "?")
        opts = state.get("options", [])
        user_states.pop(user_id, None)
        if len(opts) < 2:
            send_message(chat_id, "❌ Минимум 2 варианта!")
            handle_admin_poll_menu(chat_id, None, user_id)
            return
        ok, result = poll_create(q, opts, dur)
        if ok:
            send_message(chat_id, "✅ Опрос #" + str(result) + " создан! Рассылаю...")
            threading.Thread(target=poll_broadcast, args=(result,), daemon=True).start()
            handle_admin_poll_menu(chat_id, None, user_id)
        else:
            send_message(chat_id, "❌ " + str(result))


def handle_admin_poll_finish_options(chat_id, user_id):
    if user_id not in user_states:
        return
    state = user_states[user_id]
    if state.get("action") != "admin_poll_create" or state.get("step") != "options":
        return
    opts = state.get("options", [])
    if len(opts) < 2:
        send_message(chat_id, "❌ Минимум 2 варианта!", back_keyboard())
        return
    state["step"] = "duration"
    user_states[user_id] = state
    send_message(chat_id, "📊 Шаг 3/4\n\nГотово " + str(len(opts)) + " вариантов.\n\nВведи ДЛИТЕЛЬНОСТЬ (в минутах):", back_keyboard())


def handle_admin_poll_cancel(chat_id, message_id, user_id):
    if not is_admin(user_id):
        return
    p = poll_get_active()
    if not p:
        send_message(chat_id, "❌ Нет активного опроса.")
        handle_admin_poll_menu(chat_id, None, user_id)
        return
    try:
        poll_close(p["id"], by_manual=True)
        send_message(chat_id, "✅ Опрос закрыт.")
    except Exception as e:
        send_message(chat_id, "❌ " + str(e))
    handle_admin_poll_menu(chat_id, None, user_id)


