def craft_get_resources(user_id):
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT wood, iron, diamond FROM craft_resources WHERE user_id = ?", (user_id,))
                r = c.fetchone()
                if not r:
                    return {"wood": 0, "iron": 0, "diamond": 0}
                return {"wood": r["wood"] or 0, "iron": r["iron"] or 0, "diamond": r["diamond"] or 0}
    except Exception:
        return {"wood": 0, "iron": 0, "diamond": 0}


def craft_add_resources(user_id, wood=0, iron=0, diamond=0):
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT user_id FROM craft_resources WHERE user_id = ?", (user_id,))
                if c.fetchone():
                    c.execute("""UPDATE craft_resources
                                 SET wood = wood + ?, iron = iron + ?, diamond = diamond + ?,
                                     updated_at = ?
                                 WHERE user_id = ?""",
                              (wood, iron, diamond, db_now(), user_id))
                else:
                    c.execute("""INSERT INTO craft_resources (user_id, wood, iron, diamond, updated_at)
                                 VALUES (?, ?, ?, ?, ?)""",
                              (user_id, wood, iron, diamond, db_now()))
                conn.commit()
        return True
    except Exception as e:
        print("⚠️ craft_add_resources: " + str(e))
        return False


def craft_take_resources(user_id, wood=0, iron=0, diamond=0):
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("""UPDATE craft_resources
                             SET wood = wood - ?, iron = iron - ?, diamond = diamond - ?,
                                 updated_at = ?
                             WHERE user_id = ? AND wood >= ? AND iron >= ? AND diamond >= ?""",
                          (wood, iron, diamond, db_now(), user_id, wood, iron, diamond))
                if c.rowcount == 0:
                    conn.rollback()
                    return False
                conn.commit()
        return True
    except Exception:
        return False


def craft_get_buffs(user_id):
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("""SELECT x2_bets_left, win_boost_percent, shield_until
                             FROM craft_buffs WHERE user_id = ?""", (user_id,))
                r = c.fetchone()
                if not r:
                    return {"x2_bets_left": 0, "win_boost_percent": 0, "shield_until": None}
                return {
                    "x2_bets_left": r["x2_bets_left"] or 0,
                    "win_boost_percent": r["win_boost_percent"] or 0,
                    "shield_until": r["shield_until"],
                }
    except Exception:
        return {"x2_bets_left": 0, "win_boost_percent": 0, "shield_until": None}


def craft_update_buffs(user_id, **kwargs):
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT user_id FROM craft_buffs WHERE user_id = ?", (user_id,))
                if not c.fetchone():
                    c.execute("""INSERT INTO craft_buffs
                                 (user_id, x2_bets_left, win_boost_percent, shield_until, updated_at)
                                 VALUES (?, 0, 0, NULL, ?)""", (user_id, db_now()))
                for key, val in kwargs.items():
                    if key in ("x2_bets_left", "win_boost_percent", "shield_until"):
                        c.execute("UPDATE craft_buffs SET " + key + " = ?, updated_at = ? WHERE user_id = ?",
                                  (val, db_now(), user_id))
                conn.commit()
        return True
    except Exception as e:
        print("⚠️ craft_update_buffs: " + str(e))
        return False


def craft_get_win_boost(user_id):
    buffs = craft_get_buffs(user_id)
    return buffs["win_boost_percent"] or 0


def craft_roll_drop(user_id, won):
    dropped = {}
    for res_key, chances in CRAFT_DROP_CHANCES.items():
        chance = chances["win"] if won else chances["lose"]
        if random.randint(1, 100) <= chance:
            mn, mx = CRAFT_DROP_AMOUNTS[res_key]
            amount = random.randint(mn, mx)
            dropped[res_key] = amount
    if dropped:
        craft_add_resources(user_id,
                            wood=dropped.get("wood", 0),
                            iron=dropped.get("iron", 0),
                            diamond=dropped.get("diamond", 0))
    return dropped


def craft_check_requirements(user_id, recipe):
    req_title = recipe.get("requires_title")
    if req_title:
        if not user_has_title(user_id, req_title):
            return False, "❌ Нужен " + recipe.get("requires_text", req_title)
    if recipe.get("requires_family_owner"):
        fam = get_user_family(user_id)
        if not fam:
            return False, "❌ Ты не в семье!"
        if fam["owner_id"] != user_id:
            return False, "❌ Только владелец семьи!"
    if recipe.get("once_only"):
        buffs = craft_get_buffs(user_id)
        if buffs["win_boost_percent"] > 0:
            return False, "❌ У тебя уже есть буст +10%!\nКрафт доступен только 1 раз."
    return True, ""


def craft_can_afford(user_id, recipe):
    cost = recipe["cost"]
    res = craft_get_resources(user_id)
    for res_key in ("wood", "iron", "diamond"):
        need = cost.get(res_key, 0)
        if need <= 0:
            continue
        have = res.get(res_key, 0)
        if have < need:
            info = CRAFT_RESOURCES_INFO[res_key]
            return False, ("❌ Не хватает " + info["name"] + "\n"
                           "Нужно: " + format(need) + "\n"
                           "У тебя: " + format(have))
    points = cost.get("points", 0)
    if points > 0:
        bal = get_balance(user_id)
        if bal < points:
            return False, ("❌ Не хватает поинтов\n"
                           "Нужно: " + format(points) + "\n"
                           "У тебя: " + format(bal))
    biz_need = cost.get("business", 0)
    if biz_need > 0:
        my_biz = biz_get_by_owner(user_id)
        my_biz = [b for b in my_biz if b["biz_type"] not in ("mafia", "league")
                  and b["status"] == "owned"]
        if len(my_biz) < biz_need:
            return False, ("❌ Нужно бизнесов: " + str(biz_need) + "\n"
                           "У тебя подходящих: " + str(len(my_biz)))
    fam_rep = cost.get("family_rep", 0)
    if fam_rep > 0:
        fam = get_user_family(user_id)
        if not fam:
            return False, "❌ Ты не в семье!"
        if (fam["reputation"] or 0) < fam_rep:
            return False, ("❌ Не хватает репутации\n"
                           "Нужно: " + str(fam_rep) + " ⭐\n"
                           "У семьи: " + str(fam["reputation"] or 0) + " ⭐")
    return True, ""


def craft_spend_resources(user_id, recipe):
    """✅ BIG-INT: поинты через sub_balance."""
    cost = recipe["cost"]
    wood = cost.get("wood", 0)
    iron = cost.get("iron", 0)
    diamond = cost.get("diamond", 0)
    if wood or iron or diamond:
        if not craft_take_resources(user_id, wood, iron, diamond):
            return False, "❌ Ошибка списания ресурсов!"
    points = cost.get("points", 0)
    if points > 0:
        ok, _, reason = sub_balance(user_id, points)
        if not ok:
            return False, reason
        add_transaction(user_id, -points, "craft_spend", "craft", "Крафт")
    fam_rep = cost.get("family_rep", 0)
    if fam_rep > 0:
        fam = get_user_family(user_id)
        if fam:
            try:
                with DB_LOCK:
                    with _conn() as conn:
                        c = conn.cursor()
                        c.execute("UPDATE families SET reputation = reputation - ? WHERE id = ? AND reputation >= ?",
                                  (fam_rep, fam["id"], fam_rep))
                        conn.commit()
            except Exception:
                pass
    return True, ""


def craft_check_cooldown(user_id, craft_key, recipe):
    cd_hours = recipe.get("cooldown_hours", 0)
    if cd_hours <= 0:
        return True, ""
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("""SELECT timestamp FROM craft_history
                             WHERE user_id = ? AND craft_key = ?
                             ORDER BY id DESC LIMIT 1""", (user_id, craft_key))
                r = c.fetchone()
                if r and r["timestamp"]:
                    last = db_parse(r["timestamp"])
                    if last:
                        diff = (datetime.now() - last).total_seconds()
                        if diff < cd_hours * 3600:
                            left = int(cd_hours * 3600 - diff)
                            h = left // 3600
                            m = (left % 3600) // 60
                            return False, "⏰ Кулдаун: " + str(h) + "ч " + str(m) + "м"
    except Exception as e:
        print("⚠️ craft_check_cooldown: " + str(e))
    return True, ""


def craft_do(user_id, craft_key, extra_data=None):
    """✅ BIG-INT: начисления через add_balance, бизнес на аукцион с big_normalize."""
    recipe = CRAFT_RECIPES.get(craft_key)
    if not recipe:
        return False, "❌ Рецепт не найден!"

    ok, err = craft_check_requirements(user_id, recipe)
    if not ok:
        return False, err

    ok, err = craft_check_cooldown(user_id, craft_key, recipe)
    if not ok:
        return False, err

    ok, err = craft_can_afford(user_id, recipe)
    if not ok:
        return False, err

    ok, err = craft_spend_resources(user_id, recipe)
    if not ok:
        return False, err

    biz_need = recipe["cost"].get("business", 0)
    biz_sent_to_auction = []
    if biz_need > 0 and extra_data:
        biz_list = extra_data.get("biz_types", [])
        for bt in biz_list:
            b = biz_get(bt)
            if b and b["owner_id"] == user_id and b["status"] == "owned":
                new_end = (datetime.now() + timedelta(hours=BIZ_AUCTION_HOURS)).strftime(DB_DATE_FMT)
                try:
                    with DB_LOCK:
                        with _conn() as conn:
                            c = conn.cursor()
                            c.execute("""UPDATE biz_businesses
                                         SET owner_id = 0, status = 'auction', auction_end = ?,
                                             current_bet = ?, current_bidder = 0,
                                             seller_id = 0, upgrade_level = 0,
                                             min_bet = ?, craft_locked = 1
                                         WHERE biz_type = ?""",
                                      (new_end, big_normalize(0),
                                       big_normalize(BIZ_MIN_PRICE), bt))
                            conn.commit()
                    biz_sent_to_auction.append(b["name"])
                except Exception as e:
                    print("⚠️ craft biz auction: " + str(e))

    chance = int(recipe.get("chance", 0))
    roll = random.randint(1, 100)
    success = (roll <= chance)
    print("🎲 CRAFT: " + str(craft_key) + " roll=" + str(roll) + " chance=" + str(chance) + " success=" + str(success))

    result_text = ""
    if success:
        res_type = recipe["result"]
        if res_type == "title_dealer":
            try:
                with TITLE_LOCK:
                    with _conn() as conn:
                        c = conn.cursor()
                        c.execute("""INSERT OR IGNORE INTO titles
                                     (user_id, title_key, custom_text, awarded_by)
                                     VALUES (?, 'custom_🏆 Диллер', '🏆 Диллер', 0)""",
                                  (user_id,))
                        conn.commit()
            except Exception:
                pass
            result_text = "🏆 ТИТУЛ 'ДИЛЛЕР' ПОЛУЧЕН!"

        elif res_type == "win_boost":
            craft_update_buffs(user_id, win_boost_percent=10)
            result_text = "💎 БУСТ +10% К ВЫИГРЫШУ!\n(только 1 раз)"

        elif res_type == "points_25kkk":
            ok2, _, _ = add_balance(user_id, 25_000_000_000)
            if not ok2:
                return False, "❌ Не удалось начислить (превышен лимит)"
            add_transaction(user_id, 25_000_000_000, "craft_25kkk", "craft", "Особый кейс")
            result_text = "🎁 +25,000,000,000 ПОИНТОВ!"

        elif res_type == "title_nothing_to_lose":
            try:
                with TITLE_LOCK:
                    with _conn() as conn:
                        c = conn.cursor()
                        c.execute("""INSERT OR IGNORE INTO titles
                                     (user_id, title_key, custom_text, awarded_by)
                                     VALUES (?, 'custom_🎗 Нечего терять', '🎗 Нечего терять', 0)""",
                                  (user_id,))
                        conn.commit()
            except Exception:
                pass
            result_text = "🎗 ТИТУЛ 'НЕЧЕГО ТЕРЯТЬ' ПОЛУЧЕН!"

        elif res_type == "points_5kkk_family":
            ok2, _, _ = add_balance(user_id, 5_000_000_000)
            if not ok2:
                return False, "❌ Не удалось начислить (превышен лимит)"
            add_transaction(user_id, 5_000_000_000, "craft_5kkk_family", "craft", "Репутация семьи")
            result_text = "⭐ +5,000,000,000 ПОИНТОВ!"

        elif res_type == "shield_add_one":
            user_state_set(user_id, {"action": "craft_shield_add"})
            result_text = "👑 КОМАНДА АКТИВИРОВАНА!\nНапиши ID/@username для добавления в щит\n\n/cancel"
    else:
        result_text = "💀 ПРОВАЛ! (roll " + str(roll) + " > " + str(chance) + ")\nРесурсы сгорели."
        if biz_sent_to_auction:
            result_text += "\n🏢 Бизнесы на аукцион: " + ", ".join(biz_sent_to_auction)

    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("""INSERT INTO craft_history
                             (user_id, craft_key, resources_json, success, result_text)
                             VALUES (?, ?, ?, ?, ?)""",
                          (user_id, craft_key, json.dumps(recipe["cost"]),
                           1 if success else 0, result_text))
                conn.commit()
    except Exception:
        pass

    header = "✅ КРАФТ УСПЕШЕН!\n\n" if success else "❌ КРАФТ ПРОВАЛЕН!\n\n"
    return True, header + "🛠 " + recipe["name"] + "\n\n" + result_text


def craft_menu_text(user_id):
    res = craft_get_resources(user_id)
    buffs = craft_get_buffs(user_id)
    text = "🛠 КРАФТЫ\n\n"
    text += "🎒 ТВОИ РЕСУРСЫ:\n"
    text += "  🪵 Дерево: " + format(res["wood"]) + "\n"
    text += "  ⛏ Железо: " + format(res["iron"]) + "\n"
    text += "  💎 Алмаз: " + format(res["diamond"]) + "\n"
    if buffs["win_boost_percent"] > 0:
        text += "\n💎 Буст к выигрышу: +" + str(buffs["win_boost_percent"]) + "%\n"
    if buffs["shield_until"]:
        dt = db_parse(buffs["shield_until"])
        if dt and dt > datetime.now():
            left = int((dt - datetime.now()).total_seconds() // 3600)
            text += "🛡 Щит: " + str(left) + "ч\n"
    text += "\n📋 ВЫБЕРИ КРАФТ:"
    return text


def craft_menu_keyboard(user_id=None):
    rows = []
    for key, recipe in CRAFT_RECIPES.items():
        cost = recipe["cost"]
        cost_parts = []
        if cost.get("wood", 0) > 0:
            cost_parts.append(str(cost["wood"]) + "🪵")
        if cost.get("iron", 0) > 0:
            cost_parts.append(str(cost["iron"]) + "⛏")
        if cost.get("diamond", 0) > 0:
            cost_parts.append(str(cost["diamond"]) + "💎")
        if cost.get("points", 0) > 0:
            cost_parts.append(format_short(cost["points"]))
        if cost.get("business", 0) > 0:
            cost_parts.append(str(cost["business"]) + "🏢")
        if cost.get("family_rep", 0) > 0:
            cost_parts.append(str(cost["family_rep"]) + "⭐")
        cost_str = "+".join(cost_parts) if cost_parts else "free"
        label = recipe["name"] + " | " + cost_str
        if len(label) > 60:
            label = label[:57] + "..."
        rows.append([{"text": label, "callback_data": "craft_view_" + key}])
    rows.append([{"text": "🎒 РЕСУРСЫ", "callback_data": "craft_res_view"}])
    rows.append([{"text": "⬅️ НАЗАД", "callback_data": "back"}])
    return {"inline_keyboard": rows}


def handle_craft_menu(chat_id, message_id, user_id):
    text = craft_menu_text(user_id)
    kb = craft_menu_keyboard(user_id)
    if message_id:
        edit_message(chat_id, message_id, text, kb)
    else:
        send_message(chat_id, text, kb)


def craft_view_keyboard(craft_key, user_id=None):
    recipe = CRAFT_RECIPES.get(craft_key)
    if not recipe:
        return back_keyboard()
    return {"inline_keyboard": [
        [{"text": "🛠 КРАФТИТЬ", "callback_data": "craft_do_" + craft_key}],
        [{"text": "⬅️ НАЗАД", "callback_data": "craft_menu"}],
    ]}


def handle_craft_view(chat_id, message_id, user_id, craft_key):
    recipe = CRAFT_RECIPES.get(craft_key)
    if not recipe:
        send_message(chat_id, "❌ Крафт не найден!")
        return
    cost = recipe["cost"]
    res = craft_get_resources(user_id)
    text = "🛠 " + recipe["name"] + "\n\n"
    text += "📝 " + recipe["desc"] + "\n"
    text += "🎲 Шанс: " + str(recipe["chance"]) + "%\n"
    cd_hours = recipe.get("cooldown_hours", 0)
    if cd_hours > 0:
        text += "⏰ Кулдаун: " + str(cd_hours) + "ч\n"
    text += "\n💰 СТОИМОСТЬ:\n"
    if cost.get("wood", 0) > 0:
        have = res["wood"]
        mark = "✅" if have >= cost["wood"] else "❌"
        text += mark + " 🪵 " + format(cost["wood"]) + " (у тебя: " + format(have) + ")\n"
    if cost.get("iron", 0) > 0:
        have = res["iron"]
        mark = "✅" if have >= cost["iron"] else "❌"
        text += mark + " ⛏ " + format(cost["iron"]) + " (у тебя: " + format(have) + ")\n"
    if cost.get("diamond", 0) > 0:
        have = res["diamond"]
        mark = "✅" if have >= cost["diamond"] else "❌"
        text += mark + " 💎 " + format(cost["diamond"]) + " (у тебя: " + format(have) + ")\n"
    if cost.get("points", 0) > 0:
        bal = get_balance(user_id)
        mark = "✅" if bal >= cost["points"] else "❌"
        text += mark + " 💰 " + format(cost["points"]) + " (у тебя: " + format(bal) + ")\n"
    if cost.get("business", 0) > 0:
        my_biz = biz_get_by_owner(user_id)
        cnt = len([b for b in my_biz if b["biz_type"] not in ("mafia", "league") and b["status"] == "owned"])
        mark = "✅" if cnt >= cost["business"] else "❌"
        text += mark + " 🏢 Бизнесов: " + str(cost["business"]) + " (у тебя: " + str(cnt) + ")\n"
    if cost.get("family_rep", 0) > 0:
        fam = get_user_family(user_id)
        rep = (fam["reputation"] or 0) if fam else 0
        mark = "✅" if rep >= cost["family_rep"] else "❌"
        text += mark + " ⭐ " + format(cost["family_rep"]) + " (у семьи: " + format(rep) + ")\n"
    req = recipe.get("requires_title")
    if req:
        has = user_has_title(user_id, req)
        mark = "✅" if has else "❌"
        text += "\n" + mark + " Требуется: " + recipe.get("requires_text", req)
    if message_id:
        edit_message(chat_id, message_id, text, craft_view_keyboard(craft_key, user_id))
    else:
        send_message(chat_id, text, craft_view_keyboard(craft_key, user_id))


def _craft_biz_page_keyboard(my_biz, picked, page, need):
    per_page = 8
    start = page * per_page
    end = start + per_page
    page_biz = my_biz[start:end]
    rows = []
    for b in page_biz:
        mark = "✅ " if b["biz_type"] in picked else ""
        label = mark + b["name"]
        if len(label) > 60:
            label = label[:57] + "..."
        rows.append([{"text": label, "callback_data": "craft_pick_" + b["biz_type"]}])
    nav = []
    total = len(my_biz)
    if page > 0:
        nav.append({"text": "⬅️", "callback_data": "craft_page_" + str(page - 1)})
    if end < total:
        nav.append({"text": "➡️", "callback_data": "craft_page_" + str(page + 1)})
    if nav:
        rows.append(nav)
    rows.append([{"text": "❌ ОТМЕНА", "callback_data": "craft_menu"}])
    return {"inline_keyboard": rows}


def handle_craft_do(chat_id, message_id, user_id, craft_key):
    recipe = CRAFT_RECIPES.get(craft_key)
    if not recipe:
        send_message(chat_id, "❌ Не найдено!")
        return
    biz_need = recipe["cost"].get("business", 0)
    if biz_need > 0:
        my_biz = biz_get_by_owner(user_id)
        my_biz = [b for b in my_biz if b["biz_type"] not in ("mafia", "league") and b["status"] == "owned"]
        if len(my_biz) < biz_need:
            send_message(chat_id, "❌ Нужно бизнесов: " + str(biz_need))
            return
        state = {
            "action": "craft_pick_biz",
            "craft_key": craft_key,
            "biz_need": biz_need,
            "biz_picked": [],
            "biz_page": 0,
        }
        user_state_set(user_id, state)
        text = ("🛠 " + recipe["name"] + "\n\n"
                "🏢 Выбери бизнес (" + str(biz_need) + " шт)\n\n"
                "Уже выбрано: 0/" + str(biz_need) + "\n\n/cancel")
        kb = _craft_biz_page_keyboard(my_biz, [], 0, biz_need)
        if message_id:
            edit_message(chat_id, message_id, text, kb)
        else:
            send_message(chat_id, text, kb)
        return
    ok, result = craft_do(user_id, craft_key)
    send_message(chat_id, result)
    if ok:
        handle_craft_menu(chat_id, message_id, user_id)


def handle_craft_page(chat_id, message_id, user_id, page):
    state = user_state_get(user_id)
    if not state or state.get("action") != "craft_pick_biz":
        send_message(chat_id, "❌ Сессия истекла!")
        return
    state["biz_page"] = page
    user_state_set(user_id, state)
    my_biz = biz_get_by_owner(user_id)
    my_biz = [b for b in my_biz if b["biz_type"] not in ("mafia", "league") and b["status"] == "owned"]
    picked = state.get("biz_picked", [])
    need = state.get("biz_need", 1)
    recipe = CRAFT_RECIPES.get(state.get("craft_key"))
    rname = recipe["name"] if recipe else "Крафт"
    text = ("🛠 " + rname + "\n\n"
            "🏢 Выбери бизнес (" + str(need) + " шт)\n\n"
            "Уже выбрано: " + str(len(picked)) + "/" + str(need) + "\n\n/cancel")
    kb = _craft_biz_page_keyboard(my_biz, picked, page, need)
    if message_id:
        edit_message(chat_id, message_id, text, kb)
    else:
        send_message(chat_id, text, kb)


def handle_craft_pick_biz(chat_id, message_id, user_id, biz_type):
    state = user_state_get(user_id)
    if not state or state.get("action") != "craft_pick_biz":
        send_message(chat_id, "❌ Сессия истекла!")
        return
    picked = state.get("biz_picked", [])
    if biz_type in picked:
        send_message(chat_id, "❌ Уже выбран!")
        return
    b = biz_get(biz_type)
    if not b or b["owner_id"] != user_id or b["status"] != "owned":
        send_message(chat_id, "❌ Бизнес недоступен!")
        return
    picked.append(biz_type)
    state["biz_picked"] = picked
    user_state_set(user_id, state)
    need = state.get("biz_need", 1)
    if len(picked) < need:
        my_biz = biz_get_by_owner(user_id)
        my_biz = [b2 for b2 in my_biz if b2["biz_type"] not in ("mafia", "league") and b2["status"] == "owned"]
        text = ("🛠 ВЫБОР БИЗНЕСА\n\n"
                "Уже выбрано: " + str(len(picked)) + "/" + str(need) + "\n\n"
                "Осталось: " + str(need - len(picked)) + "\n\n/cancel")
        page = state.get("biz_page", 0)
        kb = _craft_biz_page_keyboard(my_biz, picked, page, need)
        if message_id:
            edit_message(chat_id, message_id, text, kb)
        else:
            send_message(chat_id, text, kb)
        return
    craft_key = state.get("craft_key")
    user_state_pop(user_id)
    extra_data = {"biz_types": picked}
    ok, result = craft_do(user_id, craft_key, extra_data=extra_data)
    send_message(chat_id, result)
    if ok:
        handle_craft_menu(chat_id, message_id, user_id)


