def handle_craft_sell(chat_id, message_id, user_id, res_key):
    """✅ BIG-INT: продажа через add_balance."""
    if res_key not in CRAFT_RESOURCES_INFO:
        send_message(chat_id, "❌ Неверный ресурс!")
        return
    res = craft_get_resources(user_id)
    have = res.get(res_key, 0)
    if have <= 0:
        send_message(chat_id, "❌ У тебя нет " + CRAFT_RESOURCES_INFO[res_key]["name"])
        return
    price = CRAFT_RESOURCES_INFO[res_key]["sell_price"]
    total = have * price
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("UPDATE craft_resources SET " + res_key + " = 0 WHERE user_id = ?", (user_id,))
                conn.commit()
    except Exception as e:
        send_message(chat_id, "❌ " + str(e))
        return
    ok, new_bal, reason = add_balance(user_id, total)
    if not ok:
        craft_add_resources(user_id,
                            wood=have if res_key == "wood" else 0,
                            iron=have if res_key == "iron" else 0,
                            diamond=have if res_key == "diamond" else 0)
        send_message(chat_id, "❌ " + reason)
        return
    add_transaction(user_id, total, "craft_sell", "craft",
                    "Продажа " + CRAFT_RESOURCES_INFO[res_key]["name"] + " x" + str(have))
    send_message(chat_id,
                 "✅ ПРОДАНО!\n\n" +
                 CRAFT_RESOURCES_INFO[res_key]["name"] + " x" + str(have) + "\n" +
                 "💰 +" + format(total) + "\n" +
                 "💎 Поинты: " + format(new_bal))
    handle_craft_res_shop(chat_id, message_id, user_id)


def process_res_sell(chat_id, user_id, args):
    if len(args) != 2:
        send_message(chat_id, "❌ Формат: <code>/res_sell ресурс кол-во</code>\nПример: /res_sell wood 100")
        return
    res_key = args[0].strip().lower()
    if res_key not in CRAFT_RESOURCES_INFO:
        send_message(chat_id, "❌ Ресурс: wood / iron / diamond")
        return
    try:
        amount = int(args[1])
    except ValueError:
        send_message(chat_id, "❌ Количество числом!")
        return
    if amount <= 0:
        send_message(chat_id, "❌ Больше 0!")
        return
    res = craft_get_resources(user_id)
    have = res.get(res_key, 0)
    if have < amount:
        send_message(chat_id,
                     "❌ Недостаточно!\n"
                     "У тебя: " + format(have) + " " + CRAFT_RESOURCES_INFO[res_key]["emoji"])
        return
    price = CRAFT_RESOURCES_INFO[res_key]["sell_price"]
    total = amount * price
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("UPDATE craft_resources SET " + res_key + " = " + res_key + " - ? WHERE user_id = ? AND " + res_key + " >= ?",
                          (amount, user_id, amount))
                if c.rowcount == 0:
                    conn.rollback()
                    send_message(chat_id, "❌ Ошибка списания!")
                    return
                conn.commit()
    except Exception as e:
        send_message(chat_id, "❌ " + str(e))
        return
    ok, new_bal, reason = add_balance(user_id, total)
    if not ok:
        craft_add_resources(user_id,
                            wood=amount if res_key == "wood" else 0,
                            iron=amount if res_key == "iron" else 0,
                            diamond=amount if res_key == "diamond" else 0)
        send_message(chat_id, "❌ " + reason)
        return
    add_transaction(user_id, total, "craft_sell", "craft",
                    "Продажа " + CRAFT_RESOURCES_INFO[res_key]["name"] + " x" + str(amount))
    info = CRAFT_RESOURCES_INFO[res_key]
    send_message(chat_id,
                 "✅ ПРОДАНО!\n\n" +
                 info["name"] + " x" + str(amount) + "\n" +
                 "💰 +" + format(total) + "\n" +
                 "💎 Поинты: " + format(new_bal))


def handle_res_command(chat_id, message_id, user_id):
    handle_craft_res_view(chat_id, message_id, user_id)


def process_res_give(chat_id, user_id, args):
    if len(args) != 3:
        send_message(chat_id,
                     "❌ Формат: <code>/res_give ID ресурс кол-во</code>\n\n"
                     "Ресурсы: wood, iron, diamond\n"
                     "Пример: <code>/res_give 123456789 wood 100</code>")
        return
    target_id = None
    if args[0].startswith('@'):
        target_id = get_user_id_by_username(args[0][1:])
    else:
        try:
            target_id = int(args[0])
        except ValueError:
            send_message(chat_id, "❌ ID или @username!")
            return
    if not target_id:
        send_message(chat_id, "❌ Игрок не найден!")
        return
    if target_id == user_id:
        send_message(chat_id, "❌ Себе нельзя!")
        return
    if get_user(target_id) is None:
        send_message(chat_id, "❌ Игрок не писал /start")
        return
    if fake_is_banned(target_id):
        send_message(chat_id, "❌ Получатель в бане фальшивок — передача невозможна!")
        return
    res_key = args[1].strip().lower()
    if res_key not in CRAFT_RESOURCES_INFO:
        send_message(chat_id, "❌ Ресурс: wood / iron / diamond")
        return
    try:
        amount = int(args[2])
    except ValueError:
        send_message(chat_id, "❌ Количество числом!")
        return
    if amount <= 0:
        send_message(chat_id, "❌ Больше 0!")
        return
    res = craft_get_resources(user_id)
    have = res.get(res_key, 0)
    if have < amount:
        send_message(chat_id,
                     "❌ Недостаточно!\n" +
                     "У тебя: " + format(have) + " " + CRAFT_RESOURCES_INFO[res_key]["emoji"])
        return
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("UPDATE craft_resources SET " + res_key + " = " + res_key + " - ? WHERE user_id = ? AND " + res_key + " >= ?",
                          (amount, user_id, amount))
                if c.rowcount == 0:
                    conn.rollback()
                    send_message(chat_id, "❌ Ошибка списания!")
                    return
                c.execute("SELECT user_id FROM craft_resources WHERE user_id = ?", (target_id,))
                if not c.fetchone():
                    c.execute("INSERT INTO craft_resources (user_id, wood, iron, diamond) VALUES (?, 0, 0, 0)",
                              (target_id,))
                c.execute("UPDATE craft_resources SET " + res_key + " = " + res_key + " + ? WHERE user_id = ?",
                          (amount, target_id))
                conn.commit()
    except Exception as e:
        send_message(chat_id, "❌ " + str(e))
        return
    info = CRAFT_RESOURCES_INFO[res_key]
    send_message(chat_id,
                 "📤 ПЕРЕДАНО!\n\n" +
                 info["name"] + " x" + str(amount) + "\n" +
                 "👤 Кому: " + get_display_name(target_id))
    try:
        send_message(target_id,
                     "📥 ПОЛУЧЕНО!\n\n" +
                     info["name"] + " x" + str(amount) + "\n" +
                     "👤 От: " + get_display_name(user_id))
    except Exception:
        pass


