def process_craft_shield_add(chat_id, user_id, text):
    state = user_state_get(user_id)
    if not state or state.get("action") != "craft_shield_add":
        return
    t = text.strip()
    if t.lower() in ("/cancel", "отмена"):
        user_state_pop(user_id)
        send_message(chat_id, "❌ Отменено.")
        return
    target_id = shield_resolve_id(t)
    if not target_id:
        send_message(chat_id, "❌ Игрок не найден!")
        return
    if get_user(target_id) is None:
        send_message(chat_id, "❌ Игрок не писал /start")
        return
    uname = get_display_name(target_id)
    if shield_add(target_id, uname, user_id, "Крафт"):
        user_state_pop(user_id)
        send_message(chat_id, "🛡 " + str(uname) + " (" + str(target_id) + ") добавлен в защиту!")
        try:
            send_message(target_id, "🛡 Тебя добавили в защищённые (крафт)")
        except Exception:
            pass
    else:
        user_state_pop(user_id)
        send_message(chat_id, "ℹ️ Уже в списке защищённых")


def handle_res_help(chat_id, message_id, user_id):
    text = "🛠 КРАФТЫ — СПРАВКА\n\n"
    text += "🎰 <b>Где брать ресурсы?</b>\n"
    text += "С рулетки за КАЖДУЮ ставку (шанс выше при выигрыше):\n"
    text += "  🪵 Дерево: 15% (проигрыш 7%)\n"
    text += "  ⛏ Железо: 8% (проигрыш 4%)\n"
    text += "  💎 Алмаз: 2% (проигрыш 1%)\n\n"
    text += "🛠 <b>Крафты:</b>\n"
    for key, r in CRAFT_RECIPES.items():
        cost = r["cost"]
        cost_str = []
        if cost.get("wood"): cost_str.append(str(cost["wood"]) + "🪵")
        if cost.get("iron"): cost_str.append(str(cost["iron"]) + "⛏")
        if cost.get("diamond"): cost_str.append(str(cost["diamond"]) + "💎")
        if cost.get("points"): cost_str.append(format(cost["points"]))
        if cost.get("business"): cost_str.append(str(cost["business"]) + "🏢")
        if cost.get("family_rep"): cost_str.append(str(cost["family_rep"]) + "⭐")
        text += "• " + r["name"] + "\n  " + " + ".join(cost_str) + "\n  → " + r["desc"] + "\n\n"
    text += "⚡ <b>Команды:</b>\n"
    text += "/craft — меню крафтов\n"
    text += "/res — мои ресурсы\n"
    text += "/res_give ID ресурс кол-во — передать\n"
    text += "/res_sell ресурс кол-во — продать часть\n"
    text += "/res_shop — продать всё\n"
    text += "/res_help — справка"
    if message_id:
        edit_message(chat_id, message_id, text, back_keyboard())
    else:
        send_message(chat_id, text, back_keyboard())


