def biz_view_keyboard(biz_type, user_id=None):
    biz = biz_get(biz_type)
    if not biz:
        return back_keyboard()
    rows = []
    if biz["status"] == "auction":
        is_seller = (user_id == biz["owner_id"] or
                     ("seller_id" in biz.keys() and biz["seller_id"] == user_id))
        if not is_seller:
            rows.append([{"text": "💰 СТАВКА", "callback_data": "biz_bid_" + biz_type}])
        else:
            rows.append([{"text": "❌ СНЯТЬ", "callback_data": "biz_cancel_sale_" + biz_type}])
    elif biz["status"] == "lombard":
        rows.append([{"text": "🏪 В ЛОМБАРДЕ", "callback_data": "biz_view_" + biz_type}])
    else:
        if user_id and biz["owner_id"] == user_id:
            rows.append([{"text": "💵 СНЯТЬ", "callback_data": "biz_withdraw_" + biz_type}])
            if biz_type not in ("mafia",):
                rows.append([{"text": "💳 ОПЛАТИТЬ", "callback_data": "biz_pay_menu_" + biz_type}])
            if biz_type not in ("mafia", "league", "lombard"):
                rows.append([{"text": "📢 ПРОДАТЬ", "callback_data": "biz_sell_" + biz_type}])
            if biz_type in BIZ_UPGRADE_ALLOWED:
                lvl = biz["upgrade_level"] if "upgrade_level" in biz.keys() else 0
                if lvl and lvl >= 1:
                    rows.append([{"text": "🏗 Апгрейд: ✅ (x1.5)", "callback_data": "biz_upgrade_info_" + biz_type}])
                else:
                    rows.append([{"text": "🏗 АПГРЕЙД (" + format(BIZ_UPGRADE_COST) + ")",
                                  "callback_data": "biz_upgrade_" + biz_type}])
            rows.append([{"text": "📊 СТАТИСТИКА", "callback_data": "biz_stats_" + biz_type}])
        base = biz_get_type_name(biz_type)
        if base == "apteka" and biz["status"] == "owned":
            rows.append([{"text": "💊 АПТЕЧКА (500к)", "callback_data": "biz_buy_apteka_" + biz_type}])
        elif base == "bolnitsa" and biz["status"] == "owned":
            rows.append([{"text": "🩺 ОБСЛЕДОВАНИЕ (1М)", "callback_data": "biz_buy_bolnitsa_" + biz_type}])
        elif base == "banda" and biz["status"] == "owned":
            rows.append([{"text": "🔫 ОГРАБИТЬ (50М)", "callback_data": "biz_buy_banda"}])
        elif biz_type == "league":
            rows.append([{"text": "⚽ ВЫБРАТЬ КОМАНДУ", "callback_data": "league_menu"}])
        elif base == "sud" and biz["status"] == "owned":
            rows.append([{"text": "⚖️ ПОДАТЬ В СУД (Судья " + biz["name"][-1] + ")",
                          "callback_data": "court_menu_" + biz_type}])
        elif biz_type == "advokat":
            if user_id and biz["owner_id"] == user_id:
                rows.append([{"text": "👥 УПРАВЛЕНИЕ АДВОКАТАМИ", "callback_data": "advokat_manage"}])
        elif biz_type == "mafia":
            if user_id and biz["owner_id"] == user_id:
                s = mafia_get_settings()
                rows.append([{"text": "📊 Ставка: " + str(s["current"]) + "% (лимит " + str(s["max"]) + "%)", "callback_data": "mafia_menu"}])
        elif biz_type == "lombard":
            if biz["status"] == "owned":
                if user_id and biz["owner_id"] == user_id:
                    rows.append([{"text": "📊 СТАТИСТИКА ЛОМБАРДА", "callback_data": "lombard_owner_stats"}])
                else:
                    rows.append([{"text": "💰 СДАТЬ БИЗНЕС", "callback_data": "lombard_take"}])
    rows.append([{"text": "⬅️ НАЗАД", "callback_data": "biz_list"}])
    return {"inline_keyboard": rows}


