def advokat_list_keyboard(advokats):
    rows = []
    now = datetime.now()
    for uid, name, busy_until, online in advokats:
        mark = "🟢" if online else "🔴"
        extra = ""
        if busy_until:
            dt = db_parse(busy_until)
            if dt and dt > now:
                extra = " ⏳"
        label = mark + " " + str(name) + extra
        rows.append([{"text": label, "callback_data": "advokat_pick_" + str(uid)}])
    rows.append([{"text": "❌ ОТМЕНА", "callback_data": "advokat_cancel"}])
    return {"inline_keyboard": rows}


