def rob_their_keyboard(user_id, my_biz_type):
    all_biz = biz_get_all()
    rows = []
    for b in all_biz:
        if b["biz_type"] in ROB_BIZ_FORBIDDEN:
            continue
        if b["biz_type"] == my_biz_type:
            continue
        if b["owner_id"] == user_id:
            continue
        if b["status"] != "owned":
            continue
        if not b["owner_id"]:
            continue
        rows.append([{"text": b["name"] + " — " + biz_get_owner_name(b["owner_id"]),
                      "callback_data": "rob_pick_their_" + my_biz_type + "_" + b["biz_type"]}])
    rows.append([{"text": "❌ ОТМЕНА", "callback_data": "rob_biz_menu"}])
    return {"inline_keyboard": rows}


