def rozygrysh_menu_keyboard():
    rows = []
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT last_run FROM rozygrysh_cooldown WHERE id = 1")
                r = c.fetchone()
                last = db_parse(r["last_run"]) if r and r["last_run"] else None
        if last:
            diff = (datetime.now() - last).total_seconds()
            if diff < ROZYGRYSH_COOLDOWN:
                left = int(ROZYGRYSH_COOLDOWN - diff)
                h = left // 3600
                m = (left % 3600) // 60
                rows.append([{"text": "⏰ Кулдаун: " + str(h) + "ч " + str(m) + "м", "callback_data": "admin_rozygrysh_info"}])
                rows.append([{"text": "⬅️ НАЗАД", "callback_data": "admin_panel"}])
                return {"inline_keyboard": rows}
    except Exception:
        pass
    active = rozygrysh_get_active()
    if active:
        rows.append([{"text": "❌ ОТМЕНИТЬ РОЗЫГРЫШ", "callback_data": "admin_rozygrysh_cancel"}])
    else:
        rows.append([{"text": "🎁 НАЧАТЬ РОЗЫГРЫШ", "callback_data": "admin_rozygrysh_start"}])
    rows.append([{"text": "⬅️ НАЗАД", "callback_data": "admin_panel"}])
    return {"inline_keyboard": rows}


