def house_menu_keyboard(user_id=None):
    rows = []
    houses = house_get_all()
    my_house = house_get_by_owner(user_id) if user_id else None
    has_house = my_house is not None
    for h in houses:
        hid = h["id"]
        hinfo = HOUSES.get(hid, {})
        owner = h["owner_id"] or 0
        currency = h["currency"]
        price = h["price"]
        price_str = format(price) + " 💰" if currency == "points" else str(price) + " 💎"
        hname = str(h["name"])
        if owner == 0 and not has_house:
            label = "🏠 " + hname + " — " + price_str
            if len(label) > 60:
                label = label[:57] + "..."
            rows.append([{"text": label, "callback_data": "house_buy_" + str(hid)}])
        else:
            if owner:
                label = "🔒 " + hname + " — " + get_display_name(owner)
            else:
                label = "🔒 " + hname + " — (у тебя уже есть дом)"
            if len(label) > 60:
                label = label[:57] + "..."
            rows.append([{"text": label, "callback_data": "house_info_" + str(hid)}])
    rows.append([{"text": "⬅️ НАЗАД", "callback_data": "back"}])
    return {"inline_keyboard": rows}


