def phone_pretty_auctions_keyboard():
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("""SELECT id, lot_value, current_bet, ends_at FROM auctions
                             WHERE status = 'active' AND lot_type = 'phone'
                             ORDER BY id ASC""")
                rows_data = c.fetchall()
    except Exception:
        rows_data = []
    rows = []
    for r in rows_data:
        num = r["lot_value"]
        bet = r["current_bet"] or 0
        label = "📱 +" + str(num)
        if bet > 0:
            label += " — " + format_short(bet)
        label += " 🆔" + str(r["id"])
        rows.append([{"text": label, "callback_data": "auction_view_" + str(r["id"])}])
    rows.append([{"text": "⬅️ НАЗАД", "callback_data": "phone_menu"}])
    return {"inline_keyboard": rows}


