def handle_bonus(chat_id, message_id, user_id):
    get_or_create_user(user_id)
    threshold = (datetime.now() - timedelta(hours=3)).strftime(DB_DATE_FMT)
    now_str = db_now()
    got = False
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT last_bonus FROM users WHERE user_id = ?", (user_id,))
                r = c.fetchone()
                can = False
                if r:
                    lb = db_parse(r["last_bonus"]) if r["last_bonus"] else None
                    if not lb or (datetime.now() - lb).total_seconds() >= 3 * 3600:
                        can = True
                if can:
                    c.execute("UPDATE users SET last_bonus = ? WHERE user_id = ?", (now_str, user_id))
                    conn.commit()
                    got = True
    except Exception as e:
        send_message(chat_id, "❌ " + str(e))
        return
    if got:
        ok, new_bal, reason = add_balance(user_id, 1_500_000)
        if not ok:
            send_message(chat_id, "❌ " + reason)
            return
        add_transaction(user_id, 1_500_000, "bonus")
        text = "🎁 БОНУС!\n\n💰 +1,500,000\n💎 Поинты: " + format(new_bal)
    else:
        last_bonus = get_last_bonus(user_id)
        if last_bonus is None:
            text = "🎁 БОНУС ДОСТУПЕН!"
        else:
            remaining = timedelta(hours=3) - (datetime.now() - last_bonus)
            total_sec = max(0, int(remaining.total_seconds()))
            h = total_sec // 3600
            m = (total_sec % 3600) // 60
            text = "⏰ ЖДИ " + str(h) + "ч " + str(m) + "мин"
    if message_id:
        edit_message(chat_id, message_id, text, back_keyboard())
    else:
        send_message(chat_id, text, back_keyboard())


