def process_transfer(chat_id, user_id, args):
    try:
        if len(args) != 2:
            send_message(chat_id, "❌ Формат: ID|@username Сумма")
            return
        target_id = None
        if args[0].startswith('@'):
            target_id = get_user_id_by_username(args[0][1:])
            if not target_id:
                send_message(chat_id, "❌ Игрок не найден!")
                return
        else:
            try:
                target_id = int(args[0])
            except ValueError:
                send_message(chat_id, "❌ ID числом!")
                return
        amount = int(args[1])
        if amount < 100:
            send_message(chat_id, "❌ Минимум 100!")
            return
        if target_id == user_id:
            send_message(chat_id, "❌ Нельзя себе!")
            return
        if target_id == 777000 or target_id == 1087968824:
            send_message(chat_id, "❌ Боту нельзя перевести")
            return
        target = get_or_create_user(target_id)
        if not target:
            send_message(chat_id, "❌ Ошибка!")
            return
        tax_percent = get_tax_percent()
        tax = int(amount * tax_percent / 100)
        net_amount = amount - tax
        ok, _, reason = sub_balance(user_id, amount)
        if not ok:
            send_message(chat_id, "❌ " + reason)
            return
        ok2, _, reason2 = add_balance(target_id, net_amount)
        if not ok2:
            add_balance(user_id, amount)
            send_message(chat_id, "❌ Ошибка начисления: " + reason2)
            return
        add_transaction(user_id, -amount, "transfer_out", "transfer", "→ " + str(target_id) + " (налог " + str(tax) + ")")
        add_transaction(target_id, net_amount, "transfer_in", "transfer", "← " + str(user_id))
        if tax > 0:
            try:
                cur_t = get_treasury(CHAT_ID)
                new_t = cur_t + tax
                if new_t > MAX_BALANCE:
                    new_t = MAX_BALANCE
                _save_treasury(CHAT_ID, new_t)
                add_transaction(0, tax, "transfer_tax", "treasury", "Налог с перевода")
            except Exception as e:
                print("⚠️ transfer tax: " + str(e))
        send_message(chat_id, "💸 " + format(amount) + " → " + get_display_name(target_id) +
                     "\n💰 Налог: " + format(tax) + " (" + str(tax_percent) + "%)" +
                     "\n📥 Дошло: " + format(net_amount))
        try:
            send_message(target_id, "💸 +" + format(net_amount) + " от " + get_display_name(user_id) +
                         "\n💰 Налог: " + format(tax))
        except Exception:
            pass
    except ValueError:
        send_message(chat_id, "❌ Формат: ID|@username Сумма")


