def handle_history_full(chat_id, message_id, user_id, filter_type="all"):
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("""SELECT id, amount, details, timestamp FROM transactions
                             WHERE user_id = ? AND type = 'transfer_out'
                             ORDER BY id DESC LIMIT 15""", (user_id,))
                outs = c.fetchall()
                c.execute("""SELECT id, amount, details, timestamp FROM transactions
                             WHERE user_id = ? AND type = 'transfer_in'
                             ORDER BY id DESC LIMIT 15""", (user_id,))
                ins = c.fetchall()
    except Exception as e:
        send_message(chat_id, "❌ " + str(e))
        return
    text = "📜 ИСТОРИЯ ПЕРЕВОДОВ\n\n"
    if filter_type == "in":
        text += "📥 <b>Только полученные</b>\n\n"
        items = [(r, "in") for r in ins]
    elif filter_type == "out":
        text += "📤 <b>Только отправленные</b>\n\n"
        items = [(r, "out") for r in outs]
    else:
        text += "📊 <b>Все переводы</b>\n\n"
        combined = [(r, "in") for r in ins] + [(r, "out") for r in outs]
        combined.sort(key=lambda x: x[0]["id"], reverse=True)
        items = combined[:30]
    if not items:
        text += "📭 Пусто.\n\nПереводи через <b>П ID сумма</b> или в ответ на сообщение."
    else:
        for row, direction in items:
            amount = big_load(row["amount"])
            details = row["details"] or ""
            counter_id = 0
            if "→" in details:
                try:
                    counter_id = int(details.split("→")[1].strip().split()[0])
                except Exception:
                    pass
            elif "←" in details:
                try:
                    counter_id = int(details.split("←")[1].strip().split()[0])
                except Exception:
                    pass
            counter_name = get_display_name(counter_id) if counter_id else "?"
            ts = str(row["timestamp"])[:16] if row["timestamp"] else "?"
            if direction == "in":
                emoji = "📥"
                sign = "+"
                arrow = "от"
            else:
                emoji = "📤"
                sign = "−"
                arrow = "к"
            text += emoji + " " + sign + format(abs(amount)) + " " + arrow + " " + str(counter_name) + "\n"
            text += "   🕐 " + ts + "\n\n"
    kb = {"inline_keyboard": [
        [{"text": "📊 ВСЕ", "callback_data": "hist_all"},
         {"text": "📥 ПОЛУЧЕНО", "callback_data": "hist_in"},
         {"text": "📤 ОТПРАВЛЕНО", "callback_data": "hist_out"}],
        [{"text": "⬅️ НАЗАД", "callback_data": "back"}],
    ]}
    if message_id:
        edit_message(chat_id, message_id, text, kb)
    else:
        send_message(chat_id, text, kb)


def handle_history_callback(chat_id, message_id, user_id, data):
    if data == "hist_all":
        handle_history_full(chat_id, message_id, user_id, "all")
    elif data == "hist_in":
        handle_history_full(chat_id, message_id, user_id, "in")
    elif data == "hist_out":
        handle_history_full(chat_id, message_id, user_id, "out")


