def handle_family_duel(chat_id, message_id, user_id):
    fam = get_user_family(user_id)
    if not fam or fam["owner_id"] != user_id:
        send_message(chat_id, "❌ Только владелец!", family_menu_keyboard(user_id))
        return
    last = db_parse(fam["last_duel"]) if fam["last_duel"] else None
    if last:
        diff = (datetime.now() - last).total_seconds()
        if diff < FAMILY_DUEL_COOLDOWN:
            left = FAMILY_DUEL_COOLDOWN - int(diff)
            m = left // 60
            s = left % 60
            send_message(chat_id, "⏰ Кулдаун: " + str(m) + "м " + str(s) + "с", family_menu_keyboard(user_id))
            return
    user_state_set(user_id, {"action": "family_duel_opponent"})
    text = ("⚔️ ВЫЗОВ\n\n"
            "⭐ Твоя репутация: " + str(fam["reputation"] or 0) + "\n\n"
            "Отправь @username или ID владельца:\n\n/cancel")
