def fp_time_left_short(ends_at_str):
    ends = db_parse(ends_at_str)
    if not ends:
        return "?"
    left = int((ends - datetime.now()).total_seconds())
    if left < 0:
        left = 0
    d = left // 86400
    h = (left % 86400) // 3600
    if d > 0:
        return str(d) + "д " + str(h) + "ч"
    m = (left % 3600) // 60
    return str(h) + "ч " + str(m) + "м"


