def process_admin_rl_rig(chat_id, user_id, text):
    if not cmd_rl_toggle(user_id):
        send_message(chat_id, "❌ Нужен ур. 4+")
        return
    user_state_pop(user_id)
    t = text.strip().lower()
    if t == "reset":
        rl_set_rig(chat_id, None)
        send_message(chat_id, "🔄 Сброшено (этот чат)")
        handle_admin_roulette_menu(chat_id, None, user_id)
        return
    try:
        n = int(t)
        if n < 0 or n > 36:
            send_message(chat_id, "❌ 0-36!")
            return
        rl_set_rig(chat_id, n)
        send_message(chat_id, "🎯 Следующее (этот чат): " + str(n))
        handle_admin_roulette_menu(chat_id, None, user_id)
    except ValueError:
        send_message(chat_id, "❌ Число или reset!")


