def process_promo_create(chat_id, user_id, text):
    if not cmd_promo_create(user_id):
        send_message(chat_id, "❌ Нужен ур. 5+")
        return
    user_state_pop(user_id)
    try:
        parts = text.split('|')
        if len(parts) < 2:
            send_message(chat_id, "❌ КОД | НАГРАДА | ЛИМИТ")
            return
        code = parts[0].strip().upper()
        reward = int(parts[1].strip())
        max_uses = int(parts[2].strip()) if len(parts) > 2 else 100
        if not code or reward < 1_000_000:
            send_message(chat_id, "❌ Мин. 1,000,000!")
            return
        success, result = create_promocode(code, reward, max_uses)
        send_message(chat_id, result)
        if success:
            handle_admin_promo_menu(chat_id, None, user_id)
    except ValueError:
        send_message(chat_id, "❌ Числа!")


