def handle_admin_users_top(chat_id, message_id, user_id):
    if not cmd_admin_panel(user_id):
        send_message(chat_id, "❌ Нужен ур. 4+")
        return
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT user_id, username, first_name, balance FROM users WHERE (is_left IS NULL OR is_left = 0) ORDER BY balance DESC LIMIT 20")
                users = c.fetchall()
        if not users:
            text = "🏆 ТОП-20\n\nПусто."
        else:
            text = "🏆 ТОП-20\n\n"
            for i, u in enumerate(users, 1):
                name = get_display_name(u["user_id"])
                bal_int = big_load(u["balance"])
                text += str(i) + ". " + str(name) + " (" + str(u["user_id"]) + ")\n   " + format(bal_int) + "\n\n"
        kb = admin_economy_keyboard() if message_id else admin_players_keyboard()
        if message_id:
            edit_message(chat_id, message_id, text, kb)
        else:
            send_long_message(chat_id, text, kb)
    except Exception as e:
        send_message(chat_id, "❌ " + str(e))


