def process_admin_user_info(chat_id, user_id, text):
    if not cmd_admin_panel(user_id):
        send_message(chat_id, "❌ Нужен ур. 4+")
        return
    user_state_pop(user_id)
    t = text.strip()
    target_id = None
    if t.startswith('@'):
        target_id = get_user_id_by_username(t[1:])
        if not target_id:
            send_message(chat_id, "❌ Не найден!")
            return
    else:
        try:
            target_id = int(t)
        except ValueError:
            send_message(chat_id, "❌ ID или @username!")
            return
    u = get_user(target_id)
    if not u:
        send_message(chat_id, "❌ Игрок не найден!")
        return
    wins, losses, won_amount, lost_amount = get_title_stats(target_id)
    titles = get_user_titles(target_id)
    fam = get_user_family(target_id)
    fam_text = "нет"
    if fam:
        fam_text = str(fam["name"]) + " (" + str(fam["reputation"] or 0) + " ⭐)"
    titles_text = ", ".join([t["name"] for t in titles]) if titles else "нет"
    biz = biz_get_by_owner(target_id)
    biz_text = ", ".join([str(b["name"]) for b in biz]) if biz else "нет"
    left_status = "🍂 УШЁЛ" if is_left(target_id) else "✅ В игре"
    name = get_display_name(target_id)
    res = craft_get_resources(target_id)
    res_text = "🪵" + format(res["wood"]) + " ⛏" + format(res["iron"]) + " 💎" + format(res["diamond"])
    hrow = house_get_by_owner(target_id)
    house_text = str(hrow["name"]) if hrow else "нет"
    frik = get_frik(target_id)
    try:
        phones = phone_get_owned(target_id)
        phone_text = ", ".join([p["number"] for p in phones]) if phones else "нет"
    except Exception:
        phone_text = "нет"
    try:
        port = crypto_get_portfolio(target_id)
        crypto_text = str(len(port)) + " поз. → " + format(crypto_get_total_value(target_id)) if port else "нет"
    except Exception:
        crypto_text = "?"
    try:
        fp_prog = fp_get_progress(target_id)
        if fp_prog:
            fp_text = (fp_pass_label(fp_prog["pass_type"]) + " ур." + str(fp_prog["level"])
                       + " 🎟" + str(fp_prog["tokens_total"]))
        else:
            fp_text = "нет"
    except Exception:
        fp_text = "?"
    role = get_staff_role(target_id)
    role_line = "\n🎖 Роль: " + get_role_label(role) if role else ""
    bal_int = big_load(u["balance"])
    txt = "👤 ПРОФИЛЬ\n\n"
    txt += "🆔 " + str(target_id) + "\n"
    txt += "📛 " + str(name) + "\n"
    txt += "📊 " + left_status + "\n"
    txt += "💰 " + format(bal_int) + "\n"
    txt += "💎 FrikCoins: " + str(frik)
    txt += role_line + "\n"
    txt += "👨‍👩‍👧 " + fam_text + "\n"
    txt += "🏠 Дом: " + house_text + "\n"
    txt += "📱 Номера: " + phone_text + "\n"
    txt += "📈 Биржа: " + crypto_text + "\n"
    txt += "🎫 FRIK PASS: " + fp_text + "\n"
    try:
        _sts = status_get(target_id)
        if _sts:
            txt += "👑 Статусы: " + " | ".join([s["label"] for s in _sts]) + "\n"
    except Exception:
        pass
    try:
        _snow = snow_get(target_id)
        if _snow > 0:
            txt += "❄️ Снежков: " + str(_snow) + "\n"
    except Exception:
        pass
    txt += "🏢 " + biz_text + "\n"
    txt += "🛠 " + res_text + "\n"
    txt += "📅 " + str(u["registered"])[:16] + "\n\n"
    txt += "🎯 Побед: " + str(wins) + "\n"
    txt += "💰 Выиграно: " + format(won_amount) + "\n"
    txt += "💀 Проиграно: " + format(lost_amount) + "\n\n"
    txt += "🏆 " + titles_text
    send_long_message(chat_id, txt, admin_players_keyboard())


def set_balance_admin(chat_id, admin_id, target_id, amount):
    if not cmd_setbal(admin_id):
        send_message(chat_id, "❌ Только ур. 7 (Команда проекта)!")
        return
    if amount < 0:
        send_message(chat_id, "❌ Минимум 0!")
        return
    if amount > MAX_BALANCE:
        send_message(chat_id, "❌ Максимум 10^100")
        return
    target = get_user(target_id)
    if not target:
        send_message(chat_id, "❌ Игрок не найден (не писал /start)!")
        return
    old_balance = big_load(target["balance"])
    if not save_balance(target_id, amount):
        send_message(chat_id, "❌ Ошибка сохранения!")
        return
    add_transaction(target_id, amount - old_balance, "setbal_admin", "admin",
                    "Админ установил баланс: " + format(old_balance) + " → " + format(amount))
    name = get_display_name(target_id)
    send_message(chat_id,
                 "✅ Баланс установлен\n\n"
                 "👤 " + str(name) + " (" + str(target_id) + ")\n"
                 "💰 Было: " + format(old_balance) + "\n"
                 "💰 Стало: " + format(amount))


def give_money(chat_id, admin_id, target_id, amount):
    if not is_admin_level(admin_id, 5):
        send_message(chat_id, "❌ Нужен ур. 5+")
        return
    if amount < 1:
        send_message(chat_id, "❌ Сумма > 0!")
        return
    target = get_or_create_user(target_id)
    if not target:
        send_message(chat_id, "❌ Не удалось создать!")
        return
    ok, new_bal, reason = add_balance(target_id, amount)
    if not ok:
        send_message(chat_id, "❌ " + reason)
        return
    add_transaction(target_id, amount, "admin_give", "admin", "От " + get_role_label(get_staff_role(admin_id)))
    name = get_display_name(target_id)
    send_message(chat_id, "✅ Выдано " + format(amount) + " → " + str(name) + "\n💰 " + format(new_bal))
    try:
        send_message(target_id, "💰 +" + format(amount) + " от админа\n💎 " + format(new_bal))
    except Exception:
        pass


def handle_setbal_command(chat_id, user_id, args, reply_to_user_id=None):
    if not cmd_setbal(user_id):
        send_message(chat_id, "❌ Только ур. 7 (Команда проекта)!")
        return
    target_id = None
    amount = None
    if reply_to_user_id is not None and len(args) == 1:
        target_id = reply_to_user_id
        try:
            amount = int(args[0])
        except ValueError:
            send_message(chat_id, "❌ Сумма числом!")
            return
    elif len(args) == 2:
        try:
            amount = int(args[0])
        except ValueError:
            send_message(chat_id, "❌ Сумма числом!")
            return
        t = args[1].strip()
        if t.startswith('@'):
            target_id = get_user_id_by_username(t[1:])
            if not target_id:
                send_message(chat_id, "❌ @username не найден!")
                return
        else:
            try:
                target_id = int(t)
            except ValueError:
                send_message(chat_id, "❌ ID или @username!")
                return
    else:
        send_message(chat_id,
                     "❌ Формат:\n"
                     "/setbal СУММА ID\n"
                     "/setbal СУММА @username\n"
                     "/setbal СУММА (в ответ)")
        return
    if target_id is None:
        send_message(chat_id, "❌ Не удалось определить игрока!")
        return
    set_balance_admin(chat_id, user_id, target_id, amount)


