def process_admin_treasury_add(chat_id, user_id, text):
    if not is_admin_level(user_id, 5):
        send_message(chat_id, "❌ Нужен ур. 5+")
        return
    user_state_pop(user_id)
    try:
        parts = text.strip().split(None, 1)
        amount = int(parts[0])
        reason = parts[1] if len(parts) > 1 else "Пополнение"
        cur_t = get_treasury(CHAT_ID)
        new_t = cur_t + amount
        if new_t > MAX_BALANCE:
            new_t = MAX_BALANCE
        _save_treasury(CHAT_ID, new_t)
        add_transaction(ADMIN_ID, amount, "treasury_admin_add", "treasury", reason)
        send_message(chat_id, "✅ +" + format(amount) + " в казну. Баланс: " + format(get_treasury(CHAT_ID)))
        handle_admin_treasury_menu(chat_id, None, user_id)
    except (ValueError, IndexError):
        send_message(chat_id, "❌ Формат: СУММА ПРИЧИНА")


