def handle_fcshop(chat_id, message_id, user_id):
    frik = get_frik(user_id)
    text = "🛍 МАГАЗИН FRIKCOINS\n\n"
    text += "💎 Твои FrikCoins: " + str(frik) + "\n\n"
    text += "📋 ТОВАРЫ:\n\n"
    for key, item in FCSHOP_ITEMS.items():
        text += item["name"] + "\n"
        text += "  💎 " + str(item["price"]) + " FC — " + item["desc"] + "\n\n"
    text += "💡 FrikCoins покупаются за Telegram Stars у админа."
    if message_id:
        edit_message(chat_id, message_id, text, fcshop_menu_keyboard(user_id))
    else:
        send_long_message(chat_id, text, fcshop_menu_keyboard(user_id))


def handle_fcshop_item(chat_id, message_id, user_id, item_key):
    item = FCSHOP_ITEMS.get(item_key)
    if not item:
        send_message(chat_id, "❌ Товар не найден!")
        return
    frik = get_frik(user_id)
    can_buy = frik >= item["price"]
    text = "🛍 " + item["name"] + "\n\n"
    text += "💰 Цена: " + str(item["price"]) + " FC\n"
    text += "📝 " + item["desc"] + "\n\n"
    text += "💎 Твои FC: " + str(frik) + "\n"
    if item_key == "lombard_cd":
        cd = lombard_get_cooldown(user_id)
        if cd and (datetime.now() - cd).total_seconds() < LOMBARD_COOLDOWN:
            left = int(LOMBARD_COOLDOWN - (datetime.now() - cd).total_seconds())
            text += "\n⏰ Кулдаун: " + str(left // 60) + "м " + str(left % 60) + "с"
        else:
            text += "\n⚠️ Кулдаун не активен — покупать нечего!"
            can_buy = False
    if item_key == "fake_unban":
        if not fake_is_banned(user_id):
            text += "\n⚠️ Ты не в бане фальшивок — покупать нечего!"
            can_buy = False
        else:
            left = fake_get_ban_time_left(user_id)
            text += "\n🚔 Бан: " + str(left // 60) + "м " + str(left % 60) + "с"
    if item_key == "roulette":
        try:
            rb = get_roulette_boost(user_id)
            if rb["percent"] > 0 and rb["until"]:
                text += "\n🎯 Активный буст: +" + str(rb["percent"]) + "% до " + rb["until"].strftime("%d.%m %H:%M")
                text += "\n(новая покупка ПРОДЛИТ срок)"
        except Exception:
            pass
    if not can_buy:
        text += "\n\n❌ Недостаточно FC"
    else:
        text += "\n\n✅ Готов купить!"
    if message_id:
        edit_message(chat_id, message_id, text, fcshop_item_keyboard(item_key))
    else:
        send_message(chat_id, text, fcshop_item_keyboard(item_key))


