def process_phone_buy_number(chat_id, user_id, text):
    state = user_state_get(user_id)
    if not state or state.get("action") != "phone_buy_number":
        return
    if text.strip().lower() in ("/cancel", "отмена"):
        user_state_pop(user_id)
        send_message(chat_id, "❌ Отменено.")
        return
    raw = text.strip()
    if not raw.isdigit() or len(raw) != 4:
        send_message(chat_id, "❌ Нужно 4 цифры (0000-9999)!")
        return
    num = raw.zfill(4)
    if num in PHONE_PRETTY_SET:
        send_message(chat_id, "❌ Красивый номер — только через аукцион!")
        return
    user_state_pop(user_id)
    ok, result = phone_buy(user_id, num)
    send_message(chat_id, result)


