def process_phone_sms_input(chat_id, user_id, text):
    state = user_state_get(user_id)
    if not state or state.get("action") != "phone_sms_input":
        return
    if text.strip().lower() in ("/cancel", "отмена"):
        user_state_pop(user_id)
        send_message(chat_id, "❌ Отменено.")
        return
    parts = text.strip().split(None, 1)
    if len(parts) < 2:
        send_message(chat_id, "❌ Формат: НОМЕР текст")
        return
    num_raw = parts[0].strip()
    msg_text = parts[1].strip()[:500]
    if not num_raw.isdigit() or len(num_raw) != 4:
        send_message(chat_id, "❌ Номер — 4 цифры!")
        return
    num = num_raw.zfill(4)
    user_state_pop(user_id)
    ok, result = phone_send_sms(user_id, num, msg_text)
    send_message(chat_id, result)


