def handle_phone_vish_cmd(chat_id, user_id, args):
    if len(args) != 2:
        send_message(chat_id, "❌ /phone_vish XXXX ID|@username")
        return
    raw = args[0].strip()
    if not raw.isdigit() or len(raw) != 4:
        send_message(chat_id, "❌ Номер — 4 цифры!")
        return
    num = raw.zfill(4)
    t = args[1].strip()
    target_id = None
    if t.startswith('@'):
        target_id = get_user_id_by_username(t[1:])
    else:
        try:
            target_id = int(t)
        except ValueError:
            pass
    if not target_id:
        send_message(chat_id, "❌ Получатель не найден!")
        return
    ok, result = phone_transfer(user_id, num, target_id)
    send_message(chat_id, result)


