def handle_phones_list_cmd(chat_id, user_id, args):
    if not cmd_houses_list(user_id):
        send_message(chat_id, "❌ Нужен ур. 1+")
        return
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("""SELECT number, owner_id, is_pretty FROM phones
                             WHERE owner_id != 0
                             ORDER BY is_pretty DESC, number ASC
                             LIMIT 100""")
                rows = c.fetchall()
    except Exception as e:
        send_message(chat_id, "❌ " + str(e))
        return
    if not rows:
        send_message(chat_id, "📋 Список номеров пуст — никто не купил.")
        return
    text = "📋 ЗАНЯТЫЕ НОМЕРА (до 100)\n\n"
    for r in rows:
        mark = " ✨" if r["is_pretty"] else ""
        owner_name = get_display_name(r["owner_id"])
        text += "📞 " + str(r["number"]) + mark + " — " + str(owner_name) + "\n"
    if len(text) > 3800:
        text = text[:3800] + "\n..."
    send_message(chat_id, text)


