def handle_admin_fp_recreate(chat_id, message_id, user_id):
    if not cmd_fp_start(user_id):
        return
    season = fp_get_active_season()
    if season:
        ok, msg = fp_finish_season()
        send_message(chat_id, msg)
    else:
        try:
            with FP_LOCK:
                with DB_LOCK:
                    with _conn() as conn:
                        c = conn.cursor()
                        c.execute("SELECT MAX(season_number) as mx FROM fp_season")
                        r = c.fetchone()
                        new_num = (r["mx"] or 0) + 1
                        started = datetime.now().strftime(DB_DATE_FMT)
                        ends = (datetime.now() + timedelta(days=FP_SEASON_DAYS)).strftime(DB_DATE_FMT)
                        c.execute("""INSERT INTO fp_season (season_number, started_at, ends_at, status)
                                     VALUES (?, ?, ?, 'active')""",
                                  (new_num, started, ends))
                        conn.commit()
            send_message(chat_id, "✅ Создан сезон " + str(new_num))
        except Exception as e:
            send_message(chat_id, "❌ " + str(e))
    handle_admin_fp_menu(chat_id, message_id, user_id)


def handle_admin_fp_info(chat_id, message_id, user_id):
    handle_admin_fp_menu(chat_id, message_id, user_id)


def handle_helpers_online(chat_id, message_id, user_id):
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT user_id, role FROM staff_roles WHERE role = ?", (ROLE_HELPER,))
                helper_rows = c.fetchall()
    except Exception as e:
        send_message(chat_id, "❌ " + str(e))
        return
    now = datetime.now()
    online = []
    offline = []
    for r in helper_rows:
        hid = r["user_id"]
        u = get_user(hid)
        last = db_parse(u["last_active"]) if (u and u["last_active"]) else None
        is_on = (last and (now - last).total_seconds() < HELPER_ONLINE_SEC)
        if is_on:
            online.append(hid)
        else:
            offline.append(hid)

    def _ans_sort(uid):
        st = helper_stats_get(uid)
        return -st["answered"]

    online.sort(key=_ans_sort)
    offline.sort(key=_ans_sort)
    text = "🛠 <b>ХЕЛПЕРЫ</b>\n\n"
    if online:
        text += "🟢 <b>Онлайн (" + str(len(online)) + "):</b>\n"
        for hid in online:
            name = get_display_name(hid)
            st = helper_stats_get(hid)
            text += "  🟢 " + str(name) + " — ответил " + str(st["answered"]) + "\n"
    else:
        text += "🟢 Онлайн: <i>никого нет</i>\n"
    if offline:
        text += "\n⚫ <b>Оффлайн (" + str(len(offline)) + "):</b>\n"
        for hid in offline[:10]:
            name = get_display_name(hid)
            st = helper_stats_get(hid)
            text += "  ⚫ " + str(name) + " — ответил " + str(st["answered"]) + "\n"
        if len(offline) > 10:
            text += "  ... и ещё " + str(len(offline) - 10) + "\n"
    if not helper_rows:
        text += "\n<i>Хелперов пока нет.</i>"
    text += "\n\n💬 <b>Задать вопрос:</b> /rep_helpers (в ЛС боту)"
    kb = helpers_online_keyboard(user_id)
    if message_id:
        edit_message(chat_id, message_id, text, kb)
    else:
        send_long_message(chat_id, text, kb)


def handle_rep_helpers(chat_id, user_id, is_private=False):
    if not is_private:
        send_message(chat_id,
                     "❓ Вопрос хелперам можно задать <b>только в личке бота</b>.\n\n"
                     "👉 Напиши мне в ЛС: /rep_helpers")
        return
    user = get_user(user_id)
    if not user:
        send_message(chat_id, "❌ Напиши /start")
        return
    if is_left(user_id):
        send_message(chat_id, "❌ Ты ушёл из бота!")
        return
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT COUNT(*) as cnt FROM staff_roles WHERE role = ?", (ROLE_HELPER,))
                if c.fetchone()["cnt"] == 0:
                    send_message(chat_id, "❌ Хелперов пока нет. Попробуй позже.")
                    return
    except Exception:
        pass
    help_chat = get_help_chat_id()
    if not help_chat:
        send_message(chat_id, "❌ Приём вопросов временно недоступен.\nПопробуй позже.")
        return
    user_state_set(user_id, {"action": "help_question_input"})
    text = ("❓ <b>ЗАДАТЬ ВОПРОС ХЕЛПЕРУ</b>\n\n"
            "Напиши свой вопрос одним сообщением (до " + str(HELP_MAX_QUESTION_LEN) + " символов).\n\n"
            "⚠️ Ответ придёт тебе в <b>личные сообщения</b> от хелпера.\n"
            "⏰ Кулдаун: " + str(HELP_QUESTION_COOLDOWN) + " сек между вопросами.\n\n"
            "/cancel — отменить")
    send_message(chat_id, text, back_keyboard())


def process_help_question_input(chat_id, user_id, text):
    state = user_state_get(user_id)
    if not state or state.get("action") != "help_question_input":
        return False
    t = text.strip()
    if t.lower() in ("/cancel", "отмена"):
        user_state_pop(user_id)
        send_message(chat_id, "❌ Отменено.")
        return True
    if len(t) < 5:
        send_message(chat_id, "❌ Слишком короткий вопрос (минимум 5 символов).")
        return True
    username = ""
    try:
        u = get_user(user_id)
        if u and u["username"]:
            username = "@" + str(u["username"])
    except Exception:
        pass
    ok, result = help_create_question(user_id, username, t)
    if not ok:
        send_message(chat_id, "❌ " + str(result))
        return True
    qid = result
    user_state_pop(user_id)
    help_chat = get_help_chat_id()
    qtext = ("🆘 <b>ВОПРОС #" + str(qid) + "</b>\n\n"
             "👤 " + str(get_display_name(user_id)) + " " + str(username) + "\n"
             "🆔 <code>" + str(user_id) + "</code>\n\n"
             "❓ " + esc(t))
    kb = help_question_keyboard(qid)
    res = send_message(help_chat, qtext, kb)
    if res and res.get("ok"):
        mid = res["result"]["message_id"]
        try:
            with DB_LOCK:
                with _conn() as conn:
                    c = conn.cursor()
                    c.execute("UPDATE help_questions SET chat_msg_id = ? WHERE id = ?", (mid, qid))
                    conn.commit()
            with help_chat_messages_lock:
                help_chat_messages[qid] = mid
        except Exception as e:
            print("⚠️ save chat_msg_id: " + str(e))
    send_message(chat_id,
                 "✅ <b>Вопрос принят!</b>\n\n"
                 "🆔 #" + str(qid) + "\n"
                 "⏰ Жди ответа в личку. Хелперы уже уведомлены.")
    return True


def handle_hhelp(chat_id, message_id, user_id):
    role = get_staff_role(user_id)
    if role != ROLE_HELPER:
        send_message(chat_id, "❌ Только для хелперов!")
        return
    st = helper_stats_get(user_id)
    first_seen = "?"
    if st["first_seen"]:
        dt = db_parse(st["first_seen"])
        if dt:
            first_seen = dt.strftime("%d.%m.%Y")
    avg = st["avg_response_sec"]
    if avg > 0:
        avg_str = str(avg // 60) + "м " + str(avg % 60) + "с"
    else:
        avg_str = "—"
    text = ("🛠 <b>СПРАВКА ХЕЛПЕРА</b>\n\n"
            "📅 Работаешь с: " + first_seen + "\n"
            "✅ Ответил: " + str(st["answered"]) + "\n"
            "❌ Отменил: " + str(st["cancelled"]) + "\n"
            "📥 Взял: " + str(st["taken"]) + "\n"
            "⏱ Среднее время ответа: " + avg_str + "\n\n"
            "<b>Что ты можешь:</b>\n"
            "• Отвечать на вопросы игроков (в чате хелперов)\n"
            "• Команда /ahelp — справка\n"
            "• Команда /astats — статистика\n\n"
            "<b>Твои права:</b>\n"
            "🛠 Помощник игроков")
    if message_id:
        edit_message(chat_id, message_id, text, back_keyboard())
    else:
        send_message(chat_id, text, back_keyboard())


def handle_astats(chat_id, message_id, user_id):
    role = get_staff_role(user_id)
    if not role:
        send_message(chat_id, "❌ Только для стаффов!")
        return
    text = "📊 <b>ТВОЯ СТАТИСТИКА</b>\n\n"
    text += "🎖 Роль: " + get_role_label(role) + "\n"
    u = get_user(user_id)
    if u and u["registered"]:
        dt = db_parse(u["registered"])
        if dt:
            text += "📅 В боте с: " + dt.strftime("%d.%m.%Y %H:%M") + "\n"
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT added_at, added_by FROM staff_roles WHERE user_id = ?", (user_id,))
                r = c.fetchone()
                if r:
                    added_at = db_parse(r["added_at"]) if r["added_at"] else None
                    if added_at:
                        text += "👑 Назначен: " + added_at.strftime("%d.%m.%Y %H:%M") + "\n"
                    if r["added_by"]:
                        text += "👤 Кем: " + str(get_display_name(r["added_by"])) + "\n"
    except Exception:
        pass
    if role == ROLE_HELPER:
        st = helper_stats_get(user_id)
        avg = st["avg_response_sec"]
        avg_str = (str(avg // 60) + "м " + str(avg % 60) + "с") if avg > 0 else "—"
        text += "\n<b>📞 Ответы на вопросы:</b>\n"
        text += "✅ Ответил: " + str(st["answered"]) + "\n"
        text += "❌ Отменил: " + str(st["cancelled"]) + "\n"
        text += "📥 Взял: " + str(st["taken"]) + "\n"
        text += "⏱ Средний ответ: " + avg_str + "\n"
    logs = staff_log_get(actor_id=user_id, limit=10)
    if logs:
        text += "\n<b>📜 Последние действия:</b>\n"
        for lg in logs:
            ts = str(lg["timestamp"])[:16] if lg["timestamp"] else "?"
            text += "  • " + str(lg["action"]) + " | " + ts + "\n"
    if message_id:
        edit_message(chat_id, message_id, text, back_keyboard())
    else:
        send_long_message(chat_id, text, back_keyboard())


def handle_ahelp(chat_id, message_id, user_id):
    role = get_staff_role(user_id)
    if not role or role == ROLE_HELPER:
        send_message(chat_id, "❌ Только для админов (ур. 1-7).")
        return
    lvl = get_role_level(role)
    text = "👑 <b>СПРАВКА СТАФФА</b>\n\n"
    text += "🎖 Твоя роль: " + get_role_label(role) + "\n"
    text += "📊 Уровень: " + str(lvl) + "/7\n\n"
    text += "🟢 — доступно тебе, 🔒 — нужно выше\n\n"

    commands = [
        (1, "/bal ID — баланс игрока"),
        (1, "/shield_add ID — в защиту"),
        (1, "/unban_fake ID — снять бан фальшивок"),
        (1, "/houses_list — список домов"),
        (1, "/staff_list — список стаффа"),
        (2, "/shield_remove ID — снять защиту"),
        (2, "/family_list — список семей"),
        (2, "/rozygrysh — запустить розыгрыш"),
        (2, "/give_title ID текст — титул (≤12 симв., раз в 2 дня)"),
        (2, "Опросы (UI)"),
        (3, "/unpokedova ID — вернуть ушедшего"),
        (3, "/shield_list — список защиты"),
        (3, "Создать сбор (UI)"),
        (3, "/add_advokat ID — выдать адвоката"),
        (3, "/givephone, /resetphone, /phones_list"),
        (4, "/rl_on / /rl_off — рулетка"),
        (4, "/resetplayer ID — обнулить игрока"),
        (4, "/family_give ID сумма — репутация"),
        (4, "/season_end — завершить сезон семей"),
        (4, "/fp_start — завершить сезон FRIK PASS"),
        (4, "/mafia_limit 0-100 — лимит мафии"),
        (4, "👑 АДМИН-ПАНЕЛЬ (UI)"),
        (4, "🛠 СТАФФ / ХЕЛПЕРЫ (UI)"),
        (5, "/res_add ID ресурс кол-во — выдать ресурсы"),
        (5, "/family_reset ID — удалить семью"),
        (5, "/givehouse ID номер — выдать дом"),
        (5, "Промокоды (UI)"),
        (5, "Казна (UI)"),
        (5, "/give ID СУММА — выдать поинты (макс. 100KKK)"),
        (6, "/gethelp ID|@user — назначить хелпера"),
        (6, "/delhelper ID|@user — снять хелпера"),
        (6, "/help_list — список хелперов"),
        (6, "Выдать/забрать бизнес (UI)"),
        (6, "Титулы БЕЗ лимита"),
        (7, "/add_admin УРОВЕНЬ ID|@user — выдать админку"),
        (7, "/add_admin_not ID|@user — снять"),
        (7, "/deller_admin ID|@user — понизить"),
        (7, "/set_help_chat ID — чат хелперов"),
        (7, "/setbal — установить баланс"),
        (7, "/fullreset — ПОЛНЫЙ СБРОС"),
        (7, "🎉 ИВЕНТЫ (UI) — переключение, выдача билетов/кейсов/статусов"),
    ]

    cur_lvl = 0
    for min_lvl, cmd_text in commands:
        if min_lvl != cur_lvl:
            cur_lvl = min_lvl
            text += "\n<b>─── Уровень " + str(cur_lvl) + " ───</b>\n"
        mark = "✅" if lvl >= min_lvl else "🔒"
        text += mark + " " + cmd_text + "\n"
