def handle_help_list(chat_id, message_id, user_id):
    if not cmd_help_list(user_id):
        send_message(chat_id, "❌ Только ур. 6+ (Главный Хелпер)!")
        return
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT user_id FROM staff_roles WHERE role = ?", (ROLE_HELPER,))
                rows = c.fetchall()
    except Exception as e:
        send_message(chat_id, "❌ " + str(e))
        return
    if not rows:
        send_message(chat_id, "📋 Хелперов нет.")
        return
    now = datetime.now()
    text = "🛠 <b>ВСЕ ХЕЛПЕРЫ (" + str(len(rows)) + ")</b>\n\n"
    online = []
    offline = []
    for r in rows:
        hid = r["user_id"]
        u = get_user(hid)
        last = db_parse(u["last_active"]) if (u and u["last_active"]) else None
        is_on = (last and (now - last).total_seconds() < HELPER_ONLINE_SEC)
        name = get_display_name(hid)
        st = helper_stats_get(hid)
        line = (str(name) + " | ✅ " + str(st["answered"]) +
                " | ❌ " + str(st["cancelled"]))
        if is_on:
            online.append("🟢 " + line)
        else:
            offline.append("⚫ " + line)
    if online:
        text += "<b>Онлайн:</b>\n" + "\n".join(online) + "\n\n"
    if offline:
        text += "<b>Оффлайн:</b>\n" + "\n".join(offline)
    if message_id:
        edit_message(chat_id, message_id, text, back_keyboard())
    else:
        send_long_message(chat_id, text, back_keyboard())


def handle_gethelp_cmd(chat_id, user_id, args):
    if not cmd_gethelp(user_id):
        send_message(chat_id, "❌ Только ур. 6+ (Главный Хелпер)!")
        return
    if len(args) != 1:
        send_message(chat_id, "❌ /gethelp ID|@username")
        return
    target = shield_resolve_id(args[0])
    if not target:
        send_message(chat_id, "❌ Игрок не найден!")
        return
    if get_user(target) is None:
        send_message(chat_id, "❌ Игрок не писал /start")
        return
    if target == user_id:
        send_message(chat_id, "❌ Себя нельзя!")
        return
    existing = get_staff_role(target)
    if existing == ROLE_HELPER:
        send_message(chat_id, "ℹ️ Он уже хелпер.")
        return
    if existing:
        send_message(chat_id, "❌ У него уже другая роль: " + get_role_label(existing))
        return
    ok, msg = set_staff_role(target, ROLE_HELPER, added_by=user_id)
    if ok:
        try:
            with DB_LOCK:
                with _conn() as conn:
                    c = conn.cursor()
                    c.execute("INSERT OR IGNORE INTO help_stats (helper_id) VALUES (?)", (target,))
                    conn.commit()
        except Exception:
            pass
        send_message(chat_id, "✅ " + get_display_name(target) + " теперь хелпер!")
        try:
            send_message(target,
                         "🎉 <b>ТЕБЯ НАЗНАЧИЛИ ХЕЛПЕРОМ!</b>\n\n"
                         "🛠 Ты теперь помогаешь игрокам.\n"
                         "📖 /hhelp — твоя справка\n"
                         "📊 /astats — твоя статистика\n\n"
                         "Вопросы будут приходить в чат хелперов.")
        except Exception:
            pass
    else:
        send_message(chat_id, str(msg))


def handle_delhelper_cmd(chat_id, user_id, args):
    if not cmd_delhelper(user_id):
        send_message(chat_id, "❌ Только ур. 6+!")
        return
    if len(args) != 1:
        send_message(chat_id, "❌ /delhelper ID|@username")
        return
    target = shield_resolve_id(args[0])
    if not target:
        send_message(chat_id, "❌ Игрок не найден!")
        return
    role = get_staff_role(target)
    if role != ROLE_HELPER:
        send_message(chat_id, "❌ Он не хелпер.")
        return
    ok, msg = remove_staff_role(target, removed_by=user_id)
    if ok:
        send_message(chat_id, "✅ " + get_display_name(target) + " больше не хелпер.")
        try:
            send_message(target, "❌ <b>Тебя сняли с должности хелпера.</b>")
        except Exception:
            pass
    else:
        send_message(chat_id, str(msg))


def handle_set_help_chat_cmd(chat_id, user_id, args):
    if not cmd_set_help_chat(user_id):
        send_message(chat_id, "❌ Только ур. 7 (Команда проекта)!")
        return
    if len(args) != 1:
        send_message(chat_id,
                     "❌ /set_help_chat ID\n"
                     "Пример: /set_help_chat -1001234567890\n"
                     "/set_help_chat off — сбросить")
        return
    t = args[0].strip()
    if t.lower() in ("off", "0", "none"):
        set_setting("help_chat_id", "0")
        send_message(chat_id, "✅ Чат хелперов сброшен (0).")
        return
    try:
        cid = int(t)
    except ValueError:
        send_message(chat_id, "❌ ID числом! (например -1001234567890)")
        return
    set_setting("help_chat_id", str(cid))
    try:
        res = send_message(cid,
                           "🛠 <b>Чат хелперов установлен!</b>\n\n"
                           "Сюда будут приходить вопросы от игроков.\n"
                           "Ставь ✅-ответы кнопками ниже.")
        if res and res.get("ok"):
            send_message(chat_id, "✅ Чат хелперов установлен: <code>" + str(cid) + "</code>")
        else:
            send_message(chat_id, "⚠️ Сохранил, но бот не может написать в чат.\n"
                                  "Проверь, что бот админ в чате и ID верный.")
    except Exception as e:
        send_message(chat_id, "⚠️ Сохранено, но ошибка проверки: " + str(e))


def handle_help_take_callback(cb_id, chat_id, message_id, user_id, qid):
    if get_staff_role(user_id) != ROLE_HELPER:
        answer_callback(cb_id, "❌ Ты не хелпер", True)
        return
    ok, msg = help_take_question(qid, user_id)
    if not ok:
        answer_callback(cb_id, str(msg), True)
        return
    answer_callback(cb_id, "✅ Вопрос твой!", False)
    q = help_get_question(qid)
    if not q:
        return
    private_text = (
        "✏️ <b>ВОПРОС #" + str(qid) + "</b>\n\n"
        "👤 " + str(q["username"] or get_display_name(q["user_id"])) + "\n"
        "❓ " + esc(q["question"]) + "\n\n"
        "Напиши ответ одним сообщением.\n"
        "⏰ У тебя " + str(HELP_TAKEOVER_TIMEOUT // 60) + " минут.\n\n"
        "/cancel — отменить"
    )
    send_message(user_id, private_text, help_answer_control_keyboard(qid))
    user_state_set(user_id, {"action": "help_answering", "qid": qid})
    try:
        help_chat = get_help_chat_id()
        new_text = ("🆘 <b>ВОПРОС #" + str(qid) + "</b>\n\n"
                    "👤 " + str(q["username"] or get_display_name(q["user_id"])) + "\n"
                    "🆔 <code>" + str(q["user_id"]) + "</code>\n\n"
                    "❓ " + esc(q["question"]) + "\n\n"
                    "⏳ <i>Взял: " + str(get_display_name(user_id)) + "</i>")
        kb = {"inline_keyboard": [[
            {"text": "⏳ Взято — ждём ответа", "callback_data": "help_noop"}
        ]]}
        edit_message(help_chat, message_id, new_text, kb)
    except Exception as e:
        print("⚠️ update help chat: " + str(e))


def handle_help_decline_callback(cb_id, chat_id, message_id, user_id, qid):
    if get_staff_role(user_id) != ROLE_HELPER:
        answer_callback(cb_id, "❌ Ты не хелпер", True)
        return
    answer_callback(cb_id, "ℹ️ Игнорируешь вопрос", False)


def process_help_answering(chat_id, user_id, text):
    state = user_state_get(user_id)
    if not state or state.get("action") != "help_answering":
        return False
    if get_staff_role(user_id) != ROLE_HELPER:
        user_state_pop(user_id)
        return False
    t = text.strip()
    if t.lower() in ("/cancel", "отмена"):
        qid = state.get("qid")
        user_state_pop(user_id)
        if qid:
            ok, r = help_cancel_question(qid, user_id)
            if ok:
                send_message(r["user_id"],
                             "⚠️ <b>Вопрос #" + str(qid) + " не был отвечен.</b>\n"
                             "Хелпер отменил ответ. Ожидайте.")
                try:
                    help_chat = get_help_chat_id()
                    with help_chat_messages_lock:
                        mid = help_chat_messages.get(qid)
                    if mid:
                        q = help_get_question(qid)
                        if q:
                            new_text = ("🆘 <b>ВОПРОС #" + str(qid) + "</b>\n\n"
                                        "👤 " + str(q["username"] or get_display_name(q["user_id"])) + "\n"
                                        "❓ " + esc(q["question"]) + "\n\n"
                                        "❌ <i>Отменил: " + str(get_display_name(user_id)) + "</i>")
                            edit_message(help_chat, mid, new_text, help_question_keyboard(qid))
                except Exception as e:
                    print("⚠️ cancel update chat: " + str(e))
                send_message(user_id, "❌ Ответ отменён.")
        return True
    if len(t) < 2:
        send_message(user_id, "❌ Слишком короткий ответ.")
        return True
    qid = state.get("qid")
    if not qid:
        user_state_pop(user_id)
        return False
    ok, r = help_answer_question(qid, user_id, t)
    if not ok:
        send_message(user_id, "❌ " + str(r))
        return True
    user_state_pop(user_id)
    victim_id = r["user_id"]
    answer = r["answer"]
    try:
        send_message(victim_id,
                     "📬 <b>ОТВЕТ ОТ ХЕЛПЕРА</b>\n\n"
                     "👤 " + str(get_display_name(user_id)) + "\n"
                     "💬 " + esc(answer) + "\n"
                     "🕐 " + datetime.now().strftime("%H:%M"))
    except Exception as e:
        send_message(user_id, "⚠️ Не смог отправить игроку: " + str(e))
    try:
        help_chat = get_help_chat_id()
        with help_chat_messages_lock:
            mid = help_chat_messages.get(qid)
        if mid:
            q = help_get_question(qid)
            if q:
                new_text = ("✅ <b>ВОПРОС #" + str(qid) + " — ОТВЕЧЕНО</b>\n\n"
                            "👤 " + str(q["username"] or get_display_name(q["user_id"])) + "\n"
                            "❓ " + esc(q["question"]) + "\n\n"
                            "💬 " + esc(answer) + "\n\n"
                            "✍️ <i>Ответил: " + str(get_display_name(user_id)) + "</i>")
                kb = {"inline_keyboard": [[
                    {"text": "✅ Отвечено", "callback_data": "help_noop"}
                ]]}
                edit_message(help_chat, mid, new_text, kb)
                with help_chat_messages_lock:
                    help_chat_messages.pop(qid, None)
    except Exception as e:
        print("⚠️ answer update chat: " + str(e))
    send_message(user_id, "✅ <b>Ответ отправлен игроку!</b>\n\n🎉 Спасибо за помощь.")
    return True


