def process_admin_family_delete(chat_id, user_id, text):
    if not cmd_family_reset(user_id):
        send_message(chat_id, "❌ Нужен ур. 5+")
        return
    user_state_pop(user_id)
    if text.strip().lower() in ("/cancel", "отмена"):
        send_message(chat_id, "❌ Отменено.")
        handle_admin_family_menu(chat_id, None, user_id)
        return
    fam = None
    t = text.strip()
    if t.startswith('@'):
        target = get_user_id_by_username(t[1:])
        if target:
            fam = get_family_by_owner(target)
    else:
        try:
            fid = int(t)
            fam = get_family_by_id(fid)
            if not fam:
                fam = get_family_by_owner(fid)
        except ValueError:
            pass
    if not fam:
        send_message(chat_id, "❌ Не найдена!")
        handle_admin_family_menu(chat_id, None, user_id)
        return
    name = fam["name"]
    fid = fam["id"]
    members = get_family_members(fid)
    delete_family(fid)
    for m in members:
        try:
            send_message(m, "❌ Семья " + str(name) + " удалена админом")
        except Exception:
            pass
    staff_log_write(user_id, "family_delete", 0, "Семья: " + str(name))
    send_message(chat_id, "✅ Семья " + str(name) + " (ID:" + str(fid) + ") удалена")
    handle_admin_family_menu(chat_id, None, user_id)


