def process_admin_family_give(chat_id, user_id, text):
    if not cmd_family_give(user_id):
        send_message(chat_id, "❌ Нужен ур. 4+")
        return
    user_state_pop(user_id)
    if text.strip().lower() in ("/cancel", "отмена"):
        send_message(chat_id, "❌ Отменено.")
        handle_admin_family_menu(chat_id, None, user_id)
        return
    try:
        parts = text.split('|')
        if len(parts) != 2:
            send_message(chat_id, "❌ Формат: ID | СУММА")
            return
        key = parts[0].strip()
        amount = int(parts[1].strip())
        fam = None
        if key.startswith('@'):
            target = get_user_id_by_username(key[1:])
            if target:
                fam = get_family_by_owner(target)
        else:
            try:
                fid = int(key)
                fam = get_family_by_id(fid)
                if not fam:
                    fam = get_family_by_owner(fid)
            except ValueError:
                pass
        if not fam:
            send_message(chat_id, "❌ Не найдена!")
            handle_admin_family_menu(chat_id, None, user_id)
            return
        family_add_reputation(fam["id"], amount)
        new_fam = get_family_by_id(fam["id"])
        staff_log_write(user_id, "family_rep_give", 0,
                        "Семья " + str(fam["name"]) + " +" + str(amount))
        send_message(chat_id, "✅ " + str(fam["name"]) + ": " + str(amount) + " ⭐\nТеперь: " + str(new_fam["reputation"] or 0))
        handle_admin_family_menu(chat_id, None, user_id)
    except ValueError:
        send_message(chat_id, "❌ Число!")


