def family_season_end(notify_admin=True):
    top = get_family_top(1)
    if not top:
        return None
    row = top[0]
    fid = row[0]
    name = row[1]
    owner_id = row[2]
    rep = row[3]
    oname = get_display_name(owner_id)
    season_num = get_setting("family_season_number")
    try:
        season_num = int(season_num) if season_num else 1
    except Exception:
        season_num = 1
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("""INSERT INTO family_season
                             (season_number, winner_name, winner_owner, winner_reputation, started_at, ended_at)
                             VALUES (?, ?, ?, ?, ?, ?)""",
                          (season_num, name, owner_id, rep or 0, None, db_now()))
                c.execute("UPDATE families SET reputation = 0")
                conn.commit()
        set_setting("family_season_number", str(season_num + 1))
    except Exception as e:
        print("⚠️ family_season_end: " + str(e))
    if notify_admin:
        text = ("🏆 СЕЗОН СЕМЕЙ ЗАВЕРШЁН!\n\n" +
                "🥇 " + str(name) + "\n👑 " + str(oname) + "\n🆔 " + str(owner_id) +
                "\n⭐ " + str(rep or 0))
        try:
            send_message(ADMIN_ID, text)
        except Exception as e:
            print("⚠️ season report: " + str(e))
    return (name, owner_id, oname, rep or 0)


