def process_admin_auction_create(chat_id, user_id, text):
    if not cmd_admin_panel(user_id):
        send_message(chat_id, "❌ Нужен ур. 4+")
        return
    state = user_state_get(user_id)
    if not state or state.get("action") != "admin_auction_create":
        return
    step = state.get("step")
    data = state.get("data", {})
    if text.strip().lower() in ("/cancel", "отмена"):
        user_state_pop(user_id)
        send_message(chat_id, "❌ Отменено.")
        return
    if step == "title":
        data["title"] = text.strip()[:60]
        state["data"] = data
        state["step"] = "description"
        user_state_set(user_id, state)
        send_message(chat_id, "🔨 Шаг 2/7\n\nВведи ОПИСАНИЕ лота (или «-» чтобы пропустить):", back_keyboard())
        return
    if step == "description":
        desc = text.strip()
        if desc == "-":
            desc = ""
        data["description"] = desc[:200]
        state["data"] = data
        state["step"] = "type"
        user_state_set(user_id, state)
        kb = {"inline_keyboard": [
            [{"text": "🏆 Титул", "callback_data": "auc_type_title"}],
            [{"text": "✨ Кастомный", "callback_data": "auc_type_custom_title"}],
            [{"text": "💰 Поинты", "callback_data": "auc_type_money"}],
            [{"text": "❌ ОТМЕНА", "callback_data": "auc_cancel"}],
        ]}
        send_message(chat_id, "🔨 Шаг 3/7\n\nВыбери ТИП лота:", kb)
        return
    if step == "value":
        lot_type = data.get("lot_type")
        if lot_type == "money":
            try:
                val = int(text.strip())
                if val <= 0:
                    send_message(chat_id, "❌ > 0!")
                    return
                data["lot_value"] = str(val)
            except ValueError:
                send_message(chat_id, "❌ Число!")
                return
        else:
            data["lot_value"] = text.strip()[:100]
        state["data"] = data
        state["step"] = "min_bet"
        user_state_set(user_id, state)
        send_message(chat_id, "🔨 Шаг 4/7\n\nМин. ставка:", back_keyboard())
        return
    if step == "min_bet":
        try:
            mb = int(text.strip())
            if mb < 100_000:
                send_message(chat_id, "❌ Минимум 100,000!")
                return
            data["min_bet"] = mb
        except ValueError:
            send_message(chat_id, "❌ Число!")
            return
        state["data"] = data
        state["step"] = "step"
        user_state_set(user_id, state)
        send_message(chat_id, "🔨 Шаг 5/7\n\nШаг (мин 500,000):", back_keyboard())
        return
    if step == "step":
        try:
            st = int(text.strip())
            if st < 500_000:
                send_message(chat_id, "❌ Минимум 500,000!")
                return
            data["step"] = st
        except ValueError:
            send_message(chat_id, "❌ Число!")
            return
        state["data"] = data
        state["step"] = "duration"
        user_state_set(user_id, state)
        send_message(chat_id, "🔨 Шаг 6/7\n\nДлительность (минуты):", back_keyboard())
        return
    if step == "duration":
        try:
            dur = int(text.strip())
            if dur < 1 or dur > 10080:
                send_message(chat_id, "❌ 1-10080!")
                return
        except ValueError:
            send_message(chat_id, "❌ Число!")
            return
        user_state_pop(user_id)
        ok, result = create_auction(
            data.get("title", "Лот"),
            data.get("description", ""),
            data.get("lot_type", "money"),
            data.get("lot_value", "0"),
            data.get("min_bet", 100_000),
            data.get("step", 500_000),
            dur,
            CHAT_ID,
            user_id
        )
        if ok:
            send_message(chat_id, "✅ Лот #" + str(result) + " создан!")
            staff_log_write(user_id, "auction_create", 0, "Лот: " + str(data.get("title", "?")))
            try:
                post_auction_to_chat(CHAT_ID, result)
            except Exception as e:
                print("⚠️ post_auction: " + str(e))
        else:
            send_message(chat_id, str(result))


