def handle_admin_auction_cancel(chat_id, message_id, user_id, auction_id):
    if not cmd_admin_panel(user_id):
        send_message(chat_id, "❌ Нужен ур. 4+")
        return
    a = get_auction(auction_id)
    if not a:
        send_message(chat_id, "❌ Не найден!")
        return
    if a["status"] != "active":
        send_message(chat_id, "❌ Уже завершён!")
        return
    winner = a["current_winner"]
    win_amount = a["current_bet"]
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("UPDATE auctions SET status = 'cancelled' WHERE id = ?", (auction_id,))
                conn.commit()
        if winner and win_amount > 0:
            add_balance(winner, win_amount)
    except Exception as e:
        send_message(chat_id, "❌ " + str(e))
        return
    staff_log_write(user_id, "auction_cancel", 0, "Лот #" + str(auction_id))
    send_message(chat_id, "✅ Лот #" + str(auction_id) + " отменён.")
    try:
        send_message(a["chat_id"], "❌ Лот #" + str(auction_id) + " отменён админом.")
    except Exception:
        pass


