def place_bid(chat_id, user_id, auction_id, amount):
    a = get_auction(auction_id)
    if not a or a["status"] != "active":
        send_message(chat_id, "❌ Лот неактивен!")
        return
    min_next = a["current_bet"] + a["step"] if a["current_bet"] > 0 else a["min_bet"]
    if amount < min_next:
        send_message(chat_id, "❌ Минимум: " + format(min_next))
        return
    prev = a["current_winner"]
    prev_amt = a["current_bet"]
    ok, _, reason = sub_balance(user_id, amount)
    if not ok:
        send_message(chat_id, "❌ " + reason)
        return
    if prev and prev != user_id and prev_amt > 0:
        add_balance(prev, prev_amt)
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("UPDATE auctions SET current_bet = ?, current_winner = ? WHERE id = ?",
                          (amount, user_id, auction_id))
                c.execute("INSERT INTO auction_bets (auction_id, user_id, amount) VALUES (?, ?, ?)",
                          (auction_id, user_id, amount))
                conn.commit()
        send_message(chat_id, "✅ Ставка " + format(amount) + " принята!")
        if prev and prev != user_id:
            try:
                send_message(prev, "⚠️ Твою ставку перебили на лоте #" + str(auction_id))
            except Exception:
                pass
        refresh_auction_message(auction_id)
    except Exception as e:
        add_balance(user_id, amount)
        send_message(chat_id, "❌ " + str(e))


