def handle_court_menu(chat_id, message_id, user_id, judge_biz=""):
    if not judge_biz:
        judges = court_get_judges()
        if not judges:
            send_message(chat_id, "❌ Нет активных судей!")
            return
        if len(judges) == 1:
            judge_biz = judges[0][0]
        else:
            text = ("⚖️ ВЫБОР СУДЬИ\n\n"
                    "В какой суд подать иск?")
            kb = court_judge_choice_keyboard()
            if message_id:
                edit_message(chat_id, message_id, text, kb)
            else:
                send_message(chat_id, text, kb)
            return
    biz = biz_get(judge_biz)
    if not biz or biz["owner_id"] != user_id:
        judge_name = "нет"
        if biz and biz["owner_id"]:
            judge_name = get_display_name(biz["owner_id"])
        text = ("⚖️ " + str(biz["name"]) + "\n\n"
                "👨‍⚖️ Судья: " + str(judge_name) + "\n\n"
                "📝 Можешь подать иск на того, кто тебя ограбил.\n"
                "⏰ Срок: " + str(ADVOKAT_FREEZE_MIN) + " мин\n"
                "💰 Моральный ущерб: +" + str(COURT_MORAL_PERCENT) + "%")
        if message_id:
            edit_message(chat_id, message_id, text, court_keyboard(judge_biz))
        else:
            send_message(chat_id, text, court_keyboard(judge_biz))
        return
    handle_court_judge_panel(chat_id, message_id, user_id, judge_biz)


def handle_court_judge_panel(chat_id, message_id, user_id, judge_biz=""):
    if not judge_biz:
        judges = court_get_judges()
        for bt, owner in judges:
            if owner == user_id:
                judge_biz = bt
                break
    if not judge_biz:
        send_message(chat_id, "❌ Ты не судья!")
        return
    biz = biz_get(judge_biz)
    if not biz or biz["owner_id"] != user_id:
        send_message(chat_id, "❌ Ты не судья!")
        return
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT id, plaintiff, defendant, amount, reason FROM court_cases WHERE status = 'pending' AND judge_biz = ? ORDER BY id DESC LIMIT 10",
                          (judge_biz,))
                cases = c.fetchall()
    except Exception as e:
        send_message(chat_id, "❌ " + str(e))
        return
    if not cases:
        text = "⚖️ ПАНЕЛЬ СУДЬИ (" + str(biz["name"]) + ")\n\n📭 Нет активных исков."
        if message_id:
            edit_message(chat_id, message_id, text, back_keyboard())
        else:
            send_message(chat_id, text, back_keyboard())
        return
    text = "⚖️ ПАНЕЛЬ СУДЬИ (" + str(biz["name"]) + ")\n\n📋 Активные иски: " + str(len(cases)) + "\n👇 Выбери иск:"
    rows = []
    for cs in cases:
        name1 = get_display_name(cs["plaintiff"])
        name2 = get_display_name(cs["defendant"])
        rows.append([{"text": "#" + str(cs["id"]) + ": " + name1 + " → " + name2,
                      "callback_data": "court_judge_view_" + str(cs["id"])}])
    rows.append([{"text": "⬅️ НАЗАД", "callback_data": "back"}])
    kb = {"inline_keyboard": rows}
    if message_id:
        edit_message(chat_id, message_id, text, kb)
    else:
        send_message(chat_id, text, kb)


def handle_court_judge_view(chat_id, message_id, user_id, case_id):
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT * FROM court_cases WHERE id = ?", (case_id,))
                cs = c.fetchone()
    except Exception:
        cs = None
    if not cs or cs["status"] != "pending":
        send_message(chat_id, "❌ Не найден или обработан!")
        return
    judge_biz = cs["judge_biz"] if "judge_biz" in cs.keys() else ""
    if not judge_biz:
        send_message(chat_id, "❌ У иска не указан судья!")
        return
    biz = biz_get(judge_biz)
    if not biz or biz["owner_id"] != user_id:
        send_message(chat_id, "❌ Ты не судья этого иска!")
        return
    name1 = get_display_name(cs["plaintiff"])
    name2 = get_display_name(cs["defendant"])
    text = ("⚖️ ИСК #" + str(case_id) + "\n\n"
            "👤 Истец: " + name1 + "\n"
            "🎯 Ответчик: " + name2 + "\n"
            "💰 Сумма: " + format(cs["amount"]) + "\n"
            "📝 Причина: " + str(cs["reason"] or "не указана"))
    kb = {"inline_keyboard": [
        [{"text": "✅ ОТПРАВИТЬ АДМИНУ", "callback_data": "court_send_admin_" + str(case_id)}],
        [{"text": "❌ ОТКЛОНИТЬ ИСК", "callback_data": "court_judge_reject_" + str(case_id)}],
        [{"text": "⬅️ НАЗАД", "callback_data": "court_menu_" + judge_biz}]]}
    if message_id:
        edit_message(chat_id, message_id, text, kb)
    else:
        send_message(chat_id, text, kb)


