def process_court_file_amount(chat_id, user_id, text):
    state = user_state_get(user_id)
    if not state or state.get("action") != "court_file_amount":
        return
    if text.strip().lower() in ("/cancel", "отмена"):
        user_state_pop(user_id)
        send_message(chat_id, "❌ Отменено.")
        return
    try:
        amount = int(text.strip())
    except ValueError:
        send_message(chat_id, "❌ Число!")
        return
    if amount < 100_000:
        send_message(chat_id, "❌ Минимум 100,000!")
        return
    target_id = state.get("target_id")
    judge_biz = state.get("judge_biz", "")
    user_state_pop(user_id)
    ok, result = court_create_case(chat_id, user_id, target_id, amount, "ограбил", judge_biz)
    if ok:
        start_advokat_deal_for_thief(target_id, user_id, amount)
        send_message(chat_id, "✅ Иск #" + str(result) + " подан!\nТеперь у вора есть " + str(ADVOKAT_HIRE_WINDOW_SEC // 60) + " мин, чтобы нанять адвоката.")
        if judge_biz:
            jb = biz_get(judge_biz)
            if jb and jb["owner_id"]:
                try:
                    send_message(jb["owner_id"], "⚖️ НОВЫЙ ИСК #" + str(result) + "\n\nИстец: " + get_display_name(user_id) + "\nОтветчик: " + get_display_name(target_id) + "\nСумма: " + format(amount))
                except Exception:
                    pass
        else:
            court_send_to_admin(result)
    else:
        send_message(chat_id, result)


def handle_court_my(chat_id, message_id, user_id):
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT id, defendant, amount, status FROM court_cases WHERE plaintiff = ? ORDER BY id DESC LIMIT 10",
                          (user_id,))
                cases = c.fetchall()
        if not cases:
            text = "📋 МОИ ИСКИ\n\nУ тебя нет исков."
        else:
            text = "📋 МОИ ИСКИ\n\n"
            for r in cases:
                status_map = {"pending": "⏳", "approved": "✅", "rejected": "❌"}
                st = status_map.get(r["status"], r["status"])
                text += "#" + str(r["id"]) + " → " + get_display_name(r["defendant"]) + "\n"
                text += "💰 " + format(r["amount"]) + " | " + st + "\n\n"
        if message_id:
            edit_message(chat_id, message_id, text, court_keyboard())
        else:
            send_message(chat_id, text, court_keyboard())
    except Exception as e:
        send_message(chat_id, "❌ " + str(e))


def court_judge_reject(chat_id, user_id, case_id):
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT judge_biz, status FROM court_cases WHERE id = ?", (case_id,))
                row = c.fetchone()
                if not row or row["status"] != "pending":
                    send_message(chat_id, "❌ Не найден!")
                    return
                judge_biz = row["judge_biz"] if "judge_biz" in row.keys() else ""
                if judge_biz:
                    biz = biz_get(judge_biz)
                    if not biz or biz["owner_id"] != user_id:
                        send_message(chat_id, "❌ Ты не судья этого иска!")
                        return
                c.execute("UPDATE court_cases SET status = 'rejected', resolved_at = ? WHERE id = ?",
                          (db_now(), case_id))
                conn.commit()
        send_message(chat_id, "❌ Иск #" + str(case_id) + " отклонён.")
        handle_court_judge_panel(chat_id, None, user_id, judge_biz)
    except Exception as e:
        send_message(chat_id, "❌ " + str(e))


_court_judge_send = {}
_court_judge_send_lock = threading.RLock()


def court_send_to_admin(case_id, judge_id=None):
    limit_key = judge_id if judge_id else 0
    with _court_judge_send_lock:
        now = time.time()
        times = _court_judge_send.get(limit_key, [])
        times = [t for t in times if now - t < 900]
        if len(times) >= COURT_LIMIT_PER_15MIN:
            left = int(900 - (now - times[0]))
            return False, "⏰ Лимит: 3 за 15 мин. Жди " + str(left) + "с."
        times.append(now)
        _court_judge_send[limit_key] = times
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT * FROM court_cases WHERE id = ?", (case_id,))
                case = c.fetchone()
                if not case or case["status"] != "pending":
                    return False, "❌ Не найден!"
        plaintiff_name = get_display_name(case["plaintiff"])
        defendant_name = get_display_name(case["defendant"])
        amount = case["amount"]
        reason = case["reason"] or "не указана"
        text = ("⚖️ ЗАЯВКА В СУД #" + str(case_id) + "\n\n" +
                "👤 Истец: " + plaintiff_name + "\n" +
                "🎯 Ответчик: " + defendant_name + "\n" +
                "💰 Сумма: " + format(amount) + "\n" +
                "📝 Причина: " + reason + "\n\n" +
                "Выбери действие:")
        kb = {"inline_keyboard": [
            [{"text": "✅ ОДОБРИТЬ", "callback_data": "court_approve_" + str(case_id)}],
            [{"text": "❌ ОТКЛОНИТЬ", "callback_data": "court_reject_" + str(case_id)}],
        ]}
        send_message(ADMIN_ID, text, kb)
        return True, "✅ Отправлено админу!"
    except Exception as e:
        print("⚠️ court_send_to_admin: " + str(e))
        return False, "❌ " + str(e)


