def handle_fake_menu(chat_id, message_id, user_id):
    last_try, banned_until = fake_get_status(user_id)
    text = "🖨 ФАЛЬШИВКИ\n\n"
    text += "💸 Стоимость: " + format(FAKE_COST) + "\n"
    text += "🎯 Шанс: " + str(FAKE_CHANCE) + "%\n"
    text += "💰 Награда: " + format(FAKE_MIN) + " - " + format(FAKE_MAX) + "\n"
    text += "🚔 При провале: блок на " + str(FAKE_BAN_MIN) + " минут\n\n"
    if banned_until and banned_until > datetime.now():
        left = int((banned_until - datetime.now()).total_seconds())
        m = left // 60
        s = left % 60
        text += "🚔 ТЫ В РОЗЫСКЕ: " + str(m) + "м " + str(s) + "с"
    elif last_try:
        diff = (datetime.now() - last_try).total_seconds()
        if diff < FAKE_COOLDOWN:
            left = FAKE_COOLDOWN - int(diff)
            m = left // 60
            s = left % 60
            text += "⏰ Через: " + str(m) + "м " + str(s) + "с"
        else:
            text += "✅ Можно!"
    else:
        text += "✅ Можно!"
    if message_id:
        edit_message(chat_id, message_id, text, fake_keyboard())
    else:
        send_message(chat_id, text, fake_keyboard())


