def handle_shield_cmd(chat_id, user_id, cmd, args):
    if not is_admin(user_id):
        send_message(chat_id, "❌ Нет прав!")
        return
    if cmd == "/shield_list":
        rows = shield_list_all()
        if not rows:
            send_message(chat_id, "📭 Список пуст.")
            return
        txt = "🛡 ЗАЩИЩЁННЫЕ (" + str(len(rows)) + ")\n\n"
        for uid, uname in rows:
            txt += "🆔 <code>" + str(uid) + "</code> | " + str(uname or "?") + "\n"
        send_message(chat_id, txt)
        return
    if cmd == "/shield_add":
        if len(args) < 1:
            send_message(chat_id, "❌ /shield_add ID|@username [причина]")
            return
        tid = shield_resolve_id(args[0])
        if not tid:
            send_message(chat_id, "❌ Игрок не найден!")
            return
        if get_user(tid) is None:
            send_message(chat_id, "❌ Игрок не писал /start")
            return
        reason = " ".join(args[1:]) if len(args) > 1 else ""
        uname = get_display_name(tid)
        if shield_add(tid, uname, user_id, reason):
            send_message(chat_id, "🛡 " + str(uname) + " (" + str(tid) + ") защищён")
        else:
            send_message(chat_id, "ℹ️ Уже в списке")
        return
    if cmd == "/shield_remove":
        if len(args) != 1:
            send_message(chat_id, "❌ /shield_remove ID|@username")
            return
        tid = shield_resolve_id(args[0])
        if not tid:
            send_message(chat_id, "❌ Игрок не найден!")
            return
        if shield_remove(tid):
            send_message(chat_id, "✅ " + str(tid) + " убран из защиты")
        else:
            send_message(chat_id, "ℹ️ Его там не было")
        return


