def process_dice_bet(chat_id, message_id, user_id, chosen):
    state = user_state_get(user_id)
    if not state or state.get("action") != "dice_bet":
        send_message(chat_id, "❌ Сначала ставку!", dice_keyboard())
        return
    if chosen not in range(1, 7):
        send_message(chat_id, "❌ 1-6!")
        return
    bet = state.get("bet_amount", 0)
    user_state_pop(user_id)
    if bet <= 0:
        send_message(chat_id, "❌ Ошибка!", dice_keyboard())
        return
    ok, _, reason = sub_balance(user_id, bet)
    if not ok:
        send_message(chat_id, "❌ " + reason)
        return
    dice_result = random.randint(1, 6)
    win = (chosen == dice_result)
    if win:
        prize = bet * 7
        add_balance(user_id, prize)
        add_transaction(user_id, prize, "dice_win", "dice", "x7 на " + str(chosen))
        win_text = "🎉 ПОБЕДА! +" + format(prize)
    else:
        add_transaction(user_id, -bet, "dice_lose", "dice", "не угадал " + str(chosen))
        win_text = "💀 Проигрыш -" + format(bet)
    result_msg = "🎲 Результат: " + str(dice_result) + "\n👤 Твоё: " + str(chosen) + "\n💰 Ставка: " + format(bet) + "\n" + win_text + "\n\n💎 Поинты: " + format(get_balance(user_id))
    send_message(chat_id, result_msg, dice_keyboard())


