def handle_biz_view(chat_id, message_id, user_id, biz_type):
    biz = biz_get(biz_type)
    if not biz:
        send_message(chat_id, "❌ Не найден!")
        return
    owner_name = biz_get_owner_name(biz["owner_id"])
    seller_id = biz["seller_id"] if "seller_id" in biz.keys() else 0
    text = str(biz["name"]) + "\n\n"
    if seller_id:
        text += "🔄 Продаёт: " + biz_get_owner_name(seller_id) + "\n"
    text += "👑 Владелец: " + str(owner_name) + "\n"
    text += "💰 Поинты бизнеса: " + format(big_load(biz["balance"])) + "\n"
    lvl = biz["upgrade_level"] if "upgrade_level" in biz.keys() else 0
    if biz_type in BIZ_UPGRADE_ALLOWED:
        if lvl and lvl >= 1:
            text += "🏗 Апгрейд: ✅ (x" + str(BIZ_UPGRADE_MULT) + ")\n"
    if biz["status"] == "auction":
        status_text = "🔨 Аукцион"
    elif biz["status"] == "owned":
        status_text = "✅ Владелец"
    elif biz["status"] == "lombard":
        status_text = "🏪 ЛОМБАРД"
    elif biz["status"] == "rozygrysh":
        status_text = "🎁 РОЗЫГРЫШ"
    else:
        status_text = biz["status"]
    text += "📊 Статус: " + status_text + "\n\n"
    if biz["status"] == "auction":
        ends_at = db_parse(biz["auction_end"])
        now = datetime.now()
        if ends_at:
            left = int((ends_at - now).total_seconds())
            if left < 0:
                left = 0
            h = left // 3600
            m = (left % 3600) // 60
            s = left % 60
            time_left = f"{h}ч {m}м {s}с" if h > 0 else f"{m}м {s}с"
        else:
            time_left = "?"
        text += "⏰ До конца: " + time_left + "\n"
        text += "💰 Мин.: " + format(big_load(biz["min_bet"])) + "\n"
        text += "📈 Макс.: " + format(BIZ_MAX_BET) + "\n"
        if biz["current_bidder"]:
            text += "🏆 Лидер: " + biz_get_owner_name(biz["current_bidder"]) + "\n"
            text += "💵 " + format(big_load(biz["current_bet"]))
        else:
            text += "❌ Ставок нет"
    elif biz["status"] == "owned":
        last_pay = db_parse(biz["last_payment"]) if biz["last_payment"] else None
        if last_pay:
            next_pay = last_pay
            left = int((next_pay - datetime.now()).total_seconds())
            if left < 0:
                left = 0
            days = left // 86400
            h = (left % 86400) // 3600
            m = (left % 3600) // 60
            text += "💳 Оплата через: "
            if days > 0:
                text += str(days) + "д "
            text += str(h) + "ч " + str(m) + "мин\n"
    base = biz_get_type_name(biz_type)
    if base == "apteka":
        base_price = BIZ_APTEKA_PRICE
        base_reward = BIZ_APTEKA_REWARD
        if lvl and lvl >= 1:
            base_reward = int(base_reward * BIZ_UPGRADE_MULT)
        text += "\n💊 Аптечка: " + format(base_price) + "\n📌 5 раз в день (общий лимит)\n⚠️ Штраф −10%\n💰 Доход: " + format(base_reward)
    elif base == "bolnitsa":
        base_price = BIZ_HOSPITAL_PRICE
        base_reward = BIZ_HOSPITAL_REWARD
        if lvl and lvl >= 1:
            base_reward = int(base_reward * BIZ_UPGRADE_MULT)
        text += "\n🩺 Обследование: " + format(base_price) + "\n📌 1 раз в день (общий лимит)\n⚠️ Штраф −10%\n💰 Доход: " + format(base_reward)
    elif base == "banda":
        base_reward = BIZ_BANDA_REWARD
        if lvl and lvl >= 1:
            base_reward = int(base_reward * BIZ_UPGRADE_MULT)
        text += "\n🔫 Грабеж: " + format(BIZ_BANDA_TRY) + "\n🎯 Шанс: " + str(BIZ_BANDA_CHANCE) + "%\n💰 Доход: " + format(base_reward)
    elif biz_type == "league":
        text += "\n⚽ Ставки: 1М-1ККК\n💎 x" + str(LEAGUE_MULT) + "\n🎯 Шанс: " + str(LEAGUE_WIN_CHANCE) + "%"
    elif base == "sud":
        text += "\n⚖️ Иск: бесплатно\n💰 Моральный: +" + str(COURT_MORAL_PERCENT) + "%"
    elif biz_type == "advokat":
        advokats = advokat_get_owner_advokats(biz["owner_id"]) if biz["owner_id"] else []
        biz_cut = ADVOKAT_BIZ_CUT
        if lvl and lvl >= 1:
            biz_cut = int(biz_cut * BIZ_UPGRADE_MULT)
        text += ("\n⚖️ АДВОКАТСКАЯ КОНТОРА\n"
                 "👥 Адвокатов: " + str(len(advokats)) + "/" + str(ADVOKAT_MAX) + "\n"
                 "💸 Найм адвоката: " + format(ADVOKAT_HIRE_COST) + "\n"
                 "💸 Найм владельца: " + format(ADVOKAT_OWNER_COST) + "\n"
                 "⏰ Окно найма: " + str(ADVOKAT_HIRE_WINDOW_SEC // 60) + " мин\n"
                 "💰 В бизнес: " + format(biz_cut))
    elif biz_type == "mafia":
        s = mafia_get_settings()
        text += "\n📊 Ставка: " + str(s["current"]) + "%\n🎯 Лимит: " + str(s["max"]) + "%\n💰 Не платит проплату"
    elif biz_type == "lombard":
        text += ("\n🏪 ЛОМБАРД\n"
                 "💰 Сдать бизнес → займ " + format(LOMBARD_MIN) + " - " + format(LOMBARD_MAX) + "\n"
                 "💸 Вернуть ×1.5 через 1 час\n"
                 "⚠️ Не вернёшь — бизнес на аукцион\n"
                 "⏰ Кулдаун 24ч")
    if message_id:
        edit_message(chat_id, message_id, text, biz_view_keyboard(biz_type, user_id))
    else:
        send_message(chat_id, text, biz_view_keyboard(biz_type, user_id))


