def handle_biz_bid_input(chat_id, message_id, user_id, biz_type):
    biz = biz_get(biz_type)
    if not biz:
        send_message(chat_id, "❌ Не найден!")
        return
    if biz["status"] != "auction":
        send_message(chat_id, "❌ Не на аукционе!")
        return
    seller_id = biz["seller_id"] if "seller_id" in biz.keys() else 0
    if biz["owner_id"] == user_id or seller_id == user_id:
        send_message(chat_id, "❌ Нельзя на свой лот!", back_keyboard())
        return
    user_state_set(user_id, {"action": "biz_bid", "biz_type": biz_type})
    cur_bet = big_load(biz["current_bet"])
    min_bet_int = big_load(biz["min_bet"])
    min_bet = (cur_bet + 1) if biz["current_bidder"] else min_bet_int
    text = ("💰 СТАВКА НА " + str(biz["name"]) + "\n\n"
            "💵 Текущая: " + format(cur_bet) + "\n"
            "💰 Минимум: " + format(min_bet) + "\n"
            "📈 Максимум: " + format(BIZ_MAX_BET) + "\n\n"
            "Введи сумму:\n/cancel")
    if message_id:
        edit_message(chat_id, message_id, text, back_keyboard())
    else:
        send_message(chat_id, text, back_keyboard())


def process_biz_bid(chat_id, user_id, text):
    state = user_state_get(user_id)
    if not state or state.get("action") != "biz_bid":
        return
    biz_type = state.get("biz_type")
    try:
        amount = int(text.strip())
    except ValueError:
        send_message(chat_id, "❌ Число!")
        return
    user_state_pop(user_id)
    biz = biz_get(biz_type)
    if not biz:
        send_message(chat_id, "❌ Не найден!")
        return
    if biz["status"] != "auction":
        send_message(chat_id, "❌ Закрыт!")
        return
    seller_id = biz["seller_id"] if "seller_id" in biz.keys() else 0
    if biz["owner_id"] == user_id or seller_id == user_id:
        send_message(chat_id, "❌ Нельзя на свой лот!")
        return
    cur_bet = big_load(biz["current_bet"])
    min_bet_int = big_load(biz["min_bet"])
    min_bet = (cur_bet + 1) if biz["current_bidder"] else min_bet_int
    if amount < min_bet:
        send_message(chat_id, "❌ Минимум: " + format(min_bet))
        return
    if amount > BIZ_MAX_BET:
        send_message(chat_id, "❌ Максимум: " + format(BIZ_MAX_BET))
        return
    if biz["current_bidder"] == user_id:
        send_message(chat_id, "❌ Ты уже лидируешь!")
        return
    prev_bidder = biz["current_bidder"]
    prev_bet = big_load(biz["current_bet"])
    # Списание
    ok, _, reason = sub_balance(user_id, amount)
    if not ok:
        send_message(chat_id, "❌ " + reason)
        return
    # Возврат предыдущему
    if prev_bidder and prev_bidder != user_id and prev_bet > 0:
        add_balance(prev_bidder, prev_bet)
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("UPDATE biz_businesses SET current_bet = ?, current_bidder = ? WHERE biz_type = ?",
                          (big_normalize(amount), user_id, biz_type))
                conn.commit()
        add_transaction(user_id, -amount, "biz_bid", "business", "Ставка на " + str(biz["name"]))
        if prev_bidder and prev_bidder != user_id:
            try:
                send_message(prev_bidder, "⚠️ Ставку на " + str(biz["name"]) + " перебили!\nВозврат: " + format(prev_bet))
            except Exception:
                pass
        send_message(chat_id, "✅ Ставка!\n\n" + str(biz["name"]) + "\n💰 " + format(amount))
        if amount >= BIZ_MAX_BET:
            with DB_LOCK:
                with _conn() as conn:
                    c = conn.cursor()
                    c.execute("UPDATE biz_businesses SET auction_end = ? WHERE biz_type = ?",
                              (db_now(), biz_type))
                    conn.commit()
    except Exception as e:
        add_balance(user_id, amount)
        send_message(chat_id, "❌ " + str(e))


