# ✅ BIG-INT ФИКС
def handle_biz_buy_apteka(chat_id, message_id, user_id, biz_type):
    biz = biz_get(biz_type)
    if not biz or biz["status"] != "owned":
        send_message(chat_id, "❌ Аптека не выкуплена!")
        return
    today_str = datetime.now().strftime("%Y-%m-%d")
    up_mult = biz_get_upgrade_mult(biz_type)
    reward = int(BIZ_APTEKA_REWARD * up_mult)
    # Проверяем лимит
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT count FROM biz_player_apteka WHERE user_id = ? AND date = ?",
                          (user_id, today_str))
                r = c.fetchone()
                if r and r["count"] >= BIZ_APTEKA_NEED:
                    send_message(chat_id, "❌ Уже " + str(BIZ_APTEKA_NEED) + " раз сегодня! (общий лимит)")
                    return
    except Exception:
        pass
    # Списание
    ok, _, reason = sub_balance(user_id, BIZ_APTEKA_PRICE)
    if not ok:
        send_message(chat_id, "❌ " + reason)
        return
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                # ✅ BIG-INT ФИКС: SELECT → big_load → +reward → big_normalize → UPDATE
                c.execute("SELECT balance FROM biz_businesses WHERE biz_type = ?", (biz_type,))
                _brow = c.fetchone()
                _cur_b = big_load(_brow["balance"]) if _brow else 0
                _new_b = _cur_b + reward
                if _new_b > MAX_BALANCE:
                    _new_b = MAX_BALANCE
                c.execute("UPDATE biz_businesses SET balance = ? WHERE biz_type = ?",
                          (big_normalize(_new_b), biz_type))
                c.execute("SELECT count FROM biz_player_apteka WHERE user_id = ? AND date = ?",
                          (user_id, today_str))
                r = c.fetchone()
                if r:
                    c.execute("UPDATE biz_player_apteka SET count = count + 1 WHERE user_id = ? AND date = ?",
                              (user_id, today_str))
                    new_count = r["count"] + 1
                else:
                    c.execute("INSERT INTO biz_player_apteka (user_id, date, count) VALUES (?, ?, 1)",
                              (user_id, today_str))
                    new_count = 1
                conn.commit()
        add_transaction(user_id, -BIZ_APTEKA_PRICE, "biz_buy_apteka", "business", "Аптечка " + biz_type)
        biz_stats_add(biz_type, reward)
        text = "💊 АПТЕЧКА (" + str(biz["name"]) + ")!\n\n−" + format(BIZ_APTEKA_PRICE) + "\n📊 Сегодня: " + str(new_count) + "/" + str(BIZ_APTEKA_NEED)
        if up_mult > 1.0:
            text += "\n🏗 Апгрейд: доход x" + str(up_mult)
        if new_count >= BIZ_APTEKA_NEED:
            text += "\n✅ Норма!"
        else:
            text += "\n⚠️ Ещё: " + str(BIZ_APTEKA_NEED - new_count)
        send_message(chat_id, text)
        handle_biz_view(chat_id, message_id, user_id, biz_type)
    except Exception as e:
        add_balance(user_id, BIZ_APTEKA_PRICE)
        send_message(chat_id, "❌ " + str(e))


