# ✅ BIG-INT ФИКС (2 места)
def process_biz_banda_target(chat_id, user_id, text):
    state = user_state_get(user_id)
    if not state or state.get("action") != "biz_banda_target":
        return
    t = text.strip()
    target_id = None
    if t.startswith('@'):
        target_id = get_user_id_by_username(t[1:])
        if not target_id:
            send_message(chat_id, "❌ Не найден!")
            return
    else:
        try:
            target_id = int(t)
        except ValueError:
            send_message(chat_id, "❌ @username или ID!")
            return
    user_state_pop(user_id)
    if target_id == user_id:
        send_message(chat_id, "❌ Себя нельзя!")
        return
    if is_shielded(target_id):
        send_message(chat_id, "🛡 Этот игрок под защитой.\nГрабёж невозможен.")
        return
    up_mult = biz_get_upgrade_mult("banda")
    reward = int(BIZ_BANDA_REWARD * up_mult)
    # Списание стоимости попытки
    ok, _, reason = sub_balance(user_id, BIZ_BANDA_TRY)
    if not ok:
        send_message(chat_id, "❌ " + reason)
        return
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                # ✅ BIG-INT ФИКС (1): SELECT → big_load → +reward → big_normalize
                c.execute("SELECT balance FROM biz_businesses WHERE biz_type = 'banda'")
                _brow = c.fetchone()
                _cur_b = big_load(_brow["balance"]) if _brow else 0
                _new_b = _cur_b + reward
                if _new_b > MAX_BALANCE:
                    _new_b = MAX_BALANCE
                c.execute("UPDATE biz_businesses SET balance = ? WHERE biz_type = 'banda'",
                          (big_normalize(_new_b),))
                conn.commit()
    except Exception:
        pass
    success = random.randint(1, 100) <= BIZ_BANDA_CHANCE
    stolen = 0
    if success:
        target_balance = get_balance(target_id)
        stolen = int(target_balance * 50 / 100)
        if stolen > 0:
            ok2, _, _ = sub_balance(target_id, stolen)
            if ok2:
                try:
                    with DB_LOCK:
                        with _conn() as conn:
                            c = conn.cursor()
                            # ✅ BIG-INT ФИКС (2): SELECT → big_load → +stolen → big_normalize
                            c.execute("SELECT balance FROM biz_businesses WHERE biz_type = 'banda'")
                            _brow = c.fetchone()
                            _cur_b = big_load(_brow["balance"]) if _brow else 0
                            _new_b = _cur_b + stolen
                            if _new_b > MAX_BALANCE:
                                _new_b = MAX_BALANCE
                            c.execute("UPDATE biz_businesses SET balance = ? WHERE biz_type = 'banda'",
                                      (big_normalize(_new_b),))
                            conn.commit()
                except Exception:
                    pass
            else:
                stolen = 0
    add_transaction(user_id, -BIZ_BANDA_TRY, "biz_banda_try", "business", "Попытка")
    if success and stolen > 0:
        add_transaction(user_id, stolen, "biz_banda_win", "business", "Успех")
        biz_stats_add("banda", reward + stolen)
        court_freeze_money(user_id, stolen, target_id)
        shield_until = (datetime.now() + timedelta(minutes=ROB_SHIELD_MIN)).strftime(DB_DATE_FMT)
        try:
            with DB_LOCK:
                with _conn() as conn:
                    conn.execute("UPDATE users SET rob_shield_until = ? WHERE user_id = ?",
                                 (shield_until, target_id))
                    conn.commit()
        except Exception:
            pass
        text_out = ("🎉 ГРАБЁЖ УДАЧЕН!\n\n"
                    "💰 Украдено: " + format(stolen) + "\n"
                    "🧊 Заморожено на " + str(ADVOKAT_FREEZE_MIN) + " мин\n"
                    "🛡 У жертвы щит " + str(ROB_SHIELD_MIN) + " минут\n"
                    "⚖️ Жертва может подать в суд")
        try:
            send_message(target_id, "🚨 ТЕБЯ ОГРАБИЛИ!\n\n💰 " + format(stolen) + "\n🛡 Щит " + str(ROB_SHIELD_MIN) + " мин\n⚖️ Суд " + str(ADVOKAT_FREEZE_MIN) + " мин")
        except Exception:
            pass
        if stolen > 100_000_000:
            try:
                send_message(ADMIN_ID, "🚨 КРУПНЫЙ ГРАБЁЖ\n\n" +
                             "🔫 " + get_display_name(user_id) + "\n" +
                             "🎯 " + get_display_name(target_id) + "\n" +
                             "💰 " + format(stolen))
            except Exception:
                pass
    elif success:
        biz_stats_add("banda", reward)
        text_out = "🎉 Успех! Но у жертвы нечего взять."
    else:
        biz_stats_add("banda", reward)
        text_out = "❌ ГРАБЁЖ ПРОВАЛЕН!\n\n💀 −" + format(BIZ_BANDA_TRY)
    send_message(chat_id, text_out)


def handle_rozygrysh_command(chat_id, user_id):
    active = rozygrysh_get_active()
    if active:
        rz = active
        rid = rz["id"]
        ends_at = db_parse(rz["ends_at"])
        left_str = "?"
        if ends_at:
            left = int((ends_at - datetime.now()).total_seconds())
            if left > 0:
                h = left // 3600
                m = (left % 3600) // 60
                left_str = (str(h) + "ч " if h > 0 else "") + str(m) + "м"
        biz = biz_get(rz["biz_type"])
        bname = biz["name"] if biz else rz["biz_type"]
        tickets = rozygrysh_get_tickets_count(rid)
        already = False
        try:
            with DB_LOCK:
                with _conn() as conn:
                    c = conn.cursor()
                    c.execute("SELECT id FROM rozygrysh_tickets WHERE rozygrysh_id = ? AND user_id = ?",
                              (rid, user_id))
                    already = c.fetchone() is not None
        except Exception:
            pass
        price_int = big_load(rz["ticket_price"])
        text_rz = ("🎁 РОЗЫГРЫШ!\n\n"
                   "📦 Бизнес: " + str(bname) + "\n"
                   "💰 Цена билета: " + format(price_int) + "\n"
                   "⏰ До конца: " + left_str + "\n"
                   "👥 Участников: " + str(tickets) + "\n\n")
        if already:
            text_rz += "✅ Ты уже участник!"
            kb_rz = None
        else:
            text_rz += "🎟 Жми кнопку чтобы купить билет!"
            kb_rz = rozygrysh_ticket_keyboard(rid)
        if is_admin(user_id):
            kb_admin = {"inline_keyboard": [[{"text": "⚙️ Управление розыгрышем", "callback_data": "admin_rozygrysh_menu"}]]}
            if kb_rz:
                kb_admin["inline_keyboard"].extend(kb_rz["inline_keyboard"])
            kb_rz = kb_admin
        send_message(chat_id, text_rz, kb_rz)
    elif is_admin(user_id):
        handle_admin_rozygrysh_menu(chat_id, None, user_id)
    else:
        send_message(chat_id, "❌ Сейчас нет активного розыгрыша")


