    if t == "Магазин" or t == "магазин" or t == "Fcshop" or t == "fcshop" or t == "Шоп":
        handle_fcshop(chat_id, None, user_id)
        return True
    if t == "Номер" or t == "номер" or t == "Номера" or t == "номера" or t == "Телефон":
        handle_phone_menu(chat_id, None, user_id)
        return True
    if t in ("Биржа", "биржа", "Крипта", "крипта", "Crypto", "crypto"):
        crypto_menu(chat_id, None, user_id)
        return True
    if t in ("Пасс", "пасс", "Pass", "pass", "Фрипасс", "фрипасс", "Фрип", "фрип"):
        fp_menu(chat_id, None, user_id)
        return True
    if t in ("Хелперы", "хелперы", "Хелпер", "хелпер", "Помощь", "помощь"):
        handle_helpers_online(chat_id, None, user_id)
        return True
    if t in ("Ивент", "ивент", "Ивенты", "ивенты", "Событие", "событие"):
        handle_event_info(chat_id, None, user_id)
        return True
    if t.startswith("Сбор ") or t.startswith("сбор "):
        parts = t.split()
        if len(parts) >= 2:
            try:
                amount = int(parts[1])
                handle_sbor_bet(chat_id, user_id, amount)
                return True
            except ValueError:
                pass
    return False


