# ========== ЧАСТЬ 22/25: HANDLE_START + ПЛАНИРОВЩИКИ + FULLRESET + RESETPLAYER + АДМИН-СТАФФ ==========

def handle_start(chat_id, user_id, username):
    user = get_user(user_id)
    if user is None:
        create_user(user_id, username, None)
    if is_left(user_id):
        send_message(chat_id,
                     "🍂 ТЫ УШЁЛ\n\n"
                     "Ты покинул игру. Вернуться может только админ.\n"
                     "📩 Напиши: @" + ADMIN_USERNAME + "\n\n"
                     "🆔 Твой ID: " + str(user_id))
        return
    try:
        with DB_LOCK:
            with _conn() as conn:
                if username:
                    conn.execute("UPDATE users SET username = ? WHERE user_id = ?", (username, user_id))
                conn.commit()
    except Exception as e:
        print("⚠️ handle_start: " + str(e))
    update_last_active(user_id)
    check_and_award_titles(user_id)
    balance = get_balance(user_id)
    frik = get_frik(user_id)
    treasury = get_treasury(CHAT_ID)
    progress, _ = get_special_progress(user_id)
    titles = get_user_titles(user_id)
    fam = get_user_family(user_id)
    fam_text = "\n👨‍👩‍👧 Семья: нет"
    if fam:
        fam_text = "\n👨‍👩‍👧 Семья: " + str(fam["name"]) + " (" + str(fam["reputation"] or 0) + " ⭐)"
        h = get_family_house(fam)
        if h:
            fam_text += " [" + h["name"] + "]"
    my_house = house_get_by_owner(user_id)
    house_text = ""
    if my_house:
        house_text = "\n🏠 Дом: " + str(my_house["name"])
    titles_text = ""
    if titles:
        titles_text = "\n🏆 Титулы: " + " | ".join([t["name"] for t in titles[:3]])
        if len(titles) > 3:
            titles_text += " +" + str(len(titles) - 3)
    my_biz = biz_get_by_owner(user_id)
    biz_text = ""
    if my_biz:
        biz_text = "\n🏢 Бизнесы: " + ", ".join([str(b["name"]) for b in my_biz])
    hb_text = ""
    try:
        hb, ht = get_user_house_bonus(user_id)
        if hb > 0:
            hb_text = "\n🎁 Бонус дома: +" + str(hb) + "% к рулетке"
    except Exception:
        pass
    lombard_text = ""
    try:
        active = lombard_get_active_loan(user_id)
        if active:
            lombard_text = "\n🏪 Займ: " + format(active["amount"]) + " → вернуть " + format(active["return_amount"])
    except Exception:
        pass
