    text += "💰 Поинты: " + format(balance) + "\n"
    text += "💎 FrikCoins: " + str(frik)
    text += role_text + fam_text + house_text + phone_text + titles_text + biz_text + boost_text + hb_text + lombard_text + craft_text + crypto_text + fp_text + "\n\n"
    text += "🏛 Казна: " + format(treasury) + "\n"
