# ========== ⏰ ПЛАНИРОВЩИКИ ==========
def scheduler_hourly_reputation():
    last_hour_key = None
    while not scheduler_stop.is_set():
        try:
            now_msk = moscow_now()
            hour_key = now_msk.strftime("%Y-%m-%d %H")
            if now_msk.minute == 0 and hour_key != last_hour_key:
                last_hour_key = hour_key
                try:
                    with DB_LOCK:
                        with _conn() as conn:
                            c = conn.cursor()
                            c.execute("SELECT id, name, owner_id, house_type FROM families")
                            fams = c.fetchall()
                            for fam in fams:
                                amount = random.randint(FAMILY_HOURLY_MIN, FAMILY_HOURLY_MAX)
                                ht = fam["house_type"] if "house_type" in fam.keys() else ""
                                mult = 1.0
                                if ht in FAMILY_HOUSES:
                                    mult = FAMILY_HOUSES[ht]["star_mult"]
                                if mult != 1.0:
                                    amount = int(amount * mult)
                                c.execute("UPDATE families SET reputation = reputation + ?, last_hourly = ? WHERE id = ?",
                                          (amount, db_now(), fam["id"]))
                            conn.commit()
                    print("⏰ [" + db_now() + "] Репутация: " + str(len(fams)))
                except Exception as e:
                    print("⚠️ hourly rep: " + str(e))
        except Exception as e:
            print("⚠️ scheduler_hourly_reputation: " + str(e))
        time.sleep(20)


def scheduler_weekly_season():
    last_week_key = None
    while not scheduler_stop.is_set():
        try:
            now_msk = moscow_now()
            if (now_msk.weekday() == FAMILY_SEASON_WEEKDAY and
                now_msk.hour == 0 and now_msk.minute == 0):
                week_key = now_msk.strftime("%Y-W%W")
                if week_key != last_week_key:
                    last_week_key = week_key
                    print("🏁 Сезон...")
                    result = family_season_end(notify_admin=True)
                    if result:
                        print("✅ Победитель: " + str(result[0]))
                    else:
                        try:
                            send_message(ADMIN_ID, "🏁 Сезон завершён, но семей нет.")
                        except Exception:
                            pass
        except Exception as e:
            print("⚠️ scheduler_weekly_season: " + str(e))
        time.sleep(30)


