def scheduler_freeze_watcher():
    while not scheduler_stop.is_set():
        try:
            with DB_LOCK:
                with _conn() as conn:
                    c = conn.cursor()
                    c.execute("SELECT user_id, frozen_until, victim_id, amount FROM frozen_money")
                    rows = c.fetchall()
                    now = datetime.now()
                    expired = []
                    for r in rows:
                        fz = db_parse(r["frozen_until"])
                        if fz and fz <= now:
                            expired.append(dict(r))
                            c.execute("DELETE FROM frozen_money WHERE user_id = ?", (r["user_id"],))
                    conn.commit()
            for r in expired:
                victim_id = r["victim_id"]
                amount = r["amount"]
                if victim_id:
                    add_balance(victim_id, amount)
                    add_transaction(victim_id, amount, "frozen_expire_refund", "frozen", "Возврат (заморозка истекла)")
                    try:
                        send_message(victim_id, "💰 Возврат украденного: " + format(amount))
                    except Exception:
                        pass
            if expired:
                print("🧊 [" + db_now() + "] Разморожено: " + str(len(expired)))
        except Exception as e:
            print("⚠️ scheduler_freeze_watcher: " + str(e))
        time.sleep(60)


