def scheduler_phone_auction():
    while not scheduler_stop.is_set():
        try:
            now = datetime.now()
            one_hour_ago = (now - timedelta(hours=1)).strftime(DB_DATE_FMT)
            with DB_LOCK:
                with _conn() as conn:
                    c = conn.cursor()
                    for num in PHONE_PRETTY:
                        c.execute("SELECT owner_id FROM phones WHERE number = ?", (num,))
                        row = c.fetchone()
                        owner = row["owner_id"] if row else 0
                        if owner and owner != 0:
                            continue
                        c.execute("""SELECT id FROM auctions
                                     WHERE status = 'active'
                                     AND lot_type = 'phone'
                                     AND lot_value = ?""", (num,))
                        if c.fetchone():
                            continue
                        c.execute("""SELECT COUNT(*) as cnt FROM auctions
                                     WHERE lot_type = 'phone'
                                     AND lot_value = ?
                                     AND created_at >= ?""",
                                  (num, one_hour_ago))
                        if c.fetchone()["cnt"] > 0:
                            continue
                        new_end = (now + timedelta(hours=PHONE_AUCTION_HOURS)).strftime(DB_DATE_FMT)
                        c.execute("""INSERT INTO auctions
                                     (title, description, lot_type, lot_value,
                                      min_bet, step, created_by, chat_id, ends_at, status)
                                     VALUES (?, ?, 'phone', ?, ?, ?, ?, ?, ?, 'active')""",
                                  ("📱 Красивый номер +" + str(num),
                                   "Красивый номер. Ставка: " + format(PHONE_AUCTION_MIN) + " – " + format(PHONE_AUCTION_MAX),
                                   str(num), PHONE_AUCTION_MIN, 10_000_000,
                                   BOSS_ADMIN_ID, CHAT_ID, new_end))
                        new_id = c.lastrowid
                        conn.commit()
                        print("📱 [" + db_now() + "] Аукцион номера +" + str(num) + " #" + str(new_id))
                        try:
                            post_auction_to_chat(CHAT_ID, new_id)
                        except Exception as e:
                            print("⚠️ post phone auction: " + str(e))
        except Exception as e:
            print("⚠️ scheduler_phone_auction: " + str(e))
        time.sleep(60)


