def scheduler_helper_timeout():
    while not scheduler_stop.is_set():
        try:
            expired = help_expire_old()
            for e in expired:
                qid = e["qid"]
                helper_id = e["helper_id"]
                try:
                    help_chat = get_help_chat_id()
                    with help_chat_messages_lock:
                        mid = help_chat_messages.get(qid)
                    if help_chat and mid:
                        q = help_get_question(qid)
                        if q:
                            new_text = ("🆘 <b>ВОПРОС #" + str(qid) + " (ВЕРНУЛСЯ В ОЧЕРЕДЬ)</b>\n\n"
                                        "👤 " + str(q["username"] or get_display_name(q["user_id"])) + "\n"
                                        "🆔 <code>" + str(q["user_id"]) + "</code>\n\n"
                                        "❓ " + esc(q["question"]) + "\n\n"
                                        "⏰ <i>Хелпер не ответил за " + str(HELP_TAKEOVER_TIMEOUT // 60) + " мин — вернулся</i>")
                            edit_message(help_chat, mid, new_text, help_question_keyboard(qid))
                except Exception as ex:
                    print("⚠️ expire chat update: " + str(ex))
                if helper_id:
                    try:
                        send_message(helper_id,
                                     "⏰ <b>ВОПРОС #" + str(qid) + " вернулся в очередь.</b>\n"
                                     "Ты не ответил за " + str(HELP_TAKEOVER_TIMEOUT // 60) + " мин.")
                    except Exception:
                        pass
                    try:
                        st = user_state_get(helper_id)
                        if st and st.get("action") == "help_answering" and st.get("qid") == qid:
                            user_state_pop(helper_id)
                    except Exception:
                        pass
            if expired:
                print("⏰ [" + db_now() + "] Help expire: " + str(len(expired)))
        except Exception as e:
            print("⚠️ scheduler_helper_timeout: " + str(e))
        time.sleep(30)


def start_schedulers():
    threads = [
        threading.Thread(target=scheduler_hourly_reputation, daemon=True),
        threading.Thread(target=scheduler_weekly_season, daemon=True),
        threading.Thread(target=scheduler_auction_watcher, daemon=True),
        threading.Thread(target=scheduler_biz, daemon=True),
        threading.Thread(target=scheduler_league, daemon=True),
        threading.Thread(target=scheduler_freeze_watcher, daemon=True),
        threading.Thread(target=rl_cancel_expired_bets_worker, daemon=True),
        threading.Thread(target=sbor_watcher_worker, daemon=True),
        threading.Thread(target=poll_watcher_worker, daemon=True),
        threading.Thread(target=scheduler_mafia, daemon=True),
        threading.Thread(target=advokat_expire_worker, daemon=True),
        threading.Thread(target=trade_expire_worker, daemon=True),
        threading.Thread(target=spam_cleanup_worker, daemon=True),
        threading.Thread(target=scheduler_advokat_cleanup, daemon=True),
        threading.Thread(target=biz_stats_cleanup_worker, daemon=True),
        threading.Thread(target=lombard_expire_worker, daemon=True),
        threading.Thread(target=rozygrysh_worker, daemon=True),
        threading.Thread(target=house_trade_expire_worker, daemon=True),
        threading.Thread(target=scheduler_boost_expire, daemon=True),
        threading.Thread(target=scheduler_phone_auction, daemon=True),
        threading.Thread(target=scheduler_crypto, daemon=True),
        threading.Thread(target=scheduler_fp_season, daemon=True),
        threading.Thread(target=scheduler_helper_timeout, daemon=True),
        threading.Thread(target=scheduler_event_tickets, daemon=True),
        threading.Thread(target=scheduler_event_watch, daemon=True),
    ]
    for t in threads:
        t.start()
    print("✅ Планировщики запущены (" + str(len(threads)) + " шт)")


