# ========== ♻️ /resetplayer — ПОЛНЫЙ СБРОС ОДНОГО ИГРОКА ==========
_resetplayer_pending = {}
_resetplayer_pending_lock = threading.RLock()


def do_resetplayer(target_id):
    if get_user(target_id) is None:
        return False, "❌ Игрок не найден (не писал /start)!"
    if int(target_id) == BOSS_ADMIN_ID:
        return False, "❌ BOSS_ADMIN_ID нельзя сбросить (хардкод-защита)"
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("""UPDATE users SET
                                balance = ?,
                                last_bonus = NULL,
                                invite_count = 0,
                                invited_by = 0,
                                jackpot_won = 0,
                                is_left = 0,
                                rob_shield_until = NULL,
                                apteka_immunity_until = NULL,
                                bolnitsa_immunity_until = NULL,
                                frikcoins = 0,
                                roulette_boost_until = NULL,
                                roulette_boost_percent = 0
                             WHERE user_id = ?""",
                          (big_normalize(15_000_000), target_id))
                c.execute("DELETE FROM titles WHERE user_id = ?", (target_id,))
                c.execute("DELETE FROM title_stats WHERE user_id = ?", (target_id,))
                c.execute("DELETE FROM case_stats WHERE user_id = ?", (target_id,))
                c.execute("DELETE FROM special_cases WHERE user_id = ?", (target_id,))
                c.execute("DELETE FROM roulette_bets WHERE user_id = ?", (target_id,))
                c.execute("DELETE FROM roulette_last_bets WHERE user_id = ?", (target_id,))
                c.execute("UPDATE houses SET owner_id = 0, bought_at = NULL WHERE owner_id = ?", (target_id,))
                c.execute("DELETE FROM phones WHERE owner_id = ?", (target_id,))
                c.execute("DELETE FROM crypto_portfolio WHERE user_id = ?", (target_id,))
                c.execute("DELETE FROM crypto_history WHERE user_id = ?", (target_id,))
                c.execute("DELETE FROM fp_progress WHERE user_id = ?", (target_id,))
                c.execute("DELETE FROM fp_history WHERE user_id = ?", (target_id,))
                c.execute("DELETE FROM staff_roles WHERE user_id = ?", (target_id,))
                c.execute("DELETE FROM help_stats WHERE helper_id = ?", (target_id,))
                # ✅ ХУК 8: очистка ивентов
                c.execute("DELETE FROM event_tickets WHERE user_id = ?", (target_id,))
                c.execute("DELETE FROM user_snowballs WHERE user_id = ?", (target_id,))
                c.execute("DELETE FROM user_statuses WHERE user_id = ?", (target_id,))
                c.execute("DELETE FROM event_game_players WHERE user_id = ?", (target_id,))
                c.execute("""UPDATE help_questions
                             SET status = 'cancelled', answered_at = ?
                             WHERE user_id = ? AND status IN ('open','taken')""",
                          (db_now(), target_id))
                fam_row = None
                c.execute("SELECT family_id FROM family_members WHERE user_id = ?", (target_id,))
                fm = c.fetchone()
                if fm:
                    fid = fm["family_id"]
                    c.execute("SELECT owner_id, name FROM families WHERE id = ?", (fid,))
                    fam_row = c.fetchone()
                    if fam_row and fam_row["owner_id"] == target_id:
                        members = []
                        c.execute("SELECT user_id FROM family_members WHERE family_id = ?", (fid,))
                        members = [r["user_id"] for r in c.fetchall()]
                        c.execute("DELETE FROM family_members WHERE family_id = ?", (fid,))
                        c.execute("DELETE FROM family_invites WHERE family_id = ?", (fid,))
                        c.execute("DELETE FROM family_duels WHERE challenger_family = ? OR opponent_family = ?", (fid, fid))
                        c.execute("DELETE FROM families WHERE id = ?", (fid,))
                    else:
                        c.execute("DELETE FROM family_members WHERE user_id = ?", (target_id,))
                else:
                    members = []
                new_end = (datetime.now() + timedelta(hours=BIZ_AUCTION_HOURS)).strftime(DB_DATE_FMT)
                c.execute("SELECT biz_type FROM biz_businesses WHERE owner_id = ?", (target_id,))
                bizes = c.fetchall()
                for b in bizes:
                    if b["biz_type"] in ("mafia", "league"):
                        continue
                    c.execute("""UPDATE biz_businesses
                                 SET owner_id = 0, status = 'auction', auction_end = ?,
                                     current_bet = 0, current_bidder = 0,
                                     seller_id = 0, upgrade_level = 0, min_bet = ?
                                 WHERE biz_type = ?""",
                              (new_end, BIZ_MIN_PRICE, b["biz_type"]))
                c.execute("""UPDATE lombard_loans SET status = 'cancelled', resolved_at = ?
                             WHERE user_id = ? AND status = 'active'""",
                          (db_now(), target_id))
                c.execute("DELETE FROM lombard_cooldowns WHERE user_id = ?", (target_id,))
                c.execute("DELETE FROM craft_resources WHERE user_id = ?", (target_id,))
                c.execute("DELETE FROM craft_buffs WHERE user_id = ?", (target_id,))
                c.execute("DELETE FROM craft_history WHERE user_id = ?", (target_id,))
                c.execute("DELETE FROM sbor_bets WHERE user_id = ?", (target_id,))
                c.execute("DELETE FROM poll_votes WHERE user_id = ?", (target_id,))
                c.execute("DELETE FROM court_cases WHERE plaintiff = ? OR defendant = ?", (target_id, target_id))
                c.execute("DELETE FROM advokats WHERE user_id = ? OR owner_id = ?", (target_id, target_id))
                c.execute("DELETE FROM advokat_deals WHERE thief_id = ? OR victim_id = ?", (target_id, target_id))
                c.execute("""UPDATE biz_trades SET status = 'cancelled', resolved_at = ?
                             WHERE (from_user = ? OR to_user = ?) AND status = 'pending'""",
                          (db_now(), target_id, target_id))
                c.execute("""UPDATE house_trades SET status = 'cancelled', resolved_at = ?
                             WHERE (seller_id = ? OR buyer_id = ?) AND status = 'pending'""",
                          (db_now(), target_id, target_id))
                c.execute("DELETE FROM rozygrysh_tickets WHERE user_id = ?", (target_id,))
                c.execute("DELETE FROM spam_bans WHERE user_id = ?", (target_id,))
                c.execute("DELETE FROM fake_money_log WHERE user_id = ?", (target_id,))
                c.execute("DELETE FROM frozen_money WHERE user_id = ? OR victim_id = ?", (target_id, target_id))
                c.execute("DELETE FROM shield_list WHERE user_id = ?", (target_id,))
                c.execute("DELETE FROM league_bets WHERE user_id = ?", (target_id,))
                c.execute("DELETE FROM user_states_db WHERE user_id = ?", (target_id,))
                c.execute("DELETE FROM transactions WHERE user_id = ?", (target_id,))
                c.execute("DELETE FROM users_left WHERE user_id = ?", (target_id,))
                conn.commit()
        if fam_row and fam_row["owner_id"] == target_id:
            for m in members:
                if m != target_id:
                    try:
                        send_message(m, "❌ Семья " + str(fam_row["name"]) + " распущена (полный сброс владельца)")
                    except Exception:
                        pass
        try:
            send_message(target_id, "♻️ Тебя полностью сбросили. Напиши /start")
        except Exception:
            pass
        return True, "✅ Игрок " + get_display_name(target_id) + " (" + str(target_id) + ") полностью сброшен."
    except Exception as e:
        print("⚠️ do_resetplayer: " + str(e))
        traceback.print_exc()
        return False, "❌ Ошибка: " + str(e)


def handle_resetplayer_command(chat_id, user_id, args):
    if not is_admin_level(user_id, 4):
        send_message(chat_id, "❌ Нужен ур. 4+ (Зам главного)")
        return
    if len(args) != 1:
        send_message(chat_id, "❌ /resetplayer ID|@username")
        return
    target_id = shield_resolve_id(args[0])
    if not target_id:
        send_message(chat_id, "❌ Игрок не найден!")
        return
    if get_user(target_id) is None:
        send_message(chat_id, "❌ Игрок не писал /start")
        return
    if int(target_id) == BOSS_ADMIN_ID:
        send_message(chat_id, "❌ Нельзя сбросить BOSS")
        return
    ok, reason = can_modify_role(user_id, target_id)
    if not ok:
        send_message(chat_id, reason)
        return
    name = get_display_name(target_id)
    with _resetplayer_pending_lock:
        _resetplayer_pending[user_id] = target_id
    kb = {"inline_keyboard": [
        [{"text": "✅ ДА, СБРОСИТЬ", "callback_data": "resetplayer_confirm"}],
        [{"text": "❌ ОТМЕНА", "callback_data": "resetplayer_cancel"}],
    ]}
    text = ("⚠️ ПОДТВЕРЖДЕНИЕ\n\n"
            "Полный сброс игрока:\n"
            "👤 " + str(name) + "\n"
            "🆔 " + str(target_id) + "\n\n"
            "🗑 БУДЕТ ОЧИЩЕНО:\n"
            "• 💰 Баланс → 15,000,000\n"
            "• 💎 FrikCoins → 0\n"
            "• 🏆 Титулы — снять все\n"
            "• 📦 Кейсы, крафт, рулетка — сброс\n"
            "• 📈 Портфель биржи — обнулить\n"
            "• 🎫 FRIK PASS — прогресс сброшен\n"
            "• 🏠 Дом — освободить\n"
            "• 📱 Номера — освободить\n"
            "• 👨‍👩‍👧 Семья — распустить/выйти\n"
            "• 🏢 Бизнесы — на аукцион\n"
            "• ⚖️ Суд/адвокат — удалить\n"
            "• 🎁 Билеты розыгрыша — СЖЕЧЬ\n"
            "• 🛠 Роль стаффа — снять\n"
            "• 🎉 Ивенты: билеты, снежки, статусы — сброс\n\n"
            "Продолжить?")
    send_message(chat_id, text, kb)


def handle_resetplayer_confirm(chat_id, user_id):
    with _resetplayer_pending_lock:
        target_id = _resetplayer_pending.pop(user_id, None)
    if not target_id:
        send_message(chat_id, "❌ Нет активного запроса на сброс.")
        return
    ok, msg = do_resetplayer(target_id)
    send_message(chat_id, msg)


def handle_resetplayer_cancel(chat_id, user_id):
    with _resetplayer_pending_lock:
        _resetplayer_pending.pop(user_id, None)
    send_message(chat_id, "❌ Отменено.")


