def handle_admin_staff_menu(chat_id, message_id, user_id):
    if not is_admin_level(user_id, 4):
        send_message(chat_id, "❌ Нужен ур. 4+")
        return
    lvl = get_role_level(get_staff_role(user_id))
    staff = list_all_staff()
    helpers_count = len([s for s in staff if s["role"] == ROLE_HELPER])
    admins_count = len([s for s in staff if s["role"] != ROLE_HELPER])
    text = "🛠 <b>УПРАВЛЕНИЕ СТАФФОМ</b>\n\n"
    text += "👑 Админов (ур. 1-7): " + str(admins_count) + "\n"
    text += "🛠 Хелперов: " + str(helpers_count) + "\n\n"
    text += "Твой уровень: " + str(lvl) + "/7\n"
    if lvl < 6:
        text += "\n<i>Управление ролями доступно с ур. 6+</i>\n"
        text += "<i>Но список ты видишь.</i>"
    kb = admin_staff_menu_keyboard()
    if lvl < 6:
        new_rows = []
        for row in kb["inline_keyboard"]:
            keep = True
            for btn in row:
                if btn["callback_data"] in (
                    "admin_staff_add_admin", "admin_staff_demote",
                    "admin_staff_remove", "admin_staff_add_helper",
                    "admin_staff_del_helper",
                ):
                    keep = False
                    break
            if keep:
                new_rows.append(row)
        kb = {"inline_keyboard": new_rows}
    if message_id:
        edit_message(chat_id, message_id, text, kb)
    else:
        send_message(chat_id, text, kb)


def handle_admin_staff_list(chat_id, message_id, user_id):
    if not is_admin_level(user_id, 1):
        send_message(chat_id, "❌ Нужен ур. 1+")
        return
    staff = list_all_staff()
    text = "🛠 <b>СПИСОК СТАФФА</b>\n\n"
    by_role = {}
    for s in staff:
        r = s["role"]
        by_role.setdefault(r, []).append(s)
    for role in ROLE_ORDER:
        users = by_role.get(role, [])
        if not users:
            continue
        text += "<b>" + get_role_label(role) + "</b> (" + str(len(users)) + "):\n"
        for s in users:
            uid = s["user_id"]
            name = get_display_name(uid)
            text += "  • " + str(name) + " <code>" + str(uid) + "</code>\n"
        text += "\n"
    if not staff:
        text += "<i>Стафф пуст.</i>\n"
    text += "\n<b>Владельцы (хардкод):</b>\n"
    text += "  • BOSS: <code>" + str(BOSS_ADMIN_ID) + "</code>\n"
    if ADMIN_ID and ADMIN_ID != BOSS_ADMIN_ID:
        text += "  • ADMIN_ID: <code>" + str(ADMIN_ID) + "</code>\n"
    if message_id:
        edit_message(chat_id, message_id, text, staff_list_keyboard())
    else:
        send_long_message(chat_id, text, staff_list_keyboard())


def handle_admin_helpers_online(chat_id, message_id, user_id):
    if not is_admin_level(user_id, 6):
        send_message(chat_id, "❌ Нужен ур. 6+")
        return
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT user_id FROM staff_roles WHERE role = ?", (ROLE_HELPER,))
                rows = c.fetchall()
    except Exception as e:
        send_message(chat_id, "❌ " + str(e))
        return
    now = datetime.now()
    text = "🛠 <b>ХЕЛПЕРЫ</b>\n\n"
    if not rows:
        text += "<i>Хелперов нет.</i>"
    else:
        online = []
        offline = []
        for r in rows:
            hid = r["user_id"]
            u = get_user(hid)
            last = db_parse(u["last_active"]) if (u and u["last_active"]) else None
            is_on = (last and (now - last).total_seconds() < HELPER_ONLINE_SEC)
            st = helper_stats_get(hid)
            name = get_display_name(hid)
            line = (str(name) + " — ✅ " + str(st["answered"]) + " | ❌ " +
                    str(st["cancelled"]))
            if is_on:
                online.append("🟢 " + line)
            else:
                offline.append("⚫ " + line)
        if online:
            text += "<b>🟢 Онлайн (" + str(len(online)) + "):</b>\n" + "\n".join(online) + "\n\n"
        if offline:
            text += "<b>⚫ Оффлайн (" + str(len(offline)) + "):</b>\n" + "\n".join(offline)
    kb = {"inline_keyboard": [
        [{"text": "🔄 ОБНОВИТЬ", "callback_data": "admin_helpers_online"}],
        [{"text": "⬅️ НАЗАД", "callback_data": "admin_staff_menu"}],
    ]}
    if message_id:
        edit_message(chat_id, message_id, text, kb)
    else:
        send_long_message(chat_id, text, kb)


