def handle_add_admin_cmd(chat_id, user_id, args):
    if not is_owner(user_id):
        send_message(chat_id, "❌ Только ур. 7 (Команда проекта)!")
        return
    if len(args) != 2:
        send_message(chat_id, "❌ /add_admin УРОВЕНЬ ID|@user")
        return
    try:
        level = int(args[0])
        if level < 1 or level > 7:
            send_message(chat_id, "❌ Уровень 1-7")
            return
    except ValueError:
        send_message(chat_id, "❌ Уровень числом (1-7)")
        return
    target_id = shield_resolve_id(args[1])
    if not target_id:
        send_message(chat_id, "❌ Игрок не найден!")
        return
    if get_user(target_id) is None:
        send_message(chat_id, "❌ Игрок не писал /start")
        return
    if int(target_id) == BOSS_ADMIN_ID:
        send_message(chat_id, "❌ BOSS_ADMIN_ID менять нельзя (хардкод)")
        return
    if int(target_id) == ADMIN_ID:
        send_message(chat_id, "❌ ADMIN_ID менять нельзя (env)")
        return
    role_map = {
        1: ROLE_ADMIN_1, 2: ROLE_ADMIN_2, 3: ROLE_ADMIN_3,
        4: ROLE_ADMIN_4, 5: ROLE_ADMIN_5, 6: ROLE_ADMIN_6, 7: ROLE_ADMIN_7,
    }
    new_role = role_map[level]
    ok2, msg = set_staff_role(target_id, new_role, added_by=user_id)
    if ok2:
        send_message(chat_id,
                     "✅ " + get_display_name(target_id) +
                     " → " + get_role_label(new_role))
        try:
            send_message(target_id,
                         "🎉 <b>ТЕБЕ ВЫДАЛИ РОЛЬ!</b>\n\n"
                         "🎖 " + get_role_label(new_role) + "\n"
                         "📖 /ahelp — твои команды\n"
                         "📊 /astats — статистика")
        except Exception:
            pass
    else:
        send_message(chat_id, msg)


