def handle_deller_admin_cmd(chat_id, user_id, args):
    if not is_owner(user_id):
        send_message(chat_id, "❌ Только ур. 7!")
        return
    if len(args) != 1:
        send_message(chat_id, "❌ /deller_admin ID|@user")
        return
    target_id = shield_resolve_id(args[0])
    if not target_id:
        send_message(chat_id, "❌ Игрок не найден!")
        return
    if int(target_id) == BOSS_ADMIN_ID:
        send_message(chat_id, "❌ BOSS_ADMIN_ID нельзя понизить (хардкод)")
        return
    if int(target_id) == ADMIN_ID:
        send_message(chat_id, "❌ ADMIN_ID нельзя понизить (env)")
        return
    role = get_staff_role(target_id)
    if not role:
        send_message(chat_id, "❌ У него нет роли.")
        return
    lvl = get_role_level(role)
    if role == ROLE_HELPER:
        ok, msg = remove_staff_role(target_id, removed_by=user_id)
        if ok:
            send_message(chat_id, "✅ Снят хелпер с " + get_display_name(target_id))
            try:
                send_message(target_id, "❌ Тебя сняли с должности хелпера.")
            except Exception:
                pass
        else:
            send_message(chat_id, msg)
        return
    if lvl <= 1:
        ok, msg = remove_staff_role(target_id, removed_by=user_id)
        if ok:
            send_message(chat_id, "✅ Ур. 1 → снят полностью: " + get_display_name(target_id))
            try:
                send_message(target_id, "❌ Тебя сняли с админки.")
            except Exception:
                pass
        else:
            send_message(chat_id, msg)
        return
    new_lvl = lvl - 1
    role_map = {
        1: ROLE_ADMIN_1, 2: ROLE_ADMIN_2, 3: ROLE_ADMIN_3,
        4: ROLE_ADMIN_4, 5: ROLE_ADMIN_5, 6: ROLE_ADMIN_6, 7: ROLE_ADMIN_7,
    }
    new_role = role_map[new_lvl]
    ok, msg = set_staff_role(target_id, new_role, added_by=user_id)
    if ok:
        send_message(chat_id,
                     "⬇️ " + get_display_name(target_id) +
                     " понижен: " + get_role_label(role) + " → " + get_role_label(new_role))
        try:
            send_message(target_id,
                         "⬇️ <b>ТЕБЯ ПОНИЗИЛИ</b>\n\n"
                         "🎖 " + get_role_label(new_role))
        except Exception:
            pass
    else:
        send_message(chat_id, msg)


def handle_admin_staff_remove_prompt(chat_id, user_id):
    if not is_owner(user_id):
        send_message(chat_id, "❌ Только ур. 7!")
        return
    text = ("❌ <b>СНЯТЬ РОЛЬ ПОЛНОСТЬЮ</b>\n\n"
            "Формат: <code>/add_admin_not ID|@user</code>\n\n"
            "Снимает любую роль (хелпер/админ).\n"
            "⚠️ BOSS и ADMIN_ID защищены.")
    send_message(chat_id, text, back_keyboard())


def handle_add_admin_not_cmd(chat_id, user_id, args):
    if not is_owner(user_id):
        send_message(chat_id, "❌ Только ур. 7!")
        return
    if len(args) != 1:
        send_message(chat_id, "❌ /add_admin_not ID|@user")
        return
    target_id = shield_resolve_id(args[0])
    if not target_id:
        send_message(chat_id, "❌ Игрок не найден!")
        return
    if int(target_id) == BOSS_ADMIN_ID:
        send_message(chat_id, "❌ BOSS_ADMIN_ID нельзя снять (хардкод)")
        return
    if int(target_id) == ADMIN_ID:
        send_message(chat_id, "❌ ADMIN_ID нельзя снять (env)")
        return
    role = get_staff_role(target_id)
    if not role:
        send_message(chat_id, "❌ У него нет роли.")
        return
    ok, msg = remove_staff_role(target_id, removed_by=user_id)
    if ok:
        send_message(chat_id, "✅ Снята роль: " + get_display_name(target_id) + " (было " + get_role_label(role) + ")")
        try:
            send_message(target_id, "❌ <b>Тебя сняли со стаффа.</b>")
        except Exception:
            pass
    else:
        send_message(chat_id, msg)


