def handle_admin_staff_help_chat_info(chat_id, message_id, user_id):
    if not is_owner(user_id):
        send_message(chat_id, "❌ Только ур. 7!")
        return
    current = get_help_chat_id()
    from_env = HELP_CHAT_ID_ENV
    if current:
        text = ("⚙️ <b>ЧАТ ХЕЛПЕРОВ</b>\n\n"
                "📌 Установлен: <code>" + str(current) + "</code>\n")
        if from_env and current == from_env:
            text += "Источник: env (HELP_CHAT_ID)\n"
        else:
            text += "Источник: БД (settings.help_chat_id)\n"
    else:
        text = ("⚙️ <b>ЧАТ ХЕЛПЕРОВ</b>\n\n"
                "❌ Не установлен.\n"
                "Игроки не смогут задавать вопросы через /rep_helpers.\n\n")
    text += ("\n<b>Как установить:</b>\n"
             "1. Создай супергруппу\n"
             "2. Добавь бота в чат\n"
             "3. Напиши боту: <code>/set_help_chat -1001234567890</code>\n\n"
             "<b>Как сбросить:</b>\n"
             "<code>/set_help_chat off</code>\n\n"
             "💡 Узнать ID чата: напиши в чате что-нибудь → боту в ЛС /whoami")
    kb = {"inline_keyboard": [
        [{"text": "⬅️ НАЗАД", "callback_data": "admin_staff_menu"}],
    ]}
    if message_id:
        edit_message(chat_id, message_id, text, kb)
    else:
        send_long_message(chat_id, text, kb)


