# ========== ✅ ФИЧА А: БУСТ РУЛЕТКИ ==========

def get_roulette_boost(user_id):
    """Возвращает dict: {'percent': int, 'until': datetime|None}.
    Если буст истёк — возвращает {'percent': 0, 'until': None}.
    """
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("""SELECT roulette_boost_percent, roulette_boost_until
                             FROM users WHERE user_id = ?""", (user_id,))
                r = c.fetchone()
                if not r:
                    return {"percent": 0, "until": None}
                percent = r["roulette_boost_percent"] or 0
                until_str = r["roulette_boost_until"]
                if percent <= 0 or not until_str:
                    return {"percent": 0, "until": None}
                until_dt = db_parse(until_str)
                if not until_dt or until_dt <= datetime.now():
                    return {"percent": 0, "until": None}
                return {"percent": int(percent), "until": until_dt}
    except Exception as e:
        print("⚠️ get_roulette_boost: " + str(e))
        return {"percent": 0, "until": None}


def set_roulette_boost(user_id, percent, days):
    """Ставит буст на N дней. Если уже есть активный — ПРОДЛЕВАЕТ.
    Percent всегда фиксированный (не суммируется).
    """
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("""SELECT roulette_boost_until FROM users WHERE user_id = ?""",
                          (user_id,))
                r = c.fetchone()
                old_until = None
                if r and r["roulette_boost_until"]:
                    old_until = db_parse(r["roulette_boost_until"])
                now = datetime.now()
                base = old_until if (old_until and old_until > now) else now
                new_until = base + timedelta(days=days)
                c.execute("""UPDATE users
                             SET roulette_boost_percent = ?,
                                 roulette_boost_until = ?
                             WHERE user_id = ?""",
                          (int(percent), new_until.strftime(DB_DATE_FMT), user_id))
                conn.commit()
        return True, new_until
    except Exception as e:
        print("⚠️ set_roulette_boost: " + str(e))
        return False, None


# ========== ✅ ФИЧА А: ПОКУПКА В FCSHOP ==========

def fcshop_buy(user_id, item_key):
    """Основная логика покупки. Возвращает (ok, message).
    Для кастомного титула — отдельный диалог (не тут).
    """
    item = FCSHOP_ITEMS.get(item_key)
    if not item:
        return False, "❌ Товар не найден!"
    price = item["price"]
    frik = get_frik(user_id)
    if frik < price:
        return False, ("❌ Недостаточно FrikCoins!\n"
                       "Нужно: " + str(price) + " FC\n"
                       "У тебя: " + str(frik) + " FC")
    user = get_user(user_id)
    if not user:
        return False, "❌ Напиши /start"

    # === ВАЛИДАЦИЯ ДО СПИСАНИЯ (защита от пустой траты) ===
    if item_key == "lombard_cd":
        cd = lombard_get_cooldown(user_id)
        if not cd:
            return False, "❌ У тебя нет активного кулдауна ломбарда!"
        diff = (datetime.now() - cd).total_seconds()
        if diff >= LOMBARD_COOLDOWN:
            return False, "❌ Кулдаун ломбарда уже истёк!"
    if item_key == "fake_unban":
        if not fake_is_banned(user_id):
            return False, "❌ Ты не в бане фальшивок!"
    if item_key == "title":
        # Сюда не должны попадать — идёт через handle_fcshop_buy_title
        return False, "❌ Используй кнопку покупки титула."

    # === СПИСАНИЕ FC ===
    if not add_frik(user_id, -price):
        return False, "❌ Ошибка списания FC!"

    # === ПРИМЕНЕНИЕ ===
    result_msg = ""
    try:
        if item_key == "roulette":
            ok, new_until = set_roulette_boost(user_id, 10, 7)
            if not ok:
                add_frik(user_id, price)  # возврат
                return False, "❌ Ошибка установки буста. FC возвращены."
            until_str = new_until.strftime("%d.%m %H:%M") if new_until else "?"
            result_msg = ("✅ БУСТ КУПЛЕН!\n\n"
                          "🎯 +10% к рулетке\n"
                          "⏰ До: " + until_str + "\n"
                          "💎 −" + str(price) + " FC\n"
                          "💎 Осталось: " + str(get_frik(user_id)))
        elif item_key == "immunity":
            now = datetime.now()
            old_apt = db_parse(user["apteka_immunity_until"]) if user["apteka_immunity_until"] else None
            old_bol = db_parse(user["bolnitsa_immunity_until"]) if user["bolnitsa_immunity_until"] else None
            base_apt = old_apt if (old_apt and old_apt > now) else now
            base_bol = old_bol if (old_bol and old_bol > now) else now
            new_apt = base_apt + timedelta(days=30)
            new_bol = base_bol + timedelta(days=30)
            with DB_LOCK:
                with _conn() as conn:
                    c = conn.cursor()
                    c.execute("""UPDATE users
                                 SET apteka_immunity_until = ?,
                                     bolnitsa_immunity_until = ?
                                 WHERE user_id = ?""",
                              (new_apt.strftime(DB_DATE_FMT),
                               new_bol.strftime(DB_DATE_FMT),
                               user_id))
                    conn.commit()
            result_msg = ("✅ ИММУНИТЕТ КУПЛЕН!\n\n"
                          "💊 Анти-аптека до: " + new_apt.strftime("%d.%m %H:%M") + "\n"
                          "🩺 Анти-обследование до: " + new_bol.strftime("%d.%m %H:%M") + "\n"
                          "💎 −" + str(price) + " FC\n"
                          "💎 Осталось: " + str(get_frik(user_id)))
        elif item_key == "lombard_cd":
            with DB_LOCK:
                with _conn() as conn:
                    c = conn.cursor()
                    c.execute("""UPDATE lombard_cooldowns
                                 SET last_loan = NULL
                                 WHERE user_id = ?""", (user_id,))
                    conn.commit()
            result_msg = ("✅ КУЛДАУН ЛОМБАРДА СНЯТ!\n\n"
                          "💰 Можно снова взять займ\n"
                          "💎 −" + str(price) + " FC\n"
                          "💎 Осталось: " + str(get_frik(user_id)))
        elif item_key == "fake_unban":
            fake_unban(user_id)
            result_msg = ("✅ БАН ФАЛЬШИВОК СНЯТ!\n\n"
                          "🖨 Можно снова печатать\n"
                          "💎 −" + str(price) + " FC\n"
                          "💎 Осталось: " + str(get_frik(user_id)))
        else:
            add_frik(user_id, price)
            return False, "❌ Неизвестный товар. FC возвращены."

        add_transaction(user_id, 0, "fcshop_buy", "fcshop", item["name"])
        return True, result_msg
    except Exception as e:
        add_frik(user_id, price)
        print("⚠️ fcshop_buy error: " + str(e))
        return False, "❌ Ошибка: " + str(e) + "\nFC возвращены."


# ========== ✅ ФИЧА Б: НОМЕРА ==========
# ✅ ФИКС: храним только занятые номера. Свободный = нет строки в БД.

def phone_get(num):
    """Возвращает строку phones по номеру или None (если номер свободен)."""
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT * FROM phones WHERE number = ?", (str(num).zfill(4),))
                return c.fetchone()
    except Exception:
        return None


def phone_get_owned(user_id):
    """Возвращает список Row всех номеров игрока (сначала красивые)."""
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("""SELECT number, owner_id, is_pretty, bought_at
                             FROM phones WHERE owner_id = ?
                             ORDER BY is_pretty DESC, number ASC""", (user_id,))
                return c.fetchall()
    except Exception:
        return []


def phone_buy(user_id, num):
    """Купить обычный номер за FC. Красивые не продаются."""
    num = str(num).strip().zfill(4)
    if not num.isdigit() or len(num) != 4:
        return False, "❌ Номер должен быть 4 цифры (0000-9999)!"
    if num in PHONE_PRETTY_SET:
        return False, "❌ Красивый номер — только через аукцион!"

    # Проверяем, что номер свободен (нет строки в БД)
    row = phone_get(num)
    if row and row["owner_id"] and row["owner_id"] != 0:
        owner_name = get_display_name(row["owner_id"])
        return False, "❌ Номер уже занят: " + str(owner_name)

    frik = get_frik(user_id)
    if frik < PHONE_BUY_PRICE:
        return False, ("❌ Недостаточно FrikCoins!\n"
                       "Нужно: " + str(PHONE_BUY_PRICE) + " FC\n"
                       "У тебя: " + str(frik) + " FC")

    # Списываем FC
    if not add_frik(user_id, -PHONE_BUY_PRICE):
        return False, "❌ Ошибка списания FC!"
    # Назначаем владельца (INSERT OR REPLACE — создаём строку если её нет)
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("""INSERT OR REPLACE INTO phones
                             (number, owner_id, is_pretty, bought_at)
                             VALUES (?, ?, ?, ?)""",
                          (num, user_id, 1 if num in PHONE_PRETTY_SET else 0, db_now()))
                conn.commit()
    except Exception as e:
        add_frik(user_id, PHONE_BUY_PRICE)
        return False, "❌ Ошибка: " + str(e)
    add_transaction(user_id, 0, "phone_buy", "phone", "Куплен номер +" + num)
    return True, ("✅ НОМЕР КУПЛЕН!\n\n"
                  "📱 +" + num + "\n"
                  "💰 −" + str(PHONE_BUY_PRICE) + " FC\n"
                  "💎 Осталось: " + str(get_frik(user_id)))


def phone_transfer(from_user, num, to_user):
    """Бесплатная передача номера."""
    num = str(num).strip().zfill(4)
    if from_user == to_user:
        return False, "❌ Себе передать нельзя!"
    row = phone_get(num)
    if not row or row["owner_id"] != from_user:
        return False, "❌ Этот номер не твой!"
    if get_user(to_user) is None:
        return False, "❌ Получатель не писал /start!"
    if is_left(to_user):
        return False, "❌ Получатель ушёл из бота!"
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("""UPDATE phones SET owner_id = ?, bought_at = ?
                             WHERE number = ?""",
                          (to_user, db_now(), num))
                conn.commit()
    except Exception as e:
        return False, "❌ Ошибка: " + str(e)
    add_transaction(from_user, 0, "phone_transfer_out", "phone", "Передан +" + num)
    add_transaction(to_user, 0, "phone_transfer_in", "phone", "Получен +" + num)
    try:
        send_message(to_user,
                     "📱 ТЕБЕ ПЕРЕДАЛИ НОМЕР!\n\n"
                     "📞 +" + num + "\n"
                     "👤 От: " + get_display_name(from_user))
    except Exception:
        pass
    return True, ("✅ НОМЕР ПЕРЕДАН!\n\n"
                  "📱 +" + num + "\n"
                  "👤 Кому: " + get_display_name(to_user))


def phone_send_sms(from_user, num, text):
    """SMS владельцу номера. Нужен свой номер. Отправитель виден."""
    num = str(num).strip().zfill(4)
    text = str(text).strip()[:500]
    if not text:
        return False, "❌ Пустое сообщение!"

    # Проверяем, что у отправителя есть свой номер
    my_phones = phone_get_owned(from_user)
    if not my_phones:
        return False, "❌ У тебя нет своего номера! Купи через /buynumber."

    # Находим владельца получателя
    row = phone_get(num)
    if not row:
        return False, "❌ Номер не зарегистрирован."
    owner_id = row["owner_id"] or 0
    if owner_id == 0:
        return False, "❌ По этому номеру никто не зарегистрирован."
    if owner_id == from_user:
        return False, "❌ Нельзя писать себе!"

    sender_name = get_display_name(from_user)
    sender_phone = my_phones[0]["number"]
    try:
        send_message(owner_id,
                     "📱 <b>SMS</b>\n\n"
                     "📞 От: +" + str(sender_phone) + "\n"
                     "👤 " + str(sender_name) + "\n\n"
                     "💬 " + esc(text))
    except Exception as e:
        return False, "❌ Не удалось доставить: " + str(e)
    return True, ("✅ SMS ОТПРАВЛЕНО!\n\n"
                  "📞 Кому: +" + num + "\n"
                  "💬 " + text[:100])


def phone_put_on_auction(user_id, num):
    """Выставить свой красивый номер на аукцион (1 час)."""
    num = str(num).strip().zfill(4)
    if num not in PHONE_PRETTY_SET:
        return False, "❌ На аукцион можно выставлять только красивые номера!"
    row = phone_get(num)
    if not row or row["owner_id"] != user_id:
        return False, "❌ Этот номер не твой!"

    # Проверяем, что нет активного аукциона на этот номер
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("""SELECT id FROM auctions
                             WHERE status = 'active'
                             AND lot_type = 'phone'
                             AND lot_value = ?""", (num,))
                if c.fetchone():
                    return False, "❌ Этот номер уже на аукционе!"
    except Exception:
        pass

    # Создаём аукцион на 1 час
    try:
        ends_at = (datetime.now() + timedelta(hours=PHONE_AUCTION_HOURS)).strftime(DB_DATE_FMT)
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("""INSERT INTO auctions
                             (title, description, lot_type, lot_value,
                              min_bet, step, created_by, chat_id, ends_at, status)
                             VALUES (?, ?, 'phone', ?, ?, ?, ?, ?, ?, 'active')""",
                          ("📱 Красивый номер +" + num,
                           "Красивый номер. Ставка: " + format(PHONE_AUCTION_MIN) + " – " + format(PHONE_AUCTION_MAX),
                           num, PHONE_AUCTION_MIN, 10_000_000,
                           user_id, CHAT_ID, ends_at))
                auc_id = c.lastrowid
                conn.commit()
    except Exception as e:
        return False, "❌ Ошибка: " + str(e)

    try:
        post_auction_to_chat(CHAT_ID, auc_id)
    except Exception as e:
        print("⚠️ post phone auction: " + str(e))

    return True, ("✅ НОМЕР НА АУКЦИОНЕ!\n\n"
                  "📱 +" + num + "\n"
                  "⏰ 1 час\n"
                  "💰 Мин: " + format(PHONE_AUCTION_MIN) + "\n"
                  "📈 Макс: " + format(PHONE_AUCTION_MAX) + "\n\n"
                  "⚠️ Если ставок не будет — вернётся тебе.")


# ========== ✅ ФИЧА Б: АДМИН-ОПЕРАЦИИ С НОМЕРАМИ ==========

def phone_admin_give(target_id, num):
    """Выдать номер игроку (админ). Снимает с прошлого владельца."""
    num = str(num).strip().zfill(4)
    if get_user(target_id) is None:
        return False, "❌ Игрок не найден (не писал /start)!"
    row = phone_get(num)
    old_owner = row["owner_id"] if row else 0
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("""INSERT OR REPLACE INTO phones
                             (number, owner_id, is_pretty, bought_at)
                             VALUES (?, ?, ?, ?)""",
                          (num, target_id, 1 if num in PHONE_PRETTY_SET else 0, db_now()))
                # Отменяем активный аукцион на этот номер
                c.execute("""UPDATE auctions SET status = 'cancelled'
                             WHERE status = 'active'
                             AND lot_type = 'phone'
                             AND lot_value = ?""", (num,))
                conn.commit()
    except Exception as e:
        return False, "❌ Ошибка: " + str(e)
    msg = "✅ Номер +" + num + " выдан " + get_display_name(target_id)
    if old_owner and old_owner != target_id:
        msg += "\n(забран у " + get_display_name(old_owner) + ")"
        try:
            send_message(old_owner, "❌ Твой номер +" + num + " забрал админ.")
        except Exception:
            pass
    return True, msg


def phone_admin_reset(num):
    """Освободить номер (удалить строку из БД, отменить аукционы)."""
    num = str(num).strip().zfill(4)
    row = phone_get(num)
    old_owner = row["owner_id"] if row else 0
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("DELETE FROM phones WHERE number = ?", (num,))
                c.execute("""UPDATE auctions SET status = 'cancelled'
                             WHERE status = 'active'
                             AND lot_type = 'phone'
                             AND lot_value = ?""", (num,))
                conn.commit()
    except Exception as e:
        return False, "❌ Ошибка: " + str(e)
    msg = "✅ Номер +" + num + " освобождён"
    if old_owner:
        msg += " (был у " + get_display_name(old_owner) + ")"
        try:
            send_message(old_owner, "❌ Твой номер +" + num + " освобождён админом.")
        except Exception:
            pass
    return True, msg


# ========== ✅ ФИЧА Б: СТАРТОВЫЕ АУКЦИОНЫ ==========

def phone_start_initial_auctions():
    """Запуск 10 аукционов красивых номеров при старте бота.
    Ставит на аукцион только СВОБОДНЫЕ красивые номера без активного аукциона.
    """
    print("📱 Запуск стартовых аукционов красивых номеров...")
    started = 0
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                now = datetime.now()
                for num in PHONE_PRETTY:
                    # Проверяем: номер свободен?
                    c.execute("SELECT owner_id FROM phones WHERE number = ?", (num,))
                    row = c.fetchone()
                    owner = row["owner_id"] if row else 0
                    if owner and owner != 0:
                        continue
                    # Проверяем, нет ли активного аукциона
                    c.execute("""SELECT id FROM auctions
                                 WHERE status = 'active'
                                 AND lot_type = 'phone'
                                 AND lot_value = ?""", (num,))
                    if c.fetchone():
                        continue
                    # Создаём аукцион на 1 час
                    ends_at = (now + timedelta(hours=PHONE_AUCTION_HOURS)).strftime(DB_DATE_FMT)
                    c.execute("""INSERT INTO auctions
                                 (title, description, lot_type, lot_value,
                                  min_bet, step, created_by, chat_id, ends_at, status)
                                 VALUES (?, ?, 'phone', ?, ?, ?, ?, ?, ?, 'active')""",
                              ("📱 Красивый номер +" + str(num),
                               "Красивый номер. Ставка: " + format(PHONE_AUCTION_MIN) + " – " + format(PHONE_AUCTION_MAX),
                               str(num), PHONE_AUCTION_MIN, 10_000_000,
                               BOSS_ADMIN_ID, CHAT_ID, ends_at))
                    new_id = c.lastrowid
                    conn.commit()
                    started += 1
                    try:
                        post_auction_to_chat(CHAT_ID, new_id)
                    except Exception as e:
                        print("⚠️ post phone auction: " + str(e))
    except Exception as e:
        print("⚠️ phone_start_initial_auctions: " + str(e))
    print("📱 Стартовых аукционов запущено: " + str(started))
    return started


def process_phone_vish_input(chat_id, user_id, text):
    """Обработка ввода получателя для передачи номера через кнопку."""
    state = user_state_get(user_id)
    if not state or state.get("action") != "phone_vish_input":
        return
    t = text.strip()
    if t.lower() in ("/cancel", "отмена"):
        user_state_pop(user_id)
        send_message(chat_id, "❌ Отменено.")
        return
    num = state.get("number")
    target_id = None
    if t.startswith('@'):
        target_id = get_user_id_by_username(t[1:])
    else:
        try:
            target_id = int(t)
        except ValueError:
            pass
    if not target_id:
        send_message(chat_id, "❌ Получатель не найден!")
        return
    user_state_pop(user_id)
    ok, result = phone_transfer(user_id, num, target_id)
    send_message(chat_id, result)


