def init_events_db():
    """Создаёт все таблицы ивентов. Вызывать из init_db() один раз."""
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()

                # --- Активный ивент (одна строка id=1) ---
                c.execute('''CREATE TABLE IF NOT EXISTS event_active (
                    id INTEGER PRIMARY KEY CHECK (id = 1),
                    event_key TEXT DEFAULT 'none',
                    started_at TIMESTAMP,
                    ends_at TIMESTAMP,
                    changed_by INTEGER DEFAULT 0
                )''')
                c.execute("INSERT OR IGNORE INTO event_active (id, event_key) VALUES (1, 'none')")

                # --- Билеты игроков ---
                c.execute('''CREATE TABLE IF NOT EXISTS event_tickets (
                    user_id INTEGER PRIMARY KEY,
                    dark_count INTEGER DEFAULT 0,
                    bubble_count INTEGER DEFAULT 0,
                    winter_count INTEGER DEFAULT 0,
                    last_dark_given TIMESTAMP,
                    last_bubble_given TIMESTAMP,
                    last_winter_given TIMESTAMP,
                    last_spusk TIMESTAMP
                )''')

                # --- Снежки ---
                c.execute('''CREATE TABLE IF NOT EXISTS user_snowballs (
                    user_id INTEGER PRIMARY KEY,
                    amount INTEGER DEFAULT 0,
                    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                )''')

                # --- Статусы игроков ---
                c.execute('''CREATE TABLE IF NOT EXISTS user_statuses (
                    user_id INTEGER,
                    status_key TEXT,
                    awarded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    awarded_by INTEGER DEFAULT 0,
                    PRIMARY KEY (user_id, status_key)
                )''')

                # --- Игры «Тьмы» ---
                c.execute('''CREATE TABLE IF NOT EXISTS event_games (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    creator_id INTEGER,
                    status TEXT DEFAULT 'collecting',
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    collect_until TIMESTAMP,
                    play_until TIMESTAMP,
                    message_map TEXT DEFAULT '{}'
                )''')
                c.execute("CREATE INDEX IF NOT EXISTS idx_event_games_status ON event_games(status)")

                # --- Участники игр «Тьмы» ---
                c.execute('''CREATE TABLE IF NOT EXISTS event_game_players (
                    game_id INTEGER,
                    user_id INTEGER,
                    joined_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    pressed_at TIMESTAMP,
                    PRIMARY KEY (game_id, user_id)
                )''')

                # --- История игр ---
                c.execute('''CREATE TABLE IF NOT EXISTS event_game_history (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    game_id INTEGER,
                    result TEXT,
                    players_json TEXT,
                    rewards_json TEXT,
                    ended_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                )''')

                # --- Лог выдачи ивент-кейсов (для статистики) ---
                c.execute('''CREATE TABLE IF NOT EXISTS event_case_log (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    user_id INTEGER,
                    case_key TEXT,
                    source TEXT,
                    reward_label TEXT,
                    timestamp TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                )''')

                conn.commit()
        print("✅ Ивент-таблицы созданы (8 шт.)")
        return True
    except Exception as e:
        print("❌ init_events_db: " + str(e))
        traceback.print_exc()
        return False


