def event_get_active():
    """Возвращает ключ активного ивента ('none'/'dark'/'summer'/'winter')."""
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT event_key, ends_at FROM event_active WHERE id = 1")
                r = c.fetchone()
                if not r:
                    return EVENT_NONE
                key = r["event_key"] or EVENT_NONE
                # Автосброс по ends_at
                if key != EVENT_NONE and r["ends_at"]:
                    ends = db_parse(r["ends_at"])
                    if ends and ends <= datetime.now():
                        c.execute("UPDATE event_active SET event_key = 'none', ends_at = NULL WHERE id = 1")
                        conn.commit()
                        return EVENT_NONE
                return key
    except Exception as e:
        print("⚠️ event_get_active: " + str(e))
        return EVENT_NONE


def event_set_active(key, admin_id=0, hours=0):
    """Устанавливает активный ивент. hours=0 → без автосброса.
    Возвращает (ok, message)."""
    if key not in EVENT_LABELS:
        return False, "❌ Неизвестный ивент!"
    try:
        ends_at = None
        if hours > 0:
            ends_at = (datetime.now() + timedelta(hours=hours)).strftime(DB_DATE_FMT)
        with EVENT_LOCK:
            with DB_LOCK:
                with _conn() as conn:
                    c = conn.cursor()
                    c.execute("""UPDATE event_active
                                 SET event_key = ?, started_at = ?, ends_at = ?, changed_by = ?
                                 WHERE id = 1""",
                              (key, db_now(), ends_at, admin_id))
                    conn.commit()
        staff_log_write(admin_id, "event_set", 0,
                        "Ивент: " + key + ((" до " + ends_at[:16]) if ends_at else ""))
        return True, "✅ Активный ивент: " + EVENT_LABELS[key]
    except Exception as e:
        return False, "❌ " + str(e)


