# ✅ СЕРВИС: БИЛЕТЫ
# ============================================================

def _ticket_ensure_row(user_id):
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("INSERT OR IGNORE INTO event_tickets (user_id) VALUES (?)", (user_id,))
                conn.commit()
        return True
    except Exception:
        return False


def ticket_get(user_id, kind):
    """kind: 'dark' / 'bubble' / 'winter'. Возвращает int."""
    col = {"dark": "dark_count", "bubble": "bubble_count", "winter": "winter_count"}.get(kind)
    if not col:
        return 0
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT " + col + " FROM event_tickets WHERE user_id = ?", (user_id,))
                r = c.fetchone()
                return (r[col] or 0) if r else 0
    except Exception:
        return 0


def ticket_add(user_id, kind, amount=1):
    """Начислить билеты. Возвращает новое количество."""
    col = {"dark": "dark_count", "bubble": "bubble_count", "winter": "winter_count"}.get(kind)
    if not col or amount <= 0:
        return 0
    try:
        _ticket_ensure_row(user_id)
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("UPDATE event_tickets SET " + col + " = " + col + " + ? WHERE user_id = ?",
                          (amount, user_id))
                conn.commit()
                c.execute("SELECT " + col + " FROM event_tickets WHERE user_id = ?", (user_id,))
                r = c.fetchone()
                return r[col] if r else 0
    except Exception:
        return 0


def ticket_take(user_id, kind, amount=1):
    """Списать билеты. Атомарно. Возвращает True/False."""
    col = {"dark": "dark_count", "bubble": "bubble_count", "winter": "winter_count"}.get(kind)
    if not col or amount <= 0:
        return False
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("UPDATE event_tickets SET " + col + " = " + col + " - ? WHERE user_id = ? AND " + col + " >= ?",
                          (amount, user_id, amount))
                if c.rowcount == 0:
                    conn.rollback()
                    return False
                conn.commit()
        return True
    except Exception:
        return False


def ticket_set_time(user_id, kind):
    """Обновить last_*_given при выдаче билета."""
    col = {"dark": "last_dark_given", "bubble": "last_bubble_given", "winter": "last_winter_given"}.get(kind)
    if not col:
        return False
    try:
        _ticket_ensure_row(user_id)
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("UPDATE event_tickets SET " + col + " = ? WHERE user_id = ?",
                          (db_now(), user_id))
                conn.commit()
        return True
    except Exception:
        return False


def ticket_last_given(user_id, kind):
    """Возвращает datetime последней выдачи или None."""
    col = {"dark": "last_dark_given", "bubble": "last_bubble_given", "winter": "last_winter_given"}.get(kind)
    if not col:
        return None
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT " + col + " FROM event_tickets WHERE user_id = ?", (user_id,))
                r = c.fetchone()
                if not r or not r[col]:
                    return None
                return db_parse(r[col])
    except Exception:
        return None


def ticket_give_hourly(user_id, kind):
    """Раз в N часов выдаёт билет, если у игрока 0. Возвращает True если выдан."""
    if ticket_get(user_id, kind) >= TICKET_MAX:
        return False
    if kind == "dark":
        interval = TICKET_HOURLY_SEC
    elif kind == "bubble":
        interval = TICKET_BUBBLE_SEC
    elif kind == "winter":
        interval = TICKET_WINTER_SEC
    else:
        return False
    last = ticket_last_given(user_id, kind)
    if last and (datetime.now() - last).total_seconds() < interval:
        return False
    ticket_add(user_id, kind, 1)
    ticket_set_time(user_id, kind)
    return True


# ============================================================
# ✅ СЕРВИС: СНЕЖКИ
# ============================================================

def snow_get(user_id):
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT amount FROM user_snowballs WHERE user_id = ?", (user_id,))
                r = c.fetchone()
                return (r["amount"] or 0) if r else 0
    except Exception:
        return 0


def snow_add(user_id, amount):
    if amount == 0:
        return 0
    try:
        with SNOW_LOCK:
            with DB_LOCK:
                with _conn() as conn:
                    c = conn.cursor()
                    c.execute("INSERT OR IGNORE INTO user_snowballs (user_id, amount) VALUES (?, 0)", (user_id,))
                    c.execute("UPDATE user_snowballs SET amount = amount + ?, updated_at = ? WHERE user_id = ?",
                              (amount, db_now(), user_id))
                    conn.commit()
                    c.execute("SELECT amount FROM user_snowballs WHERE user_id = ?", (user_id,))
                    r = c.fetchone()
                    return r["amount"] if r else 0
    except Exception:
        return 0


def snow_take(user_id, amount):
    """Атомарно списывает снежки. True/False."""
    if amount <= 0:
        return False
    try:
        with SNOW_LOCK:
            with DB_LOCK:
                with _conn() as conn:
                    c = conn.cursor()
                    c.execute("UPDATE user_snowballs SET amount = amount - ? WHERE user_id = ? AND amount >= ?",
                              (amount, user_id, amount))
                    if c.rowcount == 0:
                        conn.rollback()
                        return False
                    conn.commit()
        return True
    except Exception:
        return False


