# ✅ СЕРВИС: СТАТУСЫ
# ============================================================

def status_get(user_id):
    """Возвращает список dict: [{'key': 'dark_lord', 'label': '...', 'awarded_at': ...}]"""
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT status_key, awarded_at FROM user_statuses WHERE user_id = ? ORDER BY awarded_at",
                          (user_id,))
                rows = c.fetchall()
        result = []
        for r in rows:
            key = r["status_key"]
            result.append({
                "key": key,
                "label": STATUS_LABELS.get(key, key),
                "awarded_at": r["awarded_at"],
            })
        return result
    except Exception:
        return []


def status_has(user_id, key):
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT 1 FROM user_statuses WHERE user_id = ? AND status_key = ?",
                          (user_id, key))
                return c.fetchone() is not None
    except Exception:
        return False


def status_add(user_id, key, awarded_by=0):
    """Возвращает (ok, message). Если уже есть — False."""
    if key not in STATUS_LABELS:
        return False, "❌ Неизвестный статус!"
    if status_has(user_id, key):
        return False, "ℹ️ Уже есть этот статус"
    try:
        with STATUS_LOCK:
            with DB_LOCK:
                with _conn() as conn:
                    c = conn.cursor()
                    c.execute("""INSERT OR IGNORE INTO user_statuses
                                 (user_id, status_key, awarded_at, awarded_by)
                                 VALUES (?, ?, ?, ?)""",
                              (user_id, key, db_now(), awarded_by))
                    conn.commit()
        return True, "✅ Выдан статус: " + STATUS_LABELS[key]
    except Exception as e:
        return False, "❌ " + str(e)


def status_remove(user_id, key):
    try:
        with STATUS_LOCK:
            with DB_LOCK:
                with _conn() as conn:
                    c = conn.cursor()
                    c.execute("DELETE FROM user_statuses WHERE user_id = ? AND status_key = ?",
                              (user_id, key))
                    a = c.rowcount
                    conn.commit()
        return a > 0
    except Exception:
        return False


