# ✅ СЕРВИС: РОЛЛ НАГРАД (общий для всех ивентов)
# ============================================================

def event_roll_rewards(rewards_list):
    """Роллит одну награду из списка по chance. Возвращает dict или None."""
    roll = random.randint(1, 100)
    cumulative = 0
    for r in rewards_list:
        cumulative += r["chance"]
        if roll <= cumulative:
            return r
    return rewards_list[-1] if rewards_list else None


def event_grant_reward(user_id, reward, source="event"):
    """Выдаёт награду. Возвращает текст «что выдано» (или '')."""
    if not reward:
        return ""
    t = reward.get("type")
    v = reward.get("value", 0)
    label = reward.get("label", "?")

    if t == "nothing":
        return "💨 Пусто"

    if t == "points":
        ok, _, _ = add_balance(user_id, int(v))
        add_transaction(user_id, int(v), "event_reward_points", "event", source)
        return "💰 " + format(int(v)) if ok else "⚠️ Ошибка начисления поинтов"

    if t == "frik":
        add_frik(user_id, int(v))
        return "💎 " + str(int(v)) + " FC"

    if t == "wood":
        craft_add_resources(user_id, wood=int(v))
        return "🪵 " + str(int(v)) + " брёвен"

    if t == "iron":
        craft_add_resources(user_id, iron=int(v))
        return "⛏ " + str(int(v)) + " железа"

    if t == "diamond":
        craft_add_resources(user_id, diamond=int(v))
        return "💎 " + str(int(v)) + " алмазов"

    if t == "snowball":
        snow_add(user_id, int(v))
        return "❄️ " + str(int(v)) + " снежков"

    if t == "admin_role":
        lvl = int(v)
        return _event_grant_admin_role(user_id, lvl)

    if t == "status":
        ok, msg = status_add(user_id, v, awarded_by=0)
        return msg

    if t == "dark_case":
        # Открыть кейс «Тьма» сразу (не требует билета)
        return dark_case_open(user_id, source="darkgame")

    if t == "sea_case":
        return sea_case_open(user_id, source="pool")

    return label


def _event_grant_admin_role(user_id, level):
    """Выдаёт админку уровня N. Если у игрока уже выше — компенсация 100кк."""
    current_role = get_staff_role(user_id)
    current_lvl = get_role_level(current_role) if current_role else 0
    if current_lvl >= level:
        # Компенсация
        ok, _, _ = add_balance(user_id, 100_000_000)
        if ok:
            add_transaction(user_id, 100_000_000, "event_admin_compensation", "event",
                            "Компенсация за админку ур. " + str(level))
        return "💰 100,000,000 (компенсация за админку ур. " + str(level) + ")"
    # Выдаём роль
    role_map = {
        1: ROLE_ADMIN_1, 2: ROLE_ADMIN_2, 3: ROLE_ADMIN_3,
        4: ROLE_ADMIN_4, 5: ROLE_ADMIN_5, 6: ROLE_ADMIN_6, 7: ROLE_ADMIN_7,
    }
    new_role = role_map.get(level)
    if not new_role:
        return "⚠️ Неверный уровень админки"
    # Защита BOSS/ADMIN_ID не нужна — они не могут быть ниже
    ok, msg = set_staff_role(user_id, new_role, added_by=0)
    if ok:
        try:
            send_message(user_id,
                         "🎉 <b>ТЕБЕ ВЫДАЛИ АДМИНКУ ИЗ ИВЕНТА!</b>\n\n"
                         "🎖 " + get_role_label(new_role) + "\n"
                         "📖 /ahelp — твои команды")
        except Exception:
            pass
        return "🛠 " + get_role_label(new_role)
    return "⚠️ " + str(msg)


