def _event_case_open_common(user_id, case_key, rewards_list, source):
    """Общий движок для всех ивент-кейсов."""
    reward = event_roll_rewards(rewards_list)
    if not reward:
        return "❌ Кейс пуст"
    given_text = event_grant_reward(user_id, reward, source=case_key)
    # Лог
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("""INSERT INTO event_case_log
                             (user_id, case_key, source, reward_label)
                             VALUES (?, ?, ?, ?)""",
                          (user_id, case_key, source, reward.get("label", "?")))
                conn.commit()
    except Exception:
        pass
    return given_text


def dark_case_open(user_id, source="manual"):
    """Открыть кейс «Тьма». Возвращает текст награды."""
    return _event_case_open_common(user_id, "dark", DARK_CASE_REWARDS, source)


def sea_case_open(user_id, source="manual"):
    """Открыть кейс «Морской»."""
    return _event_case_open_common(user_id, "sea", SEA_CASE_REWARDS, source)


def ice_case_open(user_id, source="manual"):
    """Открыть кейс «Ледяной»."""
    return _event_case_open_common(user_id, "ice", ICE_CASE_REWARDS, source)


