def darkgame_get_active_for_user(user_id):
    """Возвращает Row активной игры (collecting/playing), где игрок участник."""
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("""SELECT g.* FROM event_games g
                             JOIN event_game_players p ON p.game_id = g.id
                             WHERE p.user_id = ?
                             AND g.status IN ('collecting', 'playing')
                             ORDER BY g.id DESC LIMIT 1""", (user_id,))
                return c.fetchone()
    except Exception:
        return None


def darkgame_get_open_collecting():
    """Активная игра в статусе 'collecting' (сбор идёт). Одна на весь бот."""
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("""SELECT * FROM event_games
                             WHERE status = 'collecting'
                             ORDER BY id DESC LIMIT 1""")
                return c.fetchone()
    except Exception:
        return None


def darkgame_get_game(game_id):
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT * FROM event_games WHERE id = ?", (game_id,))
                return c.fetchone()
    except Exception:
        return None


def darkgame_get_players(game_id):
    """Список Row участников."""
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("""SELECT user_id, joined_at, pressed_at
                             FROM event_game_players WHERE game_id = ?
                             ORDER BY joined_at ASC""", (game_id,))
                return c.fetchall()
    except Exception:
        return []


def darkgame_player_count(game_id):
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT COUNT(*) as cnt FROM event_game_players WHERE game_id = ?", (game_id,))
                r = c.fetchone()
                return r["cnt"] if r else 0
    except Exception:
        return 0


def darkgame_start_collect(creator_id):
    """Создаёт новую игру-сбор. Возвращает (ok, game_id_or_msg)."""
    # Уже есть сбор?
    active = darkgame_get_open_collecting()
    if active:
        return True, active["id"]
    try:
        collect_until = (datetime.now() + timedelta(seconds=DARKGAME_COLLECT_SEC)).strftime(DB_DATE_FMT)
        with DARKGAME_LOCK:
            with DB_LOCK:
                with _conn() as conn:
                    c = conn.cursor()
                    c.execute("""INSERT INTO event_games
                                 (creator_id, status, collect_until)
                                 VALUES (?, 'collecting', ?)""",
                              (creator_id, collect_until))
                    gid = c.lastrowid
                    conn.commit()
        return True, gid
    except Exception as e:
        return False, "❌ " + str(e)


def darkgame_join(game_id, user_id):
    """Записаться в игру. Возвращает (ok, message)."""
    game = darkgame_get_game(game_id)
    if not game:
        return False, "❌ Игра не найдена!"
    if game["status"] != "collecting":
        return False, "❌ Игра уже не собирается."
    # Проверка: игрок уже в другой игре/сборе?
    existing = darkgame_get_active_for_user(user_id)
    if existing:
        if existing["id"] == game_id:
            return False, "ℹ️ Ты уже участвуешь!"
        return False, "⚠️ Ты уже в другой игре. Доиграй сначала."
    # Билет?
    if ticket_get(user_id, "dark") < 1:
        return False, "❌ Нужен 🎫 Билет иллюзии. Копится раз в час."
    # Списание билета
    if not ticket_take(user_id, "dark", 1):
        return False, "❌ Не удалось списать билет."
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("""INSERT OR IGNORE INTO event_game_players
                             (game_id, user_id) VALUES (?, ?)""",
                          (game_id, user_id))
                conn.commit()
        count = darkgame_player_count(game_id)
        # Автозапуск при 5 игроках
        if count >= DARKGAME_NEED_PLAYERS:
            darkgame_start_play(game_id)
        return True, "✅ Ты в игре! (" + str(count) + "/" + str(DARKGAME_NEED_PLAYERS) + ")"
    except Exception as e:
        # Откат билета
        ticket_add(user_id, "dark", 1)
        return False, "❌ " + str(e)


def darkgame_start_play(game_id):
    """Переводит игру в статус playing. Шлёт ЛС всем участникам с кнопкой «Я ТУТ»."""
    game = darkgame_get_game(game_id)
    if not game or game["status"] != "collecting":
        return
    play_until = (datetime.now() + timedelta(seconds=DARKGAME_PLAY_SEC)).strftime(DB_DATE_FMT)
    try:
        with DARKGAME_LOCK:
            with DB_LOCK:
                with _conn() as conn:
                    c = conn.cursor()
                    c.execute("""UPDATE event_games
                                 SET status = 'playing', play_until = ?
                                 WHERE id = ? AND status = 'collecting'""",
                              (play_until, game_id))
                    if c.rowcount == 0:
                        conn.rollback()
                        return
                    conn.commit()
    except Exception as e:
        print("⚠️ darkgame_start_play: " + str(e))
        return

    players = darkgame_get_players(game_id)
    kb = {"inline_keyboard": [[
        {"text": "✅ Я ТУТ", "callback_data": "darkgame_press_" + str(game_id)}
    ]]}
    for p in players:
        try:
            send_message(p["user_id"],
                         "🎮 <b>ИГРА НАЧАЛАСЬ!</b>\n\n"
                         "👥 5/5 собрано\n"
                         "⏰ У тебя " + str(DARKGAME_PLAY_SEC // 60) + " минут нажать «Я ТУТ».\n\n"
                         "⚠️ Если хотя бы 1 не нажмёт — все проиграют.",
                         kb)
            time.sleep(0.2)
        except Exception as e:
            print("⚠️ darkgame_start_play send: " + str(e))


def darkgame_press(game_id, user_id):
    """Игрок нажал «Я ТУТ». Возвращает (ok, message, finished)."""
    game = darkgame_get_game(game_id)
    if not game or game["status"] != "playing":
        return False, "❌ Игра не активна.", False
    # Проверка: игрок участник?
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT pressed_at FROM event_game_players WHERE game_id = ? AND user_id = ?",
                          (game_id, user_id))
                r = c.fetchone()
                if not r:
                    return False, "❌ Ты не участник этой игры.", False
                if r["pressed_at"]:
                    return False, "ℹ️ Ты уже нажал!", False
                c.execute("""UPDATE event_game_players
                             SET pressed_at = ?
                             WHERE game_id = ? AND user_id = ?""",
                          (db_now(), game_id, user_id))
                conn.commit()
    except Exception as e:
        return False, "❌ " + str(e), False

    # Проверяем, все ли нажали
    players = darkgame_get_players(game_id)
    pressed = sum(1 for p in players if p["pressed_at"])
    total = len(players)
    if pressed >= total and total >= DARKGAME_NEED_PLAYERS:
        darkgame_finish(game_id, winner=True)
        return True, "✅ Все нажали! Победа!", True
    else:
        # Обновляем статус — шлём всем остальным прогресс
        return True, "✅ Принято! (" + str(pressed) + "/" + str(total) + ")", False


def darkgame_finish(game_id, winner):
    """Завершает игру. Раздаёт награды или провал."""
    try:
        with DARKGAME_LOCK:
            with DB_LOCK:
                with _conn() as conn:
                    c = conn.cursor()
                    c.execute("SELECT status FROM event_games WHERE id = ?", (game_id,))
                    r = c.fetchone()
                    if not r or r["status"] not in ("playing", "collecting"):
                        return
                    c.execute("UPDATE event_games SET status = ? WHERE id = ?",
                              ("finished" if winner else "failed", game_id))
                    conn.commit()
    except Exception as e:
        print("⚠️ darkgame_finish: " + str(e))
        return

    players = darkgame_get_players(game_id)
    players_json = json.dumps([p["user_id"] for p in players])
    rewards_data = {}

    if winner:
        for p in players:
            uid = p["user_id"]
            reward = event_roll_rewards(DARK_REWARDS)
            given = event_grant_reward(uid, reward, source="darkgame")
            rewards_data[str(uid)] = given
            try:
                send_message(uid,
                             "🏆 <b>ПОБЕДА!</b>\n\n"
                             "🎁 Твоя награда:\n" + str(given))
            except Exception:
                pass
    else:
        for p in players:
            uid = p["user_id"]
            try:
                send_message(uid,
                             "💀 <b>ИГРА ПРОВАЛЕНА!</b>\n\n"
                             "Кто-то не нажал «Я ТУТ».\n"
                             "🎫 Билеты сгорели.")
            except Exception:
                pass

    # История
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("""INSERT INTO event_game_history
                             (game_id, result, players_json, rewards_json)
                             VALUES (?, ?, ?, ?)""",
                          (game_id, "win" if winner else "lose",
                           players_json, json.dumps(rewards_data, ensure_ascii=False)))
                conn.commit()
    except Exception:
        pass


def darkgame_cancel_collect(game_id, reason="timeout"):
    """Отмена сбора (< 5 человек). Возврат билетов."""
    game = darkgame_get_game(game_id)
    if not game or game["status"] != "collecting":
        return
    try:
        with DARKGAME_LOCK:
            with DB_LOCK:
                with _conn() as conn:
                    c = conn.cursor()
                    c.execute("UPDATE event_games SET status = 'cancelled' WHERE id = ? AND status = 'collecting'",
                              (game_id,))
                    if c.rowcount == 0:
                        conn.rollback()
                        return
                    conn.commit()
    except Exception:
        return
    players = darkgame_get_players(game_id)
    for p in players:
        ticket_add(p["user_id"], "dark", 1)
        try:
            send_message(p["user_id"],
                         "❌ <b>Игра отменена.</b>\n\n"
                         "Не набралось 5 человек за " + str(DARKGAME_COLLECT_SEC // 60) + " мин.\n"
                         "🎫 Билет возвращён.")
        except Exception:
            pass


# ============================================================
# ✅ ИВЕНТ 2: «ВЕСЁЛЫЕ ДЕНЬКИ» (Пузыри)
# ============================================================

def pool_play(user_id):
    """Открывает ячейку /pool. Возвращает (ok, message)."""
    if event_get_active() != EVENT_SUMMER:
        return False, "❌ Ивент «Весёлые деньки» сейчас не активен."
    if ticket_get(user_id, "bubble") < 1:
        return False, "❌ Нужен 🫧 Билет Пузырей. Копится раз в 2 часа."
    if not ticket_take(user_id, "bubble", 1):
        return False, "❌ Не удалось списать билет."
    reward = event_roll_rewards(POOL_REWARDS)
    if not reward:
        return False, "❌ Ошибка ролла."
    given = event_grant_reward(user_id, reward, source="pool")
    return True, ("🌊 <b>Весёлые деньки!</b>\n\n"
                  "Ты открыл ячейку и получил:\n" + str(given))


# ============================================================
# ✅ ИВЕНТ 3: «ЗИМНИЕ ДНИ» (Спуск + снежки)
# ============================================================

def spusk_cooldown_left(user_id):
    """Секунд до конца кулдауна спуска. 0 — можно."""
    try:
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("SELECT last_spusk FROM event_tickets WHERE user_id = ?", (user_id,))
                r = c.fetchone()
                if not r or not r["last_spusk"]:
                    return 0
                last = db_parse(r["last_spusk"])
                if not last:
                    return 0
                diff = (datetime.now() - last).total_seconds()
                if diff >= SPUSK_COOLDOWN_SEC:
                    return 0
                return int(SPUSK_COOLDOWN_SEC - diff)
    except Exception:
        return 0


def spusk_set_time(user_id):
    try:
        _ticket_ensure_row(user_id)
        with DB_LOCK:
            with _conn() as conn:
                c = conn.cursor()
                c.execute("UPDATE event_tickets SET last_spusk = ? WHERE user_id = ?",
                          (db_now(), user_id))
                conn.commit()
        return True
    except Exception:
        return False


def spusk_play(user_id):
    """Спуск. Возвращает (ok, message)."""
    if event_get_active() != EVENT_WINTER:
        return False, "❌ Ивент «Зимние дни» сейчас не активен."
    cd = spusk_cooldown_left(user_id)
    if cd > 0:
        m = cd // 60
        s = cd % 60
        return False, "⏰ Кулдаун спуска: " + str(m) + "м " + str(s) + "с"
    if ticket_get(user_id, "winter") < 1:
        return False, "❌ Нужен ❄️ Билет Зимних дней. Копится раз в 3 часа."
    if not ticket_take(user_id, "winter", 1):
        return False, "❌ Не удалось списать билет."
    snow = random.randint(SPUSK_SNOW_MIN, SPUSK_SNOW_MAX)
    snow_add(user_id, snow)
    spusk_set_time(user_id)
    total = snow_get(user_id)
    return True, ("❄️ <b>СПУСК!</b>\n\n"
                  "Ты собрал: ❄️ " + str(snow) + " снежков\n"
                  "📦 Всего снежков: " + str(total) + "\n"
                  "❄️ Ледяной кейс: " + str(ICE_CASE_PRICE) + " снежков")


def ice_case_buy(user_id):
    """Покупка Ледяного кейса за 5000 снежков."""
    if event_get_active() != EVENT_WINTER:
        return False, "❌ Ивент «Зимние дни» сейчас не активен."
    have = snow_get(user_id)
    if have < ICE_CASE_PRICE:
        return False, ("❌ Нужно " + str(ICE_CASE_PRICE) + " снежков!\n"
                       "У тебя: " + str(have))
    if not snow_take(user_id, ICE_CASE_PRICE):
        return False, "❌ Не удалось списать снежки."
    given = ice_case_open(user_id, source="purchase")
    return True, ("🎁 <b>ЛЕДЯНОЙ КЕЙС ОТКРЫТ!</b>\n\n"
                  "🎉 Награда:\n" + str(given) + "\n\n"
                  "❄️ Осталось снежков: " + str(snow_get(user_id)))


