# ✅ ПЛАНИРОВЩИКИ
# ============================================================

def scheduler_event_tickets():
    """Раз в 5 минут проходит по игрокам и выдаёт билеты по таймингу.
    Тьма — раз в час, Пузыри — раз в 2ч, Зимние дни — раз в 3ч.
    Выдаются только если ивент активен."""
    while not scheduler_stop.is_set():
        try:
            active = event_get_active()
            if active != EVENT_NONE:
                users = get_all_user_ids(active_only=True)
                given_dark = given_bubble = given_winter = 0
                for uid in users:
                    try:
                        if active == EVENT_DARK:
                            if ticket_give_hourly(uid, "dark"):
                                given_dark += 1
                        elif active == EVENT_SUMMER:
                            if ticket_give_hourly(uid, "bubble"):
                                given_bubble += 1
                        elif active == EVENT_WINTER:
                            if ticket_give_hourly(uid, "winter"):
                                given_winter += 1
                    except Exception:
                        pass
                if given_dark or given_bubble or given_winter:
                    print("🎫 Билеты: dark=" + str(given_dark) +
                          " bubble=" + str(given_bubble) +
                          " winter=" + str(given_winter))
        except Exception as e:
            print("⚠️ scheduler_event_tickets: " + str(e))
        time.sleep(300)  # 5 минут


def scheduler_event_watch():
    """Каждые 20 секунд:
    - отменяет сборы «Тьмы», где истекло 5 мин;
    - проваливает игры «Тьмы», где истекло 30 мин без всех нажатий."""
    while not scheduler_stop.is_set():
        try:
            now = datetime.now()
            # Сборы
            try:
                with DB_LOCK:
                    with _conn() as conn:
                        c = conn.cursor()
                        c.execute("""SELECT id, collect_until FROM event_games
                                     WHERE status = 'collecting'""")
                        collecting = c.fetchall()
                for g in collecting:
                    ends = db_parse(g["collect_until"])
                    if ends and ends <= now:
                        darkgame_cancel_collect(g["id"], "timeout")
            except Exception as e:
                print("⚠️ event_watch collecting: " + str(e))

            # Игры
            try:
                with DB_LOCK:
                    with _conn() as conn:
                        c = conn.cursor()
                        c.execute("""SELECT id, play_until FROM event_games
                                     WHERE status = 'playing'""")
                        playing = c.fetchall()
                for g in playing:
                    ends = db_parse(g["play_until"])
                    if ends and ends <= now:
                        darkgame_finish(g["id"], winner=False)
            except Exception as e:
                print("⚠️ event_watch playing: " + str(e))

        except Exception as e:
            print("⚠️ scheduler_event_watch: " + str(e))
        time.sleep(20)


