def handle_mini_nira(chat_id, user_id):
    """Команда /mini_nira. Только в ЛС."""
    if chat_id < 0:
        send_message(chat_id, "❌ Игра доступна только в <b>ЛС бота</b>.")
        return
    if event_get_active() != EVENT_DARK:
        send_message(chat_id, "❌ Ивент «Билет иллюзии» сейчас не активен.")
        return

    existing = darkgame_get_active_for_user(user_id)
    if existing:
        # Уже в сборе — предложим присоединиться или покажем статус
        if existing["status"] == "collecting":
            gid = existing["id"]
            cnt = darkgame_player_count(gid)
            send_message(chat_id,
                         "ℹ️ <b>Ты уже в сборе #" + str(gid) + "</b>\n\n"
                         "👥 " + str(cnt) + "/" + str(DARKGAME_NEED_PLAYERS) + "\n"
                         "⏰ Жди, пока наберётся 5.")
            return
        elif existing["status"] == "playing":
            send_message(chat_id, "🎮 Ты в активной игре! Жми «Я ТУТ» в сообщении выше.")
            return

    # Билет?
    if ticket_get(user_id, "dark") < 1:
        send_message(chat_id, "❌ Нужен 🎫 Билет иллюзии. Копится раз в час.")
        return

    # Есть ли уже сбор от кого-то?
    active = darkgame_get_open_collecting()
    if active:
        gid = active["id"]
        ok, msg = darkgame_join(gid, user_id)
        send_message(chat_id, msg)
        if ok:
            # Обновим счётчик в чатах остальных
            cnt = darkgame_player_count(gid)
            _notify_darkgame_collect_update(gid, cnt)
        return

    # Создаём новый сбор
    ok, gid = darkgame_start_collect(user_id)
    if not ok:
        send_message(chat_id, "❌ " + str(gid))
        return
    # Запускающий сразу входит
    ok2, msg2 = darkgame_join(gid, user_id)
    if not ok2:
        send_message(chat_id, "❌ " + str(msg2))
        return
    send_message(chat_id,
                 "🎫 <b>ИГРА СОБИРАЕТСЯ!</b>\n\n"
                 "👥 1/" + str(DARKGAME_NEED_PLAYERS) + "\n"
                 "⏰ Окно сбора: " + str(DARKGAME_COLLECT_SEC // 60) + " мин\n\n"
                 "Ждём 5 человек...")
    # Рассылка активным
    _darkgame_broadcast_invite(gid, user_id)


def _darkgame_broadcast_invite(game_id, creator_id):
    """Рассылает приглашение всем активным игрокам (кроме создателя)."""
    users = get_all_user_ids(active_only=True)
    creator_name = get_display_name(creator_id)
    kb = {"inline_keyboard": [[
        {"text": "🎫 УЧАСТВОВАТЬ", "callback_data": "darkgame_join_" + str(game_id)}
    ]]}
    text = ("🎫 <b>ИГРА «БИЛЕТ ИЛЛЮЗИИ» СОБИРАЕТСЯ!</b>\n\n"
            "👤 Запустил: " + str(creator_name) + "\n"
            "👥 1/" + str(DARKGAME_NEED_PLAYERS) + "\n"
            "⏰ Окно: " + str(DARKGAME_COLLECT_SEC // 60) + " мин\n\n"
            "Нужно " + str(DARKGAME_NEED_PLAYERS) + " человек. У каждого — 🎫 билет.\n"
            "Нажми кнопку, чтобы вступить!")
    sent = 0
    for uid in users:
        if uid == creator_id:
            continue
        try:
            send_message(uid, text, kb)
            sent += 1
            time.sleep(0.05)
        except Exception:
            pass
    print("🎫 Invite sent: " + str(sent))


