def process_admin_event_give_case(chat_id, user_id, text):
    if not is_owner(user_id):
        return
    user_state_pop(user_id)
    if text.strip().lower() in ("/cancel", "отмена"):
        send_message(chat_id, "❌ Отменено.")
        return
    parts = text.strip().split()
    if len(parts) != 2:
        send_message(chat_id, "❌ Формат: ID|@user КЕЙС")
        return
    target = shield_resolve_id(parts[0])
    if not target or get_user(target) is None:
        send_message(chat_id, "❌ Игрок не найден!")
        return
    case_key = parts[1].strip().lower()
    if case_key == "dark":
        given = dark_case_open(target, source="admin")
    elif case_key == "sea":
        given = sea_case_open(target, source="admin")
    elif case_key == "ice":
        given = ice_case_open(target, source="admin")
    else:
        send_message(chat_id, "❌ Кейс: dark / sea / ice")
        return
    name = get_display_name(target)
    send_message(chat_id, "✅ " + str(name) + " получил: " + str(given))
    staff_log_write(user_id, "event_give_case", target, case_key)
    try:
        send_message(target,
                     "🎁 <b>АДМИН ВЫДАЛ ТЕБЕ КЕЙС!</b>\n\n"
                     "Ты получил: " + str(given))
    except Exception:
        pass


